# ===================== DA ASSENTADA =====================
estribilho_pagina()
st.append(PageBreak()); sp(30)
add("Nos primeiros dias", LIV)
QUANDO["Da assentada"] = "nos primeiros dias; antes de cada obra nova"
add("Da assentada", LT); sumario(st[-1], 0, "Da assentada")
# LBX só é definido no Livro III; este capítulo vem antes e precisa do mesmo rótulo.
LBA = ParagraphStyle('lba', **{**base, 'textColor': GRAY}, fontSize=9.5, leading=12, spaceBefore=6, spaceAfter=2, keepWithNext=1)
add("<i>“Pureza de coração é querer uma só coisa.”</i>", ParagraphStyle('as1', parent=PC, fontSize=12, spaceAfter=2))
add("Søren Kierkegaard", ParagraphStyle('as2', parent=EPA, spaceAfter=20))
SEC_NO_SUMARIO = True

sec("Da assentada")
add("Você lê este capítulo inteiro numa das primeiras noites depois do dia zero, fora das horas da obra, e sai dele com a frase de cor e as duas metades entendidas. Volte a ele quando se sentar sem saber o que fazer, quando se pegar preparando a obra em vez de fazê-la, quando quiser largar o que tem nas mãos por outra coisa que parece mais promissora ou quando uma interrupção lhe custar a volta; e releia-o inteiro na véspera de toda obra nova.", PI)
add("Talvez você conheça de perto estas duas pessoas. Uma decide aprender álgebra. Compra três livros, procura o melhor curso, faz um plano de seis meses com cores diferentes, arruma um calendário para riscar os dias seguidos. Um mês depois, sabe muito sobre como se aprende álgebra, e quase nada de álgebra. A outra decide o mesmo, num sábado de manhã se senta à mesa com um livro e um lápis, e à noite resolve equações que de manhã não sabia ler. Ela não é especialista. Mas tem a base, e a base é o que faltava à primeira para todo o resto. Com uma língua acontece o mesmo: duas semanas depois, uma das duas já fala, mal e com vontade, e a outra continua escolhendo o método.", PI)
add("É tentador explicar a diferença pelo talento, ou pela disciplina. O livro não pode lhe dar talento, e você mesmo sente que a palavra disciplina não basta, porque quem você viu fazer assim não parecia estar se forçando. Também não parecia ter um plano melhor. A segunda pessoa planejou menos do que a primeira, e contou menos. O que a separa da primeira está na maneira de pensar enquanto está sentada: ela tem uma coisa à frente, e nenhuma outra, e fica com ela até essa coisa estar feita. Há em português uma expressão antiga para isso, fazer de uma assentada, isto é, de uma vez, sentado, sem levantar até estar feito. Este capítulo trata desse modo de pensar, e de uma frase que o protege.", PI)
add("Este é o capítulo de que o Proêmio falou, o do estado que dá nome ao livro. Conhece esse estado quem já o teve numa tarde inteira sem ter tomado nada, e os outros capítulos tiram da mesa e dos dias o que o impede. Este capítulo dá a você a frase que, cada vez que você se senta, prepara o lugar onde o estado pode aparecer, e, no fim, o modo de conduzir a sessão em que ele aparece ou deixa de aparecer.", PI)
add("Franz Kafka deixou desse estado um registro com data e hora. Na noite de 22 para 23 de setembro de 1912, ele se sentou às dez horas e escreveu <i>O veredicto</i> até as seis da manhã, <i>in einem Zug</i>, de uma assentada. Anotou no diário, no dia seguinte, que mal conseguia tirar de debaixo da mesa as pernas, rígidas de tanto estar sentado, e falou do esforço terrível e da alegria de ver a história se desenvolver diante dele, como quem avança dentro da água. Às duas olhou o relógio pela última vez. Quando a empregada passou pela primeira vez pela antessala, ele escreveu a última frase. E concluiu, na mesma página, que só assim se pode escrever, com essa coesão, com essa abertura completa do corpo e da alma. Kafka passava os dias num escritório de seguros contra acidentes de trabalho, e muitas das noites dele à mesa não davam nada; aquela foi rara para ele também. O que ele descreve é o estado de que este capítulo trata: uma coisa só à frente, e ele com ela até ela acabar.", PI)

sec("Da frase")
add("A frase é esta, e se diz por dentro:", PI)
add("Isto, até acabar.", VOICE)
sp(6)
add("Ela tem duas metades, e cada uma pergunta uma coisa. <i>Isto</i> pergunta o que você tem à frente. Pede uma coisa só, presente, que se possa apontar: este capítulo, este problema, esta página, esta carta. Não pede a obra inteira, nem a vida, nem o que vem depois; pede o que está nas suas mãos agora. <i>Até acabar</i> pergunta quando isso termina, e põe o fim na própria coisa. Acaba quando o capítulo estiver lido e resolvido, quando o problema sair, quando a página estiver escrita. Não acaba quando a vontade passar, nem quando outra coisa chamar, nem quando o cansaço aparecer.", PI)
add("Convém dizer o que a frase não é, porque ela se parece com outras. Não é uma promessa. Não diz nada sobre amanhã, nem sobre quem você é, nem sobre o que você vai conseguir; não se assina, não se cumpre nem se quebra. Diz apenas como estar diante do que você tem à frente. Se você a disser e, cinco minutos depois, se levantar, a frase não foi desmentida: volta a ser dita quando você se sentar outra vez. É por isso que serve para todos os casos. As nove linhas do Livro I respondem, cada uma, a um instante; esta fica por trás de todas, como a pergunta da qual elas são respostas particulares.", PI)
add("Ela responde aos casos que mais custam a você. Quando você não sabe o que fazer, a primeira metade pergunta qual é <i>isto</i>, e obriga você a escolher uma coisa que se possa apontar. Quando você adia, ela lembra que só se acaba o que se começou, e que <i>isto</i> está aqui, agora. Quando você planeja em vez de fazer, a segunda metade pergunta o que o plano acaba, e a resposta honesta é nada. Quando outra coisa chama você, a frase diz que essa outra coisa não é <i>isto</i>, e que ela pode esperar. Quando você tem vontade de trocar de livro ou de método no meio, a frase pede que você acabe antes de trocar. E quando o cansaço chega, ela pede menos do que parece: acabar o passo em que você está, e depois ver.", PI)
add("D O &nbsp; P O R Q U Ê", LBA)
add("<b>A ideia.</b> Vários dos que pensaram o trabalho bem feito disseram, cada um a seu modo e para fins diferentes, alguma coisa sobre ter uma coisa só à frente: Dōgen, Descartes, Kierkegaard, Aristóteles, Simone Weil. Nenhum escreveu esta frase. As seções seguintes contam o que cada um pensava, e onde o livro se afasta dele.", PI)
add("<b>O mecanismo.</b> Primeiro, a voz que tira você da obra quase nunca pede que você desista; pede que você faça outra coisa no lugar, mais fácil e parecida com a obra, e a frase a reconhece sem discutir, porque essa outra coisa não é <i>isto</i>. Segundo, um fim posto na coisa é visível e se aproxima, enquanto um fim posto no humor muda a cada minuto; quem sabe onde a coisa acaba deixa de ter de decidir, a cada minuto, se continua. Nenhum estudo testou esta frase; o que está dito aqui vem do raciocínio e do que os autores contam.", PI)
add("<b>Por isso.</b> <i>Digo a frase porque, com uma coisa só à frente e o fim posto nela, deixo de ter de decidir a cada minuto se continuo, e reconheço o que me chama sem lhe responder.</i>", PI)

sec("Do cozinheiro")
add("Conto primeiro o caso de um monge japonês, Dōgen, que viveu entre 1200 e 1253 e levou para o Japão a escola zen que lá chamam de Sōtō. Aos vinte e três anos, atravessou o mar até a China em busca de um mestre e passou alguns anos no mosteiro do monte Tiantong. Muito mais tarde, já de volta ao Japão, escreveu umas <i>Instruções ao cozinheiro</i>, sobre o ofício do monge encarregado da comida da comunidade, e conta nelas um encontro dessa época.", PI)
add("Era verão, depois do almoço, e Dōgen atravessava o pátio. O cozinheiro do mosteiro, um velho curvado de sobrancelhas brancas, estava ao sol, sem chapéu, com um bastão, pondo cogumelos para secar sobre as pedras, que escaldavam; suava, e via-se que aquilo lhe custava. Dōgen lhe perguntou a idade, e ele respondeu sessenta e oito. Perguntou por que não deixava aquilo para um ajudante. O velho respondeu: os outros não são eu. Dōgen insistiu: o senhor faz bem em cumprir o seu ofício, mas por que agora, com este calor? E o velho respondeu: se não agora, quando? Dōgen se calou, e escreve que foi então que começou a perceber o que era o ofício do cozinheiro.", PI)
add("Para entender o que o velho quer dizer, convém saber como pensava a escola de Dōgen. Para ele, a prática não ficava guardada para as horas de meditação, separada do resto do dia; estava inteira em cada coisa feita com o espírito todo: cozinhar, varrer, lavar o arroz. E a prática e a realização são, para Dōgen, uma coisa só: quem se senta, ou lava o arroz, com o espírito todo, já está no caminho inteiro, e não há adiante nenhuma chegada que dê valor ao gesto. O trabalho que se tem à frente é o lugar onde a vida está nesse momento, e nada mais importante espera por trás dele. As duas respostas do velho dizem isso das duas maneiras possíveis. <i>Os outros não são eu</i>: esta tarefa é minha, e entregá-la a outro seria largar a parte de vida que ela é. <i>Se não agora, quando?</i>: o tempo desta tarefa é este, e adiá-la para uma hora mais fresca seria tratá-la como se fosse de outro dia.", PI)
add("A frase deste capítulo toma do velho a primeira metade, e só essa. <i>Isto</i> é o que ele dizia ao recusar o ajudante e ao recusar a hora mais fresca: o que está nas suas mãos é seu, e o tempo dessa coisa é agora. A segunda metade já não é de Dōgen. O velho fica no pátio até os cogumelos estarem estendidos, mas a resposta <i>se não agora, quando?</i> fala de cada instante como completo, e não de um fim posto adiante. Dōgen escreveu ainda, no <i>Genjōkōan</i>, que estudar o caminho é estudar o eu, e estudar o eu é esquecer o eu; um caderno que faz você se examinar todas as noites e contar os dias limpos vai no sentido contrário. Há ainda uma ironia: a frase vai buscar a primeira metade num velho que recusa o ajudante porque os outros não são eu, e a pergunta da máscara manda você agir como outro. As duas cabem no mesmo dia porque não falam na mesma hora. A pergunta escolhe na entrada; dito <i>Isto</i>, ela se cala até o fim do passo, e fica só a frase, com a tarefa que é sua e a hora que é esta.", PI)

sec("Da floresta")
add("O caso mais comum de quem não começa é não saber o que fazer. Você se senta, e na cabeça há uma nuvem: <i>tenho de estudar, tenho de pôr aquilo em dia, tenho de aprender francês, tenho de mudar de vida</i>. A nuvem pesa e não pode ser feita, porque não tem começo. Quem está nela diz que lhe falta motivação; quase sempre, o que falta é saber qual é <i>isto</i>.", PI)
add("Descartes passou por uma nuvem dessas e deixou escrito o que fez no <i>Discurso do método</i>, de 1637. Conta ali as quatro regras do método com que, num inverno na Alemanha, decidiu conduzir o pensamento; a quarta linha, a do impasse, que você lerá nestes dias, parte da segunda regra: dividir cada dificuldade em tantas partes quantas forem precisas. As regras são para pensar. Logo em seguida, para viver, ele conta que, enquanto reconstruía as próprias opiniões, precisava continuar a viver e a agir, e por isso fixou umas poucas máximas provisórias. A segunda era ser o mais firme e resoluto que pudesse nas ações, e seguir as opiniões mais duvidosas, uma vez decididas, com a mesma constância com que seguiria as muito certas. Ele a explica com uma imagem. Os viajantes que se perdem numa floresta não devem andar em círculos, ora para um lado, ora para outro, nem parar num lugar, mas caminhar sempre o mais reto que puderem para um mesmo lado, e não mudar de rumo por razões fracas, ainda que só o acaso tenha escolhido esse lado; porque assim, se não chegam aonde queriam, chegam pelo menos a algum lugar onde provavelmente estão melhor do que no meio da floresta.", PI)
add("Para Descartes, quando a razão não consegue escolher entre caminhos, a pior escolha é não escolher, porque quem anda em círculos gasta a força de andar sem sair do lugar. A clareza, para ele, não vem antes da escolha; vem de caminhar depois dela, porque só quem anda descobre como é a floresta. E a máxima tem uma condição: é provisória. Descartes seguia o caminho escolhido enquanto não tinha razões para revê-lo, e se reservava o direito de revê-lo quando as tivesse. No seu caderno, esse tempo de rever tem lugar marcado: a noite de passagem.", PI)
add("É assim que a primeira metade da frase funciona quando você está na nuvem. Ela não pede a coisa certa; pede uma coisa. Se há três que parecem igualmente urgentes, a primeira linha ajuda a escolher, ao perguntar o que tem de existir quando você se levantar; e a sétima, a da escolha, que você lerá nestes dias, pergunta qual delas você evitaria se pudesse, para que você escolha essa. Se mesmo assim ficarem empatadas, você escolhe a primeira e para de escolher. O que fica de fora vai para a folha de captura. Parece pouco, uma tarde de verbos para quem quer aprender francês. O problema está na nuvem: <i>aprender francês</i> é uma frase verdadeira e não se pode começar. Serve de direção, e a direção você já escreveu no dia zero. A pessoa que aprendeu a base de álgebra num sábado não se sentou para aprender álgebra; sentou-se diante da primeira coisa que a álgebra pede, até dominá-la, e depois diante da seguinte, e a álgebra foi o que ficou.", PI)

sec("Do ânimo dobre")
add("A epígrafe deste capítulo é o título de um discurso de Kierkegaard, <i>Pureza de coração é querer uma só coisa</i>, escrito em 1847 para quem se preparava para a confissão. Kierkegaard era dinamarquês, viveu quase sempre em Copenhague e escreveu muitos dos livros com nomes inventados; este ele assinou com o próprio nome. O discurso parte da Epístola de Tiago, que chama de inconstante, em todos os seus caminhos, o homem de ânimo dobre, literalmente, de duas almas.", PI)
add("O que interessa aqui é o modo como Kierkegaard pensa a palavra <i>querer</i>. Para ele, a pessoa dividida raramente é a que quer o mal às claras. É a que quer uma coisa e, ao lado, outra: o bem e a recompensa, o bem e não ser castigada, o bem para brilhar com ele, e, a mais difícil de ver, o bem até certo ponto. Quem quer até certo ponto tem sempre, para mostrar, a parte que quis, e por isso nunca se acusa. E Kierkegaard acrescenta algo que parece escrito para os nossos dias. Entre as formas da divisão, ele põe a pressa ocupada, a vida cheia de afazeres em que cada coisa puxa para um lado e nenhuma chega ao fim; diz que ela impede o homem de se recolher, e que muitas vezes é escolhida justamente para isso.", PI)
add("Com isso Kierkegaard quer dizer que a unidade de uma pessoa não está dentro dela à espera de ser encontrada; ela se faz querendo uma coisa inteira, e se desfaz querendo-a pela metade. Mas a coisa, para ele, tem nome, e é o centro do discurso: só o Bem é uma coisa só. Tudo o que é do mundo, o prazer, a honra, a riqueza, e também um capítulo ou uma obra, é muitas coisas por natureza, e quem o quer de todo o coração continua dividido. E o primeiro caso de ânimo dobre que ele examina é querer o bem pela recompensa, mesmo a recompensa interior: quem quisesse o capítulo pelo estado que dá nome a este livro seria, para Kierkegaard, de ânimo dobre. O fim do discurso é o indivíduo diante de Deus, e a ocasião é a confissão.", PI)
add("O livro toma desse discurso a forma do querer inteiro e a figura do <i>até certo ponto</i>, e as usa para um fim menor, uma obra que acaba numa tarde; Kierkegaard não chamaria isso de pureza de coração. Nessa escala, a segunda metade da frase responde ao <i>até certo ponto</i>. Quem lê o capítulo até a parte difícil e para ali quis o capítulo até certo ponto; quem lê até acabar quis o capítulo, e a diferença se sente à noite, quando o que ficou feito está inteiro ou pela metade. É isso que <i>ele</i> é: alguém que não quer até certo ponto.", PI)
add("É também por isso que a frase pede que você acabe antes de trocar. No meio de uma obra, outra obra, outro livro, outro método costumam parecer mais promissores, e muitas vezes parecem só porque você ainda não chegou à parte difícil deles. Sêneca chamava isso de fastio, e <i>Do pêndulo</i>, nas estações, conta isso por inteiro. Kierkegaard chamaria isso de ânimo dobre: querer isto e, ao lado, a saída. O que lhe parecer melhor se escreve na folha de captura e espera pela noite; se for melhor de verdade, vai continuar sendo melhor depois que você acabar <i>isto</i>.", PI)

sec("Das duas portas")
add("Você chama de sabotagem uma coisa estranha: você quer fazer, sabe que quer, e é você mesmo quem impede. Os gregos tinham para isso uma palavra, <i>akrasía</i>: saber o que é melhor e fazer o pior. A segunda linha, a da vontade de parar, conta o que Sócrates e Aristóteles disseram dela. Falta contar o resto do que Aristóteles diz no mesmo sétimo livro da <i>Ética a Nicômaco</i>, porque é esse resto que explica as duas maneiras mais comuns de você mesmo se tirar da obra.", PI)
add("Aristóteles distingue duas formas da falta de domínio. Uma é a precipitação, <i>propéteia</i>: há quem não chegue a deliberar e seja levado pela primeira coisa que aparece antes que o juízo tenha falado. A outra é a fraqueza, <i>asthéneia</i>: há quem delibere, decida bem e depois não se mantenha no que decidiu, porque outra coisa chega e o arrasta. E ele acrescenta uma observação: os que veem a tentação chegar, e se preparam para ela, não são tão arrastados, assim como quem começa fazendo cócegas nos outros já não as sente quando as fazem nele.", PI)
add("Para entender isso como ele o pensava, lembre-se de que, para Aristóteles, agir bem tinha duas partes: ver o que se deve fazer e ser levado por isso até o ato. O homem prudente tem as duas. O precipitado falha na primeira, porque nunca chega a ver; o fraco falha na segunda, porque vê e não é levado. As duas falhas pedem remédios diferentes, e a frase tem um para cada uma. A primeira metade fecha a porta da precipitação, porque quem diz <i>isto</i> teve de olhar e escolher antes de fazer; já não está à mercê da primeira coisa que aparece. A segunda metade fecha a porta da fraqueza, porque põe o fim fora do alcance do que chega depois: o que chega pode ser vontade, pode ser cansaço, pode ser uma boa ideia, e nenhuma dessas coisas acaba <i>isto</i>.", PI)
add("E a observação das cócegas explica algo que talvez você já tenha notado: a sabotagem quase nunca aparece como desistência. Aparece como outra coisa, mais fácil e parecida com a obra: preparar em vez de fazer, rever o que você já sabe em vez de enfrentar o que não sabe, ler mais um pouco em vez de tentar, ver só uma coisa e já voltar. Cada uma, vista sozinha, tem uma razão. Quem a conhece de antemão, como Aristóteles aconselhava, já não é pego por ela, e a frase reconhece todas da mesma maneira: nenhuma é <i>isto</i>. Também por isso a preparação, neste livro, tem lugar marcado: a folha das quatro perguntas da oitava linha, a de quando você começa algo novo, que você lerá nestes dias. Essa folha se faz numa sessão com prazo, e acaba ali.", PI)

sec("Da atenção")
add("Volto à palavra que incomodava você: disciplina. Quem passa uma tarde numa matéria nova, e passa bem, não descreve o dia como um esforço contra si mesmo. Quase sempre o descreve com surpresa: o tempo passou depressa, esqueceu de comer, no fim da tarde estava mais acordado do que de manhã. Uma filósofa e um psicólogo pensaram esse estado com cuidado, e convém ouvir os dois.", PI)
add("Simone Weil nasceu em Paris em 1909, estudou filosofia na École Normale e a ensinou em liceus do interior; deixou o ensino durante um ano para trabalhar como operária em fábricas metalúrgicas, para saber por dentro o que era esse trabalho. Em 1942, pouco antes de deixar a França, escreveu a um padre amigo, Joseph-Marie Perrin, um texto curto destinado a estudantes, que intitulou <i>Reflexões sobre o bom uso dos estudos escolares em vista do amor de Deus</i>; morreu na Inglaterra no ano seguinte, aos trinta e quatro anos. O texto parte de uma confusão que ela via em todas as escolas. Diz-se a um aluno <i>preste atenção</i>, e ele franze a testa, prende a respiração, contrai os músculos; depois de vinte minutos, se lhe perguntarem em que esteve atento, não sabe dizer. Esteve atento a nada. Esteve fazendo força.", PI)
add("Weil separa as duas coisas numa frase. A vontade, a que aperta os dentes e aguenta o sofrimento, é a arma principal do aprendiz no trabalho manual; mas, ao contrário do que se pensa, quase não tem lugar no estudo. A inteligência só pode ser conduzida pelo desejo, e para haver desejo é preciso haver prazer e alegria no trabalho. E ela descreve a atenção verdadeira como o contrário da força: suspender o próprio pensamento, deixá-lo disponível, vazio, aberto ao objeto, como quem do alto de uma montanha vê ao mesmo tempo, sem olhar para elas, as florestas e as planícies lá embaixo. Acrescenta que um esforço de atenção verdadeiro nunca se perde, mesmo que o problema de geometria fique sem solução, e por isso pede que se estude sem procurar o resultado. O pensamento atento, diz ela, fica vazio, à espera, sem procurar nada; a palavra francesa para espera, <i>attente</i>, é parente de <i>attention</i>, e Weil pensava as duas juntas.", PI)
add("Para Weil, a força da vontade é a ferramenta errada para aprender. A força da vontade se gasta depressa, cansa, e deixa a cabeça ocupada com o próprio esforço em vez de com a coisa. Mas o fim que Weil dava a essa atenção vai além do estudo, e o título diz isso. O latim e a geometria valem como exercício de uma atenção que serve depois à oração, que para ela é atenção pura voltada para Deus, e ao próximo. O texto termina no infeliz e na pergunta que só a atenção sabe fazer a ele, qual é o seu tormento?, e diz que quem aprendeu a olhar assim para um problema aprende a olhar assim para uma pessoa que sofre.", PI)
add("Mihaly Csikszentmihalyi chegou a um ponto parecido por outro caminho. Nasceu em 1934 em Fiume, no Adriático, e foi para os Estados Unidos aos vinte e dois anos; começou estudando pintores, que passavam horas diante da tela esquecidos de comer e de dormir e perdiam o interesse pelo quadro assim que ele ficava pronto. Depois ampliou o estudo para alpinistas, jogadores de xadrez, cirurgiões, operários. Em 1990 reuniu o que encontrou num livro que chamou de <i>Flow</i>, fluxo, a palavra que muitos dos entrevistados usavam para o estado: uma atenção tão posta na tarefa que não sobra para mais nada, a consciência de si desaparecendo, o tempo passando de outra maneira.", PI)
add("Csikszentmihalyi pensava como quem observa e descreve. Viu que o estado aparecia sobretudo quando a pessoa sabia com clareza o que estava fazendo, quando a própria tarefa lhe dizia a cada passo se ia bem, e quando a dificuldade pedia um pouco mais do que a pessoa tinha: nem muito menos, o que dá tédio, nem muito mais, o que dá ansiedade. E viu que as distrações desfaziam o estado, porque ele depende de a atenção não ter para onde ir. Convém dizer o que isso não dá: Csikszentmihalyi descreveu um estado e as condições em que ele costuma aparecer, e não um modo de ligá-lo quando se quer. Há dias em que ele não vem. A frase não o chama; põe você no lugar onde ele costuma aparecer, com uma coisa só à frente e sem outra para onde ir.", PI)
add("Convém agora não confundir o que Weil ensina com o que a frase pede. A atenção dela diz respeito à qualidade da presença diante da coisa, e se desliga do resultado. <i>Até acabar</i> diz respeito a outra virtude, a perseverança, que os monges do deserto chamavam de <i>hypomoné</i>, ficar até o fim, e que você encontrará em <i>Do pêndulo</i>. Pode-se perseverar desatento: o aluno de testa franzida ficou vinte minutos e esteve atento a nada. A frase pede menos do que Weil. Ela tira do caminho a pergunta, a cada minuto, sobre se você continua, e deixa livre o lugar onde a atenção, quando vier, não precisa se defender; se você a disser de dentes cerrados, ela lhe dará a perseverança e imitará mal a atenção. A disciplina serve ao começo, ao primeiro movimento, à hora de sentar, e a sexta linha trata dela. A perseverança protege a duração. A atenção, Weil a pedia como espera, e nem a disciplina nem a perseverança a garantem. Weil não fazia essa divisão, porque para ela o estudo inteiro era espera; o livro a faz por conta própria, e toma dela a crítica dos dentes cerrados, sem o fim ao qual ela a orientava. É por isso que a palavra disciplina não bastava para você.", PI)
add("Pascal faria uma objeção a esse estado. O divertimento de que o Proêmio falou inclui, nos <i>Pensamentos</i>, também a ocupação séria: o rei cercado de afazeres, o caçador atrás da lebre. Uma tarde inteira esquecido de si mesmo seria, para ele, o divertimento mais bem-acabado. E o alvo dele inclui quem se faz pela ocupação: aquele que pretende um cargo e imagina que, uma vez obtido, depois repousaria com gosto. Quem encarna o homem de X para chegar a X é esse caçador, com uma razão melhor. Pelas contas de Pascal, isso é divertimento, e o livro o escolhe sabendo disso, porque a pergunta que o divertimento evita, quem você é e para quê, você respondeu por escrito no dia zero, e a obra é o lugar onde essa resposta passa a existir.", PI)

sec("Do que acaba")
add("Falta dizer o que significa acabar, porque a frase poderia ser lida como uma ordem de nunca se levantar. Acabar pertence à coisa. Uma coisa que se aponta com <i>isto</i> tem um fim que se vê: o capítulo tem a última página, o problema tem a solução, a carta tem a assinatura. Se o que você apontou não tem fim que se veja, <i>a álgebra</i>, <i>o projeto</i>, você ainda não apontou uma coisa; volte à primeira metade.", PI)
add("E há coisas que não cabem num dia. A hora de parar que você escreve de manhã continua a valer, e a frase não a contradiz: quando a hora chega antes do fim, <i>isto</i> passa a ser o passo em que você está, e é esse passo que se acaba. Depois a quinta linha pergunta se está feito ou quase, e qual é a primeira coisa de amanhã, e amanhã <i>isto</i> começa ali. Com o cansaço acontece o mesmo. A segunda linha diz <i>até o fim deste passo</i>, e é a frase deste capítulo em ponto pequeno. Se no fim do passo o cansaço continua inteiro, sem trazer pergunta nenhuma sobre o valor da obra, é o corpo que chegou ao fim do que tinha para hoje, e a obra se fecha num ponto, sem culpa; <i>Do pêndulo</i>, que você lerá nas estações, ensina a distinguir esse cansaço do peso sem causa que vem no meio da obra. A frase também se entende com a sexta linha: quando nada em você quer começar, <i>isto</i> é a versão de dois minutos, e a própria linha diz o que <i>isto</i> passa a ser se você continuar.", PI)
add("A mulher de quem falei em <i>Do primeiro dia</i> quis fazer o primeiro capítulo do programa num sábado livre. Sentou-se às nove. Às onze e meia, na parte dos prazos, que não entendia, ela se lembrou de que havia um manual mais recente, recomendado por uma colega, que talvez explicasse melhor. Já estava com meio corpo fora da cadeira para ir procurá-lo. Disse a frase. O manual não era <i>isto</i>; foi para a folha de captura, numa linha. A parte dos prazos tomou a hora seguinte inteira. Às cinco, que era a hora de parar, ela estava no meio do terceiro dos cinco exercícios do fim do capítulo. Acabou esse, que era o passo em que estava, escreveu no caderno que amanhã começaria pelo quarto e se levantou. O que mais a surpreendeu foi não estar tão cansada quanto esperava; estava desperta, e no dia seguinte se sentou diante do quarto exercício sem nada a decidir. À noite, riscou o manual da folha de captura.", PI)
sec("Da sessão")
add("O estado que dá nome ao livro, quando vem, vem dentro de uma sessão, e a sessão tem três tempos: a entrada, a duração e a volta depois de uma saída. O que segue prepara os três, e nenhum deles liga o estado. Csikszentmihalyi, como você leu em <i>Da atenção</i>, descreveu as condições em que ele costuma aparecer, e há dias em que, cumpridas todas, ele não vem. Nesses dias a sessão vale do mesmo modo: a obra anda, e a marca da noite mede os atos.", PI)
add("<i>A entrada.</i> Ao sentar, em ordem, é isto. A mão tira da mesa o que distrai, em cinco minutos no máximo, e põe ao lado a folha de captura. Você pergunta o que ele faria agora, e a resposta escolhe a coisa. Diz a primeira linha: o que tem de existir quando você se levantar, e qual é o primeiro movimento; e começa. Começada a obra, a frase, <i>Isto, até acabar</i>, e o que chamar para outra coisa vai, numa linha, para a folha ao lado. Entre um passo e o seguinte, a pergunta pode voltar, para escolher o próximo. Ao se levantar, a mesa volta à ordem. Faça tudo isso sempre do mesmo modo e na mesma sequência, porque o valor do ritual está em ser igual: uma mesa que se reconhece não pede decisão nenhuma.", PI)
add("John Forster, amigo de Dickens, conta na <i>Vida de Charles Dickens</i> como era a mesa em que o romancista escrevia. Havia sobre ela sempre os mesmos pequenos objetos, entre eles um grupo de bronze francês, dois sapos que duelavam de florete. Estavam ali, diz Forster, para que o olho tivesse onde pousar nos intervalos da escrita, e Dickens sentiria a falta de qualquer um deles se o tirassem. O homem que encheu o século de personagens não buscava novidade na mesa. O olho que se levantava da página encontrava coisas conhecidas, que não contavam história nenhuma, e voltava à página sem ter ido a lugar algum. É o que a mesa arrumada faz por você: deixa à vista só o que não chama.", PI)
add("Os primeiros minutos quase sempre custam, e o custo não diz nada sobre a sessão. A cabeça resiste de três modos conhecidos, e cada um já tem resposta no livro. Se nada em você quer começar, a sexta linha e a versão de dois minutos; Tchaikóvski, ali, conta por que não se espera a vontade. Se você começa e a coisa não sai, a frase verdadeira de Hemingway, em <i>Da técnica</i>. Se a voz oferece outra coisa parecida com a obra, a frase deste capítulo, porque essa coisa não é <i>isto</i>. Em nenhum dos três casos você espera sentir que entrou; dez minutos de obra feita contra a resistência são a entrada.", PI)
add("<i>A duração.</i> O bloco tem começo e fim marcados antes de começar, e o tamanho dele está em <i>Da absorção</i>: de vinte e cinco a quarenta e cinco minutos no início, mais longo quando ficar fácil. Somados, os blocos no ponto difícil raramente passam de umas quatro horas por dia; é o teto que o estudo dos violinistas de Berlim, em <i>Da prática deliberada</i>, encontrou em todos os grupos, e o que Darwin, em Down, respeitava sem estudo nenhum.", PI)
add("Dentro do bloco, o estado se reconhece depois, e quase nunca durante, porque quem repara que está absorto já saiu um pouco. Humphrey Newton, que foi secretário de Isaac Newton em Cambridge nos anos em que se escreviam os <i>Principia</i>, contou em cartas a John Conduitt, depois da morte do mestre, como era vê-lo trabalhar. Newton esquecia as refeições, e o prato voltava quase intocado. Às vezes, dando uma volta ou duas no jardim, parava de repente, virava-se, subia correndo a escada e se punha a escrever de pé à escrivaninha, sem se dar o tempo de puxar uma cadeira. São sinais vistos de fora, e servem para você de dentro: a hora que surpreende, a refeição que passou sem ser notada, a pergunta <i>quanto falta?</i> que deixou de aparecer. Newton não é modelo de duração, e a hora de parar que você escreve de manhã existe para que o estado, quando vier, não cobre do corpo o que o corpo não tem.", PI)
add("Os sinais de que o estado se esgotou são os da quinta linha: você já se levantou por dentro, ou volta ao mesmo trecho sem mudar nada. A eles se junta um que Weil ensina a ver. A atenção virou força: a testa franzida, a respiração presa, os dentes cerrados, e você atento a nada. Quando um desses sinais aparece, o bloco termina no fim do passo em que você está, com a pergunta da quinta linha respondida por escrito, e não se arrasta até a hora marcada à espera de que o estado volte.", PI)
add("<i>A volta.</i> Toda sessão é interrompida, por alguém ou por você mesmo. Quando quem sai é você, a terceira linha basta: <i>saí</i>, <i>onde eu estava?</i>, e de volta à última linha escrita. Quando é alguém que chama, e há um minuto antes de atender, escreva na folha de captura, numa linha, onde você parou e qual é o próximo movimento. Em 2018, Sophie Leroy e Theresa Glomb publicaram experimentos em que pessoas trabalhavam numa tarefa com prazo e eram interrompidas por outra. Quem largava a primeira sem mais nada levava para a segunda um resíduo de atenção, continuava pensando no que deixara, e se saía pior. Quem gastava antes um minuto anotando onde estava e o que faltava levava menos resíduo e se saía melhor. O estudo foi feito em laboratório, com tarefas curtas, e mediu o efeito sobre a tarefa que interrompia, não sobre a volta à primeira; essa outra razão o livro acrescenta por conta própria. A linha escrita é a entrada da volta, como a resposta da quinta linha é a entrada da manhã seguinte, e como era, para Hemingway, parar sabendo o que vinha depois.", PI)
add("Ao voltar, você não refaz a entrada inteira. Lê a linha deixada, diz a frase e faz o primeiro movimento que a linha manda. Se o estado tinha vindo antes da interrupção, ele não volta porque você voltou; o bloco segue mesmo assim, e o que ele dá é obra.", PI)
add("Três sessões da mulher de <i>Do primeiro dia</i>, das semanas em que ela estudava o segundo capítulo do programa, mostram os três tempos no uso. Numa terça, às oito e meia, ela se sentou à mesa da sala, levou o telefone para o quarto e pôs a folha de captura ao lado do livro. Perguntou o que ele faria agora, e a resposta foi a parte dos recursos, que ela vinha adiando havia dois dias. Escreveu a primeira linha: <i>quando eu me levantar, os recursos numa página; primeiro movimento, reler o artigo.</i> Marcou trinta e cinco minutos e começou. Nos primeiros dez, a cabeça foi duas vezes ao escritório, e as duas pendências foram para a folha, uma linha cada. Uma delas era urgente de verdade, um e-mail que ela esquecera de mandar; ficou na folha assim mesmo, e foi mandado às dez, depois da mesa em ordem. Depois disso não houve mais nada a anotar. Quando o bloco terminou, ela estava no meio de um parágrafo e não tinha olhado o relógio desde o começo. Acabou o parágrafo, que era o passo em que estava, escreveu a resposta da quinta linha e marcou o segundo bloco igual ao primeiro. Só às quinze para as dez, ao pôr a mesa em ordem, reparou no que tinha havido, pelos sinais de fora: a xícara de chá cheia e fria, a pergunta <i>quanto falta?</i> que não tinha vindo nenhuma vez. A marca da noite mediu o gesto da vez, como em todas as noites, e o estado não entrou nela.", PI)
add("Na quinta da mesma semana, nada disso se repetiu. Ela tinha dormido mal, e o capítulo chegara às nulidades, que ela não entendia. Fez a entrada do mesmo modo e na mesma sequência, porque o ritual não depende do humor: a mesa limpa, a folha ao lado, a pergunta, a primeira linha, a frase. Em vinte minutos leu a mesma página três vezes, e a pergunta <i>quanto falta?</i> voltava a cada poucos minutos. Veio também a vontade de trocar as nulidades pelos recursos, que tinham corrido tão bem na terça; foi para a folha de captura, numa linha, porque os recursos não eram <i>isto</i>. Ela não esperou sentir que tinha entrado. Voltar ao mesmo trecho sem mudar nada era o sinal da quinta linha, e o bloco terminou no fim daquele passo, sem se arrastar até a hora marcada. Então ela disse a quarta linha e respondeu por escrito: o que exatamente não sabia era a diferença entre as duas espécies de nulidade, e a menor parte que podia fazer agora era um quadro de duas colunas. O segundo bloco foi o quadro, feito devagar e sem gosto. À noite, a linha do dia disse <i>quadro das nulidades, pela metade</i>, e a marca foi traço, porque na sessão que mais pesou ela tinha feito o gesto. Na sessão seguinte, o quadro estava sobre a mesa, e foi por ele que ela começou.", PI)
add("Num sábado de manhã, uma hora depois de começar, ela estava no estado da terça quando o telefone tocou: era a irmã. Deixou tocar enquanto escrevia na folha de captura uma linha só, <i>parei no terceiro requisito; próximo, o exemplo da página 84</i>, e atendeu. A conversa durou quase meia hora. A irmã precisava de ajuda com uma mudança, e não era coisa de deixar para depois. Quando ela voltou, a cabeça ainda estava na irmã, e a vontade era recomeçar o capítulo do princípio, para ter certeza, ou pelo menos reler tudo o que fizera de manhã. Não refez a entrada. Leu a linha deixada, disse a frase e abriu a página 84. O estado não voltou com ela, e os primeiros minutos foram de leitura sem gosto. O bloco seguiu assim mesmo até o fim marcado. Perto do fim, ela se pegou olhando a janela sem saber havia quanto tempo; disse <i>saí</i>, perguntou-se onde estava e voltou à última linha escrita. Ao meio-dia, o terceiro requisito estava entendido e o exemplo, resumido em quatro linhas, que era o que aquela manhã tinha para dar. Antes de se levantar, respondeu à quinta linha: estava quase, faltavam o quarto e o quinto requisitos, e a primeira coisa de amanhã seria o quarto. A mesa voltou à ordem, e à noite ela riscou a linha da folha de captura, que já tinha servido.", PI)
add("Das três sessões, só a da terça ela chamaria de boa, e foi a única em que o estado veio. Na folha de marcas as três ficaram iguais, e o capítulo andou nas três; no fim do mês, ao reler as linhas do dia, ela já não sabia dizer quais tinham saído das sessões boas.", PI)
add("Você não sai de uma assentada mestre de nada, e o livro não lhe promete isso. O mestre se faz em anos de obra, e o caminho dele está no Livro III, nas estações. O que a frase pode lhe dar é um começo: uma coisa feita inteira, e depois outra.", PI)
add("A frase fica sabida esta noite: diga-a em voz baixa até sair sem olhar, e veja se sabe o que cada metade pergunta: a primeira, qual é a coisa; a segunda, onde ela acaba.", PI); fleur()
# O fecho vai junto do parágrafo anterior, para não ficar sozinho numa página.
st[-3:] = [KeepTogether(st[-3:])]
