# ===================== DA TÉCNICA =====================
st.append(PageBreak()); sp(30)
add("À mão, a qualquer hora", LIV)
QUANDO["Da técnica"] = "inteiro numa noite; depois, no instante que pedir"
add("Da técnica", LT); sumario(st[-1], 0, "Da técnica")
add("<i>“Faça da postura de combate a postura de todos os dias, e da postura de todos os dias a postura de combate.”</i>", ParagraphStyle('tc1', parent=PC, fontSize=12, spaceAfter=2))
add("Miyamoto Musashi, <i>O livro dos cinco anéis</i>, Livro da Água (tradução livre)", ParagraphStyle('tc2', parent=EPA, spaceAfter=20))
SEC_NO_SUMARIO = True

# O EBG-B.ttf sai com o peso regular, então o rótulo se distingue em maiúsculas menores.
def tec(nome, texto, faca, pratica=None, primeiro=False):
    marca = " <i>(primeiro gesto)</i>" if primeiro else ""
    add(f"<font size=9.5>{nome.upper()}</font>{marca} {texto} <i>Faça assim:</i> {faca}", PI)
    if pratica:
        add(f"<i>Na prática.</i> {pratica}", PI)

sec("Da técnica")
add("Este capítulo você lê uma vez inteiro, numa noite, para aprender os gestos. Depois volta a ele pelo sumário só para recuperar o gesto quando um momento pedir: antes de entrar numa sala, no meio da obra, quando a raiva sobe, quando a cabeça trava. Cada seção é um desses momentos, e cada gesto vem de alguém que viveu o momento antes de você e deixou dito ou escrito o que fazia.", PI)
add("Em <i>Da máscara</i> você aprendeu a perguntar <i>O que ele faria agora?</i> Às vezes a resposta não vem, porque você não sabe o que ele faria naquele instante preciso, diante do medo, da dor ou da página em branco. Este capítulo responde por alguns deles. Kant, Demóstenes, Marco Aurélio, César, Curie, Feynman e os outros que aparecem aqui são máscaras de bolso. Você não precisa se sentir como nenhum deles; precisa só executar o gesto que cada um deixou.", PI)
add("Cada gesto tem duas camadas. A primeira, depois de <i>Faça assim</i>, é curta e serve para o instante. A segunda, que começa por <i>Na prática</i>, aparece nos gestos que pedem método: diz quando usar, como fazer, como saber se funcionou e o que fazer quando falha. A segunda camada se lê nesta noite, com calma, para que no instante baste a primeira.", PI)
add("Três regras valem para todos. A primeira é um gesto por vez, e esse gesto já escolhido: cada seção abre pelo seu primeiro gesto, e é esse que você usa, sem consultar o resto. Os outros ficam de reserva, para o dia em que o primeiro falhar duas vezes no mesmo tipo de momento. A segunda é que o gesto serve à obra: feito o gesto, a frase de <i>Da assentada</i> volta, <i>Isto, até acabar</i>, e você volta ao que estava fazendo. A terceira é que o livro diz o que se sabe de cada gesto. Onde a história é lenda ou só atribuída, isso vem dito. Onde um estudo vem citado, ele sustenta o princípio do gesto, quase nunca o gesto exato como está aqui; quando o estudo testou o gesto mesmo, ou quando caiu, isso também vem dito.", PI)
add("A chave é esta. Ela basta para escolher; o resto do capítulo ensina a fazer.", PI)
CHAVE = [
    ("Você percebe o que está fazendo da sua vida", "James: um ato físico em menos de um minuto"),
    ("A cabeça está cheia demais", "Os contêineres: a pendência na folha, o pensamento na esteira"),
    ("Você evita começar", "Hemingway: uma frase verdadeira"),
    ("Você se dispersa no meio", "A cavilha: a próxima tarefa mínima"),
    ("Você está confuso", "Feynman: o que eu não sei"),
    ("Você tem de falar ou executar diante de alguém", "Douglass: três frases de cor"),
    ("O medo do ridículo segura você", "Diógenes: um pedido por dia que pode ser negado"),
    ("O corpo treme antes", "O suspiro duplo"),
    ("A raiva sobe", "Sentar antes de responder"),
    ("Você está travado entre opções", "A moeda; se a decisão é grande, Franklin"),
    ("O cansaço bate no meio da obra", "Vinte minutos até um ponto visível"),
    ("A tentação já está na mão", "Alexandre: descartar à vista"),
    ("O desconforto escolhido aperta", "Ou acaba, ou eu aguento"),
    ("Chega um golpe", "Uma pergunta só, e a coroa de volta"),
    ("O perigo físico já chegou", "Meu, e a ordem de Sullenberger"),
    ("Você precisa decorar", "Por partes, recitar antes de olhar, e a noite no meio"),
]
CH_A = ParagraphStyle('cha', parent=CX, fontSize=10, leading=13)
CH_B = ParagraphStyle('chb', parent=CH_A, fontName='G-I')
t = Table([[Paragraph(a, CH_A), Paragraph(b, CH_B)] for a, b in CHAVE], colWidths=[(W-2*M)*0.48, (W-2*M)*0.52])
t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'), ('LINEBELOW',(0,0),(-1,-2),0.3,GRAY),
                       ('LEFTPADDING',(0,0),(-1,-1),2), ('RIGHTPADDING',(0,0),(-1,-1),6),
                       ('TOPPADDING',(0,0),(-1,-1),3), ('BOTTOMPADDING',(0,0),(-1,-1),3)]))
st.append(KeepTogether([st.pop(), Spacer(1, 4), t, Spacer(1, 12)]))

sec("No instante em que você percebe")
add("Este é o momento mais importante do capítulo, e talvez do livro. Ele chega sem aviso: no sinal vermelho, no banho, às duas da manhã, no meio de uma conversa à toa. De repente você vê, com uma nitidez que não pediu, o que está fazendo da sua vida. O livro inteiro começou num momento assim, a noite em que você o abriu. O problema é que quase sempre esse momento passa sem ato. A lucidez vem, dói um pouco, e no dia seguinte a vida continua igual. Os gestos desta seção servem para que a lucidez, quando vier, deixe uma marca no mundo antes de ir embora.", PI)
tec("James e o brilho que evapora.", "No capítulo sobre o hábito dos <i>Princípios de psicologia</i>, William James escreveu que cada vez que uma resolução ou um belo impulso de sentimento evapora sem dar fruto prático, isso é pior do que uma chance perdida: atrapalha as resoluções e os impulsos seguintes de chegarem ao ato. Daí vem a máxima dele que o Interlúdio retoma, agarrar a primeira ocasião possível, e a razão dela é esta: a lucidez que não vira ato ensina você a ter lucidez sem agir, e a próxima chega mais fraca.",
    "em menos de um minuto, faça um ato físico pequeno na direção do que você viu, antes que se forme a segunda frase interior.",
    "Ato é o que muda um pouco o mundo e pode ser visto amanhã: escrever a primeira linha, mandar a mensagem, apagar o aplicativo, calçar o tênis, pôr o livro em cima da mesa, marcar a hora na agenda. Não contam pensar melhor no assunto, fazer um plano, contar a alguém, comprar alguma coisa ou prometer. Se o que você viu é a vida inteira, o ato é o menor pedaço da resposta que cabe neste minuto: se é o corpo, dez agachamentos agora; se é a obra, abrir o arquivo e escrever uma linha; se é uma pessoa, a mensagem agora. Se não dá para agir, porque são duas da manhã, porque você está dirigindo, porque está numa reunião, escreva em papel uma linha com a data, o que viu e o primeiro ato de amanhã, com a hora; nesse caso a linha é o ato. À noite, ela vai para a folha de captura. Você sabe que funcionou quando, no dia seguinte, o ato existe e pode ser visto. Se a lucidez passou sem ato, não se acuse: escreva agora o ato padrão para a próxima vez, <i>quando eu perceber, eu ___</i>, para que da próxima vez não seja preciso decidir.",
    primeiro=True)
tec("Horácio e o rio.", "O verso no alto do Livro I vem de uma carta de Horácio, e logo depois dele vem a imagem do camponês que espera o rio terminar de passar para atravessá-lo; o rio corre, e vai correr para sempre.",
    "quando se pegar dizendo <i>depois desta fase</i>, <i>depois das férias</i>, <i>na segunda-feira</i>, diga por dentro: <i>o rio não passa</i>. E atravesse agora, com o ato de James.")
tec("Nansen e a costa sem volta.", "Em <i>A primeira travessia da Groenlândia</i>, Fridtjof Nansen conta por que, em 1888, cruzou o gelo a partir da costa leste, deserta, rumo às aldeias do oeste: quem saía do oeste podia voltar para o conforto. Na costa leste, não haveria recuo. A ordem, escreveu, era a morte ou a costa oeste.",
    "pergunte <i>o que me deixa voltar atrás?</i> e faça o ato de James que corta essa volta: a mensagem enviada, o valor pago, o aviso dado a quem vai cobrar.")
tec("Pascal e o papel no casaco.", "Na noite de 23 de novembro de 1654, das dez e meia até perto da meia-noite e meia, Pascal viveu algo que anotou num papel, com a data e a hora, começando por uma palavra só: <i>Fogo</i>. Costurou o papel no forro do casaco e o passava de casaco em casaco. Ninguém soube dele até que um criado o encontrou, depois da morte de Pascal.",
    "quando a lucidez vier, escreva-a numa linha, com a data, a hora e as palavras que vierem, e leve-a com você, na carteira ou na capa do celular. Releia na próxima vez que a vida antiga puxar. Agostinho, no jardim de Milão que o Livro IV conta, passou anos lúcido e dizendo <i>amanhã</i>; o que mudou naquela tarde foi que ele agiu no mesmo minuto.")

sec("Para limpar a mente")
add("Esta seção é outra coisa. Aqui você não quer resolver nada nem entender nada. A cabeça está cheia, barulhenta, com dez coisas rodando ao mesmo tempo, e você quer limpá-la por limpar, virar o jogo, recomeçar do zero no meio do dia.", PI)
tec("Os contêineres.", "Este gesto junta um achado de laboratório e um exercício da clínica. Tudo o que roda na cabeça é de dois tipos: pendência, que é algo a fazer, e pensamento, que é algo que só passa. A pendência some quando ganha um plano escrito; Masicampo e Baumeister (2011) viram isso, e é por isso que o livro tem a folha de captura. O pensamento some quando você para de lutar com ele e o deixa passar, que é o exercício das folhas no rio da terapia de aceitação e compromisso (Hayes e colegas, 1999).",
    "pegue uma folha. Cada pendência vira um contêiner: uma linha, com o verbo e o destino. Cada pensamento que não é pendência vai num contêiner numa esteira que passa diante de você: veja-o entrar, diga o nome dele, e deixe a esteira levá-lo.",
    "Faça primeiro as pendências, todas, até a cabeça não ter mais nada para lembrar: <i>pagar a conta: amanhã, nove horas</i>; <i>responder o João: hoje, depois do almoço</i>. Se você não sabe quando vai fazer, o destino é decidir: <i>decidir quando: sexta à noite</i>. Depois feche os olhos para a esteira, de três a cinco minutos. Os contêineres passam da esquerda para a direita; cada pensamento que vier, <i>e se eu não der conta</i>, <i>o que ele quis dizer</i>, entra num deles com o nome escrito do lado, e vai embora. Não empurre a esteira nem segure o contêiner. Se o mesmo pensamento voltar, ponha-o em outro contêiner; voltar é normal. Você sabe que funcionou quando a esteira fica vazia por alguns segundos e você percebe o silêncio. Se um pensamento volta o tempo todo, ele provavelmente é uma pendência disfarçada: abra os olhos e escreva-o na folha, com destino.",
    primeiro=True)
tec("Marco Aurélio e o retiro.", "Marco Aurélio anotou que as pessoas procuram retiros no campo, na praia, nas montanhas, quando podem, a qualquer hora, se retirar em si mesmas. Dê-se sempre esse retiro, escreveu, e renove-se. Noutras notas ele se dá uma ordem de duas palavras: apague a impressão.",
    "feche os olhos e imagine o que está na cabeça escrito num quadro. Diga por dentro <i>apague</i> e veja o quadro limpo, inteiro. Uma respiração longa. Depois diga uma frase sua, curta, sempre a mesma, a do estribilho se quiser, <i>reivindique-se para si</i>, e abra os olhos.")
tec("Cipião, Lélio e as conchas.", "No <i>Do orador</i>, Cícero conta que Cipião e Lélio, os homens mais sérios da Roma do seu tempo, quando conseguiam fugir da cidade para o campo, viravam meninos de um jeito incrível, e ficavam catando conchas e pedrinhas na praia.",
    "vire o jogo com uma coisa de outro registro, curta, com as mãos e sem tela: lavar a louça devagar, arrumar uma gaveta, regar as plantas, andar descalço. Dez minutos, e volte.")
tec("Churchill e a pintura.", "Em 1915, depois do desastre de Galípoli e da saída do Almirantado, Churchill começou a pintar. No ensaio <i>A pintura como passatempo</i>, explicou que as partes cansadas da mente não descansam com o nada; descansam quando se usam outras partes. A mudança, escreveu, é a chave mestra.",
    "quando a cabeça estiver gasta por um assunto, não se deite com o celular. Faça algo que use outra parte de você: as mãos, o corpo, a cor, o som. Quanto mais longe do assunto, melhor.")

sec("Para começar")
tec("Hemingway e a frase verdadeira.", "Em <i>Paris é uma festa</i>, Hemingway conta que, quando uma história não começava, dizia a si mesmo: basta escrever uma frase verdadeira; escreva a frase mais verdadeira que você sabe. Escrita essa, seguia dali.",
    "diante da página em branco, não procure o começo. Escreva uma única frase que você sabe ser verdadeira sobre o assunto, sem adjetivo. A seguinte sai dela.",
    "Use quando você está diante da obra há mais de um minuto sem começar. A frase verdadeira é uma frase que você não precisa inventar: algo que viu, sabe ou mediu. Num relatório, <i>as vendas caíram doze por cento em março</i>; num código, <i>a função recebe uma lista e devolve o maior valor</i>; numa carta, <i>faz dois anos que não falamos</i>. Se a frase sair ruim, ela já cumpriu a função, porque a mão está andando; você a corrige no fim, com o resto. Se a segunda não vier, escreva outra frase verdadeira sobre o mesmo assunto, e depois outra; três ou quatro costumam dar o esqueleto do primeiro parágrafo. Você sabe que funcionou quando está na quinta frase sem ter decidido começar. Se nem a primeira vem, o problema não está na página: você não sabe ainda o que pensa, e o gesto certo é o de Feynman, mais abaixo.",
    primeiro=True)
tec("Plínio e as janelas fechadas.", "Plínio, o Jovem, conta numa carta que, no verão, acordava e deixava as janelas fechadas. No escuro e no silêncio, longe do que distrai, compunha de cabeça, palavra por palavra, como quem escreve e corrige. Só depois deixava entrar a luz e chamava o secretário para ditar. Os olhos, diz ele, seguiam a mente, porque não tinham outra coisa para ver.",
    "antes de abrir qualquer tela, feche os olhos e componha de cabeça a primeira frase ou o primeiro passo, até ele estar pronto. Só então acenda a luz e escreva.")
tec("Demóstenes e a cabeça raspada.", "Plutarco conta que Demóstenes construiu um estúdio debaixo da terra para treinar a voz e descia lá todos os dias, às vezes por dois ou três meses seguidos. Raspava metade da cabeça, para que a vergonha o impedisse de sair, mesmo que quisesse.",
    "antes do bloco, ponha um custo de vergonha na saída. Diga a alguém que você só responde depois de certa hora, ou entregue o celular a outra pessoa. A porta continua aberta; o que muda é que sair por ela passa a custar.")

sec("Para não sair da obra")
tec("A cavilha do carpinteiro.", "Um sermão do cânone budista, atribuído ao Buda, ensina ao monge o que fazer quando um pensamento o tira do objeto. O primeiro recurso é trocar o pensamento por outro, como o carpinteiro que faz sair uma cavilha grossa batendo nela com uma fina. Os outros recursos vêm depois, em força crescente, e o último, cerrar os dentes e dominar a mente com a mente, fica em último de propósito.",
    "quando um pensamento puxar você para fora, não tente expulsá-lo no vazio. Ponha no lugar dele uma tarefa mínima da obra, a próxima frase, o próximo número. Wegner e colegas (1987) viram que tentar não pensar numa coisa faz a coisa voltar, e que ter à mão um pensamento substituto diminui essa volta.",
    "A tarefa mínima tem de estar pronta antes que o pensamento chegue; se você precisar procurá-la, já saiu. Por isso, ao fim de cada passo da obra, deixe escrito qual é o próximo, em menos de dez palavras: <i>reescrever a segunda frase</i>, <i>somar a coluna C</i>, <i>testar a lista vazia</i>. Quando o pensamento puxar, volte os olhos para essa linha e faça só ela. Se o pensamento é uma pendência real, <i>tenho de pagar a conta</i>, escreva-o em meia linha na folha de captura antes de voltar; escrito, ele para de bater. Você sabe que funcionou quando, minutos depois, percebe que esqueceu o pensamento. Se ele voltar três vezes no mesmo bloco, passe ao recurso seguinte do sermão, olhar o dano, e diga por dentro o que ele já custou: <i>este pensamento me levou o último quarto de hora</i>.",
    primeiro=True)
tec("Helmholtz e as perguntas novas.", "Helmholtz, estudando a visão, percebeu que não conseguia manter a atenção num objeto por força de vontade. Conseguia quando se fazia perguntas novas sobre ele. William James, que conta isso, tirou daí uma regra: ninguém consegue prestar atenção contínua a um objeto que não muda.",
    "quando sentir que a atenção vai escorregar do trecho, faça a ele uma pergunta nova e concreta, e trabalhe só até respondê-la.",
    "Primeiro, aponte o objeto exato: esta frase, este parágrafo, esta linha do cálculo, e não o capítulo inteiro. Depois faça uma pergunta cuja resposta esteja no próprio objeto e possa ser conferida nele: <i>de onde veio este número?</i>, <i>que palavra desta frase eu cortaria?</i>, <i>este parágrafo prova o que o título promete?</i> Trabalhe só até responder, e então faça a próxima. Se não souber o que perguntar, escreva três coisas numa linha cada: o que você está vendo, o que já sabe sobre isso e o que não consegue explicar. A pergunta nasce da distância entre a segunda linha e a terceira. Você sabe que funcionou quando o trecho começa a mudar diante de você, porque passou a vê-lo em partes.")
tec("Kant e a torre.", "Nos últimos anos em Königsberg, Kant pensava de pé junto à estufa, no fim da tarde, com o olhar pousado na torre de Löbenicht, que via pela janela. O amigo Wasianski, que conviveu com ele todos os dias, conta que, quando os choupos do vizinho cresceram e esconderam a torre, Kant ficou inquieto e perturbado no pensar, até que o vizinho mandou podá-los.",
    "quando for pensar sem escrever, escolha um ponto distante e parado, uma árvore, uma antena, a quina de um prédio, e deixe o olho descansar ali enquanto a cabeça trabalha. Não pense olhando para uma tela que se mexe. Glenberg e colegas (1998) viram que desviar o olhar ajuda a responder perguntas difíceis; o estudo vai na mesma direção, embora não teste o gesto de Kant.")

tec("Clausewitz e o atrito.", "No primeiro livro de <i>Da guerra</i>, Clausewitz escreve que na guerra tudo é muito simples, mas o mais simples é difícil. As pequenas dificuldades se somam, e agir na guerra é como andar dentro da água: o passo mais natural custa. Ele chama isso de atrito, e diz que só há um lubrificante para ele, o costume.",
    "antes de sentar para a obra, pergunte <i>o que vai emperrar nos primeiros cinco minutos?</i> e tire uma coisa do caminho: o arquivo já aberto, o carregador na tomada, a senha à mão, o material sobre a mesa. Quando emperrar mesmo assim, não leia o atrito como sinal de que o dia está errado; ele é o meio, e cada dia feito apesar dele é o costume que Clausewitz prescreve.")

sec("Para pensar com clareza")
tec("Feynman e o que ele não sabia.", "James Gleick conta que Feynman, estudante em Princeton, antes dos exames orais abriu um caderno com o título <i>Caderno das coisas que eu não sei</i>, e passou semanas desmontando cada ramo da física à procura das próprias falhas.",
    "abra uma página com o título <i>O que eu não sei sobre isto</i>. Escreva uma lacuna por linha, como pergunta que tem resposta. Comece pela que sustenta as outras.",
    "Imagine que você não consegue escrever uma busca binária. <i>Não entendo busca binária</i> é vago demais para servir. Escreva as lacunas como perguntas: não sei por que posso descartar metade da lista a cada comparação; não sei quando o laço deve parar; não sei o que acontece se o número não estiver na lista; não sei por que o tempo cresce tão devagar. Depois tente responder a cada uma em voz alta, sem olhar a solução. A que você não consegue nem começar a responder, e da qual as outras dependem, é a que destrava o resto. Aqui é a primeira: a regra de parada, o caso do número ausente e a velocidade dependem de entender por que metade pode ser jogada fora. Para separar o que você não sabe do que só esqueceu, olhe a resposta de cada lacuna por dez segundos e feche: se ela volta inteira, era esquecimento, e basta revisar; se continua opaca, era ignorância, e é essa que você estuda. Rozenblit e Keil (2002) mostraram que as pessoas acham que entendem um mecanismo até tentarem explicá-lo passo a passo; a página é o lugar onde essa ilusão se desfaz. Você sabe que funcionou quando consegue explicar a primeira lacuna em voz alta e as outras começam a parecer pequenas.",
    primeiro=True)
tec("Pólya de trás para frente.", "Pólya, em <i>A arte de resolver problemas</i>, ensina a olhar para a incógnita e a trabalhar de trás para frente: partir do que se quer obter e perguntar de onde isso poderia sair, até chegar ao que já se tem. O problema menor e parente, do mesmo Pólya, está na linha do impasse.",
    "escreva no pé da página o que tem de existir no fim: o número, a frase, a decisão. Acima dela, escreva o que teria de ser verdade logo antes. Suba assim, linha por linha, até encostar em algo que você já tem.")
tec("Einstein e o raio de luz.", "Einstein conta, nas notas autobiográficas que escreveu aos sessenta e sete anos, que aos dezesseis se imaginou correndo atrás de um raio de luz na mesma velocidade dele, e que o paradoxo dessa cena o acompanhou por dez anos, até a relatividade.",
    "entre no problema como alguém que está dentro da cena e pergunte: <i>o que eu veria se estivesse ali?</i> Leve a cena ao extremo: mais rápido, maior, zero. Onde ela ficar absurda, está a contradição que trava o problema.")
tec("Feynman e os doze problemas.", "O matemático Gian-Carlo Rota conta que Feynman mantinha sempre na cabeça uma dúzia de problemas favoritos em aberto e, cada vez que aprendia um truque novo, o testava contra cada um deles.",
    "escreva o problema travado numa linha e deixe-o à vista. Quando ler ou ouvir algo novo hoje, pergunte: <i>isto serve para aquele problema?</i>")
tec("Nietzsche andando.", "Flaubert dizia que só se pensa e escreve sentado. Nietzsche respondeu no <i>Crepúsculo dos ídolos</i> que ficar sentado é justamente o pecado contra o Espírito Santo, e que só os pensamentos que vêm andando têm valor.",
    "com o problema escrito numa linha, levante-se e ande dez ou quinze minutos, levando papel só para anotar. Ao voltar, sente-se e examine o que trouxe. Oppezzo e Schwartz (2014) viram que andar aumenta o número de ideias novas e não ajuda nas tarefas de resposta única. Anda-se para abrir caminhos e senta-se para escolher entre eles; cada um dos dois tinha razão na sua metade.")
tec("Dalí e a chave.", "Dalí ensinava a cochilar na poltrona segurando uma chave pesada sobre um prato virado no chão. Ao adormecer, a mão soltava a chave, o barulho o acordava, e ele aproveitava o que estava na cabeça naquele instante. A versão de Edison com bolas de aço é lenda.",
    "só depois de ter trabalhado no problema, sente-se reclinado, de olhos fechados, segurando um objeto leve sobre o chão duro. Quando ele cair, anote na hora o que estava na cabeça. Lacaux e colegas (2021) viram que quem passou alguns segundos no primeiro estágio do sono teve cerca de três vezes mais chance de descobrir a regra oculta de um problema, e que quem dormiu mais fundo perdeu o efeito. É um estudo só.")

tec("Lichtenberg e o caderno de rascunho.", "Lichtenberg, físico de Göttingen, tomou dos comerciantes ingleses um costume de contabilidade: o <i>waste book</i>, o livro onde se anota tudo o que se compra e vende, no dia, do jeito que vier, antes de passar a limpo para os livros de conta. Fez dele os seus <i>Sudelbücher</i>, os cadernos de rascunho, onde por mais de trinta anos pôs cada ideia no minuto em que ela vinha.",
    "não pense a limpo. Quando uma ideia vier, anote-a no ato, crua, numa linha, sem decidir ainda se presta. À noite, passe a limpo só o que sobreviveu, para o caderno ou para a obra. É a folha de captura, com mais um degrau: o rascunho é sujo por regra, e o juízo vem depois.")

sec("Para entrar e falar")
tec("Douglass em Nantucket.", "Em agosto de 1841, numa convenção em Nantucket, Frederick Douglass, que tinha fugido da escravidão três anos antes, foi chamado a falar a uma plateia de brancos. Ele conta que tremia em todos os membros e mal conseguia ficar de pé. Falou só alguns instantes, escreveu depois, e sentiu certo grau de liberdade, e disse o que queria com bastante facilidade.",
    "não espere a confiança para começar, porque ela chega depois das primeiras frases. Saiba as três primeiras de cor, para que a boca as diga enquanto o corpo ainda treme.",
    "Escreva as três frases na véspera, curtas, do jeito que você fala, e não do jeito que escreve. Decore-as recitando sem olhar: diga, confira, diga de novo, até saírem duas vezes seguidas sem erro. Depois ensaie com algum desconforto, de pé, depois de subir uma escada, com alguém olhando ou com o celular gravando, porque é assim que elas vão ter de sair. No dia, diga-as uma vez no caminho, sem papel. Você sabe que funcionou quando a terceira frase sai e você percebe que já está falando. Se travar no meio de uma delas, não volte ao começo: diga a próxima. Ninguém na sala conhece as frases; só você sabe que pulou uma.",
    primeiro=True)
tec("César e o Rubicão.", "Suetônio conta, na <i>Vida dos doze Césares</i>, que em janeiro de 49 a.C., à beira do Rubicão, Júlio César parou e hesitou: ainda podemos voltar, disse aos que estavam com ele; passada esta pequena ponte, tudo terá de ser decidido pelas armas. Depois atravessou, dizendo que a sorte estava lançada.",
    "com a mão na maçaneta, diga por dentro: <i>a sorte está lançada</i>. O ensaio acabou, e do outro lado da porta não há volta. Entre.")
tec("Demóstenes e o espelho.", "Plutarco conta, citando alguém que ouviu o próprio Demóstenes já velho, que ele corrigia a dicção falando com pedrinhas na boca, treinava a voz correndo ladeira acima e ensaiava em casa diante de um grande espelho. Cícero e Quintiliano acrescentam que declamava na praia, contra o barulho das ondas.",
    "a confiança do instante se faz na véspera. Ensaie a abertura em voz alta e de pé, com barulho em volta ou com o coração acelerado. Na hora, basta lembrar: <i>já falei por cima de coisa pior</i>.")
tec("Nicklaus e o cinema.", "O golfista Jack Nicklaus chamou de <i>ir ao cinema</i> o que fazia antes de cada tacada: primeiro via a bola parada onde queria que ela terminasse, depois o voo dela até lá, e só então o próprio movimento.",
    "um minuto antes, feche os olhos e veja a cena de trás para frente: o fim que você quer, o momento difícil, a sua primeira frase dita no tom certo.",
    "Quem nunca fez isso costuma ver um filme borrado e desistir. Comece por uma imagem só, parada: o lugar onde você vai estar quando tudo tiver dado certo, a sala, a folha entregue, a porta se fechando atrás de você. Depois acrescente o momento mais difícil, visto de dentro, com o que vai ouvir e o que vai responder. Por último, ouça a sua primeira frase no tom que você quer. Se a imagem fugir, abra os olhos, diga a frase em voz baixa e feche-os de novo. Um minuto basta; mais que isso vira devaneio. Veja a execução, e não o prêmio: Oettingen mostrou que fantasiar só o sucesso tira a força.")
tec("Xenofonte e Ali.", "Xenofonte, na <i>Anábase</i>, levantou um exército desanimado lembrando aos soldados que aquele inimigo já tinha sido vencido. Cassius Clay gravou um disco chamado <i>Eu sou o maior</i> seis meses antes de tomar o título de Sonny Liston.",
    "antes de entrar, leia duas linhas escritas por você sobre uma vez real em que venceu uma situação parecida, e diga em voz alta uma frase curta sobre a tarefa: <i>eu fecho este acordo</i>. Faça a frase falar da tarefa, nunca do seu valor: Wood e colegas (2009) viram que repetir frases sobre o próprio valor piorou o humor justamente de quem tinha a autoestima baixa.")
tec("O que caiu.", "A postura de poder, os dois minutos de pé com as mãos na cintura antes de uma entrevista, ficou famosa com um estudo de 2010 que dizia que ela mudava os hormônios e a disposição ao risco. As réplicas não encontraram nada disso, e a primeira autora do estudo disse em 2016 que não acredita mais no efeito.",
    "não gaste com ela o minuto antes da porta.")

sec("Para atravessar o ridículo")
add("O medo do ridículo é dos que mais seguram a mão. Ele chega antes de qualquer coisa nova feita diante dos outros: a primeira aula, o primeiro texto publicado, o primeiro treino numa academia cheia, a pergunta feita em voz alta na reunião. A sensação parece um aviso para parar, e quase sempre ela só mede a falta de costume.", PI)
tec("Diógenes e a estátua.", "Diógenes Laércio conta que Diógenes, o cínico, pedia esmola a uma estátua no meio de Atenas. Quando lhe perguntaram por quê, respondeu que estava se exercitando a ser recusado. Era o mesmo homem que, quando Alexandre parou diante dele e ofereceu o que ele quisesse, pediu só que saísse da frente do seu sol; e Plutarco conta que Alexandre, ao ir embora, disse que, se não fosse Alexandre, seria Diógenes.",
    "treine a recusa antes que ela importe. Faça de propósito, uma vez por dia, um pedido pequeno que pode ser negado, e receba o não sem explicar nem insistir.",
    "O pedido tem de ser real, curto e de custo baixo para os dois lados: um desconto no caixa, uma mesa melhor, cinco minutos de alguém que você admira, uma pergunta a um desconhecido. Ouvido o não, diga <i>obrigado</i> e vá embora; o exercício é esse instante, e não o sim. Anote à noite, na folha de captura, quantos pedidos fez e o que sentiu, de zero a dez, antes de cada um. Você sabe que funcionou quando o número cai de uma semana para outra. Se ficar no mesmo lugar, os pedidos estão pequenos demais ou parecidos demais entre si: aumente um degrau.",
    primeiro=True)
tec("Catão e os pés descalços.", "Plutarco conta, na <i>Vida de Catão, o Jovem</i>, que Catão, quando a moda em Roma era a púrpura viva, vestia de propósito a escura, e muitas vezes saía à rua depois da refeição sem sapatos e sem túnica. Não buscava fama com a extravagância, diz Plutarco: acostumava-se a ter vergonha só do que é de fato vergonhoso, e a desprezar a má opinião dos outros sobre o resto.",
    "uma vez por semana, escolha uma dose pequena de ridículo sem dano a ninguém e fique nela um minuto inteiro, sem se explicar. O que se treina é ficar, e não sair rindo de si mesmo para aliviar. As terapias de exposição para a ansiedade social se apoiam no mesmo princípio.")
tec("O ridículo que informa.", "Às vezes os outros riem porque você está errado. O Livro V separa a resistência que se atravessa da que informa, e o ridículo tem as mesmas duas faces.",
    "pergunte: <i>eles riem do gesto ou do erro?</i> Se riem de você estar fazendo algo novo, atravesse. Se riem de algo que você de fato fez mal, o riso é uma informação: corrija o erro e volte ao gesto.")

sec("Para tirar o nervosismo")
tec("O suspiro duplo.", "Este gesto não tem padrinho antigo, e vem primeiro porque é o mais direto. Balban e colegas (2023) compararam cinco minutos diários de suspiro com outras respirações e com meditação, e o suspiro foi o que mais melhorou o humor e mais desacelerou a respiração. O estudo é de prática diária; como dose de um minuto antes da fala, a evidência é mais fraca.",
    "duas inspirações pelo nariz, a segunda curta, para encher o resto do pulmão, e uma expiração lenta e longa pela boca, mais longa que as duas inspirações juntas. Duas ou três vezes. Você sabe que pegou o jeito quando os ombros descem na expiração sem que você mande.",
    primeiro=True)
tec("Crasso e o tremor.", "No diálogo <i>Do orador</i>, Cícero põe na boca de Crasso, o maior orador da geração anterior, uma confissão: ele empalidece no começo de cada discurso e treme com todo o espírito e com todos os membros. Na mesma conversa se diz que os melhores oradores são os que mais temem, porque sabem o que está em jogo.",
    "quando o coração disparar na porta, não tente se acalmar. Diga por dentro: <i>é o tremor de Crasso; estou pronto para isto</i>, e comece com o tremor dentro da primeira frase. Brooks (2014) viu que dizer <i>estou animado</i>, em vez de <i>estou calmo</i>, muda o que a pessoa sente; uma réplica de 2025 confirmou a mudança na sensação e não encontrou melhora no desempenho.")
tec("Alexandre e o sono de Gaugamela.", "Plutarco conta que, na noite antes de Gaugamela, a batalha que decidiria o império persa, Alexandre ficou até tarde fazendo os sacrifícios com o adivinho e depois dormiu tão fundo que, de manhã, os generais tiveram de chamá-lo mais de uma vez. Parmênio perguntou como podia dormir como quem já venceu. Alexandre respondeu que já tinham vencido: não precisariam mais correr atrás de Dario por uma terra devastada, porque Dario tinha vindo dar batalha.",
    "na véspera do que deixa você nervoso, decida por escrito tudo o que ainda pode ser decidido: a roupa, a hora, o caminho, a primeira frase. Depois diga por dentro <i>o mais difícil já está feito</i>, e vá dormir. O nervosismo da manhã fica sem nada para mastigar.")
tec("Musashi e o olhar largo.", "Musashi, no <i>Livro dos cinco anéis</i>, manda que o olhar seja largo e amplo, que veja o distante como perto e o perto como distante, e que não se prenda aos movimentos pequenos da espada do adversário. Pede também a testa sem rugas e os ombros baixos.",
    "no medo, o olhar se fecha no ponto da ameaça. Abra-o de propósito: sem mover os olhos, perceba as duas bordas do campo de visão e a sala inteira. Solte a testa e baixe os ombros. Na hora do gesto técnico, fixe o olhar outra vez: largo para esperar, fixo para agir.")
tec("Turenne e a carcaça.", "Conta-se que o marechal Turenne, antes do combate, sentindo o corpo tremer, lhe disse: <i>você treme, carcaça? Tremeria muito mais se soubesse aonde vou levá-la</i>. Não há fonte da época, e a palavra é só atribuída a ele.",
    "trate o corpo que treme como um cavalo assustado, que é seu e vai com você. Dê a ele uma ordem curta, em voz baixa: <i>treme, mas vai</i>.")

sec("Para conter a raiva")
tec("Sentar e deitar.", "Uma tradição registrada por Abu Dawud atribui a Maomé este conselho: quem se irritar de pé, que se sente; se a raiva não passar, que se deite.",
    "de pé, sente-se. Se continuar fervendo, encoste-se para trás. O corpo sai da posição de quem vai partir para cima, e você só fala depois de ter mudado de postura. Se estiver ao telefone ou numa mensagem, a regra é a mesma: nada sai de você antes de o corpo ter mudado de posição. Harmon-Jones e Peterson (2009) viram que, sob insulto, o cérebro de quem estava reclinado não mostrava o padrão de quem se prepara para avançar; o estudo é pequeno e mediu o cérebro, não a conduta.",
    primeiro=True)
tec("Marco Aurélio e o próprio erro.", "Marco Aurélio anotou: quando a falta de alguém o ofender, volte-se logo para si e pense em que você erra de modo parecido; atento a isso, você logo esquecerá a raiva.",
    "sentado, complete por dentro uma frase só: <i>eu também já...</i> Ele me interrompeu; eu também interrompo quando tenho pressa. Responda só depois de completá-la. Mischkowski, Kross e Bushman (2012) viram que quem pensava na provocação de um ponto de vista distanciado ficava menos irritado e menos agressivo.")
tec("Jefferson e o cem.", "Em 1825, Jefferson mandou a um menino que levava o seu nome dez regras para a vida. A última diz: quando zangado, conte até dez antes de falar; se muito zangado, até cem. É o alfabeto de Atenodoro, de <i>Da serenidade</i>, com uma escala.",
    "meça a raiva e dê a ela a espera que ela pede, dez ou cem. Não desabafe para aliviar: Bushman (2002) viu que quem socava um saco pensando no provocador ficava mais agressivo do que quem não fazia nada.")

sec("Para decidir")
tec("A moeda de Piet Hein.", "O dinamarquês Piet Hein, matemático e poeta, deixou num poema curto este conselho: quando você precisar decidir e não tiver decisão nenhuma, jogue uma moeda, não para que o acaso decida, mas porque, no instante em que a moeda está no ar, você de repente sabe o que espera.",
    "dê a cada opção um lado e jogue. No instante em que a moeda cai, repare no alívio ou na decepção, e decida por esse sinal. Se não sentir nada, as duas se equivalem: fique com a da moeda e siga.",
    "Serve para escolhas entre opções parecidas e que têm volta: qual tarefa primeiro, qual de dois caminhos, se aceita o convite. Para uma decisão grande, use a folha de Franklin e guarde a moeda para o fim, para ver se o resultado da folha alivia você. Levitt (2021) acompanhou pessoas que deixaram uma moeda decidir uma mudança grande na vida; as que tiraram <i>mudar</i> mudaram mais e, seis meses depois, diziam-se mais felizes. O próprio autor chama o resultado de sugestivo.",
    primeiro=True)
tec("A álgebra de Franklin.", "Em 1772, Joseph Priestley pediu conselho a Franklin sobre um cargo. Franklin respondeu que não podia dizer o que ele devia decidir, só como. Dividia meia folha em duas colunas, a favor e contra, e ia anotando durante três ou quatro dias, porque as razões não aparecem todas ao mesmo tempo. Depois riscava as que se equivaliam: uma razão a favor que pesasse tanto quanto duas contra saía junto com elas. Chamou isso de álgebra moral.",
    "folha dividida, as razões anotadas ao longo de alguns dias, os pares de mesmo peso riscados. O lado que sobrar decide.",
    "Razões não vêm com peso marcado: <i>salário maior</i> pode valer menos que <i>mais tempo com os filhos</i>, e uma única desvantagem pode valer mais que cinco vantagens. Por isso, antes das colunas, escreva no alto o que importa nesta decisão, três ou quatro critérios no máximo, como dinheiro, tempo, o que você aprende, o risco. Cada razão das colunas tem de tocar um desses critérios; a que não toca nenhum sai. Marque de modo diferente o que é fato, <i>o salário é vinte por cento maior</i>, e o que é preferência, <i>gosto mais da cidade</i>. Junte as razões que são a mesma dita duas vezes. Só então dê a cada uma um peso de um a três e risque os pares de mesmo peso. O método serve para decisões que se pesam. Não serve quando uma condição elimina sozinha uma das opções, como um prazo impossível ou uma regra que não se quebra, e pede uma noite a mais quando a decisão não tem volta. Wilson e colegas (1993) viram que quem listou razões antes de escolher um cartaz ficou menos satisfeito com ele semanas depois: em escolhas de gosto, a lista atrapalha. Se, ao fim, o lado vencedor deixa você aliviado, decida. Se deixa você abatido, o critério que pesa de verdade não está na folha: procure-o e escreva-o.")
tec("Darwin e o quando.", "Em 1838, antes de pedir Emma Wedgwood em casamento, Darwin escreveu numa folha, sob o título <i>Eis a questão</i>, duas colunas: casar e não casar. Embaixo concluiu: casar, casar, casar, como se queria demonstrar. E na mesma folha passou à pergunta seguinte: provado que é preciso casar, quando? Cedo ou tarde?",
    "feche a lista com uma linha que começa por <i>portanto</i>. Logo abaixo, escreva <i>quando</i> e responda com uma data. A decisão que fica sem data volta amanhã para ser decidida de novo.")

sec("Para continuar quando o cansaço bate")
tec("Joe Simpson e os vinte minutos.", "Em 1985, nos Andes peruanos, o alpinista Joe Simpson caiu numa fenda com a perna quebrada e foi dado como morto. Levou três ou quatro dias para se arrastar até o acampamento. Contou depois como: escolhia um ponto, aquela fenda, aquela pedra vermelha, e se dava vinte minutos para chegar lá, de olho no relógio. Quando deixou de olhar o relógio, achava que tinha descansado cinco minutos e tinham passado quarenta e cinco.",
    "quando o peso vier, escolha um ponto visível da obra, o fim desta seção, a página doze, e marque vinte minutos. Ao chegar, escolha o próximo ponto antes de levantar os olhos.",
    "O ponto certo é o que você alcança em vinte minutos trabalhando sem parar, e não o que gostaria de alcançar. Se chega a ele em cinco, o ponto era pequeno demais, e o próximo é maior; se o alarme toca e você ainda está longe, o próximo é menor. Em duas ou três rodadas você acerta o tamanho. Quando o alarme tocar, escolha o próximo ponto antes de qualquer descanso: escolher primeiro é o que impede o descanso de virar saída. O cansaço mente sobre o tempo, e o relógio corrige a mentira. Bandura e Schunk (1981) viram que metas próximas fazem avançar mais do que metas distantes. Se o cansaço for de sono, de noite sem dormir, vinte minutos não o resolvem, e o gesto certo é a hora de parar que você escreveu de manhã.",
    primeiro=True)
tec("Ulisses e o coração.", "Na <i>Odisseia</i>, na véspera da vingança, Ulisses bate no peito e diz ao próprio coração: aguenta, coração; você já aguentou coisa pior. Platão cita o verso como exemplo da razão governando a paixão.",
    "no meio do passo, diga por dentro, com o seu nome: <i>você já atravessou tal coisa; isto é menor</i>. Ponha ali um fato real da sua vida. Depois termine o passo. Blanchfield e colegas (2014) viram que duas semanas de treino em falar consigo para se motivar aumentaram em quase um quinto o tempo que ciclistas aguentavam até a exaustão.")
tec("Shackleton e os cinco minutos.", "Em maio de 1916, Shackleton, Worsley e Crean atravessaram a pé as montanhas da Geórgia do Sul para buscar socorro, cerca de trinta e seis horas sem dormir. Numa parada, Shackleton deixou os dois dormirem e ficou acordado. Depois de cinco minutos, acordou-os dizendo que tinham dormido meia hora, porque, naquele frio, dormir mais seria não acordar.",
    "no meio da obra, dê a si mesmo uma pausa curta com hora para acabar, cinco minutos no relógio, e ao levantar declare que foi o bastante. O que se copia de Shackleton é a regra de parada, a pausa que tem fim marcado. Cinco minutos não recuperam ninguém exausto, e a história dele não prova isso. Ao volante, numa máquina, no mar ou na estrada, o sono que fecha os olhos pede parar de vez.")

sec("Para resistir a um impulso")
tec("Alexandre e o capacete.", "Arriano conta que Alexandre, atravessando com o exército o deserto da Gedrósia, recebeu dos soldados um pouco de água num capacete. Diante de todos, derramou-a no chão sem beber, e cada soldado, diz Arriano, se sentiu como se tivesse bebido aquela água.",
    "quando a tentação já estiver na mão, não a guarde para mais tarde. Jogue fora, devolva, derrame, à vista. Ulisses se amarrava antes; Alexandre fechava a questão no instante, para que ela não ficasse aberta à negociação.",
    primeiro=True)
tec("Mischel e a moldura.", "Nos estudos de Walter Mischel em Stanford, nos anos 1970, crianças diante de uma guloseima esperavam muito mais quando aprendiam a vê-la como se fosse uma foto, com uma moldura em volta, ou a pensar nela pelo que tinha de frio, a forma e a cor, e não pelo gosto.",
    "quando não puder descartar, olhe para o objeto e diga por dentro: <i>é uma foto</i>. Descreva-o como quem faz um inventário: forma, cor, material. As réplicas recentes (Watts e colegas, 2018) derrubaram a ideia de que a espera aos quatro anos prevê o futuro de alguém; a técnica dentro da sala vem dos estudos antigos, feitos com poucas crianças.")

sec("Para aguentar o desconforto")
add("Esta seção é para o desconforto que você escolheu ou já conhece: o frio do banho, o treino, a fome do jejum, a cãibra do esforço, a cadeira depois de três horas. Dor nova, forte ou súbita, dor no peito, falta de ar, dor que piora em repouso, ou qualquer dor depois de uma queda ou de uma pancada é sinal, e o gesto para ela é parar e procurar um médico. Nenhum destes gestos serve para calar um sinal.", PI)
tec("Marco Aurélio e a medida.", "Nos acampamentos do Danúbio, Marco Aurélio anotou sobre a dor: a insuportável nos leva embora; a que dura é suportável.",
    "no pico do frio, da cãibra ou da fome, diga: <i>ou ela acaba, ou eu aguento</i>. Depois ponha nela uma fronteira, onde ela está e até onde vai, <i>é a mão, só a mão</i>, e não acrescente o futuro, <i>e se piorar, e se não passar</i>. Sullivan e colegas (1995) criaram uma escala para medir o hábito de ampliar e ruminar a dor e viram que quem mais faz isso relata sentir mais dor.",
    primeiro=True)
tec("Epicuro no último dia.", "No último dia, morrendo de uma doença na bexiga e de disenteria, Epicuro escreveu a um amigo: <i>escrevo-lhe neste dia feliz, que é também o último da minha vida</i>. As dores não podiam ser maiores, mas a tudo isso se opunha a alegria da alma pela lembrança das conversas que tinham tido. E pediu que cuidassem dos filhos de um amigo morto.",
    "no desconforto, ponha ao lado dele uma lembrança precisa e boa, uma conversa, um lugar, um rosto, com os detalhes. E faça um ato pequeno por alguém.")
tec("Montaigne e o gemido.", "Montaigne sofreu de pedras nos rins desde os quarenta e cinco anos e escreveu sobre elas nos <i>Ensaios</i>. Ele permitia ao corpo gemer e se queixar, contanto que o juízo não cedesse. Séculos depois, Stephens e colegas (2009) puseram voluntários com a mão em água gelada: os que repetiam um palavrão aguentaram mais e sentiram menos dor do que os que repetiam uma palavra neutra.",
    "deixe o som sair, o ai, o gemido, o palavrão que é seu, com força. O corpo grita, e a decisão continua sua.")

sec("Para aguentar um golpe")
tec("Xenofonte e a coroa.", "Diógenes Laércio conta que Xenofonte oferecia um sacrifício, com uma coroa na cabeça, quando chegou a notícia de que o filho, Grilo, tinha morrido na batalha de Mantineia. Tirou a coroa e perguntou como ele tinha morrido. Ao saber que caíra lutando bem, pôs a coroa de volta e terminou o sacrifício.",
    "recebida a notícia, pare de verdade o que tem nas mãos. Faça uma pergunta só, a que decide o que é preciso saber agora. Respondida, devolva a coroa: volte à tarefa e termine-a, ainda que pela metade. Se a notícia pede que você vá a algum lugar ou faça algo agora, essa é a tarefa, e a coroa espera.",
    primeiro=True)
tec("Marie Curie e o diário.", "Em abril de 1906, Pierre Curie morreu atropelado por uma carroça em Paris. Poucos dias depois, Marie começou um caderno escrito a ele, em segunda pessoa, com os fatos como foram. Manteve-o por cerca de um ano; a filha Ève cita trechos na biografia da mãe.",
    "no dia do golpe, escreva no caderno, por quinze minutos e sem parar, o que aconteceu e o que você sente, com os fatos e os nomes. Repita nos três dias seguintes. Pennebaker e Beall (1986) viram que escrever assim melhora a saúde nos meses depois.")
tec("Marco Aurélio e o tendo acontecido.", "O rochedo de Marco Aurélio está na epígrafe de <i>Da serenidade</i>. A mesma nota continua assim: infeliz de mim, porque isto me aconteceu. Não: feliz de mim, porque, tendo isto acontecido, continuo sem dor, sem me quebrar com o presente e sem temer o que virá.",
    "quando vier por dentro <i>que azar, isto aconteceu comigo</i>, diga <i>não</i> e complete: <i>tendo isto acontecido, eu ainda...</i> Ponha ali a próxima ação da obra: eu ainda escrevo, entrego, termino a reunião.")

sec("Diante do perigo")
add("Os gestos desta seção são para o medo diante de um perigo que já chegou e que você não pode evitar: a cirurgia marcada, a turbulência, a água que virou o barco. Eles não servem para entrar num perigo que você poderia recusar.", PI)
tec("Sullenberger e as duas palavras.", "Em janeiro de 2009, logo depois de o avião perder os dois motores ao bater num bando de gansos sobre Nova York, o comandante Sullenberger disse ao copiloto duas palavras, <i>meu avião</i>, e assumiu os comandos, enquanto o copiloto corria a lista de emergência. Poucos minutos depois pousaram no rio Hudson, e todos sobreviveram. Os pilotos aprendem uma ordem fixa para esses instantes: primeiro voar, depois navegar, por último comunicar.",
    "diante do perigo físico, tome o comando com uma palavra, <i>meu</i>, e siga a ordem: primeiro o que mantém você vivo nos próximos dez segundos, depois a direção, por último avisar alguém. A ordem funciona porque foi aprendida antes; por isso, se o seu ofício ou a sua casa têm um perigo provável, escreva hoje os três passos dele.",
    primeiro=True)
tec("Stockdale e o paraquedas.", "Em setembro de 1965, o piloto americano James Stockdale foi abatido sobre o Vietnã do Norte. Contou depois que, descendo de paraquedas para uma aldeia, pensou que deixava o mundo da tecnologia e entrava no mundo de Epicteto. Passou mais de sete anos preso.",
    "quando o perigo começar, diga a frase de passagem: <i>agora estou no mundo do que é meu</i>. Nomeie uma coisa só que depende de você naquele minuto: a respiração, a posição do corpo, a resposta que vai dar.")
tec("Montaigne e a queda.", "Montaigne conta, no ensaio <i>Do exercício</i>, que um criado montado num cavalo forte o derrubou, e que foi levado para casa como morto, vomitando sangue. Por dentro, escreve, o estado era doce, uma languidez sem medo; a dor só veio quando voltou a si.",
    "quando vier o medo da anestesia, da queda ou da água, lembre que quem esteve lá costuma contar o meio do perigo como mais calmo do que a espera dele. Ponha a atenção no corpo presente, e não no filme do que vai acontecer.")

sec("Para memorizar")
tec("Quintiliano e a noite.", "Quintiliano, que ensinava retórica em Roma, mandava decorar o discurso longo por partes, ensaiar em voz baixa e decorar do próprio manuscrito, porque a memória guarda o lugar na página. E notou que uma noite de intervalo dá força ao que se aprendeu: o que não se conseguia repetir de manhã aparece firme depois do sono.",
    "divida em blocos de sentido. Ensaie cada um em voz baixa, primeiro olhando o papel, depois sem olhar. Faça a última recitação antes de dormir e teste de manhã, sem reler antes.",
    "Um bloco é o que se diz de um fôlego só, três a cinco frases, e não uma página. Recite sempre antes de olhar: tente, erre, confira, tente de novo; é a tentativa que fixa, e não a releitura. Quando um bloco sair duas vezes seguidas sem erro, passe ao seguinte, e a cada três blocos recite os três juntos, para costurar as passagens. Você sabe que está decorado quando recita o todo de manhã, sem ter relido, e de novo no dia seguinte. Se um trecho sempre falha, marque-o no papel com um sinal, como Quintiliano mandava, e comece a próxima rodada por ele. A pesquisa sobre sono e memória (Rasch e Born, 2013) dá razão à noite no meio.",
    primeiro=True)
tec("Ebbinghaus e o espaço.", "Ebbinghaus, em Berlim, foi a própria cobaia durante anos: decorava listas de sílabas sem sentido e media quanto esquecia. Descobriu que se esquece muito nas primeiras horas e depois mais devagar, e que as mesmas repetições rendem mais espalhadas por vários dias do que juntas num só.",
    "não decore tudo na véspera. Faça uma rodada hoje, uma amanhã e uma no dia, cada uma começando por tentar recitar antes de olhar. Se só tem hoje, separe as rodadas por algumas horas, com outra tarefa no meio. Cepeda e colegas (2006) reuniram centenas de experimentos que confirmam isso.")
tec("Simônides e os lugares.", "Cícero conta que o poeta Simônides saiu de um banquete pouco antes de o teto desabar, e que identificou os mortos, irreconhecíveis, lembrando onde cada um estava sentado. Daí teria tirado a regra: escolher lugares, pôr neles imagens do que se quer lembrar e percorrê-los em ordem. Quintiliano já duvidava da história e dizia que o método serve para sequências, e não para decorar um texto palavra por palavra.",
    "escolha um percurso que você conhece de olhos fechados, com cinco a dez paradas, e ponha em cada parada uma imagem exagerada de um item. Na hora, percorra o caminho.",
    "Imagine um discurso com cinco pontos: o problema, os números, a proposta, o custo, o pedido. Na porta de casa, um homem enorme bloqueia a passagem: o problema. No sofá, uma pilha de moedas desaba: os números. Na mesa da cozinha, uma planta brota do prato: a proposta. No fogão, uma conta pega fogo: o custo. Na cama, alguém estende a mão para você: o pedido. Quanto mais absurda, viva e barulhenta a imagem, melhor ela fica. Percorra a casa duas vezes de olhos fechados, dizendo cada ponto ao chegar nele. Você sabe que funcionou quando consegue fazer o percurso de trás para frente. Se uma imagem sumir, ela era fraca: troque-a por outra mais exagerada, com movimento ou com som. Dresler e colegas (2017) treinaram novatos assim por quarenta dias, e eles se aproximaram dos campeões de memória.")
tec("Ambrósio e a voz.", "Agostinho conta nas <i>Confissões</i> que se espantava ao ver Ambrósio ler: os olhos corriam pela página, o coração buscava o sentido, a voz e a língua descansavam. Naquele tempo, quase todos liam em voz alta.",
    "leia em voz alta, ou só movendo os lábios, apenas o que precisa guardar: a definição, o número, o nome, a frase de abertura. O resto, em silêncio. MacLeod e colegas (2010) viram que dizer em voz alta fixa melhor, e que o efeito desaparece quando se lê tudo em voz alta.")
tec("Mozart e o Miserere.", "Numa carta à mulher, de abril de 1770, Leopold Mozart conta que o filho, aos catorze anos, ouviu na Capela Sistina o <i>Miserere</i> de Allegri, música que o papa não deixava copiar, e a escreveu inteira de memória.",
    "logo depois da aula ou da reunião, antes de falar com alguém ou olhar as notas, escreva de memória tudo o que guardou. Depois confira com a fonte e marque o que faltou. Roediger e Karpicke (2006) viram que tentar lembrar fixa mais do que reler.")
tec("Malcolm X e o dicionário.", "Na prisão, no fim dos anos 1940, Malcolm X tinha vergonha de não conseguir pôr nas cartas o que pensava. Pediu um dicionário, copiou à mão a primeira página inteira, até a pontuação, e depois leu em voz alta o que tinha copiado. Seguiu assim, página a página, até o fim do dicionário.",
    "para o vocabulário de uma matéria nova, copie à mão as dez palavras que você não domina, leia em voz alta o que copiou e, no dia seguinte, cubra as definições e tente dizê-las. Copiar sozinho rende pouco; o que fixou as palavras em Malcolm X foi a cópia somada à voz, à volta no dia seguinte e ao uso nas cartas.")

add("Antes de fechar o livro esta noite, escolha o momento em que você mais costuma falhar. Escolha o obstáculo que de fato se repete, e não o homem que você mais admira nem o gesto que parece mais grandioso. Ache esse obstáculo na chave, escreva ao lado dele, no caderno, o primeiro gesto da seção, numa linha curta o bastante para ser feita sem negociação, e ensaie-o uma vez antes de dormir. Amanhã, quando o momento chegar, não decida de novo. Faça o gesto.", PI)
st[-2:] = [KeepTogether(st[-2:])]
SEC_NO_SUMARIO = False

# ===================== LIVRO I =====================
livro("I", "Do pensamento")
st.append(KeepTogether([Paragraph("<i>“Dimidium facti qui coepit habet: sapere aude, incipe.”</i>", ParagraphStyle('livro1e1', parent=PC, fontSize=12, spaceAfter=2)),
                        Paragraph("Horácio, <i>Epístolas</i>, I, 2", ParagraphStyle('livro1e2', parent=EPA, spaceAfter=18))]))
add("Este livro guarda os instantes em que o estado que dá nome ao livro se perde: o começo, a vontade de parar, a saída, o impasse, o fim, a falta de vontade, a escolha, o que é novo, a onda. Cada linha é, para um desses instantes, uma forma particular da frase que <i>Da assentada</i> vai ensinar a você: <i>Isto, até acabar.</i>", PI)
add("As nove linhas não pesam igual no dia. Duas acompanham você todos os dias desde o dia um: a primeira, a cada vez que se senta diante da obra, e a sexta, quando, sentado, nada em você quer começar. A oitava serve também desde o começo, sempre que algo novo for começar. Três chegam com o exercício do terminar: a segunda, para o trecho que resiste, a quinta, para o fim de cada sessão, e a sétima, para quando várias coisas pedem atenção ao mesmo tempo. A terceira chega com o da absorção, sempre que você se perceber fora da obra, e a quarta com o da prática deliberada, para os impasses. A nona é a mais rara, e só serve depois do primeiro corte, quando volta a vontade do que você deixou.", PI)
add("Numa das noites antes do dia zero, você lê deste livro só a abertura, <i>Da forma</i> e as linhas I e VI, até saber as frases das duas sem olhar; as outras sete, nos primeiros dias, fora das horas da obra, uma de cada vez.", PI); add("Volte a ele quando uma linha lhe parecer vazia no instante de dizê-la, e releia o <i>Do sentido</i> dela, fora das horas da obra.", PI)
add("O verso no alto deste livro é de Horácio, poeta romano do tempo de Augusto, e diz: quem começou tem metade do feito; ouse saber, comece. Ele abre o livro das linhas porque todas elas tratam do instante em que se começa, ou se deixa de começar, e é desse instante que o verso fala. A carta de onde ele vem, e o que Horácio queria dizer com ele, eu conto na primeira linha. Kant, em 1784, fez das duas palavras do meio a divisa do esclarecimento. Ele pedia a cada um a coragem de se servir do próprio entendimento sem a direção de outro, e notava como é cômodo ser menor quando se tem um livro que pensa por nós; o pedido vale também diante deste livro. O que esta abertura conta se passa na manhã do dia um, e por isso ela fala dessa manhã no futuro. Nessa manhã, a folha do dia zero estará escrita na primeira página do caderno. Você terá aberto o caderno, dito o estribilho e escrito a linha da manhã com a obra de hoje, como manda a parte <i>De manhã</i> do Livro II, e a mesa estará sob a microação da ordem, a mesma cujo gesto você já marca. Nessa manhã, tudo o que se podia decidir no papel estará decidido.", PI)
add("Para essa manhã, conto a você a história de um homem que a conhecia. No começo do quinto livro das <i>Meditações</i>, Marco Aurélio, senhor de Roma, escreve a si mesmo que, ao amanhecer, quando lhe custar levantar-se, tenha à mão este pensamento: eu me levanto para a obra de homem. E discute consigo, ainda debaixo das cobertas, se terá nascido para ficar deitado e aquecido. Não lhe faltavam razões para se levantar, nem deveres, nem uma ideia nítida do que devia ser um imperador. Faltava a ele, naquele minuto, a frase certa, e ele a escrevia para tê-la à mão no minuto seguinte. Era um dos homens mais disciplinados da Antiguidade, e precisava dela. A obra de homem tem ali um sentido preciso. Os estoicos pensavam que cada ser tem sua obra própria, e Marco Aurélio, no mesmo trecho, aponta para as plantas, os pardais, as formigas, as aranhas e as abelhas, que fazem cada uma a sua; a obra do homem é agir segundo a razão. Em outras palavras, ficar deitado, quando a razão já decidiu, é recusar aquilo para que se nasceu. E guardava a frase pronta porque, no minuto do custo, não há tempo para refazer o argumento. As nove linhas servem a você do mesmo modo.", PI)
add("No dia um você vai se sentar diante da obra de hoje. Entre o momento em que você se senta e o primeiro movimento da mão vai se abrir um intervalo de poucos segundos, e nesse intervalo algo vai falar por dentro. É a voz das tentativas anteriores. Quase nunca fala alto. Diz <i>daqui a pouco</i>, diz <i>primeiro arrume isto</i>, diz <i>hoje não é o melhor dia, amanhã se começa direito</i>. A folha do dia zero não tem resposta para ela. Foi escrita para dar direção, e a direção não governa o instante.", PI)
add("Passei por isso mais de uma vez. As tentativas raramente morriam no dia em que se decidia mudar de vida. Morriam dias depois, às nove e dez de uma manhã qualquer, numa conversa de três segundos que ninguém ouviu. Este livro trata dessas conversas, nos poucos momentos em que um dia se decide: ao começar, ao querer parar, ao perceber que você saiu, ao travar, ao julgar que terminou, ao não querer nada, ao não saber por onde ir, ao começar algo novo, ao sentir de volta a vontade do que você cortou. Para cada momento há uma linha de pensamento: duas, três ou quatro frases curtas que você diz por dentro, em silêncio, no instante em que ele chega, sem discuti-las. Nove momentos, nove linhas. No dia um você vai precisar só de duas, a primeira e a sexta, cujas frases você vai reler nessa manhã; as outras vêm com os exercícios, quando a ocasião delas começar a aparecer.", PI)
sec("Da forma")
add("Repare no que costuma acontecer nesse intervalo. A voz fala, e você responde; ela replica, e você pondera; ao fim de um minuto, você está deliberando se a obra de hoje deve ser feita hoje, coisa que decidiu ontem. Entre perceber e agir, você abriu um tribunal. Ouviu a preguiça, a dúvida, o cansaço, e se pôs a julgar. As nove linhas têm todas a mesma forma, e essa forma serve para que o tribunal nem chegue a abrir. Ela tem quatro tempos:", PI)
add("<i>perceber &nbsp;·&nbsp; nomear &nbsp;·&nbsp; o próximo movimento &nbsp;·&nbsp; mover</i>", ParagraphStyle('f2', parent=PC, fontSize=13, spaceBefore=8, spaceAfter=12))
add("Você percebe: nota que algo mudou, a mão parou, o olhar foi à janela, veio uma frase que pede outra coisa. Nomeia: dá ao que veio o nome que a linha lhe dá, <i>é vontade</i>, <i>saí</i>, <i>é a onda</i>. Diz o próximo movimento, que a linha também traz e que é sempre um gesto pequeno e visível. E move: a mão faz esse gesto antes que outra frase se forme. Você não argumenta, não se persuade, não se examina. O exame pertence à noite, aos minutos com o caderno; durante o dia, há o ato. Os atletas conhecem isso como a rotina que antecede o lance: a mesma sequência, sempre na mesma ordem, para que no instante decisivo não reste nada a decidir.", PI)
add("A forma não foi inventada aqui. Os estoicos, a escola de Epicteto e de Marco Aurélio, descreveram, há mais de dois mil anos, o caminho que vai do mundo até o ato. Primeiro chega a impressão, que eles chamavam de <i>phantasía</i>: algo se apresenta ao espírito, uma coisa vista, uma lembrança, um desejo, um cansaço. Depois o espírito concorda ou não com o que a impressão afirma, e disso vai falar o livro seguinte. Só então vem o impulso, <i>hormé</i>, e com ele o movimento. Entre a impressão e o impulso há um ponto em que o homem ainda é senhor de si, e boa parte da prática estoica consistia em guardar esse ponto. Eles o guardavam porque, para eles, só uma coisa depende inteiramente de nós: o juízo que fazemos sobre o que nos aparece. A impressão vem sem ser chamada; concordar com ela é obra nossa, e é nesse concordar que o homem se governa ou se deixa levar.", PI)
add("Epicteto ensinava a guardar esse ponto com uma frase. O <i>Manual</i>, o resumo de suas lições composto pelo discípulo Arriano, abre com a distinção da qual todo o resto depende: umas coisas estão em nosso poder, o juízo, o impulso, o desejo, a recusa; outras não, o corpo, os bens, a reputação. Logo nesse primeiro capítulo, Epicteto aconselha o discípulo a se exercitar desde o início em dizer a toda impressão áspera: você é uma impressão, e de modo algum aquilo que parece. A impressão se apresenta como o próprio estado das coisas, e é preciso lembrá-la de que é só uma aparência, para que o juízo, que é nosso, não lhe dê razão sem exame. Isso é o nomear. A vontade de largar a obra se apresenta como verdade sobre o mundo, <i>isto está difícil demais</i>; nomeada, volta ao tamanho que tem, o de um estado que passou pelo espírito. Marco Aurélio dava ao mesmo gesto uma forma mais técnica: fazer sempre a definição ou a descrição do que se apresenta, para vê-lo tal como é, nu, separado das palavras com que veio vestido (<i>Meditações</i>, III, 11).", PI)
add("O que este livro faz com os estoicos é diferente, e de propósito. Para eles, guardar o ponto era examinar a impressão antes de lhe dar assentimento, fosse ela qual fosse, e faziam disso a vida inteira. Você tem uma obra à frente e poucos segundos. Por isso a forma toma deles só o nomear, reduz esse nomear a uma palavra e acrescenta a ele o próximo movimento, decidido antes. O exame propriamente dito fica para outra hora, a noite e as passagens. O que a forma faz no instante pertence mais ao hábito e ao pré-compromisso do que ao assentimento estoico, e o livro seguinte diz isso na segunda lei. Nomear sem mover não basta. Quem diz <i>é vontade, não fato</i> e continua sentado reconheceu o estado e, mesmo assim, deixou que ele decidisse.", PI)
add("A objeção óbvia é que isso empobrece o pensamento: que um homem que responde ao instante com fórmulas se torna um mecanismo, e que a liberdade estaria justamente em deliberar a cada vez. Mas a deliberação não sai deste caminho. Ela continua, em outra hora. No dia zero você vai deliberar, durante um dia inteiro, sobre quem quer ser, e depois voltará a deliberar todas as noites diante da folha de marcas e, com mais vagar, em cada noite de passagem. O que a forma recusa é reabrir às nove e dez da manhã, com o cansaço como juiz e a preguiça como advogado, o processo que foi julgado de cabeça fria. Um tribunal que reabre a causa a cada hora acaba sempre dando razão a quem fala por último, e quem fala por último, no meio da manhã, é o desejo do mais fácil. <i>Da máscara</i>, que você vai ler depois do dia zero, dá um rosto a esse tribunal fechado: o homem da sua visão, que decidiu quem é e não reabre a causa.", PI)
add("Por isso as linhas são curtas. Uma frase longa convida à réplica; uma frase de três palavras já acabou antes que a réplica se forme. Elas não precisam ser entendidas no momento. São entendidas antes, quando você lê com calma o sentido de cada uma, e no momento apenas são ditas. Decorar uma linha é lê-la em voz baixa até conseguir dizê-la sem olhar, como você fez com o estribilho; depois disso, dita por dentro, ela leva o tempo de uma respiração.", PI)

sec("As nove linhas")
add("Cada linha segue a mesma ordem: o título e, numa frase, o momento em que ela chega; as frases que você diz por dentro, e que decora; o que você faz em seguida; <i>Do porquê</i>, com a ideia, o mecanismo e a frase que você diz ao usá-la; e <i>Do sentido</i>, que conta o instante como você vai vivê-lo, o que outros viveram nesse ponto do caminho e a objeção mais forte à linha, com a resposta.", PI)
add("O sentido se lê com calma, uma vez, fora das horas da obra, e se relê quando a linha parecer vazia. As objeções estão lá de propósito: é melhor encontrá-las primeiro aqui, com tempo, do que numa manhã difícil, quando a voz as usar contra você.", PI)

LBL = ParagraphStyle('lbl', **{**base, 'textColor': GRAY}, fontSize=9.5, leading=12, spaceBefore=8, spaceAfter=4, keepWithNext=1)
def linha(num, nome, quando, preludio, vozes, corpo, sentido, nota=None, porque=None):
    blk = [sumario(Paragraph(f"{num}. &nbsp;{nome}", ParagraphStyle('hh', parent=HEAD, fontSize=13.5, spaceBefore=16)), 1, f"{num}. {nome}"),
           Paragraph(quando, WHEN)]
    if preludio: blk.append(Paragraph(preludio, BODY))
    for v in vozes: blk.append(Paragraph(v, VOICE))
    blk.append(Paragraph(corpo, BODY))
    st.append(KeepTogether(blk))
    if porque:
        st.append(Paragraph("D O &nbsp; P O R Q U Ê", LBL))
        for par in porque: st.append(Paragraph(par, PI))
    st.append(Paragraph("D O &nbsp; S E N T I D O", LBL))
    for par in sentido: st.append(Paragraph(par, PI))
    if nota: st.append(Paragraph(nota, NOTE))

linha("I", "Do começar", "Quando você for iniciar o que importa.",
 "Sente-se, afaste de você o que distrai e repouse os olhos num ponto fixo, em silêncio; entre sentar e começar não se passam mais de cinco minutos. Então, nesta ordem:",
 ["O que deve existir quando eu me levantar daqui?", "Qual é o primeiro movimento da mão?",
  "<font color='#6b6b6b'>(Veja-se, por um instante, fazendo os primeiros cinco minutos.)</font>", "Comece."],
 "E a mão se move.",
 ["No dia um, à mesa da obra, você vai fazer isto pela primeira vez. Você se senta, e a microação da ordem já está trabalhando: o que distrai sai da mesa. Você fica diante da obra de hoje, e é provável que ela lhe pareça, nesse instante, maior e mais vaga do que parecia quando você a escreveu na linha da manhã. Talvez venha então a primeira voz do dia: <i>primeiro vejo só uma coisa</i>, ou <i>preciso pensar melhor por onde pegar isto</i>. Você reconhece o momento por esta figura: você está à mesa, a obra está à sua frente, e a mão ainda não fez nada. É o começar. Repouse os olhos num ponto da parede e deixe assentar o ruído das horas anteriores. Depois pergunte por dentro: <i>o que deve existir quando eu me levantar daqui?</i> E responda com uma coisa que se possa ver e tocar ao fim, escrita na margem da folha de captura (a folha que você deixa ao lado da obra) ou no canto do caderno.",
  "É quase certo que, nessa primeira sessão, a resposta saia grande demais. Se você escreveu a obra inteira, ou uma intenção, <i>avançar</i>, <i>trabalhar nisto</i>, corte a resposta até que ela caiba nesta sessão. Então vem a segunda pergunta: <i>qual é o primeiro movimento da mão?</i> Abrir o caderno na página certa, escrever o título, pegar a primeira peça. Veja-se por um instante fazendo os primeiros cinco minutos, e diga <i>comece</i>. Depois disso, você não espera outro pensamento; a mão se move. Se você se pegar à mesa há mais de cinco minutos sem que a mão tenha se movido, o silêncio já virou adiamento: faça a segunda pergunta e mova a mão. Quando a mão se mover, a linha terá feito o que tinha a fazer, e o resto da sessão pertence à obra, uma coisa só à frente até ela acabar.",
  "A obra adiada continua por fazer, e amanhã pesa mais, porque à indefinição se soma o atraso. <font color='#6b6b6b'>(Lição VIII)</font>",
  "A primeira pergunta transforma <i>trabalhar no relatório</i> em <i>a segunda seção escrita</i>. Os minutos diante da parede servem para esvaziar o espírito do ruído anterior, para que a obra encontre o lugar limpo.",
  "Conto agora a você a história de um homem que resolveu este instante com um relógio. Na Inglaterra de meados do século XIX, um funcionário dos correios chamado Anthony Trollope se tornou um dos romancistas mais lidos de seu tempo sem deixar o emprego. Na <i>Autobiografia</i>, publicada depois de sua morte, ele conta como fez isso. Um velho criado vinha acordá-lo de madrugada, com café, e recebia por isso cinco libras a mais por ano; Trollope escreveu que devia a esse homem, mais do que a qualquer outro, o êxito que tivera. Às cinco e meia estava à mesa, com o relógio diante de si, e exigia de si mesmo duzentas e cinquenta palavras a cada quarto de hora. Escrevia cerca de três horas, e depois ia trabalhar. Mantinha um diário de páginas, semana a semana, e, se lhe escapavam um ou dois dias de ociosidade, o registro estava ali, olhando-o de frente e cobrando dele trabalho redobrado. Escrevia também nos trens, numa prancheta apoiada nos joelhos.",
  "Trollope não começava o dia decidindo se escrevia, nem o quê: a obra da manhã tinha contorno, e o primeiro movimento era sempre o mesmo, a pena no papel. As duas perguntas fazem por você, de modo menos mecânico, o que o relógio fazia por ele: dão à sessão uma forma antes que ela comece. E repare no tamanho da conta. Duzentas e cinquenta palavras num quarto de hora são um passo que se cumpre mesmo num dia ruim. Quem responde à primeira pergunta com <i>o livro inteiro</i> trocou uma névoa por outra, maior. A resposta certa tem o tamanho de uma sessão.",
  "Os antigos sabiam o peso deste ponto do caminho e o disseram de várias maneiras. Horácio, numa carta a um jovem amigo, Lólio, que estudava retórica em Roma, escreve o verso que abre este livro: quem começou tem metade do feito; ouse saber, comece. <i>Sapere</i>, em latim, é também ter juízo, e o que Horácio pede ao rapaz é que ouse começar desde já a viver com juízo, em vez de deixar isso para mais tarde. Os versos seguintes dizem o mesmo com uma imagem: quem adia a hora de viver bem é como o camponês que espera, à beira do rio, que a água acabe de passar para atravessá-lo, e o rio continua correndo. Para Horácio, a ocasião perfeita para começar não chega, porque as razões para esperar se renovam como a água; é a voz do <i>amanhã se começa direito</i>. O <i>incipe</i> no fim do verso é um imperativo de uma palavra, como o <i>comece</i> desta linha.",
  "Você vai dizer que tudo isso é ofício de artesão, e que a obra que vale a pena nasce da inspiração, que não se convoca com relógio. Foi o que disseram de Trollope. A <i>Autobiografia</i> saiu em 1883, e durante décadas a reputação dele sofreu com ela: muitos leitores não perdoaram o romancista por ter confessado o relógio. Ele previra a objeção e respondia a ela no próprio livro, comparando o escritor ao sapateiro, que, acabado um par de botas, não se senta à espera da musa para começar o seguinte. Há uma resposta mais forte. A inspiração, quando vem, é mais bem aproveitada por quem já está trabalhando. A primeira linha promete apenas que haverá obra, boa ou ruim, e uma página escrita pode ser melhorada; os romances de Trollope continuam sendo lidos."],
 "Mais de cinco minutos entre sentar e começar já são adiamento.",
 porque=[
  "<b>A ideia.</b> Aristóteles diz, na <i>Ética a Nicômaco</i>, que o princípio parece ser mais da metade do todo, porque muito do que se procura fica claro a partir dele. Numa sessão de trabalho, o começo pesa por causa da indefinição. Enquanto a obra não tem contorno, não há por onde pegá-la, e quem adia quase sempre foge dessa névoa, mais do que da tarefa. As duas perguntas desta linha dão contorno à obra antes que a mão se mova.",
  "<b>O mecanismo.</b> Primeiro, uma obra definida como um objeto que se pode ver ao fim da sessão diz a você por onde começar e quando você acabou; uma intenção, <i>trabalhar nisto</i>, não diz nenhuma das duas coisas, e sem esse critério o espírito adia. Segundo, o primeiro movimento da mão é tão pequeno que não deixa nada para deliberar, e, uma vez feito esse movimento, a obra começa a mostrar o passo seguinte, como Aristóteles dizia do princípio. O instante em que você se vê trabalhando ensaia esse gesto antes que você o faça. Nenhum estudo testou esta linha; o que fica dito é razão, e a experiência de quem trabalhou assim, como Trollope.",
  "<b>Por isso.</b> Faço as duas perguntas porque um primeiro gesto pequeno não me deixa nada para discutir."])

linha("II", "Da vontade de parar", "Quando, no meio da obra, vier o desejo de largá-la.", None,
 ["É vontade, não fato.", "Até o fim deste passo."],
 "Termine a frase, a série, o parágrafo. A mão não sai do lugar.",
 ["Você lê isto nos primeiros dias, e esta linha só lhe será pedida mais adiante, quando o exercício do terminar for a da vez, depois da primeira passagem. Até lá, é provável que você sinta muitas vezes este momento sem lhe dar nome. Conto a você como ele vem. Você está no meio da obra, e a obra anda. Depois chega um trecho que resiste: uma frase que não sai, uma série que pesa, um cálculo que não fecha. A mão desacelera. Vem então uma voz, quase sempre sensata: <i>você já fez bastante por hoje</i>, <i>vou só me levantar um minuto</i>, <i>amanhã, com a cabeça fresca, isto sai</i>. Você reconhece o momento por uma coincidência: a vontade de parar chegou junto com o trecho difícil, e não ao fim de horas de trabalho.",
  "Diga por dentro: <i>é vontade, não fato</i>. Depois: <i>até o fim deste passo</i>. E termine só isso, a frase, a série, o parágrafo, sem se levantar da cadeira. Ao fim do passo, olhe outra vez para a vontade. Se ela passou, e quase sempre passa, você segue, muitas vezes sem perceber. Se continua lá, inteira, você para, mas num ponto fechado, e amanhã retoma sem névoa. Nas duas saídas, a obra não ficou interrompida no meio de uma frase.",
  "No meio da obra, a vontade de parar quase sempre anuncia o desconforto do trecho difícil. E, como ela aparece justamente onde a obra resiste, muitas vezes é o sinal de que você chegou ao ponto que importa.",
  "Um homem teve essa vontade com todos os motivos. Entre 1508 e 1512, Michelangelo pintou a abóbada da Capela Sistina, em Roma, por encomenda do papa Júlio II. Não queria a encomenda. Considerava-se escultor, e tinha na cabeça outra obra, o túmulo do papa, que lhe fora prometido e depois posto de lado. Subiu aos andaimes mesmo assim e passou quatro anos pintando com a cabeça dobrada para trás. Numa folha desses anos, ao lado de um pequeno desenho de si mesmo de pé, com o braço erguido para o teto, escreveu um soneto a um amigo, Giovanni da Pistoia. É uma das queixas mais engraçadas e mais tristes que a história da arte guardou. Diz que lhe nasceu um papo de tanto esforço; que tem a barba virada para o céu e a nuca colada às costas; que o pincel, sempre acima do rosto, pinga na cara dele e faz dela um pavimento de cores; que os rins lhe entraram na barriga e o corpo se curvou como um arco sírio. E termina pedindo ao amigo que defenda a pintura morta e a honra dele, porque ele não está no lugar certo, e não é pintor.",
  "O corpo doía de verdade, e a obra não era a que ele escolhera. Repare no que Michelangelo fez com a vontade: ele a escreveu. Deu a ela rima e até humor, a pôs fora de si, do tamanho que tinha, e depois voltou ao teto. O soneto é, à sua maneira, um <i>é vontade, não fato</i> de catorze versos: a queixa nomeada para que a mão pudesse continuar. Michelangelo sentiu a dor inteira e não a deixou decidir. A abóbada foi descoberta em 1512.",
  "Os gregos tinham uma palavra para o que esta linha enfrenta: <i>akrasía</i>, a falta de domínio, o estado de quem sabe o que é melhor e faz o pior. Sócrates, no <i>Protágoras</i> de Platão, negava que isso existisse. Ninguém, dizia ele, escolhe o pior sabendo que é pior; quem parece ceder ao prazer contra o próprio juízo errou o cálculo, como quem vê grande o que está perto e pequeno o que está longe. Corrige-se o saber, e a conduta acompanha. É uma doutrina nobre, e quase todos os que já largaram uma obra pela metade sabem que ela não descreve o que lhes aconteceu: no momento de largar, eles sabiam muito bem que faziam o pior.",
  "Aristóteles retomou o problema no sétimo livro da <i>Ética a Nicômaco</i> e lhe deu uma resposta mais fina. O acrático sabe e, de certo modo, não sabe: tem o saber como o têm o homem que dorme, o louco ou o bêbado, que podem recitar versos de Empédocles sem que as palavras lhes digam nada. O desejo não apaga o conhecimento; ele o adormece no instante em que seria preciso. No trecho difícil, você não esquece que a obra importa; durante alguns segundos, isso deixa de estar presente, como uma oração sabida de cor e dita sem ouvir. E repare como Aristóteles fecha a análise. O que o desejo adormece é o saber do caso presente, aquele que liga a regra ao gesto de agora; o saber em sentido próprio não é arrastado pela paixão, e por isso, conclui ele, parece resultar o que Sócrates procurava (VII, 3, 1147b14-17, paráfrase). A resposta de Aristóteles corrige Sócrates e acaba por lhe conceder uma parte.",
  "Às vezes parar é o certo, e a vontade diz a verdade: o corpo esgotado, a obra que perdeu o sentido, a dor que vem da vida inteira e não do trecho difícil. A linha não nega isso, e a nota abaixo já o reconhece. Mas repare que ela pede pouco, só o fim do passo. Uma resistência verdadeira não se dissolve no fim de uma frase; continua lá, intacta, e pode ser ouvida com calma depois. A vontade passageira quase sempre se dissolve. Assim, a linha funciona como uma prova barata: dê um passo e veja o que sobra. Há uma resistência que fala, e o Livro V ensina a ouvi-la. Esta linha garante apenas que você não a confunda com o primeiro desconforto do trecho difícil."],
 "Esta linha vale para a vontade, não para o limite. Depois de horas de trabalho, a pausa planejada faz parte da obra; dela trata a seção sobre o descanso.",
 porque=[
  "<b>A ideia.</b> É a <i>akrasía</i> dos gregos, que o <i>Do sentido</i> conta: o desejo não apaga o saber, ele o adormece no instante em que seria preciso. A vontade de parar aproveita esses segundos.",
  "<b>O mecanismo.</b> Primeiro, as frases separam um estado de uma razão. Um estado passa sozinho; uma razão pode ser escrita numa linha. Se você não consegue escrevê-la, era o estado, e dar nome a ele acorda o que você já sabia. Segundo, a linha pede só o fim do passo, uma tarefa tão pequena que o saber acordado a cumpre sem ter de ganhar a discussão inteira. Ao fim do passo, você vê o que sobra: uma resistência verdadeira continua lá, e uma vontade passageira quase sempre se desfez. A mão fica no lugar porque se levantar já seria obedecer. Nenhum estudo testou esta linha; o que fica dito é razão.",
  "<b>Por isso.</b> Termino o passo porque esta vontade é um estado que passa, e porque um passo pequeno se faz mesmo com ela presente."])

linha("III", "Da dispersão", "Quando você perceber que saiu.", None,
 ["Saí.", "Onde eu estava?"],
 "Feche o que abriu, releia a última linha e continue. Não pergunte por quê.",
 ["Esta linha virá com o exercício da absorção, mas o momento dela aparece desde o primeiro dia. Você está trabalhando e, a certa altura, se percebe em outro lugar: olhando pela janela, pensando numa conversa de ontem, com a distração na mão sem se lembrar de ter ido buscá-la. Você não se lembra de nenhuma decisão, só de um intervalo do qual não guardou nada. O momento desta linha é o instante em que você percebe isso. E, logo depois da constatação, costuma vir uma segunda voz, que faz mais estrago do que a saída: <i>outra vez</i>, <i>nunca consigo manter a atenção</i>, <i>esta manhã já está perdida</i>.",
  "Diga por dentro só: <i>saí</i>. Sem adjetivo. Depois: <i>onde eu estava?</i> Feche o que abriu, volte à obra, releia a última linha que escreveu ou o último passo que deu, e continue dali. Se, no meio da volta, vier à cabeça uma coisa que não pertence à obra, escreva-a numa linha na folha de captura e continue. Numa manhã você pode sair e voltar trinta vezes, e cada volta conta como uma repetição do treino. Com os dias, o que encurta é o tempo entre sair e perceber que saiu. Quando a absorção for a da vez, cada saída que você perceber será uma repetição do exercício.",
  "<i>Onde eu estava?</i> volta o olhar para o ponto exato da obra, como quem retoma uma conversa interrompida. Se a mesma causa se repete, a mesma distração, na mesma hora, resolva-a à noite, mudando o ambiente.",
  "Conto a você agora a história de homens que fizeram desta volta a vida inteira. No século IV, nos desertos do Egito, homens iam viver sozinhos numa cela com uma tarefa única, e a tarefa era ficar. Evágrio Pôntico, que passou entre eles os últimos anos da vida, descreveu os oito pensamentos que assaltam o monge e chamou o mais pesado de <i>acédia</i>, o demônio do meio-dia. Ele chega, escreve Evágrio, por volta da quarta hora e cerca a alma até a oitava. Primeiro faz parecer que o sol mal se move, que o dia tem cinquenta horas. Depois obriga o monge a olhar o tempo todo pela janela, a sair da cela, a fitar o sol para calcular quanto falta para a refeição, a olhar para um lado e para o outro à espera de que algum irmão apareça. Por fim, faz o monge odiar o lugar, o trabalho das mãos, a vida que escolheu, e lhe sussurra que em outro lugar tudo seria mais fácil.",
  "Se você já tentou trabalhar uma manhã inteira numa só coisa, talvez reconheça cada traço do retrato. As distrações do seu tempo têm outros objetos; o movimento é o do monge à janela. E o conselho dos padres do deserto era simples: não sair da cela. Evágrio avisa que a hora da tentação não é hora de abandonar o lugar. Não se discutia com o demônio, não se procurava outra ocupação mais nobre; voltava-se ao trabalho das mãos.",
  "João Cassiano, que levou esses ensinamentos do Egito para a Gália, conta nas <i>Instituições</i> a história do abade Paulo. Paulo vivia no deserto de Porfírio, a sete dias de caminho de qualquer cidade, sustentado pelas tâmaras e por uma pequena horta. Não precisava trabalhar para comer, nem teria a quem vender o que fizesse. Ainda assim, todos os dias, recolhia folhas de palmeira e cumpria a tarefa de cestos como se vivesse dela; e quando, ao fim de um ano, a gruta estava cheia, queimava tudo e recomeçava. Fazia isso, diz Cassiano, para mostrar que sem o trabalho das mãos o monge não consegue ficar no próprio lugar. Cassiano quer ensinar que o cesto valia pelo que fazia ao monge, e que o destino do cesto pouco importava: as mãos ocupadas numa tarefa precisa seguravam o espírito na cela. A última linha escrita é o seu monte de folhas de palmeira; você volta a ela porque é ela que prende você à mesa, mesmo antes que a obra ande.",
  "Mil e duzentos anos depois, Montaigne encontrou o mesmo demônio sem procurá-lo. Conta, no ensaio <i>Da ociosidade</i>, que se retirou para casa decidido a não fazer outra coisa senão deixar o espírito repousar em si mesmo, e esperava que ele, com o tempo, se tornasse mais pesado e mais maduro. Aconteceu o contrário. Como um cavalo que escapa, o espírito se deu cem vezes mais trabalho por conta própria do que antes se dava pelos outros. Pôs diante de Montaigne tantas quimeras e monstros fantásticos, uns atrás dos outros, sem ordem nem propósito, que ele começou a registrá-los por escrito, para contemplar à vontade a inépcia e a estranheza deles, esperando com o tempo fazer o espírito se envergonhar deles.",
  "Montaigne ensina duas coisas a esta linha. O espírito deixado sem tarefa galopa, e por isso a volta é sempre a um ponto preciso, a última linha escrita, e nunca a um vago <i>preciso me concentrar</i>. E o que ele fez com as quimeras foi registrá-las por escrito, sem sermões, que é o que faz a folha de captura.",
  "No século XVII, num convento de carmelitas descalços em Paris, um irmão leigo, Lourenço da Ressurreição, passou anos na cozinha, trabalho ao qual tinha, por natureza, grande aversão. Das conversas e cartas dele que foram recolhidas e publicadas com o título de <i>A prática da presença de Deus</i>, sai um único método: manter a atenção em Deus no meio das panelas e, quando percebia que tinha se afastado, voltar, sem se inquietar. Quando falhava, reconhecia a falta e retomava, sem fazer disso um drama. Para Lourenço, voltar era voltar à presença de Deus, e a cozinha valia como lugar de oração. Daqui se tira só a maneira de voltar, que serve fora do convento porque a inquietação por ter saído ocupa a atenção que devia voltar à obra.",
  "Se a mesma distração tira você da obra dez vezes por manhã, parece sensato parar e investigar a causa. A linha não recusa a investigação; adia-a para a noite. O que se recusa é investigar no meio da obra, por duas razões. A primeira é que, no instante, a investigação usa a mesma atenção que acabou de fugir, e foge com ela: <i>por que me distraio?</i> leva a pensar nas distrações, e dali a elas. A segunda é que o espírito, no meio da manhã, é um mau detetive de si mesmo, e explica tudo pelo cansaço ou pelo caráter. À noite, com a folha de captura na mão, as provas estão escritas: a hora, o lugar, o que veio. É aí que a causa aparece, e aparece quase sempre no ambiente. Evágrio foi um observador minucioso desses pensamentos, mas a regra, no momento do assalto, era não sair da cela."],
 porque=[
  "<b>A ideia.</b> A atenção se desvia sozinha, dezenas de vezes por hora, e nenhum mestre esteve livre disso. Lourenço da Ressurreição, irmão leigo de um convento de carmelitas em Paris no século XVII, fez da volta todo o método dele: quando percebia que tinha se afastado, voltava, sem se inquietar. A saída vem de qualquer maneira. O que esta linha treina é o modo da volta e o tempo que ela leva.",
  "<b>O mecanismo.</b> Primeiro, julgar a si mesmo por ter saído usa a mesma atenção que devia voltar à obra. Cada palavra a mais, <i>de novo</i>, <i>sempre faço isto</i>, é uma segunda saída; <i>saí</i> nomeia sem condenar e gasta uma palavra só. Segundo, cada troca de tarefa custa tempo e erros, mesmo quando é prevista, como mostram os estudos de laboratório sobre alternância de tarefas que Stephen Monsell resumiu. Voltar ao ponto exato, a última linha escrita, reduz o que você tem de reconstruir, e investigar a causa ali seria abrir mais uma tarefa. A causa se examina à noite, com a folha de captura na mão.",
  "<b>Por isso.</b> Digo só <i>saí</i> e volto à última linha porque cada tarefa nova que abro me obriga a reconstruir onde estava."])

linha("IV", "Do impasse", "Quando o problema não andar.", None,
 ["O que exatamente eu não sei?", "Qual é a menor parte que posso fazer agora?"],
 "Escreva a pergunta numa linha. Faça a menor parte.",
 ["Esta é para mais tarde, quando o exercício da prática deliberada for a da vez, já na segunda estação (o Livro III agrupa os exercícios em estações, trechos do caminho). Nesse ponto, a obra deixa de ser só fazer e passa a ser fazer o que você ainda não sabe, e os impasses se multiplicam. Convém que se multipliquem, porque uma prática que nunca trava está abaixo do seu limite. O instante tem uma figura, e vale reconhecê-la antes que ele venha. Você está diante de um problema e não sai do lugar. Relê o mesmo parágrafo pela terceira vez, tenta a saída que já falhou, olha para o todo à espera de que ele ceda. O tempo passa e tem a aparência de trabalho. A voz que vem aqui tem duas formas: <i>não tenho jeito para isto</i>, ou <i>preciso ler mais antes de continuar</i>. Você reconhece o momento pelo giro: há algum tempo você não faz nada diferente do que fazia.",
  "Pare de girar. Pergunte por dentro: <i>o que exatamente eu não sei?</i> E escreva a resposta numa linha, em forma de pergunta, no caderno ou na folha de captura. Depois: <i>qual é a menor parte que posso fazer agora?</i> Um caso particular, um pedaço do problema, a parte que você já sabe resolver. Faça essa. Se, depois de algumas voltas assim, o impasse continuar, é hora de pedir a crítica de quem sabe mais, ou de fazer uma pausa com a pergunta escrita. Abandonar não está entre as saídas. E <i>não tenho jeito para isto</i> é uma sentença sobre o caráter, que nada diz sobre o problema; a resposta a ela é a menor parte, feita.",
  "Conto a você a história de um homem que viveu este impasse durante quinze dias. Henri Poincaré, o maior matemático francês do fim do século XIX, contou numa conferência, recolhida depois em <i>Ciência e método</i>, como fez uma de suas primeiras descobertas. Durante quinze dias, ele se esforçou para provar que não podia existir certa classe de funções, que depois chamaria de fuchsianas. Sentava-se todos os dias à mesa por uma ou duas horas, experimentava um grande número de combinações e não chegava a nada. Uma noite, contra o costume, tomou café preto e não conseguiu dormir; as ideias surgiam em multidão, e ele as sentia se chocar até que algumas se prenderam umas às outras. De manhã, tinha estabelecido a existência dessas funções. Pouco depois, deixou Caen, onde vivia, para uma excursão geológica, e as peripécias da viagem o fizeram esquecer o trabalho. Em Coutances, os viajantes subiram numa carruagem coletiva, puxada a cavalos, para um passeio. No instante em que Poincaré punha o pé no estribo, a ideia lhe veio, sem que nada nos pensamentos anteriores parecesse prepará-la: as transformações que ele usara para definir aquelas funções eram idênticas às da geometria não euclidiana. Não a verificou ali; retomou a conversa começada. Mas sentiu logo uma certeza completa. De volta a Caen, verificou a ideia com calma.",
  "A cena costuma ser contada em louvor do descanso, e o que há de verdade nisso tem sua Lição <font color='#6b6b6b'>(Lição III)</font>. Mas Poincaré tirou dela outra conclusão, e é essa que esta linha leva a sério. As iluminações súbitas, escreveu ele, só acontecem depois de alguns dias de esforços voluntários que pareceram absolutamente infrutíferos, e depois delas é preciso trabalho consciente de novo, para verificar e pôr em ordem o que veio. Os quinze dias em que ele não chegava a nada fizeram parte do trabalho, embora não se vissem.",
  "Daí se poderia concluir que, diante do impasse, o melhor é largar e esperar a ideia no estribo. Isso seria ler Poincaré pela metade. Ele largou depois de quinze dias de trabalho definido, sabendo exatamente o que procurava e onde falhava. A pergunta escrita desta linha faz esse papel. Quem a escreveu e fez a menor parte pode, sim, se levantar e caminhar, e o espírito continuará trabalhando sobre um problema com contorno. Quem larga o problema informe, sem tê-lo nomeado, não deu ao espírito nada sobre o que trabalhar durante a pausa. A pausa de que esta linha fala é a que vem depois da pergunta, nunca a que toma o lugar dela.",
  "Pólya, aliás, não foi o primeiro a dar o conselho da menor parte. Em 1637, no <i>Discurso do método</i>, Descartes conta como, jovem, num inverno na Alemanha, fechado sozinho num quarto aquecido por uma estufa, com todo o vagar para conversar com os próprios pensamentos, fixou as quatro regras com que decidiu conduzi-los. A segunda é quase a pergunta desta linha: dividir cada uma das dificuldades que examinasse em tantas parcelas quanto possível e quanto fosse preciso para melhor resolvê-las. A terceira a completa: começar pelos objetos mais simples e mais fáceis de conhecer, para subir pouco a pouco, como por degraus, até os mais compostos.",
  "A regra parece óbvia e, no entanto, é esquecida: diante do impasse, o espírito contempla o bloco inteiro e espera que ele ceda de uma vez. Dividir exige escrever, porque as parcelas não cabem na cabeça ao mesmo tempo que o todo."],
 porque=[
  "<b>A ideia.</b> George Pólya, matemático húngaro, escreveu em <i>A arte de resolver problemas</i> um conselho para quem trava: se você não consegue resolver um problema, resolva primeiro um menor que seja parente dele. O impasse vem quase sempre de um problema mal definido, ou grande demais para ser tomado inteiro. O espírito fica girando diante do todo, à espera de que ele ceda, e o tempo passa com a aparência de trabalho.",
  "<b>O mecanismo.</b> Primeiro, escrever o que exatamente você não sabe transforma uma ignorância vaga numa pergunta, e uma pergunta tem resposta possível. Escrita no papel, a dúvida deixa de voltar sempre ao mesmo ponto, como volta quando fica só na cabeça, e muitas vezes o ato de escrevê-la já mostra o caminho. Segundo, a menor parte faz a obra avançar e devolve informação: mostra por onde o problema cede e por onde resiste, coisa que a contemplação do todo nunca mostra. Nenhum estudo controlado testou esta linha; o que fica dito é razão de quem passou a vida resolvendo problemas, de Descartes a Pólya.",
  "<b>Por isso.</b> Escrevo a pergunta e faço a menor parte porque uma lacuna com nome tem resposta possível, e porque a parte pequena me mostra por onde o problema cede."])

linha("V", "Do fim", "Quando você julgar que terminou.", None,
 ["Está feito, ou está quase?", "O que faço primeiro amanhã?"],
 "Confira uma vez com o que você definiu ao começar. Escreva o primeiro passo de amanhã. Levante-se.",
 ["Esta também vem com o exercício do terminar, depois da primeira passagem, e por boa razão: quem aprende a não largar no meio tem de aprender também a não largar no último trecho. O momento é o fim de uma sessão, ou o que lhe parece o fim. Talvez venha um cansaço bom, e a obra tenha a aparência de feita. Vem a voz: <i>está bom assim</i>, <i>o resto reviso amanhã</i>, <i>falta tão pouco que não vale a pena agora</i>. Ou a contrária, se você é dos que nunca terminam: <i>ainda não está bom, mais uma volta</i>. Você reconhece o momento por um de dois sinais: você já se levantou por dentro, ou volta ao mesmo trecho sem mudar nada.",
  "Pergunte: <i>está feito, ou está quase?</i> E compare uma vez, só uma, com o que você escreveu ao começar, a resposta à primeira pergunta da linha I. Se o objeto prometido existe, está feito. Se falta um pedaço, está quase, e o quase se termina agora, enquanto a obra está quente: a segunda metade de <i>Isto, até acabar</i> quer dizer feito, e o quase ainda não acabou. Depois pergunte: <i>o que faço primeiro amanhã?</i>, e escreva a resposta numa linha; à noite, no caderno, ela passa a ser a primeira tarefa de amanhã, como diz <i>Do dia</i>, no Livro II. Levante-se. A sessão acaba por decisão sua, antes que o esgotamento a acabe por você.",
  "Há dois perigos no fim. O primeiro é parar no quase: a obra oitenta por cento pronta, que parece feita e ainda não está. O último trecho, a revisão, o acabamento, a conferência, é o mais tedioso, e é o que mais vezes fica por fazer. O segundo perigo é parar sem saber como recomeçar. Nesse caso, a manhã seguinte começa com névoa, e a névoa, como se viu na primeira linha, é o que mais adia. Hemingway, o romancista americano, conta em <i>Paris é uma festa</i>, as memórias de seus anos de juventude em Paris, publicadas depois de sua morte, que trabalhava sempre até ter alguma coisa feita e parava quando sabia o que ia acontecer em seguida, para ter certeza de continuar no dia seguinte. É o que faz a segunda pergunta desta linha: deixa escrito, antes que você se levante, o ponto por onde a manhã seguinte começa.",
  "Conto agora a você o aviso mais caro que conheço sobre o quase. Virgílio passou os últimos onze anos da vida escrevendo a <i>Eneida</i>. A biografia antiga dele que chegou até nós conta que trabalhava devagar: ditava de manhã um grande número de versos e passava o resto do dia reduzindo-os a muito poucos. Dizia, com graça, que dava forma ao poema como a ursa dá forma às crias, lambendo-as. No ano 19 antes de Cristo, partiu para a Grécia, decidido a passar três anos polindo o poema e a dedicar depois o resto da vida à filosofia. Encontrou Augusto em Atenas, resolveu voltar com ele, adoeceu na viagem e morreu em Brindisi. Antes de morrer, pediu que queimassem a <i>Eneida</i>, porque não estava acabada. Augusto proibiu a queima e mandou que dois amigos do poeta, Vário e Tuca, publicassem o poema como estava, sem acrescentar nada. Por isso ainda hoje se leem na <i>Eneida</i> versos cortados no meio, que Virgílio deixara para completar depois.",
  "Virgílio sabia o que faltava e tinha um plano para fazê-lo; deixou o acabamento para uma viagem, e a viagem não terminou. O poema se salvou porque um imperador desobedeceu ao poeta. Uma obra comum não conta com essa intervenção.",
  "Leonardo é o caso contrário, e mais próximo de nós. Vasari, que escreveu as vidas dos artistas no século seguinte, diz que ele começou muitas coisas e não acabou nenhuma, porque lhe parecia que a mão não podia alcançar a perfeição da arte que imaginava. Conta que Leonardo trabalhou quatro anos no retrato da mulher de Francesco del Giocondo e o deixou inacabado; e que, enquanto pintava a Última Ceia em Milão, ficava às vezes meio dia diante da parede, absorto, sem dar uma pincelada, a ponto de o prior do convento se queixar ao duque. E conta, no fim, que Leonardo, já doente, lamentou ter ofendido a Deus e aos homens por não ter trabalhado em sua arte como devia. Não se sabe se as palavras são dele; Vasari gostava de um bom fim. Mas Vasari as achou verossímeis na boca de Leonardo.",
  "Aristóteles abre a <i>Ética a Nicômaco</i> dizendo que toda arte e toda investigação, e do mesmo modo toda ação e toda escolha, parecem visar algum bem, e logo separa dois fins. Nas artes que fabricam, a <i>poíesis</i>, o fim é uma obra à parte da atividade; na ação, a <i>práxis</i>, o fim é agir bem, e a ação é seu próprio fim (I, 1; VI, 5, paráfrase). Esta linha trata a sessão como <i>poíesis</i>. Uma obra que fica no quase ainda não alcançou aquilo para que foi começada. A pergunta desta linha usa <i>télos</i> nos dois sentidos: compara o que existe com o que você prometeu na primeira linha, e esse prometido é o <i>télos</i> da sessão.",
  "Dizem que a obra boa nunca termina, que só é abandonada, e que exigir de cada sessão um <i>está feito</i> é se contentar com pouco. Há verdade nisso para a obra inteira: um livro, um ofício, uma vida nunca acabam de ser melhorados. Mas a pergunta desta linha é feita à sessão, com base num objeto que você mesmo definiu ao começar. O Leonardo de Vasari não tinha esse objeto: comparava cada pincelada com uma perfeição imaginada, e nenhuma pincelada aguenta essa comparação. A primeira linha serve também para isso: ao fixar antes o que deve existir quando você se levantar, ela dá ao fim uma medida que não é a perfeição. O retrato pode continuar sendo melhorado amanhã; o que se pediu hoje existe, ou não existe. E repare que o perfeccionismo e a pressa erram do mesmo modo: nenhum dos dois compara a obra com o que foi prometido."],
 porque=[
  "<b>A ideia.</b> Os gregos chamavam o fim de <i>télos</i>, e a palavra quer dizer ao mesmo tempo o término e o propósito, aquilo em que uma coisa acaba e aquilo para que ela existe. Aplicada a uma sessão, a ideia é simples: a sessão termina quando alcança aquilo para que foi começada. Esse propósito ficou escrito na primeira linha, na resposta a <i>o que deve existir quando eu me levantar daqui?</i>",
  "<b>O mecanismo.</b> Primeiro, comparar uma vez com um objeto que você mesmo definiu dá ao fim uma medida fechada, que se verifica num olhar: o objeto existe, ou lhe falta um pedaço. Uma medida assim impede tanto o quase quanto a volta sem fim ao mesmo trecho, porque não depende do cansaço nem de uma perfeição imaginada. Segundo, escrever o primeiro passo de amanhã deixa o recomeço decidido. Decidir antes que ação concreta você vai fazer num momento concreto aumenta a probabilidade de fazê-la, de forma consistente nos 94 testes reunidos por Peter Gollwitzer e Paschal Sheeran em 2006. A manhã seguinte começa sem névoa.",
  "<b>Por isso.</b> Comparo com o que prometi e escrevo o passo de amanhã porque uma medida fechada me diz se acabei, e porque um recomeço já escrito não me deixa nada a decidir de manhã."])

linha("VI", "Da falta de vontade", "Quando nada em você quiser começar.", None,
 ["Não preciso de vontade. Preciso do primeiro movimento.", "Qual é a versão de dois minutos?"],
 "Faça a versão de dois minutos: abra o caderno, calce o tênis, abra o livro na página marcada. Depois disso, você pode parar.",
 ["Esta é a outra linha de hoje, e pode ser pedida a você já nesta manhã, ou amanhã, ou num dia qualquer da primeira semana. Você se senta à mesa, a distração sai dela, e nada em você quer começar. Você ainda não trabalhou e, no entanto, tudo pesa, sem objeto preciso. É comum que o peso venha com uma frase razoável: <i>não estou com cabeça para isto</i>, ou <i>se começar assim vai sair ruim; espere até ter vontade</i>. Você reconhece o momento por um sinal exato: está esperando sentir vontade antes de se mexer.",
  "Diga por dentro: <i>não preciso de vontade; preciso do primeiro movimento</i>. E pergunte: <i>qual é a versão de dois minutos?</i> Responda com o menor gesto da obra de hoje (abrir o caderno na página, escrever a primeira frase, calçar o tênis) e faça esse gesto. Depois disso, você pode parar, e a permissão é verdadeira. Se parou ao fim dos dois minutos, cumpriu o que a linha pedia. Se continuou, repare, sem fazer disso uma vitória, em quando a vontade apareceu: quase sempre depois que você começou. Esta linha se encaixa assim com a frase de todas, <i>Isto, até acabar</i>, que você diz desde o dia um: a versão de dois minutos é a entrada, e é ela mesma um <i>isto</i> pequeno, que acaba ao fim dos dois minutos. Se você parou ali, terminou o que tinha se proposto. Se continuou, o <i>isto</i> passa a ser o que a primeira linha disse que tem de existir quando você se levantar, e a frase vale para ele. Nos dias seguintes, observe quantas vezes a permissão para parar fica sem uso. À noite, a marca é sobre a da vez, a microação da mesa, como <i>Do primeiro dia</i> ensinou; as linhas não se marcam.",
  "<i>Não preciso de vontade</i> tira da vontade o direito de voto. Ela pode estar presente, e é bem-vinda; mas já não decide. Nos dias de piso, o mínimo que se declara de manhã para a doença ou a viagem (as regras estão no Livro II, na seção <i>Do piso</i>), a versão de dois minutos é a maneira de começar esse mínimo, e o mínimo cumprido conta. O piso é para a circunstância; para a falta de vontade existe esta linha.",
  "Piotr Tchaikóvski trabalhou a vida inteira sem esperar a vontade, e falou disso, por carta, a uma mulher com quem nunca chegou a conversar. Nadejda von Meck, viúva rica, o sustentou durante treze anos com uma pensão anual, e os dois combinaram não se conhecer pessoalmente; em vez disso, trocaram mais de mil cartas. Numa delas, em 1878, ela lhe perguntou como compunha, e se esperava pela inspiração. Ele respondeu, em substância, que a inspiração é uma visita que não gosta de visitar os preguiçosos; que se sentava ao trabalho todas as manhãs, quisesse ou não; e que um artista que se respeita não pode cruzar os braços sob o pretexto de não estar disposto, porque quem espera pela disposição sem ir ao encontro dela cai depressa na indolência. Às vezes, contava, começava sem vontade nenhuma e só no meio a coisa se acendia; outras vezes não se acendia, e ele trabalhava mesmo assim, e em outro dia ela voltava a se acender (paráfrase das cartas).",
  "Tchaikóvski viveu atormentado por crises de melancolia e por dúvidas sobre o próprio valor, e por isso o testemunho dele pesa. Ele aprendera que o sentimento chegava atrasado e que, se o esperasse para começar, raramente começaria.",
  "Aristóteles disse a coisa mais simples sobre isso, no segundo livro da <i>Ética a Nicômaco</i>: nós nos tornamos justos praticando atos justos, temperantes praticando atos temperantes, corajosos praticando atos corajosos. É como nas artes, em que alguém se torna construtor construindo e citarista tocando a cítara. A ordem das palavras conta. Ele diz que é praticando os atos justos que alguém se torna justo; o ato vem antes da disposição que depois o tornará fácil. Aristóteles chama essa disposição de <i>héxis</i>, o modo de ser que os atos repetidos deixam em quem os faz, e o livro seguinte volta a ela. Nesta manhã, a vontade de escrever é a disposição que você ainda não tem, e a versão de dois minutos é um dos atos que a formam.",
  "Pascal levou a mesma ideia a um lugar mais desconfortável, no fragmento da aposta que <i>Da máscara</i> também conta. Ao homem que a razão já convenceu e que não consegue crer, ele manda fazer como os que se curaram, água benta e missas, porque o costume dobra as paixões que o argumento não alcança. Somos autômato tanto quanto espírito, e quem espera crer para agir deixa de fora metade de si. O fim de Pascal era a fé, que ele tinha por dom de Deus, e o costume servia para abater o orgulho; aqui, o costume serve à obra que você escolheu. Fora da fé, a ideia se aplica a esta linha: o gesto de abrir o caderno, repetido nas manhãs sem vontade, ensina ao corpo o caminho da obra, e a vontade vem atrás dele.",
  "Resta uma objeção: agir sem vontade seria falso. Quem não quer escrever e escreve estaria traindo a si mesmo, vivendo contra si, como o homem de Pascal que toma água benta sem crer. É a objeção mais séria a esta linha, e vem de um lugar respeitável: a ideia de que o autêntico é o que se sente, e o resto é máscara. Aceite a palavra. <i>Persona</i>, como <i>Da máscara</i> vai contar, era a máscara por onde passava a voz do ator, e deu origem a <i>pessoa</i>; o homem de Pascal põe uma máscara para que o rosto tome a forma dela, e você, ao escrever sem vontade, põe a do homem da sua visão. A folha que você tem na primeira página do caderno também responde a essa objeção. Nela você escreveu, de cabeça fria, durante um dia inteiro, quem quer ser, e escreveu isso em atos. A falta de vontade desta manhã é um estado de algumas horas; a folha é o que você disse querer depois de olhar sua vida de frente. Se uma das duas é a sua voz verdadeira, não é a do humor da manhã. Obedecer ao humor contra a folha é trair o que você escreveu naquele dia. E o sentimento, muitas vezes, chega depois e dá razão ao ato <font color='#6b6b6b'>(Lição VII)</font>."],
 porque=[
  "<b>A ideia.</b> William James, um dos fundadores da psicologia americana, contou como se levantava nas manhãs frias: ficava deliberando debaixo das cobertas e, a certa altura, se via já com os pés no chão, antes que a mente acabasse de decidir, e só depois chamava isso de decisão. A vontade quase sempre chega depois do começo. Quem espera estar disposto para se mexer está esperando o efeito antes da causa. <font color='#6b6b6b'>(Lição VII)</font>",
  "<b>O mecanismo.</b> Primeiro, a maior parte da resistência está no começo, e a versão de dois minutos reduz o custo de entrada a quase nada; fazer um gesto tão pequeno custa menos do que discutir se você vai fazê-lo. Segundo, a permissão de parar ao fim dos dois minutos tira da falta de vontade o argumento de que o dia inteiro está em jogo. Essa permissão tem de ser verdadeira, ou o espírito não acredita nela, e é por ser verdadeira que muitas vezes fica sem uso. Nenhum estudo testou a regra dos dois minutos; o que fica dito é razão, coerente com o que se sabe sobre começar pequeno e repetir.",
  "<b>Por isso.</b> Faço a versão de dois minutos porque posso mesmo parar depois dela."])

linha("VII", "Da escolha", "Quando muitas coisas pedirem e você não souber qual.", None,
 ["Qual delas eu evitaria, se pudesse?", "Essa."],
 "E volte à primeira linha.",
 ["Esta chega com o exercício do terminar, quando as coisas começadas já se acumulam, e é diante delas que ela serve. O momento vem muitas vezes de manhã, ou depois de uma interrupção. Há cinco coisas pedindo atenção ao mesmo tempo, e você não sabe qual pegar. Anda de uma para outra, abre uma, se lembra de outra, compara. A voz, desta vez, tem o tom de um bom administrador: <i>despacho primeiro as pequenas, para ficar com a cabeça livre</i>, ou <i>antes de tudo, uma lista de prioridades</i>. Você reconhece o momento pela comparação que não acaba.",
  "Pergunte por dentro: <i>qual delas eu evitaria, se pudesse?</i> A resposta costuma vir depressa, e é desagradável. Diga <i>essa</i>. Depois volte à primeira linha (o que deve existir quando você se levantar, qual é o primeiro movimento) e comece. A comparação acabou. Se entre as cinco há uma urgência real, com prazo, ela vence, e a pergunta se faz depois dela.",
  "Conto a você a história de um homem que adiou vinte anos sem nunca estar parado. Charles Darwin teve a ideia central de sua vida no outono de 1838, aos vinte e nove anos, ao ler Malthus, como ele mesmo conta, por distração. Em 1842, escreveu um esboço a lápis de trinta e poucas páginas; em 1844, um ensaio de mais de duzentas, e deixou para a mulher uma carta pedindo que ela o publicasse se ele morresse, com quatrocentas libras para as despesas. Depois guardou o ensaio. Nos anos seguintes, fez de tudo: livros de geologia, a revisão do diário da viagem do <i>Beagle</i> e, sobretudo, oito anos inteiros estudando cracas, que dissecava em Down House, até escrever a um amigo que odiava uma craca como nenhum homem jamais odiara. Tudo isso era trabalho sério, e útil. Tudo isso o afastava do único livro que ele temia escrever. A Joseph Hooker ele confessara, em 1844, que dizer que as espécies não são imutáveis era como confessar um assassinato.",
  "Em 1856, a conselho de Lyell, começou enfim o grande livro, devagar, com a intenção de torná-lo exaustivo. Em junho de 1858, chegou a ele pelo correio uma carta de Alfred Russel Wallace, um naturalista que trabalhava nas ilhas do arquipélago malaio, com um manuscrito curto. Era a mesma teoria. Darwin escreveu a Lyell que nunca vira coincidência mais impressionante, e que, se Wallace tivesse o esboço dele de 1842, não teria feito resumo melhor. Os amigos organizaram, em julho, a leitura conjunta dos dois textos na Sociedade Lineana de Londres. E Darwin, que adiara vinte anos, escreveu em pouco mais de um ano <i>A origem das espécies</i>, que saiu em novembro de 1859 e que ele chamava de resumo.",
  "Nos vinte anos de adiamento, Darwin trabalhou mais do que quase todos os homens de seu tempo, e a armadilha estava justamente aí. Quando há muitas coisas boas a fazer, o adiamento dispensa a preguiça: basta escolher sempre outra coisa boa, e a mais temida fica esperando. A pergunta <i>qual delas eu evitaria?</i> teria apontado para a gaveta de Darwin em qualquer manhã daqueles anos.",
  "Há uma velha imagem para a indecisão, o asno de Buridano. Um asno igualmente faminto e igualmente distante de dois montes de feno iguais não teria razão para preferir um ao outro e morreria de fome entre eles. A imagem tem o nome de João Buridano, mestre de Paris no século XIV, mas não se encontra nos escritos dele; deve ter nascido como sátira à doutrina dele sobre a vontade. Essa doutrina dizia, em resumo, que a vontade segue o juízo do intelecto sobre qual dos bens é maior, e que pode suspender a escolha enquanto esse juízo não vem. O asno leva a doutrina ao absurdo, porque entre dois bens iguais o juízo nunca viria. O problema é mais antigo. Aristóteles já fala, no tratado <i>Do céu</i>, do homem igualmente faminto e sedento, posto a igual distância da comida e da bebida, que por isso ficaria parado. É o que a comparação que não acaba faz com você diante das cinco coisas: você espera que ela lhe dê a razão para escolher, e, enquanto espera, nada se faz.",
  "A linha desfaz o asno recusando a igualdade. Entre as coisas que lhe pedem atenção, raramente há dois montes iguais. Quase sempre há um que pesa mais, por assustar mais, e a resistência raramente empata. O asno morreria de simetria; quem está diante de muitas tarefas costuma se perder de outro modo, escolhendo sempre o monte mais perto, como Darwin escolhia as cracas, e chamando isso de prioridade.",
  "Você vai dizer que Darwin fez bem: que as cracas lhe deram o conhecimento das variações que sustentou o livro, que vinte anos de espera o tornaram mais sólido, e que esta linha, aplicada a ele, teria produzido um livro mais cedo e pior. É possível, e os historiadores discutem até hoje quanto o adiamento lhe serviu. Mas repare no que a objeção concede: ele precisou de uma carta vinda do outro lado do mundo para fazer o que sabia ser o trabalho dele. Sem Wallace, ninguém sabe quando a gaveta se abriria. E a nota desta linha responde ao resto: a bússola vale entre coisas que importam, e a preparação que serve à obra temida faz parte dela. A pergunta não manda pular a preparação. Manda verificar, com honestidade, se aquilo ainda serve à obra temida ou se já só a adia."],
 "A bússola vale entre coisas que importam. Se há uma urgência real, com prazo, ela vence. E nenhum desconforto se torna dever só por ser desconfortável.",
 porque=[
  "<b>A ideia.</b> Entre coisas que parecem igualmente boas, a comparação não tem fim natural, porque cada uma tem razões a seu favor. Aristóteles já descrevia, no tratado <i>Do céu</i>, quem fica parado entre duas necessidades iguais. Diante de muitas tarefas, a comparação muitas vezes serve para fugir da que mais importa: enquanto se compara, nada se faz, e a mais temida fica esperando.",
  "<b>O mecanismo.</b> Primeiro, a pergunta troca um critério que empata por um que quase nunca empata. A importância e a urgência se discutem sem fim; a resistência se sente numa resposta rápida, e entre cinco coisas raramente há duas que assustem por igual. Segundo, o que pesa costuma ser o que importa, porque o que é fácil já teria sido feito; e <i>essa</i>, uma palavra só, fecha a deliberação antes que ela recomece. Isso vale entre coisas que importam, e uma urgência com prazo vence. Nenhum estudo testou esta pergunta; o que fica dito é razão.",
  "<b>Por isso.</b> Escolho a que evitaria porque a resistência decide depressa onde a importância empata, e porque o que pesa costuma ser o que ainda não fiz por ser difícil."])

linha("VIII", "Da estratégia", "Quando você for começar algo novo: um projeto, um estudo, um ofício, até um passatempo.",
 "<font color='#6b6b6b'><i>\u201cO guerreiro vitorioso vence primeiro, e só depois vai à guerra.\u201d &nbsp;\u2014 Sun Tzu</i></font><br/>Nada avulso. Antes de entrar, uma folha e quatro perguntas:",
 ["O que exatamente eu quero com isto?", "Qual é o terreno?", "Qual é o sistema?", "Qual é o primeiro movimento, e até quando pesquiso?"],
 "Marque o prazo da pesquisa antes de abrir a primeira página. Vencido o prazo, faça o primeiro movimento com o que você sabe.",
 ["Esta pode ser pedida a você já nos primeiros dias, porque ninguém sabe quando vai ter vontade de começar uma coisa nova. O livro não sabe o que será; você saberá quando vier. O momento se reconhece por um calor particular: você leu, ouviu ou pensou em alguma coisa, e quer começá-la já. A voz, desta vez, é entusiasta: <i>comece hoje, depois você vê</i>. Ou, se você é do outro feitio, ela aparece prudente: <i>antes de começar, preciso saber tudo sobre isto</i>. As duas levam ao mesmo lugar: a primeira dificuldade que ninguém previu, ou o começo que nunca chega.",
  "Antes de entrar, pegue uma folha e escreva as quatro perguntas, com uma resposta curta para cada uma. Depois marque o prazo da pesquisa (uma sessão, uma hora no máximo para coisas pequenas) antes de abrir a primeira página sobre o assunto. Quando o prazo vencer, faça o primeiro movimento com o que souber, e o resto se aprende no terreno. Se o que você tem à frente é a obra que já decidiu, vale a primeira linha, e esta fica de lado.",
  "O impulsivo começa muitas coisas e as abandona quando a primeira dificuldade aparece, porque não sabia que ela viria. <i>Qual é o terreno?</i> pergunta o que já existe, quem faz isso bem, quais são as regras, e poupa erros que outros já cometeram por você. A quarta pergunta amarra a estratégia ao ato.",
  "Nenhuma pesquisa dissipa a névoa inteira. Carl von Clausewitz, general prussiano que combateu nas guerras contra Napoleão e passou os últimos anos escrevendo <i>Da guerra</i>, lembrava que a guerra é o domínio da incerteza, e que três quartos do que sustenta a ação ficam sempre encobertos por uma névoa mais ou menos espessa. Daí ele tirava a necessidade de um juízo treinado, capaz de agir dentro dela. Quem espera ver tudo antes de agir chama a espera de prudência, e a pesquisa sem prazo é essa espera. <font color='#6b6b6b'>(Lição VI)</font>",
  "No verão austral de 1911, duas expedições partiram para o polo sul. A do norueguês Roald Amundsen chegou em 14 de dezembro e voltou sem perder um homem. A do inglês Robert Falcon Scott chegou em 17 de janeiro de 1912, encontrou a barraca que os noruegueses tinham deixado lá e morreu inteira no caminho de volta; os três últimos homens foram encontrados na barraca deles, a cerca de dezoito quilômetros de um depósito de provisões. Coragem não faltou a nenhum dos dois. A diferença esteve no conhecimento do terreno.",
  "Amundsen passara anos aprendendo o gelo. Na viagem do <i>Gjøa</i> pela passagem do noroeste, entre 1903 e 1906, passou o inverno junto dos inuítes netsilik, no Ártico canadense, e aprendeu com eles a vestir peles em vez de lã e a conduzir cães. Copiou os meios de quem já vivia no gelo, sem discuti-los, e o fim continuou sendo dele: os netsilik viviam no Ártico, e ele queria o polo. É assim que se copiam os meios de quem domina o terreno, ainda que essa pessoa não queira o que você quer: copiam-se os atos que levam aonde você decidiu ir, e nunca o fim dela. O seu fim vem da sua visão, aquela que passou no dia zero pelo teste de <i>quero isto, ou quero ser visto com isto?</i> Para o sul, Amundsen levou cães e esquiadores experientes. Deixou depósitos ao longo do caminho e os marcou com fileiras de bandeiras atravessadas na rota, para que um pequeno erro de navegação na volta não o fizesse passar ao lado deles sem vê-los. Calculou de antemão quantos cães seriam abatidos em cada etapa para alimentar os outros e os homens. Scott, que tinha também fins científicos e merece mais justiça do que a comparação costuma lhe dar, confiou sobretudo em pôneis, que não aguentaram o frio, e acabou puxando os trenós com a força dos homens. Amundsen escreveu depois, no relato da expedição, que a vitória espera quem tem tudo em ordem, e as pessoas chamam isso de sorte, e que a derrota é certa para quem deixou de tomar a tempo as precauções necessárias, e a isso chamam azar.",
  "Mas os planejadores sérios também conheceram o limite do plano. O marechal prussiano Helmuth von Moltke, que preparou as guerras de seu país com um cuidado que ficou lendário, deixou escrito que nenhum plano de operações vai, com alguma segurança, além do primeiro encontro com a força principal do inimigo, e que a estratégia é um sistema de expedientes. Ele não concluía daí que fosse inútil planejar. Concluía que o plano serve para pôr em marcha e para preparar o juízo, e que depois do primeiro contato é preciso se adaptar ao que o terreno revela. É o que a quarta pergunta pede: um primeiro movimento e um prazo para a pesquisa, sabendo que o resto se aprende pisando no terreno.",
  "Aristóteles fez, no terceiro livro da <i>Ética a Nicômaco</i>, uma observação que esta linha pressupõe. Não deliberamos sobre os fins, diz ele, mas sobre os meios. O médico não delibera se vai curar, nem o orador se vai persuadir. Eles pressupõem o fim e examinam como e por que meios alcançá-lo: se há vários, por qual se chega mais fácil e melhor; se há só um, como se chega a ele, e a esse por meio de quê, até chegarem à primeira causa, que é a última a ser encontrada. Aristóteles compara isso à análise dos geômetras e conclui que o último na análise é o primeiro na execução.",
  "Tudo isso pode parecer uma forma refinada de adiar: planejar dá a sensação do trabalho sem o custo dele, e o impulsivo, ao menos, começa. A suspeita acerta contra muito do que passa por planejamento, e a nota desta linha diz isso em menos palavras. Mas duas coisas separam a estratégia do adiamento. A primeira é o prazo, marcado antes de abrir a primeira página; sem ele, a pesquisa não tem fim natural, porque há sempre mais uma coisa a saber. A segunda é que a estratégia termina num movimento, e o adiamento termina em outro plano. Amundsen planejou durante anos, e em outubro de 1911 saiu com os trenós para o sul. Uma folha com quatro respostas, feita numa sessão, é estratégia. Seis semanas de leituras sobre como começar um ofício, sem nunca praticá-lo, são adiamento.",
  "O próprio caderno começou assim. O dia zero foi a folha de estratégia da sua vida: a anti-visão e a visão disseram o que você queria, as perguntas da manhã mostraram o terreno, as alavancas e a microação da vez são o sistema, e o dia um é o primeiro movimento. Esta linha é a mesma folha em ponto pequeno."],
 "Pesquisa sem prazo é uma forma de adiamento. Esta linha vale para o que é novo; para o que já foi decidido, vale a primeira.",
 porque=[
  "<b>A ideia.</b> A frase de Sun Tzu no alto desta linha vem de <i>A arte da guerra</i>, o tratado chinês de estratégia que a tradição atribui a um general do século VI antes de Cristo. No trecho de onde ela sai, Sun Tzu opõe o exército vitorioso, que primeiro se põe em condições de vencer e só depois procura a batalha, ao derrotado, que primeiro combate e só depois procura a vitória. A vitória, para ele, se decide na preparação, no conhecimento do terreno e das próprias forças, e o combate a confirma. Por isso a frase abre a linha do que é novo, em que a folha das quatro perguntas é essa preparação. Aristóteles observou, no terceiro livro da <i>Ética a Nicômaco</i>, que quem delibera fixa primeiro o fim e só depois examina os meios, descendo de meio em meio até o primeiro gesto, que é o último a ser encontrado e o primeiro a ser feito. As quatro perguntas seguem essa ordem: o fim; o terreno e o sistema, que são os meios; e o primeiro movimento, com o prazo que fecha a pesquisa.",
  "<b>O mecanismo.</b> Primeiro, fixar o fim antes dos meios impede a deliberação em círculos, em que cada meio parece bom para um fim diferente, e separa o objetivo da excitação do começo. Segundo, o prazo dá à pesquisa um fim que ela não tem por natureza, e a pergunta do sistema dá à prática uma hora e um lugar. Isso conta, porque os hábitos são respostas disparadas pelas pistas do contexto, como mostrou a psicóloga Wendy Wood. Uma prática repetida no mesmo lugar e na mesma hora acaba se fazendo quase sozinha; sem hora nem lugar, depende do entusiasmo do começo.",
  "<b>Por isso.</b> Escrevo as quatro respostas e marco o prazo porque, com o fim fixado, a pesquisa deixa de andar em círculos e acaba num dia certo, e porque uma prática com hora e lugar continua depois de passar o entusiasmo."])

linha("IX", "Da onda", "Quando vier a vontade daquilo que você cortou.", None,
 ["É a onda.", "Ela sobe, e passa.", "O que faço com as mãos agora?"],
 "Faça o gesto que você pôs no lugar. Levante-se, mude de cômodo, vá à paixão contrária. Não discuta com a vontade: espere que ela passe, fazendo outra coisa.",
 ["Esta é a última, e você só vai usá-la no dia em que traçar o primeiro corte, de que trata o Livro IV: deixar de uma vez um hábito que desfaz o que os exercícios fazem, com uma linha escrita e assinada. Você lê isto agora, nos primeiros dias, para conhecê-la antes de precisar dela. Neste livro, chama-se onda a vontade súbita daquilo que você decidiu deixar. Conto a você como ela costuma vir. Passaram-se horas, ou dias, desde o corte. Você está fazendo outra coisa e, sem aviso, a vontade do que você deixou está ali. Muitas vezes ela chega na hora que o hábito costumava ocupar, ou num lugar que o lembra, ou num estado em que ele era o seu consolo: o cansaço do fim da tarde, o tédio, uma contrariedade. É comum que comece no corpo antes de chegar às palavras: uma inquietação nas mãos, a atenção que se estreita, o olhar que vai ao lugar onde a coisa estava. Depois chegam as palavras, e são das mais hábeis que você vai ouvir: <i>só hoje</i>; <i>uma vez não conta</i>; <i>você já aguentou tantos dias, merece</i>; <i>isto não vai passar, mais vale acabar com isto já</i>. A vontade sobe, e tudo nela afirma que vai continuar subindo. Você reconhece a onda por esse conjunto: um desejo súbito, dirigido ao que você cortou, com pressa, e com razões que já chegam prontas.",
  "Diga por dentro: <i>é a onda</i>. Não responda às razões dela. Diga: <i>ela sobe, e passa</i>. E pergunte: <i>o que faço com as mãos agora?</i> Responda com o gesto que você pôs no lugar do hábito quando traçou o corte, e faça esse gesto já: levante-se, mude de cômodo, vá à paixão contrária, a ocupação maior que o Livro IV vai lhe ensinar a pôr nas horas que o hábito deixou vazias. Se o caderno estiver à mão, abra-o na primeira página e leia a frase da anti-visão, o primeiro ponto da folha; a onda é uma das duas ocasiões em que ela se lê. Diga o estribilho, como <i>Do uso</i> já pedia para este momento. Enquanto você faz isso, a vontade continua lá, talvez ainda subindo, e você não tem de calá-la; tem só de não obedecer enquanto as mãos estão ocupadas. Em algum ponto, muitas vezes ao fim de poucos minutos, ela chega ao alto e começa a descer. Raramente se percebe esse instante. Ele é percebido depois, quando você nota que há algum tempo está pensando em outra coisa. Quando perceber isso, não volte a olhar para ela para confirmar que passou; continue o que as mãos estavam fazendo. À noite, o livro não sabe o que aconteceu. Se você a atravessou, o dia continua limpo. Se obedeceu, o Livro IV diz o que se escreve, e começa por <i>caí; a linha continua</i>, e no dia seguinte não pode haver outra queda.",
  "Pergunta-se <i>o que faço com as mãos?</i> porque a onda se atravessa fazendo; resistir parado é ficar olhando para a tentação. Cada onda atravessada sem obedecer torna a próxima mais fraca. Epicteto, como o Livro IV vai contar, mandava contar os dias em que não se cedeu, porque o hábito definha quando lhe negam o alimento, e cada onda atravessada é um desses dias contados.",
  "Aulo Gélio, um romano do século II que passou a vida recolhendo histórias e citações, conta nas <i>Noites áticas</i> uma travessia que fez de Cássiope, em Corcira, para Brindisi. No mar Jônio, de noite, levantou-se uma tempestade violenta, e o navio se encheu de água. Viajava a bordo um filósofo da escola estoica, homem de algum renome, que Gélio conhecera em Atenas. Durante a tormenta, Gélio o observou: estava pálido e assustado, embora não chorasse nem gritasse como os outros. Quando o mar se acalmou, um grego rico da Ásia, homem de muito luxo, lhe perguntou com ironia como um filósofo podia ter tido medo e empalidecido, enquanto ele próprio ficara sem medo nenhum. O estoico respondeu com a réplica que Aristipo, discípulo de Sócrates, dera em outra tempestade a um homem do mesmo tipo: você não tinha razão para se inquietar pela vida de um homem sem valor; eu temia pela vida de Aristipo. Era uma graça para despachar o rico, como quem diz que uma vida vazia tem pouco a perder; a explicação séria, o filósofo a guardou para quem a pedisse a sério. Mais tarde, quando Gélio lhe perguntou a sério, ele tirou da bagagem um livro dos <i>Discursos</i> de Epicteto, que não chegou até nós, e lhe mostrou uma passagem.",
  "A passagem dizia, em substância, o seguinte. As impressões do espírito, que os filósofos chamam de <i>phantasíai</i>, não dependem da vontade. Quando algo terrível acontece (um estrondo no céu, a queda de um edifício, a notícia súbita de um perigo), até o sábio é abalado por um instante, empalidece, se contrai, não por julgar que há ali um mal, mas por movimentos rápidos que se antecipam à razão. O sábio, porém, não aprova essas impressões nem lhes acrescenta sua opinião: ele as rejeita, e não vê nelas nada a temer. O insensato julga que elas são o que parecem, as aprova e as confirma com seu juízo. O filósofo do navio empalidecera, portanto, e não se envergonhava disso. O que ele não fizera era concordar com a palidez.",
  "O estoico sente, e sente no corpo, como talvez você sinta a onda no corpo; a diferença está no que vem depois. Quando a vontade do que você cortou vier e o corpo inteiro a pedir, não conclua, por sentir, que o corte falhou. Você estará no lugar do filósofo no navio, abalado e sem obedecer.",
  "Sêneca, no segundo livro <i>Da ira</i>, dá nome a essa experiência. Há movimentos que nos acontecem sem nossa vontade, e que por isso nem a razão vence: o arrepio de quem é salpicado de água fria, o recuo diante de certos contatos, o cabelo que se eriça com uma má notícia, o rubor que sobe às faces com palavras indecentes, a vertigem de quem olha de um precipício. Sêneca os chama de primeiros movimentos, e eles ainda não são paixão. A paixão começa quando o espírito, depois do primeiro abalo, consente nele e o segue. O primeiro movimento não se evita; o segundo, sim, e é nele que mora a responsabilidade. A onda é um primeiro movimento. Você não escolheu que ela viesse, e nenhum corte, por firme que seja, a impede de vir durante algum tempo. <i>É a onda</i> é a frase de quem reconhece o primeiro movimento como primeiro movimento, sem confundi-lo com uma decisão já tomada.",
  "Isso pode parecer só reprimir: segurar a vontade à força, de dentes cerrados, até ela estourar mais adiante. A repressão existe, e falha muitas vezes. Mas a linha pede outra coisa. Reprimir é lutar contra a vontade, negar que ela está ali, empurrá-la para baixo. A linha começa por admitir que ela está ali, e lhe dá nome. Não manda deixar de senti-la; manda deixar de obedecer a ela, enquanto as mãos fazem outra coisa. Sêneca não esperava que o sábio deixasse de se arrepiar com a água fria. Queria que o arrepio não decidisse por ele. A diferença se vê no corpo: quem reprime está tenso, de olhos fixos na vontade; quem atravessa a onda tem as mãos ocupadas em outra coisa."],
 "Quando a onda não passa, ou passa e vence sempre, vale aqui a nota com que fecha o Livro IV.",
 porque=[
  "<b>A ideia.</b> Alan Marlatt, psicólogo americano que estudou recaídas nas dependências, descreveu a vontade de voltar a um hábito como uma onda: ela sobe, chega a um pico e desce, quase sempre em minutos, embora, enquanto sobe, pareça que vai subir para sempre. Com seus colaboradores, ensinou a <i>surfar o impulso</i>: observá-lo no corpo, sem obedecer e sem lutar, até que passe. A vontade que volta depois de um corte é o hábito ainda se manifestando, e o corte não falhou por isso.",
  "<b>O mecanismo.</b> Primeiro, chamar a vontade de onda a trata como um estado que passa, e por isso você não precisa vencê-la, só não obedecer a ela durante alguns minutos. Num estudo de Sarah Bowen e Marlatt com estudantes fumantes, a instrução de observar a vontade não a fez diminuir, mas quem a recebeu fumou menos nos sete dias seguintes; os autores chamam isso de dados preliminares. Segundo, as mãos ocupadas dão à atenção outro objeto. Daniel Wegner mostrou que proibir um pensamento, sozinho, o faz voltar com mais força, e que uma alternativa decidida de antemão reduz esse rebote; o Livro IV conta o estudo.",
  "<b>Por isso.</b> Faço o gesto que pus no lugar porque a vontade sobe e desce em minutos se eu não lhe obedecer, e porque com as mãos ocupadas a atenção tem para onde ir."])

sec("Da ordem das linhas")
add("Com que exercício chega cada linha, a abertura deste livro disse. Uma linha está aprendida quando você a percebe em si sem ter precisado se lembrar dela.", PI)
add("Quando chegar a primeira passagem, você terá dito a primeira e a sexta linhas dezenas de vezes, e algumas vezes elas terão funcionado sem que você percebesse. Outras vezes, não. É provável que você comece bem às nove e largue às dez; que volte de uma dispersão para cair em outra; que tenha um dia inteiro em que as frases vêm sozinhas e, no seguinte, nenhum instante em que se lembre de linha alguma. Conheço essa irregularidade, e sei de onde ela vem.", PI)
add("Baudelaire a conheceu por dentro. Nos cadernos íntimos que deixou sem publicar, e que só saíram anos depois com os títulos de <i>Fusées</i> e <i>Mon cœur mis à nu</i>, há umas páginas a que ele deu o nome de <i>Higiene</i>, escritas por volta de 1862, quando <i>As flores do mal</i> já tinham saído e ele devia dinheiro a meio Paris. Nelas ele jura tomar por regras eternas da sua vida coisas simples: trabalhar todos os dias, ao menos tanto quanto as forças deixassem, e preferir o trabalho imediato, mesmo ruim, ao devaneio. Escreve que uma série de pequenas vontades faz um grande resultado, e que, para se curar de tudo, só lhe faltava o gosto do trabalho (paráfrase). O homem que escreveu isso sabia governar o instante como poucos, e refez poemas d’<i>As flores do mal</i> verso a verso durante anos. O que nunca chegou a ter foi o dia. Mudava de quarto para fugir dos credores, trabalhava quando calhava, perdia semanas, e as mesmas resoluções voltam nos cadernos quase com as mesmas palavras, sinal de que não se cumpriam. Tinha as frases certas, e faltava a elas uma moldura que as trouxesse de volta todas as manhãs.", PI)
add("As linhas governam o instante, e um dia não é feito só de instantes. É feito também do que os liga: a hora em que se acorda, o que se faz primeiro, o que se marca à noite, o que acontece depois de uma queda, quantas coisas se abrem ao mesmo tempo, quando se dorme. Um instante bem governado num dia sem forma se perde como uma frase certa numa conversa confusa.", PI)
add("Os instantes precisam, portanto, de uma moldura: uma lei que diga o que nunca se faz, e um dia que diga quando cada coisa acontece. É dessa moldura que trata o livro seguinte, que você vai ler nos primeiros dias, fora das horas da obra. A parte <i>De manhã</i> desse livro, você a lê numa destas noites antes do dia zero, para fazê-la desde a manhã do dia um.", PI)

add("O livro seguinte supõe que você diga de cor as frases da linha I e da linha VI; se ainda não diz, releia-as numa das noites antes do dia zero, e outra vez na manhã do dia um. As outras linhas chegam com os exercícios que a abertura deste livro nomeia.", PI)
# O fecho vai junto do parágrafo anterior, para não ficar sozinho numa página.
st[-2:] = [KeepTogether(st[-2:])]
# ===================== LIVRO II =====================
livro("II", "Da lei e do dia")

add("As leis e o dia arrumam o tempo em volta da obra, para que, na hora em que você se sentar, tenha uma coisa só à frente e nada que a interrompa. O estado de foco de que fala <i>Da assentada</i> precisa de um dia assim para caber.", PI)
add("Deste livro, <i>De manhã</i> se lê numa das noites antes do dia zero, e <i>À noite</i> na noite do dia um, antes da primeira marca; o resto, nos primeiros dias, fora das horas da obra, começando pelas nove leis. Você sai dele fazendo a manhã e a noite sem abrir o livro.", PI); add("Volte a ele na noite de uma cruz, para a quarta e a quinta leis; na manhã em que acordar doente ou em viagem, para <i>Do piso</i>; e quando o cansaço atravessar as noites, para <i>Do descanso</i>.", PI)
add("Talvez seja o segundo dia, talvez o quarto. As linhas já fizeram algum trabalho no instante: a primeira ao sentar, a sexta quando nada em você queria começar. Mas, como diz o fim do Livro I, os instantes não se lembram uns dos outros, e falta o que os junta num dia, e cada dia ao seguinte.", PI)
add("Para começar, vou lhe contar de um homem que resolveu isso para outros. Por volta do ano 529, num monte entre Roma e Nápoles, Bento de Núrsia reuniu alguns monges sobre as ruínas de um templo antigo e escreveu uma regra para eles. Pediu-lhes duas coisas que quem tenta mudar sozinho quase nunca tem: umas poucas leis que não se discutem, e um horário que diz quando cada coisa acontece. A oração tinha horas; o trabalho, a leitura, a refeição e o sono tinham as suas. O monge de Monte Cassino não precisava decidir, a cada manhã, se ia rezar, nem lembrar a que horas: a lei o poupava da deliberação, e o sinal o poupava da memória. Quinze séculos depois, a regra ainda governa mosteiros.", PI)
add("Este trecho do caminho é plano e longo, e nele você aprende a andar todos os dias no mesmo passo. Ele lhe dá o que Bento deu aos monges. Primeiro, nove leis, curtas, escritas para serem lembradas sem esforço e cumpridas sem discussão. Depois, o dia, com seus momentos fixos. Por fim, o que sustenta os dois, dia após dia: o descanso, o piso para os dias ruins e a companhia dos livros. Quando uma lei lhe parecer dura, procure o que ela protege: é o que se perdeu nas tentativas anteriores.", PI)
st.append(CondPageBreak(5*cm))  # a § 1 não se parte; sem isto o título fica sozinho no pé da página
sec("Da lei")
add("Uma lei, neste livro, é uma frase que não se discute durante o dia: ela se discute aqui, uma vez, de cabeça fria. Cada uma vem em negrito, para que você a encontre depressa quando estiver cedendo. Embaixo vem <i>Do porquê</i>, com a ideia, o mecanismo e a frase que você diz por dentro ao cumpri-la; depois, o momento do caminho em que ela vai lhe servir, e a história de onde ela vem.", PI)
leis = [
 ("Uma só microação nova de cada vez, e na ordem.",
  "A regra está na primeira de <i>Da medida</i>, no capítulo <i>Do primeiro dia</i>; a razão dela ficou dita acima.",
  ["O momento desta lei costuma vir cedo, e talvez já tenha vindo. A da vez é a da ordem, e a ordem parece pouco: tirar o que distrai ao sentar, dois minutos ao levantar. É comum que, no terceiro ou quarto dia, folheando o Livro III, você sinta vontade de somar a ela outra coisa: o treino, uma hora de leitura, a primeira hora do dia longe das distrações, já que tudo isso também está, de algum modo, na folha do dia zero. Se sentiu essa vontade, repare na frase que veio com ela: <i>isto é pouco, posso mais</i>. É a essa frase que esta lei responde.",
   "Para essa tarde, vou lhe contar de Franklin. Em Filadélfia, por volta de 1730, um tipógrafo de vinte e poucos anos chamado Benjamin Franklin decidiu chegar à perfeição moral e conta na <i>Autobiografia</i> que logo descobriu a dificuldade. Enquanto vigiava uma falta, outra o surpreendia; o hábito aproveitava a distração, e a inclinação era mais forte do que a razão. Escolheu então treze virtudes e resolveu dar a cada uma, por uma semana, atenção estrita, deixando as outras entregues à sorte de costume. Comparou-se ao jardineiro que não tenta arrancar de uma vez todas as ervas daninhas do jardim, o que excederia o alcance e a força dele. Em vez disso, ele limpa um canteiro e só passa ao seguinte quando termina. Do caderno em que Franklin marcava as faltas trata outra página <font color='#6b6b6b'>(Lição XI)</font>; aqui importa só a ordem. Franklin dava a cada virtude uma semana certa; este livro não dá prazo a nenhuma microação, e a seguinte só entra quando a da vez chegou.",
   "E a ordem não era arbitrária. Franklin pôs a temperança em primeiro lugar porque ela dá a frieza e a clareza de cabeça de que todas as outras precisam; depois vinham o silêncio e a ordem, cada virtude preparando o terreno da seguinte. O mesmo princípio governa a sequência deste livro. A ordem vem antes do terminar, o terminar vem antes da prática deliberada, e a crítica só vem depois de haver obra para criticar.",
   "Se alguma das suas tentativas antigas começou com quatro gestos de uma vez, num primeiro de janeiro ou numa segunda-feira qualquer, você conhece o desenho. Na primeira semana tudo corre bem, porque o entusiasmo paga a conta de todos os gestos. Na segunda, um deles falha, e a falha contamina os outros, que estão presos ao mesmo fio. Vem então uma frase: <i>se o dia já falhou num ponto, por que não nos restantes?</i> No fim do mês não resta nenhum dos quatro, e há mais uma tentativa abandonada.",
   "Restam as microações que já passaram, e o que fazer com elas. São as que ficaram, e não pedem atenção nova; pedem só que você não as abandone. A regra que traz uma delas de volta, a sexta de <i>Da medida</i>, também deixa esta lei intacta: o que volta já foi aprendido uma vez, e nunca há mais de uma da vez. E se a microação da vez lhe parecer menos urgente do que um exercício mais adiante, desconfie dessa urgência: é a impaciência dos começos. O exercício seguinte entra quando a da vez chegar."]),
 ("Percebeu, aja, antes que se forme a segunda frase interior.",
  "Quem age antes da segunda frase não precisa vencê-la, porque ela não chegou a existir.",
  ["Esta lei serve numa manhã que você talvez já conheça, ou que vai conhecer amanhã. Você acorda, e a primeira frase vem limpa: <i>levante-se</i>. A segunda vem logo atrás: <i>cinco minutos</i>. Se você lhe dá o assentimento, só esse, pequeno, vem uma terceira, <i>já que vai se atrasar, abra o caderno depois</i>, e uma quarta, <i>a linha da manhã se escreve no almoço</i>. Cada uma é mais razoável que a anterior, porque cada uma parte da derrota da outra como de um fato consumado. Às oito, o dia já foi decidido por uma fileira de concessões que, sozinhas, pareciam nada. A fileira começou na primeira concessão, feita antes de qualquer argumento. A mesma fileira se forma às nove, ao chegar à mesa: <i>arrumo depois</i>, <i>só vejo uma coisa primeiro</i>.",
   "O que acontece nesse intervalo tem um nome antigo, e vou lhe contar de onde ele vem. Em Atenas, no Pórtico Pintado, Zenão de Cício ensinava essa diferença com a mão. Cícero conta a cena. Zenão mostrava a mão aberta, os dedos estendidos, e dizia: assim é a impressão. Dobrava um pouco os dedos: assim é o assentimento. Fechava o punho: assim é a compreensão. E apertava o punho com a outra mão, com força: assim é o saber, que só o sábio possui. Os estoicos chamavam de <i>phantasía</i> o que aparece no espírito sem que se possa impedi-lo, e de <i>synkatáthesis</i> o movimento seguinte, o de aceitar o que apareceu e agir de acordo com isso. O primeiro não está em nosso poder. O segundo está.",
   "A segunda frase interior é um pedido de assentimento. <i>Mas talvez depois</i> não chega como ordem; chega como proposta razoável, numa voz parecida com a sua, e espera que os dedos se dobrem. Aqui a lei se separa dos estoicos, e convém que você saiba disso. Para eles, <i>tenho de começar</i> também era uma impressão e pedia tanto exame quanto <i>talvez depois</i>. A disciplina deles consistia em não dar assentimento a nada sem prova, e Epicteto mandava dizer à impressão que esperasse um pouco, para que ele a pusesse à prova. A frase dele que você leu na forma das linhas, <i>você é uma impressão</i>, serve aqui só para reconhecer a segunda frase. O resto vem do hábito e do pré-compromisso. O exame foi feito de manhã, quando você escolheu o gesto, e agir na primeira frase é não reabrir no instante o que você decidiu de cabeça fria, como Ulisses, que se fez amarrar ao mastro antes de ouvir as sereias. Dessas duas coisas, a prova de Epicteto e o mastro de Ulisses, fala o Livro IV, em <i>Do modo</i>. O exame à maneira estoica continua tendo sua hora, à noite e nas passagens.",
   "É verdade que às vezes a segunda frase tem razão. Você vai sair para correr e se lembra de que o joelho dói desde ontem; vai começar a obra e falta um dado que só outra pessoa pode lhe dar. A lei não manda ignorar os fatos. Ela os distingue pelo modo como chegam. Um fato se verifica em segundos, olhando, tocando, perguntando; a negociação pede tempo e oferece um <i>depois</i>. A questão do joelho se decide olhando para o joelho, e o que couber no corpo de hoje se faz já. Se falta o dado, comece pelo passo que não depende dele. Resta o medo de errar por agir depressa. O gesto que esta lei protege foi escolhido antes e é pequeno; o pior que pode lhe acontecer é ser feito numa hora menos boa. Para o que é novo e grande existe a oitava linha, que manda pensar antes. Esta lei vale para o que já foi pensado."]),
 ("A vontade não é condição. Sem ela, faz-se igual.",
  "Quando a vontade vem, ela ajuda (sexta linha, Lição VII); quando não vem, o que há para fazer continua o mesmo.",
  ["O momento desta lei é uma manhã, talvez ainda nesta primeira semana, em que, ao chegar à mesa, vem uma frase: <i>hoje não estou com vontade</i>. Note-a antes de obedecer a ela. A sexta linha lhe responde no instante, com a versão de dois minutos; esta lei responde antes: a vontade não entra na lista do que é preciso para começar.",
   "No Liceu, Aristóteles chamava de <i>héxis</i> a disposição que os atos repetidos deixam em quem os pratica, e deixou na <i>Ética a Nicômaco</i> uma observação que serve de régua para esta lei. O prazer ou a dor que acompanham um ato são o sinal da disposição já formada: quem se abstém dos prazeres do corpo e se alegra com isso é temperante; quem se abstém e se aborrece ainda não é. Nesse sentido, a vontade de agir chega no fim, como sinal de que a disposição nasceu. Pedi-la antes de agir é exigir, como condição para começar, o que só a repetição produz. Com a mesma régua se mede a frieza com que você a põe: ela é necessária enquanto o gesto custa, e deixa de ser quando o gesto já não custa.",
   "Se você deixar a vontade decidir, verá o resultado na folha de marcas depois de algumas semanas: os traços agrupados nos dias de ânimo, as cruzes espalhadas por todos os outros, e nenhum <i>chegou</i>, porque o gesto continua precisando do ânimo para aparecer. A disposição que se forma assim é a de agir só quando se tem vontade.",
   "Se a falta de vontade durar e se estender a tudo, até o que antes lhe dava gosto, o humor de uma manhã terá virado circunstância, como a doença, e para a circunstância existe o piso, declarado de manhã. Se ela persistir por semanas e pesar sobre tudo, procure quem cuida da saúde; nenhum livro faz esse ofício."]),
 ("Você falhou: o próximo momento é seu. Nada se compensa; nada volta ao começo.",
  "Compensar é fazer em dobro amanhã; voltar ao começo é declarar perdidos os traços que você já marcou. A lei recusa os dois.",
  ["Esta lei espera por você na noite da sua primeira cruz. O livro não sabe quando será; para quase todos, ela vem nos primeiros dias. Você vai marcar a cruz, escrever a linha da queda, e é comum que, ao fechar o caderno, venha uma de duas frases. Uma diz <i>amanhã faço em dobro</i>. A outra diz <i>estragou tudo; recomeço em outra segunda-feira, como deve ser</i>. A frase em negrito as recusa na ordem em que vêm: nada se compensa, nada volta ao começo.",
   "Repare no que a primeira faz, se você obedecer a ela. Suponhamos que você falhe numa terça a hora de leitura que pôs entre as alavancas. Na quarta, para compensar, você lê duas horas e se deita tarde. Na quinta, sem forças, falha de novo, agora com uma dívida de três horas. No domingo, ao folhear os dias, você faz a conta das culpas e quase não vê os traços, e a saída mais limpa que encontra é a da segunda frase: declarar o caderno perdido e recomeçar do zero na segunda. É assim que termina boa parte das tentativas.",
   "Para a noite da primeira cruz, vou lhe contar de Jerusalém. Nos séculos em que o Templo ainda estava de pé, o Dia da Expiação era o dia em que o povo inteiro jejuava e o sumo sacerdote entrava no lugar mais santo. Os mestres que depois fixaram a tradição na Mishná escreveram, no tratado sobre esse dia, uma regra de exatidão notável: o Dia da Expiação apaga as faltas do homem para com Deus, mas não apaga as faltas para com o próximo enquanto o próximo não tiver sido apaziguado. O jejum e o rito não substituem o ato de ir até quem foi ferido.",
   "Dessa regra sai a distinção de que esta lei precisa. Compensar é pagar ao caderno: fazer em dobro amanhã para que a folha de marcas fique bonita. Isso se faz sozinho, à noite, e por isso engana. Reparar é responder a quem sua falha atingiu, e exige o outro. Se você prometeu a alguém de casa ler com ele à noite e não leu, se ficou de entregar a um colega a parte que lhe cabia e ele passou a tarde parado esperando, a lei não o dispensa de nada. Você vai até ele, diz o que falhou, sem discurso, e faz o que ainda pode ser feito: a parte entregue hoje, a leitura amanhã, o que mais ele precisar. A reparação se faz no próximo momento, que é exatamente o que esta lei lhe dá. A cruz da noite fica onde está; a reparação não a apaga, e não precisa apagá-la.",
   "Os antigos tinham também a outra metade da lei. Marco Aurélio lembrava que ninguém perde outra vida senão a que está vivendo agora <font color='#6b6b6b'>(<i>Meditações</i>, II, 14)</font>. Cada um, portanto, só tem nas mãos o presente: o dia de ontem, com a falha dele, já não se pode perder nem ganhar de novo, e por isso não há nada a pagar por ele. O próximo momento é a parte dessa vida que ainda está à sua frente, e é nele que esta lei põe você na noite da cruz.",
   "Falhar muitos dias também não muda nada. Nenhum prazo se perdeu, porque não havia nenhum: a microação da vez continua sendo a da vez, e espera seu <i>chegou</i> como esperava antes."]),
 ("Nunca dois dias seguidos de queda.",
  "É a terceira regra de <i>Da medida</i>, com o que conta como queda e por que o ponto não separa duas: tolerante com o primeiro dia, severa com o segundo.",
  ["Esta é a lei da manhã seguinte à primeira cruz. Nessa manhã, ao abrir o caderno, é comum que fale uma voz que você talvez já tenha ouvido em outras tentativas: <i>já há uma cruz, que diferença faz outra?</i> Foi assim que ela falou à mulher de <i>Do primeiro dia</i>, na quinta-feira da primeira semana, e a mulher fez o que a lei pede. O que <i>sagrada</i> quer dizer está na terceira regra de <i>Da medida</i>. Se a cruz vier mesmo assim, a lei foi quebrada, e o caminho continua, porque nada volta ao começo.",
   "Para essa manhã, vou lhe contar de Aristóteles. No primeiro livro da <i>Ética a Nicômaco</i>, ao perguntar o que torna uma vida boa, ele recorre a um provérbio: uma andorinha não faz a primavera, nem um só dia; assim também um dia, ou pouco tempo, não faz ninguém feliz. Escreveu isso para conter o entusiasmo de quem julga que um bom ato basta. Para Aristóteles, a vida boa, como a disposição de que falei na terceira lei, se forma pela repetição dos atos ao longo do tempo, e um dia isolado não decide nada. Lido ao contrário, o provérbio serve para conter o desespero. Uma cruz também é um dia só, e não faz de você alguém sem disposição; o que forma a disposição contrária é a repetição, e a repetição começa no segundo dia. Por isso a lei é tolerante com o primeiro e guarda a manhã seguinte.",
   "Se você guarda registros de tentativas antigas, releia-os: é comum ver neles o mesmo desenho, uma cruz isolada no meio dos traços e, depois dela, uma fileira inteira.",
   "Há também uma razão de fora, e convém dizê-la na medida exata. No estudo de Lally, em <i>Da medida</i>, uma falta isolada quase não alterou o caminho do gesto. O estudo não mediu o que acontece depois de duas faltas seguidas, e este livro não lhe atribui esse achado. A severidade com o segundo dia vem do raciocínio do provérbio: a primeira cruz interrompe uma cadeia; a segunda, colada a ela, já é o primeiro elo de outra, a da disposição contrária. O número dois, por fim, foi escolhido pelo método, e nenhum estudo o descobriu. Três seria mais confortável. O livro ficou com o menor número que ainda separa o acidente do começo de um costume, porque é o único que põe a manhã seguinte inteira sob a lei.",
   "Há dias em que nem o piso é possível. Suponha que você fique de cama, com febre, por três dias. A lei não muda, mas é lida com honestidade. De manhã você declara o piso, que, para quem está doente, é muito pequeno. Onde a ocasião não chega porque você não sai da cama, marca-se ponto. Onde ela chega e você não consegue, é cruz, e no dia seguinte o gesto se faz uma vez, por menor que seja, mesmo da cama. Nada volta ao começo; a microação espera."]),
 ("Nada se abre antes que o anterior se feche. Um livro por vez, até a última página.",
  "Fechar quer dizer terminar, ou encerrar por decisão, por escrito, com a razão. O que não se pode é deixar a coisa aberta, pesando em silêncio.",
  ["O momento desta lei vem quase sempre fora da obra, no fim do dia. Talvez numa noite destas você sinta vontade de começar um livro novo, com o anterior marcado pela metade na mesa de cabeceira. Quando a coisa nova chegar durante a obra, no trecho difícil, você ainda não terá um gesto treinado para ela: esse gesto é a segunda microação, a do terminar, que entra na manhã da primeira passagem. Até lá, você tem esta lei, uma linha na folha de captura e a frase de <i>Da assentada</i>, que reconhece a coisa nova sem discuti-la: ela não é <i>isto</i>.",
   "Para essa noite, vou lhe contar de duas cartas e de um homem que não fechou nada. Sêneca, já passado dos sessenta anos e retirado da corte de Nero, começa a segunda carta a Lucílio com um elogio: ouviu dizer que o amigo não anda de um lado para o outro, que fica onde está e se demora consigo mesmo. Logo depois o previne contra uma inquietação mais sutil, a das leituras. Ler muitos autores e livros de toda espécie, escreve, tem algo de vago e instável; é preciso demorar-se em certos espíritos e alimentar-se deles, se se quer tirar alguma coisa que fique. Quem passa a vida viajando tem muitos anfitriões e nenhum amigo. O alimento devolvido logo não nutre. A planta mudada de lugar muitas vezes não ganha força. A multidão de livros dispersa; e, se você sentir vontade de variar, volte aos que já leu. Todas essas imagens dizem a mesma coisa: um livro só deixa alguma coisa em quem se demora nele o tempo de digeri-lo, assim como o alimento só nutre quando fica; quem salta de um para outro conhece muitos e não fica com nenhum. Para os estoicos, ler servia para formar o juízo, e o juízo se forma devagar. Na sua mesa de cabeceira, o livro novo que você tem vontade de começar é mais um anfitrião, e o que está marcado pela metade é o que ainda pode ficar.",
   "Quase dezoito séculos depois, na Inglaterra, Samuel Taylor Coleridge deu a esta lei a demonstração contrária mais conhecida. Tinha talento para várias vidas e anunciou obras para outras tantas: revistas, tratados, poemas longos e, sobretudo, uma grande obra de filosofia que reuniria tudo o que pensava, da qual falou durante décadas a amigos, editores e leitores. Começava, prometia, abria outra coisa. Quando morreu, em 1834, essa obra era um monte de manuscritos e fragmentos, que só muito depois seriam publicados. Boa parte do que ficou de maior dele são poemas curtos e livros nascidos de outros, como a <i>Biographia Literaria</i>, que começou como um prefácio. A história mostra o que esta lei evita: cada obra nova que Coleridge abria tirava tempo e força das que já estavam abertas, e a que ele mais queria foi a que ficou em pedaços.",
      "A lei não vale para tudo o que você lê. O dicionário, o manual de consulta, o texto que o trabalho exige se abrem e se fecham no mesmo dia, como ferramentas; a lei fala do livro que se lê para ser lido, do começo ao fim, e da obra que é sua. E se o livro for ruim, feche-o como a lei manda: por escrito, com a razão, numa linha. A linha escrita impede que o abandono se repita com o livro seguinte sem que você perceba."]),
 ("Fala-se do que está feito, nunca do que se fará.",
  "Anunciar um plano também expõe a obra ao olhar dos outros antes de ela estar pronta para isso (Lição IX). Pedir ajuda ou crítica sobre a obra é outra coisa, e faz parte do trabalho. <font color='#6b6b6b'>(Epicteto, <i>Manual</i>, 46)</font>",
  ["Esta lei serve num momento que talvez já tenha vindo: a primeira conversa depois do dia zero. Alguém pergunta como você vai, e dá vontade de contar o dia, a folha, a visão, o alvo do ano. Você pode dizer, se quiser, que passou um dia escrevendo, porque isso está feito. O que você decidiu nesse dia fica no caderno.",
   "Epicteto, na passagem que esta lei cita, pede ao discípulo que nunca se chame de filósofo e não discorra sobre princípios diante de quem não os pratica; que faça, antes, o que deles decorre. E, se a conversa cair nesses assuntos, que se cale quase sempre, porque é grande o perigo de devolver logo o que ainda não digeriu. Na mesma passagem ele dá a imagem das ovelhas: elas não vomitam a erva diante do pastor para lhe mostrar quanto comeram; digerem-na por dentro e dão por fora lã e leite. Para Epicteto, o princípio anunciado se gasta em palavras antes de chegar a ato, e o que se mostra aos outros deve ser o que ele produziu. Na conversa de que falei acima, o plano contado é a erva devolvida, e a obra feita, que você pode mostrar, é a lã.",
   "Dezenove séculos depois, em 2009, Peter Gollwitzer e colegas puseram a advertência à prova numa série de experimentos com estudantes, entre eles futuros juristas, decididos a alcançar um objetivo ligado à própria identidade. Pediu-se a uns que escrevessem o que pretendiam fazer e entregassem a folha a alguém que a lia e tomava nota; a outros, que guardassem a intenção para si. Depois, todos receberam um trabalho ligado a esse objetivo. Os que tinham visto a própria intenção anotada por outra pessoa trabalharam menos e, apesar disso, se sentiam mais perto da meta. Os autores explicam o resultado por uma ideia antiga da psicologia social: quando a identidade que se busca é reconhecida por outro, o espírito a registra como em parte conquistada, e afrouxa. É um estudo, e vale com a prudência devida a um estudo; mas diz em números o que Epicteto dizia por experiência.",
      "Muitos melhoram justamente porque alguém lhes cobra: o amigo com quem se combinou correr, o colega a quem se prestam contas. A lei mantém essa companhia e diz o que levar a ela. Ao parceiro se leva o que está feito: as marcas da folha, a passagem que veio, a obra entregue, com as cruzes à vista. Isso é um fato que ele pode verificar, e o fato não dá a satisfação antecipada que o anúncio dá. O que não se leva é o plano grandioso do que virá, à espera de aplauso."]),
 ("O quarto é para dormir: nada que distraia entra nele à noite. O sono, de sete a oito horas, não se negocia.",
  "Um homem sem dormir negocia consigo mesmo o dia inteiro, e dormir pouco não tem mérito nenhum. Por isso a disciplina de cada dia começa na noite anterior.",
  ["O momento desta lei é todas as noites, e a primeira foi a do dia um. Você fecha o caderno depois da marca; entre isso e o sono há um tempo curto em que é comum levar alguma distração para o quarto, só por um momento. A lei decide esse momento antes de ele chegar: o que distrai fica fora do quarto, e você se deita numa hora que deixe sete a oito horas até acordar. Se a primeira noite não foi assim, mude hoje mesmo o lugar onde a distração dorme.",
   "Volto a Bento. A regra que emoldurava o dia em Monte Cassino era escrita para monges que se levantavam de noite para rezar, e seria de esperar que tratasse o sono como inimigo. Ela faz o contrário. Ao fixar os horários do inverno, manda que os irmãos se levantem na oitava hora da noite, para que repousem um pouco mais da metade dela e se levantem com a digestão feita. Manda que cada um durma na própria cama, vestido, para estar pronto ao sinal, e que uma lâmpada fique acesa no dormitório até de manhã. E, depois da última oração do dia, as Completas, ninguém mais fala. A regra protegia o sono com disposições precisas.",
   "O modo importa aqui. A regra tira a conversa do dormitório em vez de pedir ao monge força para resistir a ela. É o mesmo princípio desta lei: nada que distraia entra no quarto, porque à noite, com sono, ninguém vence o que tem ao alcance da mão. E quando a lei se quebra, ela se quebra sem barulho. Você fica acordado mais uma hora, e depois outra. Na manhã seguinte a primeira linha custa o dobro, a segunda frase interior chega mais forte e, às quatro da tarde, tudo se negocia. O cansaço entra na folha de marcas na forma de uma cruz, e a cruz é posta na conta da fraqueza.",
   "Talvez você tenha um filho de poucos meses que acorda três vezes por noite, e sete horas seguidas sejam uma lembrança. A lei não o acusa disso. O que ela proíbe é negociar o sono, e levantar-se para um filho é responder a uma circunstância que nenhuma negociação consigo mesmo decidiu. Nesses meses, a lei pede que você proteja o que pode proteger: deitar-se mais cedo, dividir as noites com quem as compartilha com você, não tirar das horas que restam nada para a distração. As sete a oito horas continuam sendo a medida, e a circunstância, quando passa, devolve você a ela.",
   "Para quem trabalha em turnos, à noite, a lei muda de hora. A noite da lei é o tempo do seu sono, caia ele quando cair, e o quarto se guarda nessas horas como se guardaria à noite. A regra de Bento também mudava as horas do sono com as estações, do inverno para o verão, e o protegia em todas."]),
 ("Este método não se emenda no meio do caminho: só numa passagem.",
  "É a sétima regra de <i>Da medida</i>, e vale também para a folha do dia zero.",
  ["O momento desta lei vem, para muitos, no quinto ou no sexto dia. A da vez já não é novidade, o gesto ainda não chegou, e é comum que você veja, ou julgue ver, um defeito: a ocasião mal escolhida, uma alavanca longa demais, uma marca que deveria contar de outro modo. A mulher de quem lhe falei viu um no oitavo dia e o escreveu na folha de captura sem mudar nada. É isso que esta lei lhe pede quando o seu vier.",
   "O trecho entre duas passagens é a sua moral provisória. Enquanto uma microação está em treino, a ocasião e o gesto que você definiu valem como se fossem certos, mesmo que não sejam, porque não há outra maneira de saber se estão errados. Veja o que acontece com quem emenda a cada dificuldade: no quinto dia acha o gesto mal escolhido e o troca por outro, no nono alarga a ocasião, no décimo segundo muda a maneira de marcar. Depois de duas semanas assim, essa pessoa tem um método melhor no papel e nenhuma marca que diga coisa alguma, porque cada traço foi medido com uma régua diferente.",
   "Mas, você insiste, e se no quinto dia eu vir com clareza que a ocasião está mal definida? Escreva isso na folha de captura, com a data e a razão, e espere. Na próxima passagem, as marcas confirmam ou desmentem a observação, e então você emenda, por escrito. É comum que as marcas desmintam uma certeza do quinto dia. Você vai perguntar também o que fazer se a prática lhe fizer mal, se o gesto lhe tirar o sono ou ferir quem depende de você. Nesse caso a pergunta sai do método e passa ao discernimento, de que trata o Livro V.",
   "Se a passagem não vier, o caminho não fica parado à espera: há a passagem por decisão, a oitava regra de <i>Da medida</i>."]),
]
LAWT = ParagraphStyle('lawt', parent=P, fontSize=12, leading=16, spaceBefore=10, spaceAfter=3, keepWithNext=1)
PORQUE_LEIS = [
 ["<b>A ideia.</b> Um gesto novo, enquanto não é hábito, só acontece se for lembrado na ocasião, e lembrar gasta atenção. Benjamin Franklin descobriu isso ao tentar treze virtudes de uma vez: enquanto vigiava uma falta, outra o surpreendia. Passou a treiná-las uma de cada vez, e numa ordem em que cada uma preparava a seguinte.", "<b>O mecanismo.</b> Primeiro, dois gestos novos disputam a mesma atenção, e a memória falha justamente na ocasião em que se precisa dela; com um só, há uma só coisa a lembrar. Segundo, um gesto leva tempo para se tornar automático. No estudo de Lally que <i>Da medida</i> relata, esse tempo foi de três semanas a mais de meio ano. Quem junta quatro gestos nesse período tem quatro coisas a lembrar durante semanas ou meses, e o entusiasmo dos primeiros dias não basta para tanto. A ordem conta porque os primeiros exercícios constroem o terreno em que os seguintes se apoiam.", "<b>Por isso.</b> Treino um gesto de cada vez porque só assim tenho uma coisa a lembrar na ocasião, e porque cada gesto precisa de semanas, às vezes meses, de repetição para ficar."],
 ["<b>A ideia.</b> Esta lei é uma regra de hábito e de pré-compromisso, no sentido que Jon Elster deu à palavra: escolher de cabeça fria de modo a restringir as escolhas do momento fraco, como Ulisses amarrado ao mastro. O gesto foi decidido antes. A primeira frase interior, <i>tenho de começar</i>, só lembra essa decisão; a segunda, <i>mas talvez depois</i>, propõe reabri-la, e a lei manda não reabri-la. O vocabulário do assentimento vem dos estoicos, mas a regra deles era outra: eles examinavam todas as impressões, inclusive a primeira, e não davam assentimento a nenhuma sem prova.", "<b>O mecanismo.</b> Primeiro, o gesto que esta lei protege foi decidido de manhã, com a ocasião prevista no breviário. Quando a ocasião chega, não há nada novo a examinar, e qualquer exame reabre o que estava fechado. Decidir de antemão <i>quando acontecer X, faço Y</i> aumenta a probabilidade de fazer Y, de forma consistente nos 94 testes reunidos por Peter Gollwitzer e Paschal Sheeran em 2006. Segundo, cada concessão torna a seguinte mais razoável, porque parte da anterior como de um fato consumado. Agir na primeira frase corta a fileira antes que ela comece.", "<b>Por isso.</b> Ajo na primeira frase porque o gesto já foi decidido e não há nada a examinar, e porque a primeira concessão abre a fileira das outras."],
 ["<b>A ideia.</b> Para Aristóteles, o gosto de agir é o sinal de que a disposição já se formou, e chega no fim; pedi-lo antes de começar é exigir da causa o que só a repetição produz.", "<b>O mecanismo.</b> Primeiro, o humor muda de uma manhã para outra por razões que nada têm a ver com a obra. Se é ele que decide, o gesto aparece só nos dias de ânimo, e a folha de marcas mostra isso depois de algumas semanas. Segundo, o que se repete fica ligado àquilo que o dispara. Os hábitos, como mostrou a psicóloga Wendy Wood, são respostas ativadas pelas pistas do contexto, relativamente independentes da intenção do momento. Daí se segue que o gesto feito na ocasião, com ou sem vontade, se liga à ocasião, e o gesto feito só quando se tem vontade se liga à vontade.", "<b>Por isso.</b> Faço igual sem vontade porque a vontade vem depois da repetição, e porque o gesto que faço na ocasião, todas as vezes, fica ligado à ocasião, seja qual for o humor."],
 ["<b>A ideia.</b> Sêneca observa, em <i>Da brevidade da vida</i>, que das três partes do tempo o passado é a única certa: a fortuna já não tem poder sobre ele. Daí sai a lei. A falha de ontem não se desfaz, e os traços de ontem também não, porque ninguém os tira de você. O que ainda depende de você é o próximo momento.", "<b>O mecanismo.</b> Primeiro, compensar faz da falha uma dívida, e a dívida se paga com excesso, cansaço e nova falha, até que abandonar parece a saída limpa. Tratar a si mesmo com compreensão depois de falhar dá o resultado contrário: em experimentos de Juliana Breines e Serena Chen, quem foi levado a isso depois de um mau resultado estudou mais tempo para o teste seguinte. Segundo, recomeçar do zero apaga o registro dos traços, e o registro trabalha a seu favor. Numa meta-análise de Benjamin Harkin e colegas, com 138 estudos, registrar o progresso aumentou a probabilidade de chegar ao objetivo.", "<b>Por isso.</b> Não compenso nem recomeço porque a dívida termina em abandono, e porque os traços que já marquei continuam contando e me ajudando."],
 ["<b>A ideia.</b> Uma andorinha não faz a primavera, diz Aristóteles, nem um só dia; o mesmo vale para a disposição contrária. Uma queda isolada não forma nada; duas seguidas já são o começo de uma repetição.", "<b>O mecanismo.</b> Primeiro, a severidade cai sobre o único dia em que ainda é barato frear a repetição: depois da segunda cruz, a terceira custa menos, porque já não há nada a proteger. Segundo, a manhã seguinte à queda traz a voz mais perigosa, <i>já há uma cruz, que diferença faz outra?</i> Alan Marlatt observou, em quem tinha deixado um hábito, que um deslize decidia pouco por si; o que decidia era o que a pessoa dizia a si mesma logo depois. Tornar sagrada essa manhã responde à voz antes que ela fale. Nenhum estudo testou a regra dos dois dias; o que fica dito é razão.", "<b>Por isso.</b> Cumpro a da vez na manhã depois de uma cruz porque duas quedas seguidas começam a repetição contrária, e porque o que digo a mim mesmo depois da queda pesa mais do que a queda."],
 ["<b>A ideia.</b> Começar costuma dar prazer, e terminar costuma custar. Quem tem muitas coisas abertas pode escolher sempre o prazer de começar e adiar sempre o custo de terminar, e fica com muitas obras pela metade e nenhuma inteira. Sêneca avisava Lucílio da mesma coisa nas leituras: quem passa de livro em livro não tira de nenhum alguma coisa que fique.", "<b>O mecanismo.</b> Primeiro, cada coisa aberta pede para ser lembrada, e cada pedido é uma pequena saída da obra; fechar, terminando ou encerrando por escrito, cala esse pedido. Segundo, alternar entre várias obras tem um custo a cada troca. Os estudos de laboratório sobre alternância de tarefas que Stephen Monsell resumiu mostram perda de tempo e mais erros a cada mudança, mesmo quando a mudança é prevista. Com uma só coisa aberta, não há troca a pagar.", "<b>Por isso.</b> Fecho antes de abrir porque cada coisa aberta me pede atenção mesmo parada, e porque cada troca entre obras me custa tempo e erros."],
 ["<b>A ideia.</b> Peter Gollwitzer, psicólogo alemão, estuda os objetivos que dizem quem queremos ser: ser jurista, ser escritor, ser alguém que corre. A ideia em que ele se apoiou diz que esses objetivos se alimentam de sinais de que se está chegando lá, e que ser visto por outro declarando a intenção já conta como um desses sinais. O espírito registra a intenção anunciada como em parte conquistada, e afrouxa.", "<b>O mecanismo.</b> Primeiro, o anúncio dá antes do tempo uma parte da satisfação que só a obra deveria dar, e um espírito satisfeito trabalha menos; os experimentos contados abaixo mediram isso uma vez. Segundo, o que está feito é um fato que outro pode verificar, e mostrá-lo ajuda. Na meta-análise de Benjamin Harkin e colegas, registrar o progresso aumentou a realização dos objetivos, e o efeito foi maior quando o progresso era mostrado ou relatado a alguém. A lei deixa passar o que está feito e guarda o plano.", "<b>Por isso.</b> Falo do que fiz e calo o que farei porque anunciar o plano me dá antes do tempo a satisfação de tê-lo feito, e porque mostrar o que fiz me ajuda a continuar."],
 ["<b>A ideia.</b> Bento de Núrsia tratou o sono dos monges como parte da regra, com horas e lugar marcados, e o protegeu pelo arranjo do dormitório. A lei faz o mesmo com duas coisas: a quantidade, sete a oito horas, e o quarto, onde nada que distraia entra à noite. Do sono depende o resto, porque o cansaço corrói primeiro o juízo e depois a vontade.", "<b>O mecanismo.</b> Primeiro, o sono curto degrada a atenção, e degrada sem que se perceba. Num estudo de Hans Van Dongen e David Dinges, catorze noites de seis horas produziram déficits de atenção equivalentes aos de uma a duas noites sem dormir, e os participantes subestimaram o próprio déficit; as academias de medicina do sono recomendam a um adulto sete horas ou mais. Segundo, à noite, com sono, decide-se pior, e o que está ao alcance da mão leva a melhor. Os hábitos são disparados pelas pistas do ambiente, e por isso a distração tirada do quarto vale mais do que a força para resistir a ela.", "<b>Por isso.</b> Deixo a distração fora do quarto e guardo as sete a oito horas porque dormir pouco me tira atenção sem que eu perceba, e porque à noite o arranjo do quarto decide melhor do que a minha força."],
 ["<b>A ideia.</b> É a moral provisória de Descartes, que <i>Da floresta</i> lhe contou: a ocasião e o gesto que você definiu valem como certos até as marcas dizerem o contrário.", "<b>O mecanismo.</b> Primeiro, só uma régua fixa permite saber se um gesto funciona. Se você muda a ocasião no quinto dia e a maneira de marcar no décimo, cada traço foi medido de outro modo, e as marcas deixam de dizer alguma coisa; além disso, um gesto pode levar semanas, às vezes meses, para ficar. Segundo, o dia em que a prática custa é aquele em que o defeito parece mais claro, e a dificuldade se apresenta como prova de erro. A observação escrita na folha de captura espera a passagem e então é confrontada com as marcas, que muitas vezes a desmentem. Nenhum estudo testou esta regra; o que fica dito é razão.", "<b>Por isso.</b> Escrevo o defeito e espero a passagem porque só com a mesma régua as marcas me dizem se o gesto funciona, e porque no dia difícil eu julgaria o método pelo cansaço."],
]
assert len(PORQUE_LEIS) == len(leis)
for i, ((l, e, mais), pq) in enumerate(zip(leis, PORQUE_LEIS), 1):
    st.append(KeepTogether([Paragraph(f"§ {i}. &nbsp;<b>{l}</b>", LAWT), Paragraph("D O &nbsp; P O R Q U Ê", LBL), Paragraph(pq[0], PI)]))
    for par in pq[1:]: add(par, PI)
    add(e, PI)
    for par in mais:
        add(par, PI)

sec("Do dia")
st.append(KeepTogether([Paragraph("<i>“Omnes horas complectere.”</i>", ParagraphStyle('r3dia1', parent=PC, fontSize=12, spaceAfter=2)),
                        Paragraph("Sêneca, <i>Cartas a Lucílio</i>, 1", ParagraphStyle('r3dia2', parent=EPA, spaceAfter=14))]))
add("A frase latina no alto é de Sêneca e quer dizer <i>abrace todas as horas</i>: tome posse de cada hora do dia, em vez de deixá-la passar sem perceber. Ela abre este capítulo porque é dela que sai a ideia, contada abaixo, de que a vida se segura no dia que se tem à frente. A manhã e a noite você já fez, pelas duas partes que este capítulo reserva para elas. Falta saber de onde vem a forma desse dia, e por que este livro não conhece outra unidade de tempo. Vou lhe contar de três vozes antigas que chegaram ao mesmo ponto.", PI)
add("A primeira é a de Sêneca, na carta do estribilho que você diz a cada manhã. Abrace todas as horas, escreve ele, porque você dependerá menos do amanhã se puser a mão no dia de hoje; enquanto se adia, a vida passa correndo.", PI)
add("A segunda é a de Marco Aurélio. Um século depois, nos anos das guerras do Danúbio, ele escrevia para si, em grego, a frase que você leu na quarta lei: ninguém perde outra vida senão a que vive agora. A passagem continua, e o resto dela é o que importa aqui. Ainda que você vivesse três mil anos, ou trinta mil, o mais longo e o mais curto dão no mesmo, porque o presente é igual para todos, e o que cada um perde é só o instante presente; o passado e o futuro ninguém pode perder, porque ninguém perde o que não tem <font color='#6b6b6b'>(<i>Meditações</i>, II, 14; paráfrase)</font>. O que Marco Aurélio dá aqui como posse de cada um é só o presente.", PI)
add("A terceira é mais antiga que as duas. Num monte da Galileia, o sermão que o Evangelho de Mateus conta tinha chegado ao mesmo ponto por outro caminho. Depois de mandar olhar as aves do céu, que não semeiam, e os lírios do campo, que não fiam, o sermão fecha o argumento assim: não vos inquieteis com o dia de amanhã, porque o dia de amanhã cuidará de si; basta a cada dia o seu mal <font color='#6b6b6b'>(Mateus 6, 34)</font>. Quem diz isso sabe que a preocupação com o dia seguinte, trazida para hoje, não resolve nada dele e tira forças do presente.", PI)
add("Um estoico rico, um imperador em campanha e um pregador da Galileia não tinham muito em comum, e mesmo assim concordam nisto: a unidade em que a vida se pode segurar é o dia. É por isso que este livro não tem semanas nem prazos. A direção foi escrita no dia zero, e quase não se mexe nela; a execução acontece no dia, que começa de manhã e termina à noite.", PI)
add("Você vai dizer que assim se perde a perspectiva. Quem só olha o dia anda de cabeça baixa, sem ver para onde vai; a semana e o mês eram os degraus de onde se olhava o caminho inteiro, e sem eles cada dia é um passo às cegas. A resposta está no que você já fez. A perspectiva não ficou sem lugar: ela mora na visão, no alvo do ano e na obra em curso, escritos no dia zero, e você vai relê-la em cada passagem, as noites de que este capítulo trata mais adiante. Além disso, todas as manhãs a obra de hoje desce da obra em curso, de modo que cada dia traz consigo a direção inteira, reduzida ao tamanho de uma linha. Ao dia, a semana só acrescentava um prazo mais largo e, com ele, mais espaço para adiar. Lembre-se da conta das culpas que você viu na quarta lei, feita no domingo e terminada num recomeço marcado para segunda.", PI)
add("O seu dia tem, portanto, três momentos: a manhã, o tempo que corre entre ela e a noite, e a noite. A manhã e a noite pedem o caderno: nas primeiras semanas, cerca de dez minutos cada uma. Enquanto um exercício é a da vez, a noite ganha a escrita curta que ele pedir; quando ele chega, essa escrita acaba, exceto as poucas que o próprio exercício manda continuar e que a seção <i>Da marca</i> dele nomeia. No resto do tempo você vive, e o método se cumpre nas ocasiões que esse tempo traz. De vez em quando, quando um gesto chega, a noite se alonga um pouco: é a passagem.", PI)
add("Franklin, na mesma <i>Autobiografia</i> em que conta o método das virtudes, copiou o horário que se impunha. Levantava-se às cinco e, nas três primeiras horas, lavava-se, dirigia-se ao que chamava de Bondade Poderosa, planejava os negócios do dia, tomava a resolução do dia e prosseguia o estudo em curso; no alto dessas horas escreveu uma pergunta: <i>Que bem farei hoje?</i> Das seis às nove da noite, punha as coisas no lugar, jantava, ouvia música ou conversava, e examinava o dia; no alto dessas horas, a pergunta gêmea: <i>Que bem fiz hoje?</i> Entre uma e outra, o trabalho, e das dez às cinco, o sono. Confessou depois que a ordem foi a virtude que mais lhe custou, porque um homem de negócios tem de receber os outros nas horas deles. Mas as duas perguntas ficaram e são, com outras palavras, as duas pontas do seu dia: a linha da manhã, que diz a obra, e a linha da noite, que pergunta o que existe agora que não existia.", PI)
add("Antes dos passos, falta dizer o que manda no começo de cada dia, porque vários lugares deste livro falam disso. A obra de hoje é o objeto do dia: a coisa que existirá à noite e de manhã não existe. A primeira tarefa é o primeiro passo dessa obra, escolhido na noite anterior, quando você escreve a primeira tarefa de amanhã, e confirmado de manhã, logo depois da linha da manhã. Se a obra só acontece no fim do dia, porque o emprego ocupa as horas até lá, a primeira tarefa da manhã é a tarefa do trabalho que você evitaria se pudesse, e a obra começa na hora dela. Quem trabalha no turno da noite numa fábrica e acorda às duas da tarde tem a manhã nessa hora: abre o caderno ao acordar e escreve <i>A obra de hoje é o procedimento de troca da ferramenta da prensa escrito numa página</i>; no posto, começa pela verificação que vinha adiando, e a ordem se faz ao chegar ao posto e ao deixá-lo. Quem cuida da casa e de dois filhos pequenos, e tem por obra em curso as contas da família postas em ordem, escreve <i>A obra de hoje é o mês de março lançado e conferido</i>; de manhã, começa pela tarefa da casa que evitaria, e às nove da noite, com as crianças dormindo, abre a obra à mesa da cozinha pelo passo que deixou escrito na véspera. O que outras partes do livro dizem sobre o começo cabe dentro disso. A terceira parte do estribilho e a sétima linha pedem que a primeira tarefa seja a que você evitaria. A quinta linha escreve, no fim de cada sessão, o primeiro passo de amanhã, e é esse passo que à noite se torna a primeira tarefa. A primeira hora da absorção é o tempo, longe das distrações, em que se começa a primeira tarefa, e a parte difícil da prática deliberada é por onde começa a sessão no domínio. Nenhuma delas muda o que é a primeira tarefa.", PI)
MOM = ParagraphStyle('mom', parent=HEAD, fontSize=12.5, spaceBefore=14)
st.append(Paragraph("De manhã &nbsp;<font size=10 color='#6b6b6b'>cerca de dez minutos, antes de qualquer distração</font>", MOM))
add("Você lê isto numa das noites antes do dia zero, e por agora não precisa de nada do que vem antes. Os passos vêm na ordem em que você os faz, a partir da manhã do dia um. Nessa primeira manhã, além deles, releia só as frases da primeira e da sexta linhas do Livro I, e não leia mais nada antes da obra.", PI)
add("<b>O caderno primeiro.</b> Abra o caderno antes de qualquer outra coisa. O que se abre primeiro tende a ocupar a manhã. Se numa manhã você abrir outra coisa antes, feche-a já, e no dia seguinte o caderno vem primeiro. Depois <b>diga o estribilho</b>, uma vez, em voz baixa, com os colchetes calados, como aprendeu em <i>Do estribilho</i>.", PI)
add("<b>A linha da manhã.</b> Escreva: <i>Posso morrer hoje. A obra de hoje é ____.</i> A primeira metade lembra que o tempo é limitado; a segunda diz em que este dia se gasta. A obra de hoje é um objeto, uma coisa que existirá à noite e hoje de manhã não existe, e desce da obra em curso que você escreveu no quinto ponto da folha: é o pedaço dela que cabe neste dia. O livro não sabe qual é; você sabe, está na folha. Se o que você escreveu é uma intenção, <i>trabalhar no projeto</i>, corte-a até que vire um objeto. Marco Aurélio recomendava regular cada ato como quem pode deixar a vida a qualquer momento. Ele quer dizer com isso que a lembrança da morte serve para escolher o que se faz agora: quem sabe que o dia pode ser o último não o gasta com o que não importa. Esse é o uso da primeira metade da linha; a segunda diz o que, por isso, vale a pena fazer hoje. Essa lembrança foi chamada mais tarde de <i>memento mori</i>, lembre-se de que vai morrer, e os estoicos faziam dela um exercício diário: Epicteto, no <i>Manual</i>, pede que a morte esteja todos os dias diante dos olhos, porque quem sabe que o tempo é limitado põe o dia em ordem. Se você anda frágil, se você se reconhece nos sinais do aviso de <i>Como usar este livro</i> ou nos de <i>Do escrúpulo</i>, no Livro V, escreva, em vez da primeira metade, <i>O meu tempo é limitado.</i> Diz a mesma coisa, e o resto da linha não muda. <font color='#6b6b6b'>(Lição X)</font>", PI)
add("<b>A da vez e a sua ocasião.</b> Leia no breviário a linha da microação da vez. No dia um, é a da ordem, a primeira do livro: quando você se sentar à mesa, tudo o que distrai sai dela; quando se levantar dela, a mesa volta à ordem. O exercício inteiro está no Livro III, e você vai lê-lo numa destas noites antes do dia zero. Depois, preveja: onde, hoje, vai aparecer a ocasião? Percorra o dia por dentro, as vezes em que você vai se sentar e se levantar, e escolha a que vai pesar mais, que é quase sempre a da obra de hoje. Marco Aurélio começava o dia prevendo o intrometido e o ingrato que ia encontrar, para que, quando viessem, não o pegassem desprevenido e ele lhes respondesse como tinha decidido de manhã <font color='#6b6b6b'>(<i>Meditações</i>, II, 1)</font>; você prevê o momento em que o gesto vai ser posto à prova.", PI)
add("<b>A hora de parar.</b> Escreva a hora depois da qual, hoje, não há obra nem culpa. Ela é marcada de manhã, de cabeça fria, porque à noite ninguém a julga bem; a razão está em <i>Do descanso</i>.", PI)
add("<b>O piso, se for dia dele.</b> Se você acordou com febre, se vai estar em viagem, se a circunstância lhe tira as condições do dia, escreva agora: <i>hoje, piso</i>. Se nada disso acontece, não declare nada. À tarde já não se declara; <i>Do piso</i> diz por quê.", PI)
add("<b>A primeira tarefa.</b> Confirme a primeira tarefa que você escreveu na noite anterior (na manhã do dia um, escolha-a agora), feche o caderno e vá a ela. É o primeiro passo da obra de hoje; se a obra só acontece no fim do dia, é a tarefa do trabalho que você evitaria se pudesse, como ficou dito acima, antes destes passos. O que se faz na primeira hora tende a definir o que se faz no resto do dia. A sétima linha, que vai lhe chegar com o exercício do terminar, diz isso numa pergunta e numa palavra.", PI)
add("Há manhãs que começam com uma urgência, um filho que chora, alguém que precisa de você antes que você tenha aberto os olhos. A urgência se atende; ela não é distração. O caderno se abre logo que ela passa, e antes de qualquer outra coisa que não a exija.", PI)
st.append(Paragraph("Durante o dia", MOM))
add("Depois, o dia corre como correm os dias. As linhas atravessam os instantes em que são chamadas; a da vez acontece quando chega a ocasião dela e, mais adiante no caminho, também as que ficaram, que já não se marcam mas continuam, cada uma na sua ocasião. Fora das ocasiões, o método não lhe pede nada. Não interrompa a vida para pensar nele.", PI)
add("<b>A folha de captura</b> fica ao lado da obra, como você viu em <i>Do primeiro dia</i>. O que surge sem pertencer à tarefa, uma lembrança, uma conta a pagar, a vontade de fazer outra coisa, vai para lá numa linha, e você volta ao trabalho. Escrever a linha não o obriga a nada; só tira a coisa da cabeça e deixa você outra vez com uma coisa só à frente.", PI)
add("A folha tem antepassados. Os gregos e romanos letrados mantinham <i>hypomnémata</i>, cadernos em que se anotava o que se lia, o que se ouvia, o que vinha ao espírito e merecia ser guardado, para ser relido e trabalhado depois. Michel Foucault, que estudou a prática, notou que esses cadernos não serviam para confessar nada; serviam para reunir o disperso e tê-lo à mão na hora certa. A folha de captura é mais humilde e guarda o que interrompe, raramente uma máxima. Mas o gesto é o mesmo: o que passa pelo espírito vai para o papel para que o espírito o solte, e só é retomado na hora marcada. Uma boa memória, pode parecer, dispensa a folha. É certo que a ideia não se perderia; o custo está em mantê-la esperando, porque, enquanto não está escrita, ela pede para ser lembrada, e cada pedido é uma pequena saída da obra.", PI)
st.append(Paragraph("À noite &nbsp;<font size=10 color='#6b6b6b'>cerca de dez minutos, longe de toda distração</font>", MOM))
add("Se você lê isto na noite do dia um, antes da primeira marca, a obra de hoje existe ou ficou por fazer, e a hora de parar já passou ou está perto. Sente-se com o caderno, longe do que distrai. São de novo cerca de dez minutos, e os passos vêm na ordem.", PI)
add("<b>A marca.</b> Uma só, na folha de marcas, sobre a da vez, que hoje é a da ordem, decidida pela sessão que mais pesou e pelas regras de <i>Da medida</i>. Hoje você não escreve <i>chegou</i>, aconteça o que acontecer.", PI)
add("<b>A linha do dia.</b> Escreva a resposta a uma pergunta: <i>O que existe agora que não existia de manhã?</i> Um objeto, uma entrega, um passo concreto, que você possa pôr ao lado da obra de hoje escrita na linha da manhã. Se a resposta for nada, escreva nada, sem enfeite. Na mesma linha, diga, com um sim ou um não, se as alavancas de hoje foram feitas. Elas não têm marca própria: a marca é só da microação da vez, que acontece dentro do dia, nas ocasiões dela, enquanto as alavancas são os passos da obra. Nas noites de passagem, esses sins e esses nãos mostram se alguma alavanca pede emenda. Na noite em que a obra em curso ficar pronta, escreva logo a seguinte, descendo de novo do ano.", PI)
add("<b>A linha da queda,</b> só se houve queda: hoje, se você marcou cruz; mais adiante, também quando ceder numa das que ficaram. Uma linha basta. Primeiro, numa palavra, diga que perda foi: tirada, levada ou deixada cair, a divisão de Sêneca que o estribilho pede. Depois, diga onde foi e o que você fará diferente. Pergunte onde estava o buraco e deixe de fora o juízo sobre si mesmo. <font color='#6b6b6b'>(Lição IV)</font> A linha da queda guarda a ordem do exame de Sêneca, que você viu em <i>Da outra chance</i>, em que o perdão vem depois da correção: primeiro o que você fará diferente, e só então o caderno fechado, sem sentença sobre você.", PI)
add("<b>A folha de captura.</b> Percorra as linhas do dia e decida cada uma: faz-se amanhã, marca-se para um dia, ou risca-se.", PI)
add("<b>A primeira tarefa de amanhã,</b> escrita: o primeiro passo da obra de amanhã ou, se a obra só acontece no fim do dia, a tarefa do trabalho que você evitaria, como ficou dito em <i>Do dia</i>, antes dos passos da manhã. A quinta linha, que vai lhe chegar com o exercício do terminar, deixa esse passo escrito no fim de cada sessão de obra, e é ele que você copia aqui. Depois, feche o caderno.", PI)
add("Este exame é dos mais antigos que se conhecem. Os <i>Versos de ouro</i>, poema que os antigos ligavam à escola de Pitágoras, pedem que não se deixe o sono descer sobre os olhos antes de ter repassado três vezes cada ato do dia, com três perguntas: em que falhei? que fiz? que dever deixei de cumprir? Séculos mais tarde, Epicteto ainda os citava aos discípulos. A sua noite herda as três perguntas e as encolhe: a marca e a linha da queda respondem à primeira, a linha do dia à segunda, a folha de captura e a tarefa de amanhã à terceira. Uns dez minutos, porque um exame que custa uma hora é abandonado depois de poucos dias. Nos dias de piso, declarado de manhã, a noite se reduz à marca e, numa linha, à primeira tarefa de amanhã.", PI)
add("A linha do dia tem um antepassado mais modesto, e vem de um pintor. Plínio, o Velho, no livro trinta e cinco da <i>História natural</i>, conta que Apeles, o mais célebre dos pintores gregos, o único a quem Alexandre permitia retratá-lo, tinha um costume: nenhum dia, por mais ocupado que fosse, passava sem que ele exercitasse a arte traçando ao menos uma linha. O costume, diz Plínio, virou provérbio, e é dele que vem o latim <i>nulla dies sine linea</i>, nenhum dia sem linha. Dezoito séculos depois, Émile Zola mandou pintar essas palavras sobre a lareira do escritório da casa de Médan, onde escreveu a maior parte dos romances dos Rougon-Macquart, um número fixo de páginas a cada manhã. Repare no tamanho da exigência de Apeles. Bastava-lhe uma linha, desde que estivesse na tábua à noite e de manhã não estivesse. É a pergunta da sua noite, <i>o que existe agora que não existia de manhã?</i>, respondida por quem a respondia com o pincel.", PI)
add("Fechado o caderno, vem o quarto, sem nada que distraia, como manda a oitava lei. Amanhã de manhã você volta a estes passos, e só abre o livro se um caso o deixar em dúvida.", PI)

st.append(Paragraph("Na noite de passagem", MOM))
add("Numa noite que este livro não sabe dizer qual será, ao fazer a marca, você vai reconstruir a ocasião que mais pesou e encontrar o gesto feito sem encontrar a decisão de fazê-lo: foi a ocasião que o lembrou dele, e não o caderno. Você vai escrever <i>chegou</i> ao lado do traço, como a mulher de quem lhe falei em <i>Do primeiro dia</i>. Essa noite e a manhã seguinte formam a passagem, e a passagem é também o único momento em que o método se emenda, como diz a nona lei. Nessa noite, depois dos minutos de sempre, faça o que está abaixo, na ordem.", PI)
for i, t_ in enumerate([
 "Leia uma das Doze Lições, a seguinte na ordem, ou no tempo de ócio.",
 "Releia a folha do dia zero e a página do Homem, as treze frases que vêm depois das Lições. Na primeira noite de passagem, copie-a à mão; nas seguintes, releia-a.",
 "Leia a frase da anti-visão, o primeiro ponto da folha do dia zero. Só nestas noites e na onda, não todos os dias: o peso dela se gasta com o uso.",
 "Faça por escrito as emendas que as marcas pedirem, ao método, à folha do dia zero ou ao domínio. Se não pedirem nenhuma, não emende nada.",
 "Leia, no Livro III, o exercício da microação que entra amanhã, e preveja onde a ocasião dela vai aparecer.",
], 1):
    add(f"{rom(i)}. &nbsp;{t_}", LAW)

sec("Do descanso")
add("<i>“É preciso dar descanso ao espírito: repousado, ele se levanta melhor e mais vivo.”</i> &nbsp;<font color='#6b6b6b'>— Sêneca, <i>Da tranquilidade da alma</i></font>", ParagraphStyle('dq', parent=P, alignment=TA_CENTER))
add("Sêneca escreve a frase do alto no fim de <i>Da tranquilidade da alma</i>, e compara o espírito ao campo fértil, que se esgota se nunca o deixam repousar. A ideia é que o espírito precisa de pausas para continuar a trabalhar bem, e é por isso que, neste livro, o descanso tem regras, como o trabalho as tem. O primeiro descanso deste caminho você já teve, se o dia um correu como a manhã previa: a hora de parar que você escreveu antes da obra. Quando ela chegou, a obra se fechou onde estava. Se você continuou depois dela, tratou como sugestão o que decidiu de manhã; amanhã, quando ela chegar, termine o passo em que estiver, e a obra se fecha aí.", PI)
add("Um esforço sem repouso não se mantém. Quem passa semanas no limite costuma parar de uma vez e, com essa parada, abandona também o que tinha conseguido. O descanso pertence à disciplina, assim como o intervalo entre as séries pertence ao treino.", PI)
add("Max Weber viveu essa parada por inteiro. Nos anos noventa do século XIX, professor jovem e já célebre, primeiro em Friburgo e depois em Heidelberg, ele dava aulas, examinava, escrevia pareceres e estudos sobre os trabalhadores rurais do leste alemão, e trabalhava noite adentro, sem se conceder pausa, como conta Marianne Weber, a mulher dele, na biografia que escreveu depois. Em 1898 a máquina parou de uma vez. Ele já não conseguia ler, nem escrever, nem dar aula. Pediu licença, viajou para a Itália, tentou voltar mais de uma vez, e em 1903 renunciou à cátedra. Foram anos sem obra, para um homem que antes não sabia parar uma noite. Quando voltou a escrever, em 1904 e 1905, saiu <i>A ética protestante e o espírito do capitalismo</i>, e Weber nunca mais teve a capacidade de trabalho daqueles anos de Heidelberg. O limite que ele não quis marcar, o corpo marcou por ele, e cobrou anos.", PI)
add("Há uma razão mais profunda, e vou contá-la a você com Pieper. Em 1947, em Bonn, numa Alemanha em ruínas onde tudo pedia reconstrução e trabalho, o filósofo Josef Pieper deu umas conferências que publicou no ano seguinte com o título <i>Muße und Kult</i>, ócio e culto. Começava por uma palavra grega. <i>Scholé</i> era o tempo livre, o tempo em que não se está preso ao necessário, e dela vêm a <i>schola</i> latina e a nossa escola; o trabalho se dizia pela negativa, <i>ascholía</i>, falta de ócio. Pieper lembrava a frase de Aristóteles no último livro da <i>Ética a Nicômaco</i>: trabalhamos para ter ócio, como fazemos a guerra para ter paz. Aristóteles queria dizer que o ócio é o fim e o trabalho é o meio, e que uma vida feita só de trabalho toma o meio pelo fim. E Pieper defendia, contra a pressa do momento, que o ócio é a base da cultura: uma atitude de receber e de deixar as coisas serem, que o trabalhador ocupado o tempo todo perde a capacidade de ter.", PI)
add("Pieper dava a esse ócio uma raiz que o título do livro dele nomeia e que este livro deixa de lado: o culto. Para ele, o ócio vive da festa, e a festa vive do culto, do louvor que diz sim ao mundo; cortado dessa raiz, o tempo livre degenera em pausa entre dois trabalhos. E ele lia a acédia, a velha tristeza dos monges, com Tomás de Aquino, de um modo que talvez surpreenda você: como a recusa de consentir no próprio ser, que está na raiz da inquietação de quem não consegue parar de trabalhar. O contrário da acédia, para Pieper, é o ócio, a afirmação alegre do próprio ser, do mundo e de Deus.", PI)
add("Isso corrige, sem desmentir, o que se disse sobre o intervalo entre as séries. O ócio também repõe as forças, e é bom que reponha. Mas Pieper alertava contra o descanso que serve só para render mais: quem descansa apenas pensando no dia seguinte já trouxe o trabalho para dentro do tempo livre, e passa a medir se está descansando bem.", PI)
add("O método guarda o ócio de duas maneiras. A primeira é diária, e pequena: a hora de parar, que você marca a cada manhã. Quando ela chega, você termina o passo em que está, como pede <i>Da assentada</i>, e a obra se fecha aí; o que ficou por fazer espera a manhã seguinte. Depois dela não há obra nem culpa. Ela é marcada de manhã, de cabeça fria, pela mesma razão que o piso: à noite, com cansaço ou com o entusiasmo do trabalho, ninguém julga bem a hora de parar. A noite e a sua marca vêm depois dela como sempre, e as microações também não param, porque são pequenas e pertencem à vida, e não à obra.", PI)
add("A segunda é maior e mais rara: o dia de ócio. Ele não tem frequência fixa. Talvez venha daqui a semanas, numa noite em que você perceba que o cansaço atravessa as noites e que o descanso de cada dia já não o desfaz; o Livro V ensina a reconhecer esse ponto. Nessa noite, na véspera, declare por escrito o dia seguinte como dia de ócio. Nunca no próprio dia: declarado de manhã, seria o cansaço do momento que escolheria a data. Nunca dois seguidos, e nunca no dia seguinte a uma cruz, que é o dia sagrado da quinta lei. Nesse dia não há obra nem culpa: você caminha, conversa, lê por prazer, dorme. As microações continuam nele, e à noite se marca como em qualquer outro dia. Ele não é dia de recaída, nem de distração sem fim, que cansa mais do que repousa.", PI)
add("Abraham Joshua Heschel, rabino nascido em Varsóvia, que deixou a Europa à beira da guerra e acabou ensinando em Nova York, escreveu em 1951 um livro breve, <i>O sábado</i>, sobre o sétimo dia da tradição dele. Ele o chamou de palácio no tempo. As outras civilizações, dizia, santificaram lugares, templos e montanhas; a Bíblia santificou um tempo, e o fiel entra nele toda semana como quem entra num edifício, com hora certa para as portas se abrirem e se fecharem. Ao seu ócio, este livro pede só o que fazia daquele dia um palácio: as paredes. A hora de parar, marcada de manhã, é a parede de cada dia; o dia de ócio tem as suas desde a véspera, quando foi declarado. Sem elas, o descanso se dispersa em pausas curtas, e nenhum dia fica inteiro para ele. Heschel escreveu também que os dias da semana existem por causa do sábado. O dia de ócio deste livro guarda essa ordem só em parte: ele serve também à obra, e por isso as microações e a marca continuam nele. É, em parte, um ócio instrumental; de Pieper e de Heschel, este livro toma as paredes e deixa com eles o centro, o culto e o sábado como fim.", PI)
add("O ócio e a preguiça podem ocupar as mesmas horas com as mesmas coisas. O que os separa é o modo como começam e terminam: o ócio foi decidido antes e tem fim marcado; a preguiça começa sem decisão e termina quando calha.", PI)
add("Quanto ao que cabe nele, a pergunta que separa é simples: faço isto para ter feito, ou porque é bom fazê-lo? O que se faz para ter feito é obra, e espera o dia seguinte. O risco é que um dia de ócio sem data certa acabe não vindo nunca, ou vindo sempre. Contra o <i>sempre</i> estão as paredes: a véspera, a proibição de dois seguidos, o dia depois de uma cruz. Contra o <i>nunca</i> estão a hora de parar, que dá a cada dia o seu pedaço de ócio sem esperar licença, e o Livro V, que mostra o cansaço que já não se atravessa. Quando o dia vier, guarde-o como guardaria uma consulta marcada.", PI)
add("E quando a trégua vier sem ter sido merecida, num dia em que tudo pesa menos sem razão aparente, aceite-a. Muitas vezes a clareza vem fora das horas de trabalho, numa caminhada ou no banho, depois que se deixou de procurá-la. <font color='#6b6b6b'>(Lição III)</font>", PI)

sec("Do piso")
add("Há dias em que o que falta são condições, e não vontade: doença, viagem, um período de provas, um peso na família. Para esses dias existe o piso, o mínimo de cada coisa, declarado de manhã. Você o viu em uso em <i>Do primeiro dia</i>, na manhã de febre da mulher de quem lhe falei. Aqui ficam a lista inteira e a razão de cada regra. O piso se define agora, e não no dia ruim, quando tudo parece justificar o abandono.", PI)
add("O piso é usado numa manhã que este livro não pode prever. Você acorda com febre, ou tem de partir antes do sol, ou alguém da sua casa adoece durante a noite. Nessa manhã, antes de qualquer outra coisa, ainda na cama se for preciso, escreva no caderno <i>hoje, piso</i>, e o dia passa a pedir só isto:", PI)
piso = [
 ("A microação da vez:", "ao menos uma vez, no piso que o exercício dela dá. É a única linha que decide a marca."),
 ("A leitura:", "uma página."),
 ("O corpo:", "dez minutos, ou uma caminhada."),
 ("O domínio:", "quinze minutos na parte difícil."),
 ("A noite:", "a marca na folha e, numa linha, a primeira tarefa de amanhã."),
 ("O corte:", "não tem piso. É a única coisa que nunca se reduz."),
]
for a_, b_ in piso:
    add(f"<b>{a_}</b> {b_}", LAW)
add("O dia de piso se declara de manhã, nunca à tarde: declarado à tarde, quem o escolhe é o cansaço do dia. Cumprido o piso da microação da vez, o dia conta como traço, porque o que se protege nesses dias é a continuidade do gesto, e ela só se mantém se o dia pequeno contar como dia. O piso que decide a marca é só esse, o mínimo da microação, que cada exercício dá em <i>Do piso e do sinal</i>. As outras linhas da lista são o mínimo recomendado para o dia, e valem para quem já tem a leitura, o corpo ou o domínio nos dias comuns. Num dia de piso declarado, cumprir só o da microação da vez já é traço, como na manhã de febre da mulher. Mas o piso é para a circunstância, e não para a falta de vontade; para esta, há a sexta linha e a terceira lei. E o corte não tem piso porque um corte reduzido deixaria entrar de novo, aos poucos e com licença, aquilo que se cortou; o Livro IV ensina isso.", PI)
add("O piso pode parecer a meia-força que o começo deste livro condenou, a de quem começa o treino e não o faz de verdade, agora com licença por escrito. A diferença está no que cada um guarda. A meia-força finge fazer a obra e a faz pela metade, para que reste a desculpa de não ter dado tudo; estraga a obra e protege só a sentença sobre você. O piso não promete a obra. Ele guarda a ocasião, que continua sendo encontrada pelo gesto no dia em que tudo pedia que ela passasse sem ele, e a identidade de quem faz isto todos os dias, também nos de febre. A obra desse dia fica declaradamente por fazer, e por isso o piso se escreve de manhã, com o tamanho dito, e se cumpre inteiro nesse tamanho: a página lida até o fim, os dez minutos de corpo feitos de verdade. O que foi declarado não deixa reserva onde a desculpa se esconda; a meia-força de um dia comum, sem nada escrito, continua condenada.", PI)
add("Matisse viveu um piso que durou anos. Em 1941, aos setenta e um, foi operado em Lyon de um câncer abdominal e saiu da cirurgia sem forças para ficar muito tempo de pé diante do cavalete; passou boa parte do que lhe restava de vida na cama ou numa cadeira de rodas. Não parou, e também não fingiu que nada tinha mudado. Reduziu o gesto ao que o corpo permitia: os assistentes cobriam folhas de papel com guache, e ele recortava as formas com uma tesoura grande, sentado, e indicava onde prendê-las na parede. Assim fez <i>Jazz</i>, o livro publicado em 1947, em cujo texto escreveu que recortar direto na cor lhe lembrava o talhe direto dos escultores. Os vitrais da capela de Vence, que ele desenhou nesses anos, também saíram de recortes. O gesto ficou menor, e a obra não se interrompeu.", PI)
add("Bento também previa esses dias. Na mesma regra que defendia o sono, ele manda que aos irmãos doentes ou de pouca força se dê um trabalho ou um ofício tal que nem fiquem ociosos nem sejam esmagados pelo peso do trabalho. O piso lhe pede o mesmo. Num dia de febre não se exige a obra inteira, e também não se larga tudo: faz-se o gesto pequeno, e o caminho não se interrompe.", PI)

sec("Da companhia")
add("Boas companhias são raras, e não se escolhem como se escolhe um livro. As obras, sim. Os livros dos melhores autores estão à mão a qualquer hora e custam pouco.", PI)
add("Sêneca, em <i>Da brevidade da vida</i>, diz que só estão verdadeiramente vivos os que dedicam tempo aos sábios: podem discutir com Sócrates, duvidar com Carnéades, repousar com Epicuro, e nenhum deles os despedirá de mãos vazias. Maquiavel, exilado da política, escreveu a um amigo, Francesco Vettori, em dezembro de 1513, que, ao anoitecer, tirava a roupa do dia, enlameada, vestia-se com dignidade e entrava nas antigas cortes dos homens antigos. Ali perguntava, e eles respondiam; e por quatro horas não sentia tédio nem temia a pobreza. Para Sêneca, o tempo passado com os livros dos sábios é o único que se soma à vida, porque junta à sua os séculos deles; cada nome da lista está ali pelo que ensina. Maquiavel mostra o modo: tratava a leitura como um encontro, com roupa de visita e perguntas de quem conversa, e por isso, exilado e pobre, tinha nessas horas uma companhia que o exílio não lhe tirava.", PI)
add("Mais de um século e meio antes de Maquiavel, Petrarca levou a conversa mais longe. Em 1345, em Verona, encontrou na biblioteca do cabido da catedral um manuscrito com as cartas de Cícero ao amigo Ático, que quase ninguém lia havia séculos. Leu-as e encontrou um Cícero que não conhecia, metido nas lutas da república, volúvel nas amizades, longe do sábio sereno dos tratados. E fez uma coisa estranha: escreveu para ele. Uma carta a Cícero, morto havia quase catorze séculos, censurando-o como a um amigo que falhou, e logo outra, reconhecendo a grandeza dele. Escreveu depois a Sêneca, a Tito Lívio, a Virgílio, a Homero, e reuniu essas cartas no último livro da correspondência dele. Tratava os antigos como vivos, isto é, como gente de quem se pode discordar.", PI)
add("Montaigne fez da companhia um lugar. Em 1571, aos trinta e oito anos, retirou-se para a torre do castelo dele, onde tinha a biblioteca, uma sala redonda com os livros em volta, em cinco prateleiras, e mandou inscrever na parede, em latim, que consagrava aquele retiro à liberdade, à tranquilidade e ao ócio dele. Nas vigas do teto mandou gravar dezenas de sentenças gregas e latinas, de modo que, ao levantar os olhos da página, dava com outra voz. No ensaio sobre os três comércios, ele compara as companhias da vida, os amigos, as mulheres e os livros: as duas primeiras são mais vivas e mais incertas; os livros são a mais constante e a que está sempre à mão, e o consolam na velhice e na solidão.", PI)
add("Escolha, portanto, seus companheiros entre os autores. O livro da vez é o companheiro da vez, e com ele se conversa: anota-se na margem, discorda-se, pergunta-se. Antes de uma decisão difícil, consulte um deles e pergunte o que faria Marco Aurélio, ou o que diria Sêneca. É a pergunta da máscara feita a um rosto que deixou escrito como pensava, e por isso a resposta vem com as razões dele. Ouvidas as razões, quem decide é você.", PI)
add("Você não precisa de torre nem de vigas. Copie numa folha duas ou três frases do livro da vez e ponha a folha onde possa vê-la quando levantar os olhos da obra. Troque-a quando o livro se fechar. No fim de um ciclo, você terá, numa gaveta, as vozes que o acompanharam, na ordem em que vieram.", PI)
add("Mas a conversa pede que você responda. Schopenhauer, no ensaio <i>Sobre a leitura e os livros</i>, dos <i>Parerga e Paralipomena</i>, avisava que ler é pensar com a cabeça de outro, e que quem só lê acaba sem cabeça própria. Ele quer dizer que, enquanto você lê, quem pensa é o autor, e o seu pensamento descansa; esse pensamento só trabalha quando você responde ao que leu. Leia com a caneta na mão e escreva na margem de cada livro ao menos uma discordância sua, mesmo torta. <font color='#6b6b6b'>(Lição V)</font>", PI)
add("Um livro não corrige você em tempo real, nem vê o seu trabalho. Para isso, o exercício da crítica continua necessário, e uma pessoa que saiba mais, mesmo distante, vale como mestre.", NOTE)
add("Às vezes esse mestre está do outro lado do mundo. Em janeiro de 1913, Srinivasa Ramanujan, escriturário de vinte e cinco anos no porto de Madras, sem diploma, que aprendera matemática quase sozinho num livro de fórmulas, mandou a G. H. Hardy, em Cambridge, uma carta com umas dez páginas de teoremas. Hardy recebia cartas de excêntricos e quase a pôs de lado; à noite, leu-a com Littlewood, e os dois concluíram que estavam diante de um matemático de primeira ordem. Hardy escreveu depois que algumas daquelas fórmulas tinham de ser verdadeiras, porque, se não fossem, ninguém teria tido imaginação para inventá-las. Mas a carta trazia também erros, e quase nenhuma demonstração. Nenhum livro podia dizer isso a Ramanujan. Hardy disse, primeiro por carta e depois em Cambridge, onde passou anos ensinando-lhe a prova rigorosa sem apagar o resto. Ramanujan tinha os livros; faltava-lhe alguém que olhasse o trabalho dele.", PI)
add("Agora você tem a moldura inteira. A folha do dia zero diz para onde você vai; as linhas dizem o que pensar no instante; as leis dizem o que não se discute; o dia diz quando cada coisa acontece; o piso e o descanso dizem como atravessar os dias ruins e os cansados sem quebrar; e os livros lhe dão com quem falar pelo caminho. Tudo isso serve a uma só hora, aquela em que você se senta diante de uma coisa e fica com ela até acabar. Falta o gesto, e o gesto tem uma ordem. Você já o começou: a estação zero ficou no dia zero, e a primeira microação está na folha de marcas desde a manhã do dia um, como você a viu entrar em <i>Do primeiro dia</i>. O livro seguinte lhe entrega os exercícios na ordem, estação após estação, até o décimo terceiro. Daqui em diante você abre o livro sobretudo nas noites de passagem, e o caderno todas as manhãs e todas as noites.", PI)
add("Duas coisas decidem se você já pode passar aos exercícios. Se a manhã e a noite de hoje ainda lhe pediram o livro aberto, releia <i>Do dia</i> a partir de <i>De manhã</i> e faça amanhã os passos com ele aberto. E se a da vez não chega há muitas noites, leia o Livro V antes de mudar seja o que for, porque a passagem por decisão depende das quatro provas dele.", PI); fleur()
# O fecho vai junto do parágrafo anterior, para não ficar sozinho numa página.
st[-3:] = [KeepTogether(st[-3:])]
# ===================== LIVRO III =====================
livro("III", "Dos exercícios")

add("Os treze gestos deste livro preparam, um de cada vez, o lugar onde costuma aparecer o estado de foco que dá nome ao livro. Os primeiros tratam da mesa, do terminar, da atenção e do corpo; os do meio tratam da obra; os últimos tratam do ânimo que sustenta a obra. Esses últimos trabalham mais longe da mesa: nas conversas, nas opiniões, no conforto e na vontade de contar, que formam o dia em volta dela. Cada gesto, quando chega, tira um obstáculo entre você e a coisa que está à sua frente, alguns de perto, outros de longe.", PI)
add("Você lê esta abertura e o exercício da ordem numa das noites antes do dia zero, enquanto faz a marca de <i>Da primeira marca</i>; cada um dos outros é lido na noite de passagem em que o anterior chegar, e só esse. Você sai deste livro, no fim das estações, com as treze microações entre as que ficaram e o ciclo pronto para <i>Da prova</i>, no Livro V.", PI)
add("Este livro guarda treze exercícios, e mais um, o exercício zero, que você fará no dia zero. Um exercício, aqui, é um gesto treinado até ser feito sem esforço de decisão, e cada um se reduz a uma microação: um gesto central, curto, na ocasião certa, como o da mulher de quem <i>Do primeiro dia</i> vai lhe falar. Alguns exercícios trazem práticas que servem ao gesto, mas só o gesto central é marcado. Você treina uma microação de cada vez, a da vez, até a noite em que escreve <i>chegou</i>; na manhã seguinte ela passa a ficar, e entra a seguinte. Os exercícios estão agrupados em estações, trechos do caminho com um assunto só. A estação zero é a do domínio; a primeira treina as condições do trabalho; a segunda entra na obra; a terceira trata do que você faz quando a obra, as pessoas e as circunstâncias o contrariam. Os nomes das três seguem as fases com que Robert Greene, escritor contemporâneo, autor de <i>Maestria</i>, de 2012, descreve nesse livro a formação num ofício, do aprendizado à maestria.", PI)
add("Quanto tempo leva cada trecho, ninguém pode lhe dizer de antemão: o gesto chega quando chega. Posso lhe dizer outra coisa, porque fiz este caminho antes de você. Haverá noites em que um exercício mais adiante vai lhe parecer mais urgente. Não se pula para a frente para escolher o trecho que agrada: a ordem existe para que o exercício de hoje torne possível o de mais adiante (§1).", PI)
add("Todos os exercícios têm a mesma forma, para que, numa noite de dúvida daqui a três semanas, você encontre depressa o que procura. No alto, o número, o nome e uma letra, H ou J. Embaixo, em itálico, a frase de um autor. Depois, em negrito, o gesto: a microação inteira em uma ou duas frases, quase sempre começando pela ocasião, <i>quando você se sentar</i>, <i>quando vier o desejo</i>. É esse gesto que o breviário resume numa linha, e é sobre ele que você faz a marca. Logo abaixo do gesto, <b>Do porquê</b> diz em três partes por que você o faz: a ideia de onde ele vem, o mecanismo que o faz funcionar e uma frase que você pode dizer por dentro quando o fizer.", PI)
add("Em seguida vêm as partes, sempre na mesma ordem. <b>Do começo</b> conta o primeiro dia do exercício e fecha com uma linha, <b>Você sai com</b>, que diz o que tem de existir, no caderno ou no seu dia, quando chegar a primeira noite do exercício; se faltar alguma coisa dessa linha, o começo ainda não está feito. <b>Do modo</b> são os passos, numerados, para você reler de pé e com pressa. <b>Da marca</b> diz o que, naquele gesto, conta como traço, como cruz e como ponto, e como se reconhece a noite de escrever <i>chegou</i>. As regras gerais de <i>Da medida</i> valem acima de tudo e não se repetem em cada exercício. Nos exercícios com várias partes, só o gesto central é marcado; e, se o exercício pede uma escrita curta à noite ou traz práticas, <i>Da marca</i> diz o que acaba com o gesto e termina numa linha, <i>Depois do chegou fica</i>, com o que continua. <b>Dos erros</b> nomeia os modos de cumprir o exercício por fora sem cumpri-lo de fato. <b>Do piso e do sinal</b> tem duas linhas secas: o piso é o mínimo do gesto para um dia de doença ou viagem, declarado de manhã; o sinal de consolidação descreve o gesto já maduro, semanas ou meses depois de ter chegado, e não entra na marca nem na passagem. <b>Do sentido</b>, por último, é a razão do gesto: de onde ele vem, quem o praticou antes de você, a objeção mais forte e a resposta a ela.", PI)
add("Depois de cada exercício vêm dois parágrafos sem rótulo. O primeiro adapta o gesto a outras vidas; o segundo é feito de frases que começam com <i>Se</i>: se a mesa enche no fim da tarde, se a lista cresce. É esse segundo parágrafo que você vai procurar quando o gesto falhar sempre do mesmo modo e você não souber por quê.", PI)
add("Falta a letra do título. <b>H</b> quer dizer hábito: com a repetição, o gesto passa a acontecer quase sem decisão, como quando se acende a luz ao entrar num quarto escuro. <b>J</b> quer dizer juízo: o gesto fica mais rápido e mais leve, mas sempre pede que você pense, porque a situação nunca se repete igual; ouvir uma crítica ou mudar de opinião diante de um argumento são gestos assim. Os quatro da primeira estação são H. Num exercício J, <i>chegou</i> quer dizer que o gesto apareceu na ocasião sem o breviário, e não que deixou de pedir cabeça.", PI)
add("Logo abaixo vem a estação zero, que você vai atravessar no dia zero. Ela não é para esta noite: você vai lê-la, ou relê-la, numa noite antes do próximo dia zero. Passe à primeira estação e ao exercício da ordem.", PI)


PEND = []
def estacao(t, sub):
    PEND.extend([Paragraph(t.upper().replace(" ", " &nbsp;"), SEC), Paragraph(sub, ParagraphStyle('ss', parent=EXQ, alignment=TA_CENTER, spaceAfter=8))])
LBX = ParagraphStyle('lbx', **{**base, 'textColor': GRAY}, fontSize=9.5, leading=12, spaceBefore=6, spaceAfter=2, keepWithNext=1)
def exe(n, nome, tipo, frase, autor, texto, sentido=None, como=None, erros=None, piso=None, sinal=None, comeco=None, marca=None, sai=None, porque=None, saber=None):
    pre = PEND[:]; PEND.clear()
    st.append(KeepTogether(pre + [
        sumario(Paragraph(f"{n}. &nbsp;{nome} <font size=9.5 color='#6b6b6b'>&nbsp;{tipo}</font>", ParagraphStyle('exh', parent=EXE, fontSize=13.5, spaceBefore=20)),
                1, f"{n}. {nome}"),
        Paragraph(f"“{frase}” &nbsp;— {autor}", EXQ),
        Paragraph(f"<b>{texto}</b>", P)]))
    if porque:
        st.append(Paragraph("D O &nbsp; P O R Q U Ê", LBX))
        for par in porque: st.append(Paragraph(par, PI))
    if comeco or sai:
        st.append(Paragraph("D O &nbsp; C O M E Ç O", LBX))
        for par in comeco or []: st.append(Paragraph(par, PI))
        if sai: st.append(Paragraph(f"<b>Você sai com:</b> {sai}", PI))
    if como:
        st.append(Paragraph("D O &nbsp; M O D O", LBX))
        for i, c in enumerate(como, 1): st.append(Paragraph(f"{i}. &nbsp;{c}", LAW))
    if marca:
        st.append(Paragraph("D A &nbsp; M A R C A", LBX))
        st.append(Paragraph(marca, PI))
    if erros:
        st.append(Paragraph("D O S &nbsp; E R R O S", LBX))
        st.append(Paragraph(erros, PI))
    if piso or sinal:
        blk=[Paragraph("D O &nbsp; P I S O &nbsp; E &nbsp; D O &nbsp; S I N A L" if piso else "D O &nbsp; S I N A L", LBX)]
        if piso: blk.append(Paragraph(f"<b>Piso:</b> {piso}", P))
        if sinal: blk.append(Paragraph(f"<b>Sinal de consolidação:</b> {sinal}", P))
        st.append(KeepTogether(blk))
    if sentido:
        st.append(Paragraph("D O &nbsp; S E N T I D O", LBX))
        for par in sentido: st.append(Paragraph(par, PI))
    if saber:
        st.append(Paragraph("D O &nbsp; Q U E &nbsp; S E &nbsp; S A B E", LBX))
        st.append(Paragraph(saber, PI))

estacao("Estação zero", "Do domínio. Uma vez por ciclo.")
st.extend(PEND); PEND.clear()
add("Esta estação é lida numa de duas ocasiões. Pode ser no dia zero, se a lista do que você amou não mostrou nada e você veio procurar o porquê. Ou pode ser numa noite do caminho, antes do próximo dia zero, para você ler com calma a razão do que fez às pressas. O exercício zero vem primeiro porque é ele que diz para onde vão os outros treze. Volta-se a ele uma vez por ciclo, em cada novo dia zero.", PI)
exe("0", "Da vocação", "", "O que você amou verdadeiramente até agora?", "Nietzsche",
 "Faz-se no dia zero, descrito no prólogo.",
 ["Se você lê isto numa noite do caminho, vou lhe contar sobre um poeta que fez a mesma pergunta a um rapaz, por carta.",
  "No inverno de 1902, Franz Xaver Kappus, aluno da escola militar de Wiener Neustadt, com pouco menos de vinte anos, mandou alguns poemas a Rainer Maria Rilke e lhe pediu que dissesse se valiam alguma coisa. Rilke respondeu de Paris, em fevereiro de 1903, e a resposta começa com uma recusa: ele não vai julgar os versos. Diz ao rapaz que ele olha para fora, que compara seus poemas com os de outros e se inquieta quando as revistas os recusam, e que é exatamente isso que ele deve deixar de fazer. Ninguém pode aconselhá-lo nem ajudá-lo. Há um só caminho: entrar em si mesmo e perguntar, na hora mais silenciosa da noite, se morreria caso fosse proibido de escrever. Se a resposta for um sim simples e forte, que ele construa a vida segundo essa necessidade, até nas horas mais indiferentes.",
  "Rilke não pergunta ao rapaz se ele tem talento, nem se a poesia dá futuro. Pergunta pela necessidade, e manda procurá-la por dentro, numa hora sem plateia. Essa pergunta está perto da de Nietzsche, que também procura por dentro o que nenhum conselho dá, e que a manhã do dia zero obrigou você a fazer por escrito. A lista do que você amou é o seu modo de responder a Rilke sem ficar esperando uma voz no escuro. Em vez de perguntar uma única vez se morreria sem aquilo, você procura os momentos em que, fazendo aquilo, esqueceu o tempo, e deixa que eles se repitam na página até mostrarem o desenho.",
  "Talvez você nunca tenha amado nada com essa força, e a pergunta de Rilke o deixe de mãos vazias. Quase ninguém responde com um sim limpo, aos vinte ou aos quarenta. Por isso o exercício pede uma lista: um gosto fraco também deixa rastros, e, juntos, os rastros mostram o que se repete. Numa carta escrita meses depois, Rilke pede a Kappus paciência com tudo o que não está resolvido no coração, e que ame as próprias perguntas como quartos fechados ou livros escritos numa língua estrangeira; talvez, vivendo essas perguntas, ele entre um dia na resposta sem perceber. O domínio que você escreveu no dia zero é uma pergunta desse tipo, vivida durante um ciclo inteiro. No fim do ciclo, você volta a escrevê-lo, e só então sabe se era resposta."],
 ["Na manhã do dia zero, depois das oito perguntas, liste à mão tudo o que você amou fazer ou estudar desde criança, sem filtro de utilidade.",
  "Ao lado de cada item, escreva o momento em que você esqueceu o tempo fazendo aquilo.",
  "Sublinhe o que se repete. Escreva o domínio em uma frase; pode ser uma combinação de campos.",
  "Abaixo, escreva o porquê com rosto: o que de fato tira você da cama numa terça-feira, sem plateia. <font color='#6b6b6b'>(Lição I)</font>"],
 "Os dois erros aparecem enquanto a lista está sendo escrita. O primeiro é escolher o domínio pelo prestígio e não pelo amor. A mão hesita diante de um item que lhe causa vergonha e escreve no lugar dele uma coisa que soaria bem dita em voz alta. Escreva o que a mão ia escrever. O segundo é esperar ter certeza antes de escrever a frase. Ninguém tem certeza no dia zero. O domínio pode mudar no ciclo seguinte; o que ele não pode é ficar em branco.",
 None, "você consegue explicá-lo em trinta segundos sem hesitar.",
 comeco=[
  "O exercício zero é escrever, numa frase, o campo em que você vai até o fundo durante este ciclo, e embaixo dela o porquê. Ao contrário dos outros treze, ele não tem microação nem ocasião que volte todos os dias: é feito uma vez, na manhã do dia zero, logo depois das oito perguntas da escavação, e é feito de novo no começo de cada ciclo.",
  "Domínio, neste livro, quer dizer o campo de trabalho ou de estudo a que você vai dar as melhores horas: um ofício, uma arte, uma ciência, uma parte da sua profissão. Para uma enfermeira pode ser o cuidado de doentes graves; para um marceneiro, os móveis de encaixe sem pregos; para quem estuda direito, uma só área dele; para quem passou anos criando os filhos e agora tem as tardes livres, a pintura abandonada aos vinte anos. Pode ser a profissão, ou o que se cultiva nas margens dela.",
  "Se, no meio da lista do dia zero, surgiu a pergunta <i>para que serve isto?</i> e um item ficou sem ser escrito, escreva-o agora: a utilidade fica fora deste exercício. Se a frase do domínio não saiu limpa, ficou a melhor que você tinha, e é com ela que você trabalha até a próxima passagem.",
  "Por isso este exercício não tem marca, nem <i>chegou</i>, nem passagem: é uma decisão escrita uma vez por ciclo, e não há noite em que se pergunte se ela foi cumprida. O que faz as vezes de marca é o teste que a síntese já aplica a ela: explicar o domínio em trinta segundos sem hesitar. Se, na noite do dia zero, você hesita ao dizê-lo, a frase ainda não está pronta e deve ser reescrita nessa mesma noite, antes de você fechar o caderno. Depois dessa noite, o domínio só é revisto numa passagem, por escrito e com base nas marcas, ou no dia zero do ciclo seguinte.",
 ], sai="o domínio numa frase no terceiro ponto da folha do dia zero, com o porquê com rosto embaixo, e a lista do que você amou com o que se repete sublinhado.",
 porque=[
  "<b>A ideia.</b> Nietzsche, em <i>Schopenhauer como educador</i>, de 1874, oferece um caminho indireto a quem quer saber quem é. Ele pede que você olhe para trás e pergunte o que amou verdadeiramente até agora, o que elevou sua alma, o que a dominou e ao mesmo tempo a fez feliz, e que ponha em fila esses objetos venerados. Talvez a fila lhe mostre a lei fundamental do seu verdadeiro ser, que, segundo ele, está imensamente acima de você. Nietzsche chama esses objetos de seus educadores, e o dele foi Schopenhauer: a pergunta procura quem eleva você acima do que você é. Aqui o uso é outro. Na fila entram coisas feitas, com os momentos em que, fazendo-as, você esqueceu o tempo, e dela se tira um domínio, o campo a que você vai dar as melhores horas do ciclo. Para Nietzsche, esse ser de cima é seu, e o educador só liberta você para alcançá-lo; o domínio diz em que campo você vai procurá-lo.",
  "<b>O mecanismo.</b> Primeiro, a pergunta direta, o que devo fazer da vida?, é respondida com o que soa bem dito em voz alta; a pergunta pelos momentos em que você esqueceu o tempo é respondida com lembranças de coisas feitas, que o prestígio distorce menos. Isso é raciocínio, e não estudo. Segundo, os treze exercícios seguintes são planos do tipo quando acontecer isto, faço aquilo, e a meta-análise de 94 testes que Gollwitzer e Sheeran publicaram em 2006 encontra efeitos maiores quando a pessoa de fato quer o objetivo; sem esse querer, o efeito diminui. Sem um domínio, os outros exercícios treinam gestos que não servem a obra nenhuma.",
  "<b>Por isso.</b> Faço esta lista porque o que amei aparece nos momentos em que esqueci o tempo, e porque os gestos dos outros exercícios só pegam se servirem a uma coisa que eu queira."])
add("Quem já tem a vida presa a um ofício que não escolheu faz o exercício sem demolir nada. O domínio não precisa ser a profissão: pode ser o campo que se cultiva nas margens dela, ou a parte da profissão que a pessoa faria de graça. Quem chega a este livro com muitos anos de vida procura também nos anos de trabalho, e não só na infância, porque há amores que só apareceram tarde. Quem cuida de outros, dos filhos, de um pai doente, não escreve o domínio contra esse cuidado; o escreve ao lado dele, com a pequena hora que sobra. Em todos os casos o exercício é o mesmo: no dia zero, uma vez por ciclo, a lista, o sublinhado, a frase, o porquê.", PI)
add("Quando o exercício falha, falha de poucos modos. Se a lista fica curta, com cinco itens respeitáveis, você filtrou pela utilidade ou pelo prestígio sem perceber; recomece pelo inútil, pelos jogos da infância, pelo que você lia escondido, pelo que fazia quando ninguém pedia. Se a lista é longa e nada se repete, você listou assuntos, e às vezes o que se repete é o verbo: ordenar, consertar, explicar, contar histórias, cuidar. Procure o verbo. Se, ao tentar explicar o domínio em trinta segundos, você hesita, a frase junta três coisas que não se tocam; procure o que as une, ou escolha uma para este ciclo e guarde as outras para o seguinte. E se, semanas depois, o domínio lhe parecer errado, não o corrija no meio do caminho (§9). Escreva a dúvida na folha de captura e leve-a à próxima passagem, onde ela será examinada com a cabeça fria, diante das marcas.", PI)

estacao("Primeira estação", "Do aprendizado, segundo Robert Greene.")
st.extend(PEND); PEND.clear()
add("A primeira estação começa na manhã do dia um. Do domínio escrito passa-se ao chão em que ele vai ser servido: o lugar onde se trabalha, a recusa de abrir o que não se fecha, a atenção que permanece, o corpo que sustenta tudo. Esses quatro gestos quase não aparecem na obra de hoje; servem para que ela se sustente nos meses que vêm. Robert Greene chama de aprendizado esse tempo em que se aceita a disciplina antes de ter alguma coisa para mostrar. No meio deste trecho, numa noite de marca, vai lhe parecer que você avança pouco. Essa impressão engana. O que conta é o que você já faz sem esforço, e é nisso que a estação seguinte se apoia.", PI)
exe("1", "Da ordem", "H", "Algumas coisas dependem de nós, outras não.", "Epicteto",
 "Quando você se sentar à mesa: tudo o que distrai sai dela. Quando você se levantar dela: a mesa volta à ordem.",
 ["Se esta noite você não tem tempo para o que vem a seguir, leia-o em outra das noites antes do dia zero.",
  "Os monges do deserto egípcio, os mesmos de Evágrio e da terceira linha, viviam em celas que quase nada continham: uma esteira, um jarro de água, as folhas de palmeira com que trançavam cestos para vender. Um irmão foi a Scete pedir uma palavra ao abade Moisés, e o velho lhe respondeu: vá, sente-se na sua cela, e a sua cela lhe ensinará tudo. A frase foi guardada nos <i>Ditos dos Padres do Deserto</i> e repetida durante séculos nos mosteiros. Ela fala do lugar, mais do que da pobreza: num espaço onde nada chama, a mente, depois de se agitar, não tem para onde ir senão para aquilo que se veio fazer ali.",
  "Quinze séculos depois, em Londres, o mesmo princípio servia a outro ofício. Auguste Escoffier, que a partir de 1890 dirigiu as cozinhas do Savoy e depois as do Carlton, organizou os cozinheiros em brigadas, cada um com seu posto e sua tarefa. Uma regra dessas cozinhas, que os franceses chamam de <i>mise en place</i>, pôr no lugar, governa a hora antes do serviço. Cada cozinheiro prepara sua bancada, corta, mede e dispõe os recipientes sempre na mesma ordem, para que, quando os pedidos começarem a chegar, a mão encontre tudo sem procurar. E a limpeza se faz durante o trabalho, e não só no fim, porque a bancada suja de uma hora é a confusão da hora seguinte. No meio do serviço, nenhum cozinheiro tem tempo para decidir onde está o sal. Ele decidiu isso antes.",
  "A sua mesa é as duas coisas. É cela, porque nela a distração não deve ter onde morar; é bancada, porque nela a obra deve estar pronta para a mão. O estado neutro que você vai escrever no dia um é a sua <i>mise en place</i>: o mínimo de que você precisa, sempre no mesmo lugar. Os dois minutos ao se levantar são o que o cozinheiro faz ao fechar o serviço, e por isso a manhã seguinte começa sem nada a decidir.",
  "Há quem trabalhe bem no meio do caos; as mesas de alguns grandes espíritos ficaram famosas pela desordem. Mas a desordem deles se acumulava em volta de uma só obra. O exercício deixa na mesa o papel acumulado do seu trabalho, e tira dela o que chama você para fora dele."],
 ["No primeiro dia, arrume tudo: o quarto e a mesa, por completo, num único esforço.",
  "Defina o estado neutro da mesa, o que fica nela quando você não está trabalhando, e escreva-o no caderno. O mínimo.",
  "Ao se sentar, antes de abrir a obra, tire da mesa e do alcance tudo o que distrai.",
  "Ao se levantar, dois minutos: devolva a mesa ao estado neutro, para que amanhã ela comece limpa."],
 "O primeiro erro tem ar de zelo. Numa manhã de obra difícil, a arrumação se alonga: você tira o pó, alinha as canetas, reorganiza uma gaveta, e meia hora depois a obra continua fechada. A ordem tem um limite de cinco minutos, e depois começa a obra. O segundo erro é buscar a ordem perfeita, a mesa que nunca mais vai precisar ser pensada, e corrigir o estado neutro todas as tardes. Basta a ordem suficiente, a da lista que você escreveu no caderno.",
 "ao se sentar, só tirar a distração.", "a mesa está neutra e a distração ausente sem que você tenha precisado se lembrar.",
 comeco=[
  "Você lê isto numa das noites antes do dia zero, e o que vem a seguir conta o dia um. O exercício da ordem treina um gesto de dois tempos. Ao se sentar para trabalhar, você tira da mesa e do alcance da mão o que o distrai; ao se levantar, devolve a mesa a um estado combinado de antemão, que o modo chama de estado neutro. Esse gesto, em negrito acima, é a microação deste exercício, a primeira do livro. É o mesmo gesto que você já marca em <i>Antes do dia zero</i>, e a partir do dia um ele é a da vez. Leia o que vem a seguir também como verificação do que você tem feito nestas noites.",
  "A ocasião é o momento de se sentar no lugar onde você trabalha ou estuda, e o momento de se levantar dele. Mesa, aqui, é qualquer lugar onde você se sente para trabalhar ou estudar, incluindo o do emprego: a escrivaninha de um escritório, a mesa da cozinha onde um estudante abre os livros depois do jantar, a bancada de um carpinteiro, a estante e a cadeira de quem estuda um instrumento, o balcão onde um comerciante faz as contas no fim do dia. Num dia comum a ocasião vem várias vezes: ao começar, depois de cada pausa, ao sair. Quem trabalha de pé ou em movimento a tem ao chegar ao posto e ao deixá-lo.",
  "Na manhã do dia um, nos minutos do caderno, você vai ler no breviário a linha deste exercício e se perguntar onde e a que horas vai se sentar nesse dia. Depois vai se perguntar qual dessas vezes vai pesar mais, e anotá-la numa linha. Quase sempre é a sessão da obra do dia, a que você escreveu na linha da manhã, com o sentar que a abre e o levantar que a fecha. Se você se sentar seis vezes, é essa sessão que decide a noite, como você vai ver com a mulher de <i>Do primeiro dia</i>.",
  "No dia um, antes da primeira vez que você se sentar para a obra, ou, se o trabalho o chamar cedo, na primeira hora livre, faça a arrumação grande: o quarto e a mesa, tudo, de uma vez. Ela leva o tempo que levar, e não se repete. Termine-a escrevendo no caderno o estado neutro, a lista curta do que fica na mesa quando você não está trabalhando. Cada mesa da sua vida tem sua lista. A de uma mesa fora de casa, como a do escritório, você escreve lá, num papel, na primeira vez que se sentar, e passa para o caderno à noite.",
  "Depois vem a primeira ocasião verdadeira. Você chega à mesa para a obra do dia e, antes de abri-la, olha o que está em volta. Vem uma frase pequena e razoável: <i>isto pode ficar, não incomoda</i>, ou <i>tiro depois, se me distrair</i>. Não lhe obedeça. É a segunda frase interior de que fala a segunda lei, e o gesto existe para que você não precise discuti-la: a distração sai antes de a obra abrir. A primeira linha, que você lê numa destas noites, começa pelo mesmo movimento, <i>afaste de você o que o distrai</i>. Ao se levantar, talvez venha outra frase, mais cansada: <i>arrumo amanhã de manhã</i>. São dois minutos, e a mesa volta ao que a lista diz antes de você sair.",
  "Na noite do dia um, nos minutos do caderno, você vai fazer a primeira marca da folha de marcas. Nessa noite, aconteça o que acontecer, não se escreve <i>chegou</i>: no dia em que uma microação entra, nunca se escreve.",
 ],
 marca="Você reconstrói a sessão da obra, só essa. Se a distração saiu quando você se sentou e a mesa ficou neutra quando se levantou, é traço, ainda que você tenha falhado na volta do almoço. Se você falhou nessa sessão, ainda que tenha cumprido todas as outras vezes do dia, é cruz. Cumprir o sentar e falhar o levantar, ou o contrário, é ceder em metade da sessão, e a metade basta para a cruz. É ponto quando a ocasião não veio naquele dia, como num dia em que você não se sentou a mesa nenhuma, por viagem ou doença de cama; sentar só para pagar contas ou escrever uma carta já é ocasião, e nesse dia é essa a que mais pesa. Numa noite que você ainda não sabe qual será, ao reconstruir a sessão, você vai encontrar a mesa limpa e não vai encontrar a decisão de limpá-la. As mãos tiraram a distração, ou arrumaram ao levantar, sem que você se lembrasse do caderno, porque foi a mesa, ao ser vista, que o lembrou. Nessa noite você escreve <i>chegou</i> ao lado do traço.", sai="o estado neutro de cada mesa escrito no caderno, o quarto e a mesa arrumados de uma vez, e a primeira linha da folha de marcas com o número um. No <i>Manual operacional</i>, as ações do grupo <i>Ordem</i>.",
 porque=[
  "<b>A ideia.</b> Epicteto abre o <i>Manual</i> com a frase do alto, a distinção entre o que depende de nós e o que não depende, que <i>Da forma</i> lhe contou. A mesa, a rigor, está no segundo grupo. O seu ato de arrumá-la, e a escolha de não deixar o espírito ir atrás do que está à vista, estão no primeiro, e é nesse ato que o exercício põe a força. O que está à vista pesa na decisão antes que você a tome. Cada objeto sobre a mesa é um convite, e quem trabalha cercado de convites passa a sessão recusando-os, com a força que devia ir para a obra.",
  "<b>O mecanismo.</b> Primeiro, muito do que fazemos é disparado pelo ambiente, quase sem intenção. David Neal, Wendy Wood e colegas mostraram em 2011 que um hábito continua funcionando contra a própria preferência enquanto a pista está presente: no cinema, quem costumava comer pipoca comia a pipoca velha quase tanto quanto a fresca. Tirar a distração da mesa tira a pista, e com ela a escolha. Segundo, como mostra o estudo de Phillippa Lally, que você lerá em Da medida, um gesto repetido num momento fixo do dia vai saindo cada vez mais sem pensar. Por isso o gesto se prende ao sentar e ao levantar, que voltam todos os dias, e é a mesa neutra, vista ao chegar, que um dia vai lembrar você sem o caderno.",
  "<b>Por isso.</b> Tiro a distração ao me sentar porque o que está à vista me chama antes de eu decidir, e arrumo ao me levantar porque a mesa neutra é o que amanhã vai me lembrar."],
 saber="Os estudos sustentam duas coisas: que uma pista à vista dispara o hábito mesmo contra a preferência, como nas pipocas de Neal e Wood, e que um gesto repetido num momento fixo vai ficando automático, como no estudo de Lally. Nenhum deles testou a mesa neutra nem os dois minutos ao se levantar; a passagem dos estudos para este gesto é inferência. A força é moderada para o princípio e pequena para os números, pelas ressalvas ao estudo de Lally que <i>Da medida</i> registra.")
add("O gesto é o mesmo para quem não tem mesa. O carpinteiro tem a bancada, o músico tem a estante e a cadeira; o estudante que trabalha na mesa da cozinha tem uma caixa onde a obra mora, de onde ela sai inteira quando ele se senta e para onde volta quando ele se levanta. Quem trabalha em lugar alheio, numa sala compartilhada, numa biblioteca, leva sua <i>mise en place</i> consigo: o que tira da bolsa ao chegar e o que guarda nela antes de sair. Quem trabalha com o corpo, na oficina ou no campo, aplica o gesto às ferramentas, e o estado neutro é a parede onde cada uma tem seu prego. A ocasião continua sendo o sentar e o levantar, ou o chegar ao posto e o deixá-lo; o resto se adapta ao chão.", PI)
add("Se, no fim da primeira semana, a mesa está neutra de manhã e cheia no fim da tarde, a causa mais comum é que as coisas não têm lugar fora da mesa, e por isso voltam a ela. Dê a cada uma um lugar fixo, fora do alcance do braço, e o gesto ao se levantar fica mais curto. Se a arrumação passa dos cinco minutos e começa a ser o melhor momento do dia, é adiamento, e o ajuste é contar: cinco minutos, e começa-se com a mesa imperfeita. Se aquilo que mais distrai você volta à mesa sem que você perceba como, é a mão que o traz por hábito, e o remédio é a distância: outro cômodo, uma gaveta que se fecha, um lugar que obrigue você a se levantar para ir buscá-lo. E se, depois de ter chegado, a ordem só se mantém nos dias em que você se lembra dela, e começa a aparecer na coluna das que ficaram, o estado neutro é grande demais; tire dele mais uma coisa.", PI)
exe("2", "Do terminar", "H", "Até quando você vai adiar exigir de si o melhor?", "Epicteto",
 "Quando vier o desejo de abrir algo novo: volte ao que está aberto e dê o próximo passo.",
 ["O desejo de abrir algo novo chega quase sempre no ponto difícil do que já está aberto, e é uma maneira de fugir dele com aparência de interesse. Epicteto faz a pergunta do alto no fim do <i>Manual</i>, a um discípulo que já recebeu os princípios e continua esperando um dia melhor para pô-los em prática. Você já não é um rapaz, ele lembra, e não há outro mestre por quem esperar. Ou seja: o adiamento se apresenta como preparação, e a hora de exigir de si o melhor é a presente. A forma mais comum de adiar é começar outra coisa.",
  "Em Berlim, nos anos vinte, contava-se no círculo do psicólogo Kurt Lewin uma observação feita num café. O garçom lembrava, sem anotar, tudo o que cada mesa tinha pedido enquanto a conta estava por pagar, e esquecia tudo assim que a mesa pagava. Uma aluna de Lewin, Bluma Zeigarnik, levou a observação para o laboratório. Deu a várias pessoas uma série de pequenas tarefas, montar, contar, modelar, e interrompeu algumas antes do fim. Quando depois lhes pediu que recordassem o que tinham feito, as tarefas interrompidas voltavam à memória muito mais vezes do que as terminadas. O trabalho saiu em 1927, e o efeito ficou com o nome dela: o que fica aberto continua ocupando a mente.",
  "A lista que você vai fazer amanhã mostra, então, o que pesa. Cada coisa nela é uma conta por pagar, como as das mesas daquele café, e o exercício aceita duas maneiras de fechá-la: terminá-la, ou encerrá-la por escrito, com a razão.",
  "Edward Gibbon conta em suas memórias o começo e o fim de uma obra. O começo foi em Roma, em 15 de outubro de 1764. Sentado entre as ruínas do Capitólio, ao entardecer, enquanto os frades descalços cantavam as vésperas no lugar do antigo templo de Júpiter, ele teve a ideia de escrever a decadência e a queda da cidade. O primeiro volume só saiu doze anos depois. O fim foi em Lausanne, na noite de 27 de junho de 1787, entre as onze e a meia-noite, num pequeno pavilhão do jardim. Ele escreveu as últimas linhas da última página, pousou a pena e deu algumas voltas por uma alameda coberta de acácias, de onde se viam o lago e as montanhas sob a lua. Confessa a alegria de ter recuperado a liberdade, e confessa também que ela durou pouco: veio uma melancolia sóbria ao pensar que se despedira para sempre de um velho e agradável companheiro.",
  "Foram vinte e três anos entre a ideia e a última linha, e nesse tempo coube uma vida inteira: o parlamento, as finanças apertadas, a mudança para a Suíça. Gibbon terminou porque, ao longo desses anos, sempre voltou ao que estava aberto. A melancolia daquela noite mostra que terminar custa também por dentro, além do trabalho: quem fecha uma obra perde a companhia dela. Talvez parte do desejo do novo, no ponto difícil, venha da vontade de evitar essa perda.",
  "Algumas coisas abertas não merecem ser terminadas, é verdade. O exercício o dispensa de levar até o fim o livro ruim que você começou por engano, e em troca lhe pede uma decisão. O livro ruim se encerra numa linha: <i>paro aqui, porque não me ensina o que procuro</i>. O que não se permite é o estado intermediário, a coisa nem viva nem morta, que continua cobrando atenção como a conta da mesa por pagar."],
 ["No primeiro dia, liste à mão tudo o que está aberto: livros, projetos, tarefas, promessas.",
  "Quando vier o desejo do novo, escreva-o na folha de captura. Ele não se perde; espera.",
  "Volte ao que está aberto e dê o próximo passo dele, por menor que seja.",
  "À noite, se uma coisa da lista já não pede nada de você, encerre-a por escrito, com a razão."],
 "Dois erros aparecem cedo. Numa noite, no fim de um dia longo, você olha para uma coisa quase pronta e a dá por terminada, porque o que falta é pouco e chato; para essa noite, a quinta linha pergunta se está feito ou se está quase. O outro erro é confundir encerrar com abandonar. Encerrar é uma decisão escrita, com a razão, que fecha a conta; abandonar é deixar a coisa apodrecer em silêncio, ainda na lista.",
 "um passo de uma coisa aberta.", "a lista de coisas abertas encolhe, e o novo já não puxa você como antes.",
 comeco=[
  "Você está na noite da primeira passagem. (Daqui em diante, o número de uma passagem conta só as que trazem um exercício novo. As noites em que uma das que ficaram, depois de ter voltado, chega de novo também são passagens, com a sua Lição, mas não mudam esse número.) Você escreveu há pouco, ao lado do traço da ordem, a palavra <i>chegou</i>. Se não a escreveu, esta página ainda não é sua: a ordem continua sendo a da vez, e você volta aqui na noite em que ela chegar. Nesta noite você fez, ou vai fazer, o que só nas passagens se faz: a primeira Lição, a folha do dia zero relida, a página do Homem copiada à mão, as correções que as marcas pedirem. Esta página é a última coisa da noite. Amanhã de manhã a ordem passa a ficar, e entra a segunda microação.",
  "O exercício do terminar treina a resposta a um desejo preciso: o de começar uma coisa nova quando outras estão por acabar. Quando esse desejo vier, você não abre a coisa nova. Escreve o desejo numa linha da folha de captura e dá o próximo passo numa das coisas que estão abertas. Com esse exercício chegam a segunda, a quinta e a sétima linhas do Livro I; releia-as antes de dormir.",
  "A ocasião é esse desejo, e ele tem muitas caras. A estudante, no meio de um capítulo árduo, sente vontade de começar o livro mais leve que lhe recomendaram. O homem que pinta a casa nos fins de semana quer começar a cozinha antes de terminar a sala. A dona de uma pequena loja, no meio de uma encomenda difícil, tem uma ideia para um produto novo e quer cuidar dele imediatamente. O desejo se reconhece pela hora em que chega, quase sempre no ponto difícil do que está aberto, e pelo ar de boa ideia que traz.",
  "Amanhã, depois dos minutos do caderno, você faz à mão a lista do que está aberto: livros começados, projetos, tarefas pendentes, promessas feitas a alguém. Ela não precisa ser bonita; precisa estar completa. Guarde-a na página que <i>Do caderno, página a página</i> reserva para ela.",
  "Em algum momento do dia, provavelmente no trecho mais difícil da obra, vem uma ideia com ar de boa: <i>e se eu começasse aquilo agora?</i> Ela vem acompanhada de um pequeno alívio, como se a dificuldade de agora se resolvesse em outro lugar. Não lhe obedeça. No trecho difícil não se abre a coisa nova, e a resposta são três movimentos: a linha na folha de captura, a lista à sua frente, o próximo passo de uma das coisas dela, por menor que seja. Se você não souber qual, a sétima linha pergunta qual delas você evitaria, se pudesse.",
  "À noite, ao rever a folha de captura, as coisas novas que estão ali esperam: nada se abre antes que o anterior se feche (§6). E você olha a lista. Se alguma coisa dela já não pede nada de você, encerre-a ali mesmo, por escrito, com a razão. Isso pode acontecer numa noite qualquer, e não acontece em todas.",
  "Há dias em que o desejo vem dez vezes, e dias em que não vem. Quando vem muitas vezes, a ocasião que mais pesa é a que chega durante a obra do dia, no trecho difícil, porque é ali que ele lhe tira mais.",
 ],
 marca="Você pensa na vez que mais pesou, quase sempre a do trecho difícil da obra. Se você escreveu o desejo e voltou ao que estava aberto, com um passo dado, é traço. Se, nessa vez, você abriu a coisa nova, é cruz. Se o desejo não veio o dia inteiro, é ponto. O encerramento da noite não tem marca própria: é feito quando a lista o pede, e uma noite sem nada a encerrar não é falha. Escreve-se <i>chegou</i> na noite em que você percebe que o desejo do novo veio no trecho difícil e que, antes de você se lembrar do caderno, a mão já o tinha posto na folha de captura e voltado ao que estava aberto. Muitas vezes você só percebe isso à noite, ao encontrar a linha escrita sem lembrar de ter decidido escrevê-la. Depois do <i>chegou</i> fica: o desejo na folha de captura e o passo numa coisa aberta, e o encerramento da noite, sempre que a lista o pedir.", sai="a lista à mão de tudo o que está aberto, guardada na página que <i>Do caderno, página a página</i> reserva para ela; cada desejo do novo numa linha da folha de captura; e o que você encerrou, por escrito, com a razão. No <i>Manual operacional</i>, as ações do grupo <i>Ordem</i>.",
 porque=[
  "<b>A ideia.</b> Kurt Lewin, psicólogo em Berlim nos anos vinte, explicava que cada intenção deixa na mente uma tensão, uma espécie de pequena necessidade, que só se desfaz quando a coisa acaba. Enquanto a tarefa fica aberta, a tensão continua e puxa a atenção para ela. A experiência de Bluma Zeigarnik, que você vai ler em Do sentido, foi feita no círculo dele para pôr essa ideia à prova.",
  "<b>O mecanismo.</b> Primeiro, cada coisa aberta continua pedindo atenção enquanto você faz outra, assim como as tarefas interrompidas de Zeigarnik voltavam à memória mais vezes do que as terminadas; abrir uma nova soma mais uma tensão às que você já tinha, por mais alívio que dê no momento. Segundo, em 2011, E. J. Masicampo e Roy Baumeister verificaram que os pensamentos intrusivos sobre uma tarefa pendente diminuem quando se faz para ela um plano concreto, mesmo antes de cumpri-la. Por isso o desejo novo vai para a folha de captura, e cada encerramento leva a razão escrita: a decisão posta no papel tira da mente parte do que a coisa aberta lhe pedia.",
  "<b>Por isso.</b> Escrevo o desejo e volto ao que está aberto porque cada coisa aberta continua puxando minha atenção, e porque o que fica decidido por escrito deixa de me interromper."],
 saber="O estudo de Masicampo e Baumeister sustenta que um plano concreto para a tarefa pendente reduz os pensamentos intrusivos sobre ela; é um artigo só, com poucos experimentos pequenos. O efeito de memória de Zeigarnik se replicou de modo irregular desde 1927, e aqui serve mais de imagem do que de prova. Nenhum estudo mede se voltar ao que está aberto, em vez de abrir o novo, faz a obra andar mais depressa. A força é fraca: o gesto se apoia em razão, com um apoio experimental estreito.")
add("Quem tem uma única obra enorme, uma tese, uma casa por construir, um ofício de anos, tem uma lista curta, e o gesto se aplica dentro dela: o capítulo aberto, a parede começada, a peça na bancada. Quem vive de muitas tarefas pequenas, num ofício de atendimento ou no governo de uma casa, tem uma lista de pendências, e o próximo passo é o menor pedaço da mais antiga. Nos estudos, cada livro conta como uma coisa aberta (§6). E as promessas feitas a outros, que também estão na lista, se fecham quando são cumpridas ou quando se diz com franqueza que não vão ser cumpridas; nesse caso, o encerramento escrito é entregue também a quem esperava.", PI)
add("Se a lista cresce em vez de encolher, o desejo do novo está passando da folha de captura para a mão: você abriu o que só devia ter anotado. Deixe a captura dormir alguns dias antes de qualquer decisão sobre ela, e lembre-se de que nada se abre antes que o anterior se feche. Se a lista encolhe só por encerramentos, nunca por coisas terminadas, o encerramento virou a nova fuga; antes de cada um, pergunte-se se a razão escrita convenceria um amigo exigente. Se o próximo passo é sempre o mesmo e nunca acaba, ele é grande demais; corte-o até caber numa sessão, como a quarta linha faz com o impasse. E se o desejo do novo continua tão forte depois de semanas quanto no primeiro dia, observe a hora em que ele chega. Quase sempre é a mesma, e é a hora do trecho difícil.", PI)
exe("3", "Da absorção", "H", "Quem está em toda parte não está em lugar nenhum.", "Sêneca",
 "Quando você perceber que se dispersou: a terceira linha. E a primeira hora do dia longe das distrações do seu tempo.",
 ["Em Down, no condado de Kent, o mesmo Darwin das cracas, que você leu na sétima linha, mandou abrir, nos anos quarenta do século XIX, um caminho de areia em volta de um pequeno bosque nos fundos da casa. Ele o chamava de Sandwalk. Percorria-o todos os dias, às vezes mais de uma vez, sozinho ou com o cachorro. O filho Francis lembra que ele deixava um monte de pedras de sílex na entrada e derrubava uma a cada volta, para saber quantas tinha dado sem precisar contá-las. A rotina da casa tinha o mesmo desenho: as melhores horas da manhã para o trabalho, a correspondência depois, o caminho, o descanso, e de novo um pouco de trabalho. Doente durante boa parte da vida, Darwin trabalhava poucas horas por dia, mas horas inteiras.",
  "Repare nas pedras. Darwin não queria pensar no número de voltas, e por isso deu ao corpo a tarefa de contar. O bloco com começo e fim marcados faz o mesmo: tira de você a pergunta <i>quanto falta?</i>, que está entre as que mais vezes interrompem o trabalho. E o caminho era sempre o mesmo, sem nada de novo para ver, para que a atenção não tivesse onde se prender senão no problema. A primeira hora do dia longe das distrações do seu tempo faz por você o que o Sandwalk fazia por Darwin: é uma hora sem nada que puxe a atenção para fora do trabalho.",
  "A tradição dominicana guardou o caso de um homem que estava num lugar só. Guilherme de Tocco, que conheceu Tomás de Aquino em Nápoles e escreveu a vida dele para o processo de canonização, conta que, em Paris, Tomás foi convidado à mesa do rei Luís IX. Ele trabalhava então contra os maniqueus, e, no meio da refeição, entre os convidados e as conversas da corte, ficou calado, preso ao problema. De repente bateu na mesa com a mão e disse que estava concluído contra os maniqueus. O prior que o acompanhava o tocou e lembrou que ele estava à mesa do rei da França. Tomás pediu desculpas; o rei, em vez de se ofender, mandou chamar um secretário para que o argumento fosse escrito antes que se perdesse. O exercício não lhe pede que esqueça onde está, e quem tem um filho pequeno ou um cliente à frente não pode esquecer. Mas o caso mostra até onde vai a atenção que fica: diante da distração mais nobre que havia em Paris, a mesa de um rei, ela continuou no problema.",
  "Os estoicos tinham um nome para a atenção que permanece: <i>prosoché</i>, o estar voltado para. Epicteto dedica a ela um dos últimos discursos, e o que ele diz é menos consolador do que se espera. Não pense, ele avisa, que, afrouxando um pouco a atenção, você a recuperará quando quiser: o descuido de hoje torna mais fácil o de amanhã, e de adiamento em adiamento se forma o hábito de não prestar atenção. E pergunta: é possível nunca errar? Não; mas é possível estar sempre voltado para não errar, e é preciso se contentar se assim se escapa ao menos de alguns erros. Lida ao lado da terceira linha, a frase dá a medida exata do exercício. O exercício pede que se volte sempre, porque uma dispersão ou outra é inevitável; e o que se forma, se você não vigiar, é o hábito de não voltar logo.",
  "Talvez a sua vida não lhe permita uma hora assim, logo ao acordar: há quem dependa de você, há trabalho que chama. O exercício pede que você tire, nessa hora, o que o distrai, e deixa com você o que o obriga. Quem tem um filho pequeno continua cuidando dele na hora da absorção; o que essa pessoa põe de lado é tudo o que ocupava os intervalos entre os cuidados."],
 ["Trabalhe em blocos com começo e fim marcados. Comece com blocos de vinte e cinco a quarenta e cinco minutos; alongue-os quando ficarem fáceis.",
  "Antes de cada bloco, escreva a única coisa em que você vai estar nele.",
  "Quando se dispersar, a terceira linha: <i>saí; onde eu estava?</i> Releia a última linha e continue. O pensamento que puxou você vai para a folha de captura.",
  "A primeira hora do dia, do acordar em diante, longe das distrações do seu tempo."],
 "No fim de um bloco em que você saiu vinte vezes, é provável que você faça a conta e a leia como uma sentença. Contar as voltas como fracassos é o primeiro erro: cada volta é uma repetição do exercício. O segundo é começar com blocos longos demais, uma hora e meia logo na primeira manhã, e desanimar no primeiro dia.",
 "um bloco de vinte e cinco minutos.", "você volta mais depressa e os blocos se alongam sem esforço.",
 comeco=[
  "Você está na noite da segunda passagem. O terminar chegou há pouco, e amanhã passa a ficar, ao lado da ordem. Amanhã entra a terceira microação, e com ela a terceira linha do Livro I, a da dispersão; releia-a esta noite.",
  "O exercício da absorção treina a volta. Você trabalha em blocos com começo e fim marcados e, quando percebe que saiu do que estava fazendo, diz por dentro a terceira linha, <i>saí; onde eu estava?</i>, relê a última linha do trabalho e continua. E a primeira hora de cada dia é passada longe das distrações do seu tempo. A terceira linha diz para onde você volta; <i>Isto, até acabar</i>, a frase de <i>Da assentada</i>, diz até quando você fica. Os dois fins não se contradizem. O fim marcado do bloco é a medida mínima, o tempo que você dá à coisa antes de se levantar; o fim de <i>isto</i> continua pertencendo à coisa. Se o bloco acaba e <i>isto</i> não, você termina o passo em que está, e o bloco seguinte começa com a mesma coisa escrita antes dele.",
  "A ocasião é o instante em que você percebe que saiu. Raramente é o instante em que você sai, que quase nunca se nota; é aquele, segundos ou minutos depois, em que você se dá conta de que estava em outra coisa. O estudante descobre que leu a mesma página três vezes sem saber o que ela dizia. A costureira percebe que o pensamento foi parar numa conversa da véspera e que a mão parou na bainha. O contador tem uma coluna de números à frente e percebe que há um bom tempo está pensando no fim de semana. Ou se percebe, simplesmente, que a mão foi buscar o que distrai sem que você tivesse dado a ordem.",
  "Antes de fechar o caderno, ao escrever a primeira tarefa de amanhã, escreva também o que você vai fazer na primeira hora, para que ela não seja um vazio. A primeira hora começa com o caderno, que já é aberto antes de qualquer distração, e continua depois dele. Amanhã de manhã, decida quantos blocos você vai fazer, a que horas e de que tamanho: vinte e cinco minutos é um bom começo. A primeira hora não muda a primeira tarefa, que <i>Do dia</i>, no Livro II, define; ela é o tempo, longe das distrações, em que você começa essa tarefa.",
  "Lá pelo décimo minuto do primeiro bloco, você se dá conta de que está em outro lugar, numa conversa, numa conta por pagar, ou com a mão já a caminho do que distrai. Logo atrás vem uma segunda frase, mais pesada: <i>de novo, não aguento nem dez minutos</i>. Essa frase é outra dispersão, agora contra você mesmo, e a linha a corta: <i>saí; onde eu estava?</i> Você relê a última linha do trabalho, o pensamento que o puxou vai para a folha de captura numa linha, e você continua. Nos primeiros dias as saídas vêm às dezenas.",
  "A ocasião que mais pesa é, quase sempre, a que acontece no bloco da obra do dia. É nela que a dispersão custa mais, e é ela que decide a noite.",
 ],
 marca="Marca-se só a volta no bloco da obra do dia; a primeira hora longe das distrações e a única coisa escrita antes de cada bloco servem a essa volta e não entram na marca. A marca olha para o que você fez depois de perceber que tinha saído; quantas vezes você saiu fica fora dela. Se, no bloco da obra do dia, você voltou com a terceira linha em vez de seguir para onde a dispersão o levava, é traço. Se, nesse bloco, você ficou fora, é cruz. Ponto, só num dia sem nenhum trabalho que peça atenção, como um dia de cama; pular os blocos marcados para não ter de voltar não dá ponto. Escreve-se <i>chegou</i> na noite em que você percebe que, no bloco da obra, a pergunta <i>onde eu estava?</i> veio sozinha no instante em que você percebeu que tinha saído, e que você voltou antes de se lembrar de que havia um exercício para isso. Se você precisou se lembrar da linha para voltar, ainda não chegou. A linha da primeira hora, escrita à noite, acompanha o exercício enquanto ele é a da vez, e acaba quando ele chega; daí em diante basta a primeira tarefa de amanhã. Depois do <i>chegou</i> fica: a volta com a terceira linha no bloco da obra.", sai="a primeira hora do dia longe das distrações, escrita na véspera; blocos com começo e fim marcados, cada um com sua única coisa escrita antes; e a volta com a terceira linha quando você percebe que saiu. No <i>Manual operacional</i>, as ações do grupo <i>Atenção e obra</i>.",
 porque=[
  "<b>A ideia.</b> Sêneca escreve a Lucílio que quem está em toda parte não está em lugar nenhum, e que o espírito que pula de coisa em coisa não cria raízes. Quase tudo o que este livro treina depende de atenção prolongada. Nunca se dispersar é impossível; o que se treina é a volta, cada vez mais rápida, e uma hora por dia em que nada puxe você para fora.",
  "<b>O mecanismo.</b> Primeiro, cada mudança de tarefa custa tempo e erros, mesmo quando é prevista e preparada, como mostram os estudos de laboratório revisados pelo psicólogo Stephen Monsell em 2003. Quem fica fora mais tempo, ou pula para outra coisa, paga esse custo mais vezes; o bloco com uma só coisa escrita antes e a volta rápida o reduzem. Segundo, a terceira linha é um plano decidido de antemão, do tipo quando eu perceber que saí, digo isto e releio a última linha. Planos assim, postos à prova nos 94 testes que Peter Gollwitzer e Paschal Sheeran reuniram em 2006, aumentam de forma consistente a probabilidade de a ação acontecer, porque, no instante em que a situação chega, já não há nada para decidir.",
  "<b>Por isso.</b> Digo <i>saí; onde eu estava?</i> e releio a última linha porque cada minuto em outra coisa me custa a volta, e porque a frase decidida antes me poupa de decidir no instante em que percebo que saí."],
 saber="O custo da troca de tarefa está entre os resultados mais repetidos da psicologia experimental, mas foi medido em frações de segundo, em tarefas de laboratório, e o salto para uma manhã de trabalho é inferência. Os planos <i>se... então</i> têm apoio largo, de centenas de testes, com efeito de tamanho médio na revisão de 2006 e grande variação de um comportamento para outro. Nenhum estudo testou a terceira linha nem a primeira hora longe das distrações. A força é boa para os dois princípios e nula para a forma exata do gesto.")
add("Quem trabalha com pessoas, no balcão, na sala de aula, junto de um doente, não tem blocos solitários; tem conversas, aulas, plantões. O gesto se aplica a eles do mesmo modo: antes de cada um, a única coisa que deve acontecer nele; durante, a terceira linha sempre que o espírito se afastar da pessoa que está à sua frente. Quem faz trabalho manual mede os blocos pelo próprio trabalho, uma peça, uma parede, um canteiro, com o começo e o fim marcados antes de pegar a ferramenta. Quem estuda faz blocos com o livro, a caneta e a folha de captura, e mais nada.", PI)
add("Se a dispersão chega sempre perto do mesmo minuto do bloco, o bloco é longo demais para agora; encurte-o em cinco minutos e só o alongue quando três blocos seguidos passarem sem esforço. Se você volta mas não sabe para onde, pulou a frase escrita antes do bloco, e sem ela <i>onde eu estava?</i> não tem resposta. Se as voltas não ficam mais curtas ao longo das semanas, olhe para as noites: o cansaço é a causa mais comum da dispersão, e nenhum treino de atenção compensa o sono que falta (§8). Se o que puxa você vem sempre de fora, do ambiente ou dos objetos, a falha está no primeiro exercício, e a coluna das que ficaram deve dizer se a ordem anda caindo. E se a primeira hora se desfaz depois de dez minutos, dê forma a ela: uma tarefa escolhida na véspera, com começo e fim. Uma hora sem tarefa definida quase sempre acaba nas distrações.", PI)
exe("4", "Do corpo", "H", "É vergonha envelhecer sem conhecer a força do próprio corpo.", "Sócrates",
 "Quando você chegar ao treino: nada que distraia vai com você, a ficha de papel vai na mão, e a ficha é cumprida inteira.",
 ["Para os gregos, a ginástica fazia parte da formação da alma.",
  "O ginásio grego era mais do que um lugar de exercício. A palavra vem de <i>gymnós</i>, nu, porque se treinava nu; mas no mesmo recinto, à sombra dos pórticos, havia quem conversasse, ensinasse e ouvisse. Foi num ginásio dos arredores de Atenas, junto ao bosque de Academo, que Platão abriu sua escola, e Aristóteles ensinou em outro, o Liceu. Ninguém achava estranho que a filosofia e a luta dividissem o mesmo chão. Na <i>República</i>, Platão vai mais longe: a ginástica e a música, que para os gregos incluía a poesia, foram dadas ao homem, as duas, por causa da alma. Quem só faz ginástica fica áspero e bruto; quem só faz música fica mole; a educação acerta quando afina uma contra a outra, como as cordas de um instrumento. Para Platão, o corpo também é treinado por causa da alma, e um sem o outro deforma quem o pratica. É por isso que um exercício do corpo entra num livro sobre a obra.",
  "De Crotona, no sul da Itália, a tradição guardou a história do lutador Mílon, muitas vezes vencedor em Olímpia. Conta-se que, quando rapaz, ele começou a carregar um bezerro nos ombros todos os dias, e continuou carregando o bezerro à medida que o animal crescia, até levar nas costas um touro. É lenda, e as lendas não se verificam. Ela foi guardada porque diz em imagem a regra de progressão que este exercício segue: a carga sobe tão devagar que o corpo não percebe o aumento, e a cada dia se carrega um pouco mais do que no anterior. O terceiro passo do modo, o pouco a mais quando as repetições são cumpridas duas vezes, é o bezerro de Mílon posto em números.",
  "E há o próprio Sócrates. No <i>Banquete</i>, Alcibíades conta o que viu na campanha de Potideia, onde os dois serviram juntos. Quando os mantimentos faltavam, Sócrates aguentava a fome melhor do que todos. No inverno, que naquela região é terrível, ele saía com a capa de sempre e andava descalço sobre o gelo com mais facilidade do que os outros, calçados. Num dia de verão ficou de pé, da madrugada até a madrugada seguinte, pensando num problema, sem se mover. Na batalha, salvou Alcibíades ferido, e insistiu com os generais para que o prêmio de bravura fosse para o outro.",
  "Você vai dizer que não quer ser atleta nem soldado, e que a sua obra é de cabeça. A de Sócrates também era. O que o corpo treinado lhe dava era disponibilidade: o frio, a fome e a vigília não decidiam por ele, nem no dia em que um só problema o prendeu de pé de uma madrugada à outra. Na mesma passagem de Xenofonte de onde vem a frase deste exercício, Sócrates lembra ao jovem Epígenes, que cuidava mal do corpo, que muitos falham no próprio pensamento por causa da saúde ruim, com o esquecimento, o desânimo e o mau humor que ela traz. A ficha cumprida inteira é o mesmo treino que os exercícios anteriores pediram à mesa e à atenção, aplicado a um lugar onde é difícil você se enganar: a ficha anotada diz o que você levantou. E há mais uma razão para o corpo estar aqui. O corpo é o lugar onde o hábito fica, e é nele que mora cada gesto que chegou. Por isso o que você copia do homem de X inclui o corpo dele: a postura com que ele se senta para a obra, o passo com que chega ao treino, a respiração com que espera a série seguinte. Você os copia como copia os outros meios, porque fazem parte do que ele faz, e o livro não lhe promete que eles mudem o que você sente."],
 ["Escreva a ficha antes de sair: exercícios, séries, repetições, carga.",
  "No treino, anote cada série feita, com a carga real.",
  "Progressão simples: quando você cumprir todas as repetições de um exercício em duas sessões seguidas, aumente um pouco a carga ou as repetições.",
  "No fim de cada treino, compare com a ficha anterior e mude no máximo uma coisa."],
 "Há três erros. Treinar sem plano, decidindo na hora o que dá vontade, faz de cada sessão uma negociação nova. Mudar a ficha inteira de uma vez, numa noite de entusiasmo, apaga a comparação com a sessão anterior. E buscar a exaustão em vez da progressão: sair destruído não é sinal de bom treino.",
 "dez minutos de movimento, ou uma caminhada.", "a ficha é cumprida sem negociação e os números sobem devagar.",
 comeco=[
  "Você está na noite da terceira passagem. A absorção chegou, e amanhã serão três as que ficaram. Amanhã entra o último exercício da primeira estação, e é o único que se faz longe da mesa.",
  "O exercício do corpo treina a maneira de treinar: chegar ao lugar onde você se exercita com a ficha escrita na mão, sem nada que o distraia, e cumprir a ficha inteira, anotando cada série com a carga real.",
  "A ocasião é a chegada ao treino, nos dias e na hora que a ficha marca. Pode ser a chegada à sala de musculação, à pista, à piscina, ao parque onde um homem aposentado caminha todas as manhãs, ou ao canto da sala onde uma mãe estende um tapete depois de pôr os filhos para dormir. Ela se reconhece pelo que costuma vir junto: a vontade de levar consigo a distração, de improvisar em vez de seguir a ficha, de cortar as duas últimas séries.",
  "Amanhã de manhã você escreve a ficha, se ainda não a tem: em que dias da semana você treina e a que hora e, para cada sessão, os exercícios, as séries, as repetições e a carga. Se você não sabe por onde começar, comece com pouco; se você tem lesão, doença ou muitos anos, escreva-a com quem entende do seu caso. Se a ficha não marca treino para amanhã, a ocasião não vem, e a noite leva ponto; a primeira ocasião verdadeira é o primeiro treino que a ficha marcar. Num dia de treino, de manhã, você prevê a hora da chegada.",
  "A hora chega. É aqui que as frases vêm: <i>levo isto comigo, só para o intervalo</i>; <i>hoje faço outra coisa, mais leve</i>; e, perto do fim, <i>as duas últimas séries não fazem diferença</i>. É a voz antiga pechinchando o preço, e o preço do atleta de Epicteto, a hora marcada, o calor e o frio, não se pechincha. As frases ficam sem resposta. Todas fazem parte da mesma ocasião, e a ficha é cumprida inteira. A distração fica onde você não a alcança, a ficha vai na mão, cada série é anotada com a carga real, e no fim você compara com a sessão anterior e muda no máximo uma coisa.",
  "A ocasião vem uma vez em cada dia de treino, e por isso ela mesma é a que mais pesa. Cada série que você pensa em pular faz parte dela.",
 ],
 marca="Marca-se só a chegada ao treino sem o que distrai, com a ficha, e a ficha cumprida inteira; a anotação das séries, a progressão e a comparação com a sessão anterior servem ao gesto e não entram na marca. Num dia de treino, se você chegou sem o que distrai, com a ficha, e a cumpriu inteira, é traço. Se você cortou a ficha, se levou a distração consigo, ou se não foi no dia e na hora que a ficha marcava, é cruz: a ocasião chegou na hora marcada, ainda que você não tenha chegado. Nos dias em que a ficha não marca treino, é ponto. Neste exercício os pontos são muitos, e, como não separam as cruzes, o treino seguinte a uma cruz é sagrado. Escreve-se <i>chegou</i> na noite em que você percebe que saiu para o treino com a ficha na mão e a distração deixada para trás sem ter pensado nisso, como quem pega as chaves ao sair de casa: foi a hora do treino que o lembrou, e não o breviário. Depois do <i>chegou</i> fica: chegar ao treino sem o que distrai, com a ficha, e cumpri-la inteira.", sai="a ficha escrita, com dias, hora, exercícios, séries, repetições e carga; cada sessão anotada com a carga real; e uma só mudança de cada vez, decidida no fim do treino. No <i>Manual operacional</i>, as ações do grupo <i>Corpo</i>, e antes delas <i>Dos cuidados</i>.",
 porque=[
  "<b>A ideia.</b> Sócrates, nas <i>Memoráveis</i> de Xenofonte, diz a um jovem que descuidava do corpo que é vergonha envelhecer sem ver a força e a beleza de que o corpo é capaz. Para ele o corpo fazia parte da formação de quem pensa, e era treinado como o resto. O exercício toma essa ideia pelo lado da maneira: treinar com um plano escrito antes, sem distração, cumprido inteiro e anotado.",
  "<b>O mecanismo.</b> Primeiro, o exercício físico faz bem ao humor e melhora um pouco o desempenho mental logo depois; Yu-Kai Chang e colegas reuniram em 2012 setenta e nove estudos de sessões únicas e encontraram um efeito real e pequeno, menor do que muitos livros anunciam. O ganho mais certo está no corpo e no humor. Segundo, registrar o progresso por escrito aumenta a probabilidade de alcançar o objetivo: Benjamin Harkin e colegas reuniram em 2016 cento e trinta e oito estudos, e o efeito foi maior quando o registro era físico. A ficha anotada é esse registro; ela lhe diz, sem margem para interpretação, se você cumpriu, e mostra se a carga sobe.",
  "<b>Por isso.</b> Levo a ficha e anoto cada série porque o corpo que treino sustenta o humor e a cabeça de que a obra precisa, e porque o que fica escrito me mostra se cumpri e se avanço."],
 saber="A meta-análise de Chang sustenta um ganho pequeno e real no desempenho mental logo depois de uma sessão de exercício, e a de Harkin, um efeito moderado do registro do progresso sobre o alcance do objetivo, maior quando o registro é físico. O efeito do exercício sobre o humor tem apoio mais largo do que o efeito sobre a cabeça. Nenhum estudo testou a ficha cumprida inteira nem a regra de não levar distração ao treino. A força é moderada para o registro e para o humor, e pequena para a ideia de que o treino melhora a obra do dia.")
add("O gesto se adapta a qualquer corpo, porque a ficha é sua e não de um modelo. Quem tem uma lesão, uma doença crônica ou muitos anos escreve a ficha com quem entende do seu caso, e progride no que pode progredir: amplitude, equilíbrio, distância, tempo. Quem não pode sair de casa treina em casa, e a ocasião continua sendo a chegada ao treino, ainda que seja a um canto da sala. Quem trabalha com o corpo o dia inteiro, na obra ou no campo, não precisa de mais do mesmo cansaço; a ficha dessa pessoa trabalha o que o ofício deixa parado. E quem prefere correr, nadar ou lutar escreve as séries em distâncias, tempos ou assaltos.", PI)
add("Se os números param durante três ou quatro semanas, a causa raramente está no treino: está no sono e na comida, que são metade da progressão. Se, com o sono e a comida em ordem, eles ainda param, o aumento era grande demais, e o corpo não sobe de touro em touro; faça um aumento menor. Se aparece uma dor que não é o cansaço normal do músculo, você buscou a exaustão; volte à carga anterior e, se a dor continuar, procure quem saiba avaliá-la antes de voltar à ficha. Se você cumpre a ficha mas se esquece de anotar, algo que o distrai foi junto, e a ocasião está sendo cumprida pela metade. E se você falta ao treino sempre nos mesmos dias da semana, a ficha está posta na hora errada da sua vida: mude a hora antes de pôr em dúvida a vontade.", PI)
estacao("Segunda estação", "Da ação criativa.")
st.extend(PEND); PEND.clear()
add("Você está na noite da quarta passagem. Há pouco você escreveu <i>chegou</i> ao lado do traço do corpo, leu a Lição seguinte, releu a folha do dia zero e a página do Homem, e fez as correções que as marcas pediam, se pediam alguma. Você olha a folha de marcas e vê a coluna do número subir quatro vezes desde o dia um, e cada subida foi uma noite como esta. O caminho já leva meses. Se os quatro gestos chegaram de verdade, a mesa se arruma quase sozinha, as coisas abertas foram diminuindo, os blocos se alongaram e a ficha do corpo é cumprida sem negociação. Tudo isso foi preparação e, ainda que pareça pouco, é sobre esse chão que <i>Isto, até acabar</i> se sustenta por uma tarde inteira.", PI)
add("O chão plano da primeira estação acaba aqui, e o caminho começa a subir. A segunda estação entra na obra propriamente dita: a hora passada no domínio, o que dela fica na memória, a crítica de quem sabe mais, as pessoas com quem se trabalha. Os gestos da primeira estação continuam entre as que ficaram, e são eles que tornam possível o que vem agora: ninguém treina no limite da habilidade numa mesa cheia, com seis coisas abertas e a atenção fugindo. Antes de fechar o caderno, leia o exercício que entra amanhã.", PI)
exe("5", "Da prática deliberada", "H", "Sem pressa, mas sem pausa.", "Goethe",
 "Quando você começar o trabalho no seu domínio: pela parte mais difícil, sem preâmbulo. À noite, anote as horas reais.",
 ["Robert Greene, de quem esta parte do livro tira os nomes das estações, mostra que a maestria nasce de anos de prática intensa e focada. Goethe resume o ritmo: sem pressa, mas sem pausa.",
  "Benjamin Franklin conta na <i>Autobiografia</i> como aprendeu a escrever, ainda rapaz, quando era aprendiz de tipógrafo em Boston. Ele encontrou um volume avulso do <i>Spectator</i>, o jornal de Addison e Steele, e achou a escrita excelente. Pegava um ensaio, anotava em poucas palavras o sentido de cada frase, deixava as notas de lado por alguns dias e depois, sem olhar o original, tentava reescrever o ensaio inteiro com suas próprias palavras. Então comparava a sua versão com a do jornal, descobria as falhas e as corrigia. Quando percebeu que lhe faltavam palavras, passou a converter os ensaios em verso e, mais tarde, de volta em prosa. Para aprender a ordenar as ideias, embaralhava as notas e tentava pô-las de novo na melhor ordem. Fazia isso à noite, depois do trabalho, de manhã cedo, antes dele, e aos domingos.",
  "Franklin não se limitava a escrever muito. Ele arranjou um modelo melhor do que ele mesmo, um modo de se medir contra o modelo e uma dificuldade precisa em cada fase: primeiro o sentido da frase, depois o vocabulário, depois a ordem. É a máscara feita na página, com um modelo real e copiando os meios dele. Franklin não esperou escrever como o <i>Spectator</i> para escrever como ele; escreveu como ele, mediu a distância, e a distância foi encurtando. É o que o segundo passo do modo lhe pede quando você define o que é melhor hoje. Sem esse alvo, a hora passada na parte difícil é só sofrimento; com ele, cada sessão termina com uma resposta a <i>consegui ou não consegui</i>. Um alvo claro, um modo de saber se você vai bem e uma dificuldade um pouco acima do que você tem são também as condições em que, segundo Csikszentmihalyi, como você leu em <i>Da atenção</i>, costuma aparecer o estado de foco que dá nome a este livro.",
  "Em 1993, Anders Ericsson, Ralf Krampe e Clemens Tesch-Römer publicaram um estudo feito numa escola superior de música de Berlim. Pediram aos professores que separassem os estudantes de violino em grupos: os que prometiam ser solistas de primeira linha, os bons, e os que se preparavam para ser professores de música. Depois pediram a todos que reconstituíssem as horas de prática solitária desde a infância e que registrassem uma semana inteira num diário. Por volta dos dezoito anos, os melhores tinham acumulado em média milhares de horas a mais do que os do último grupo. E não era qualquer hora: era a prática solitária dirigida a uma dificuldade, que os próprios violinistas apontavam como a atividade que mais os fazia melhorar e, ao mesmo tempo, como pouco agradável. Havia ainda um detalhe que poucos citam: os melhores dormiam mais, cochilo incluído, e quase ninguém, em grupo nenhum, sustentava mais de umas quatro horas por dia daquela prática. Vinte e um anos depois, Brooke Macnamara, David Hambrick e Frederick Oswald reuniram 88 estudos e mediram quanto das diferenças de desempenho a prática deliberada explica: cerca de um quarto nos jogos, como o xadrez, um quinto na música, um pouco menos nos esportes, quatro por cento na educação e menos de um por cento nas profissões. O resto vem de outros fatores, que a prática não substitui. O exercício continua de pé com essa medida: a hora no ponto de falha é a parte do caminho que depende de você, e pesa menos do que o estudo de Berlim fazia parecer.",
  "Quem quer fazer oito horas por dia de prática no limite acaba fazendo oito horas de ocupação. O número que você soma nas noites de passagem só serve se for verdadeiro, ainda que pequeno.",
  "A comparação que o exercício permite fazer é com você mesmo: entre o que você faria com esta prática e o que faria sem ela."],
 ["Antes do bloco, escolha a parte mais difícil da obra, a que você evitaria se pudesse.",
  "Defina o que é melhor hoje: o que você conseguiria fazer no fim da sessão e que não consegue agora.",
  "Comece por ela, no início do bloco, quando a energia é maior. Nada de preparação nem de tarefas menores primeiro.",
  "À noite, anote as horas reais, sem contar as pausas. Nas noites de passagem, some as do caminho."],
 "Há dois modos de falhar que se parecem com trabalho. No primeiro, você passa a tarde no domínio, sempre fazendo alguma coisa, e à noite as horas são muitas e nada ficou mais difícil. Você confundiu horas com prática: a tarde passou no que você já sabia fazer. No segundo, você faz o fácil primeiro para aquecer, e a sessão acaba antes de você chegar ao difícil.",
 "quinze minutos na parte difícil.", "as horas se mantêm ao longo dos meses e a dificuldade do que você faz aumenta.",
 comeco=[
  "O que entra amanhã é a quinta microação. O exercício da prática deliberada treina o começo do trabalho no seu domínio: começar pela parte mais difícil, sem preparação nem tarefas menores antes, e anotar à noite as horas reais que você passou nela.",
  "A ocasião é o momento em que você começa a trabalhar no domínio que escreveu no dia zero. O livro não sabe qual é; ele está no terceiro ponto da sua folha. Para quem escreve, é abrir o manuscrito; para o violinista, tirar o violino do estojo; para o carpinteiro, pegar a primeira peça do dia; para a médica que estuda uma especialidade, abrir o capítulo que vem adiando. A ocasião se reconhece pela tentação que vem com ela: arrumar antes, rever o que já está feito, despachar primeiro o que é fácil para aquecer.",
  "Amanhã de manhã, logo depois da linha <i>a obra de hoje é</i>, você vai escolher a parte mais difícil da obra, a que evitaria se pudesse, e escrever numa linha o que é melhor hoje: o que você conseguiria fazer no fim da sessão e agora não consegue. Na folha de marcas, a linha de amanhã leva o número cinco. Quando você se sentar para o domínio, a mesa já estará neutra, porque esse gesto ficou, e você vai começar por essa parte, logo, no início do bloco. À noite, antes da marca, você vai escrever as horas reais, sem as pausas. Nas noites de passagem, vai somar as do caminho. A parte difícil não muda a primeira tarefa, que <i>Do dia</i>, no Livro II, define. Se a obra de hoje é no domínio e abre a manhã, a parte difícil é a primeira tarefa; se a obra começa mais tarde, é pela parte difícil que a sessão abre, na hora dela.",
  "No instante em que você se senta, vem uma frase com ar de método: <i>primeiro reviso o que fiz ontem, para entrar no ritmo</i>. Não lhe obedeça. Você conhece a resposta desde as primeiras semanas, na sétima linha: <i>Qual delas eu evitaria, se pudesse? Essa.</i> E a primeira linha manda começar. Se, dez minutos depois, a parte difícil travar e você não souber por quê, é a vez de uma linha que até agora você só leu. A quarta, a do impasse, chega com este exercício: <i>O que exatamente eu não sei? Qual é a menor parte que posso fazer agora?</i> Escreva a pergunta numa linha e faça a menor parte.",
  "Se você trabalha no domínio mais de uma vez por dia, cada começo é ocasião, e a que mais pesa é a do bloco principal, o primeiro do dia ou o mais longo, quando a energia é maior.",
 ],
 marca="Marca-se só o começo da sessão principal pela parte difícil; o melhor de hoje, escrito de manhã, e as horas reais, anotadas à noite, servem ao gesto e não entram na marca. À noite, a marca olha para a sessão principal no domínio. Se você começou pela parte difícil sem preâmbulo, é traço. Se a sessão começou pelo fácil, é cruz. Se você começou pela parte difícil só depois de rever um pouco, e hesita, é cruz. Ponto, só num dia em que a circunstância o impediu de trabalhar no domínio; um dia sem domínio por adiamento não é ponto, porque a ocasião estava marcada nas suas alavancas e foi você que não chegou a ela. <i>Chegou</i> é escrito na noite em que você percebe que, ao se sentar para o domínio, a mão foi direto à parte que você evitaria, sem preparação, antes de você se lembrar de que era isso que o exercício pedia. A anotação das horas reais é uma das escritas da noite que ficam depois do <i>chegou</i>: ela continua todas as noites, sem arredondamento, porque a soma das noites de passagem e o sinal dependem dela. Depois do <i>chegou</i> fica: começar a sessão principal pela parte difícil, e as horas reais anotadas todas as noites.", sai="a parte mais difícil escolhida de manhã, com o melhor de hoje escrito numa linha; a sessão principal começada por ela; e as horas reais anotadas a cada noite e somadas nas noites de passagem. No <i>Manual operacional</i>, as ações do grupo <i>Atenção e obra</i>.",
 porque=[
  "<b>A ideia.</b> A epígrafe é de Goethe, o poeta alemão, que em uns versos curtos escritos já velho pede que cada um gire em volta do próprio fardo como um astro, sem pressa, mas sem pausa. O trabalho de uma vida, para Goethe, se faz num passo que se aguenta todos os dias: a pressa gasta em semanas a força que os anos pedem, e a pausa deixa perder o que se ganhou. A frase abre este exercício porque esse é o passo das horas reais, poucas e verdadeiras, somadas noite após noite. Prática deliberada é o nome que o psicólogo Anders Ericsson deu, em 1993, a um tipo preciso de trabalho: a sós, no ponto exato em que você ainda falha, com um alvo de melhoria e um modo de saber se você o atingiu. Ericsson a separava das horas passadas no domínio repetindo o que já se sabe fazer, que enchem o dia e deixam a habilidade onde estava.",
  "<b>O mecanismo.</b> Primeiro, os violinistas de Ericsson apontavam a prática solitária dirigida a uma dificuldade como a que mais os fazia melhorar. Por isso se escolhe a parte que você evitaria e se escreve o melhor de hoje. Segundo, essa prática é pouco agradável e tem limite: quase nenhum deles a sustentava mais de umas quatro horas por dia. Ela gasta a energia que houver, e por isso vem primeiro, sem esperar que dê vontade (§3). Que ela fique no começo do bloco é raciocínio, e não estudo; nenhum ensaio testou a regra de fazer primeiro o mais difícil. As horas reais anotadas mostram quanto dessa prática houve de fato.",
  "<b>Por isso.</b> Começo pela parte que evitaria porque só a hora no ponto onde falho me faz melhorar, e porque essa hora é curta e cansa, e tem de ficar com o começo do bloco."],
 saber="O estudo de 1993 sustenta que os melhores violinistas de uma escola tinham praticado mais a sós. Ele compara grupos e se apoia em horas lembradas pelos próprios músicos, e por isso mostra que as duas coisas andam juntas sem provar que uma produz a outra. A revisão de Macnamara, Hambrick e Oswald, de 2014, dá a essa prática uma parte modesta das diferenças de desempenho, que muda muito de um domínio para outro, e a regra de começar pelo mais difícil não foi testada. A força é moderada para a ideia de que a hora no ponto de falha ajuda, e fraca para a promessa de que ela basta.")
add("No ofício manual, a parte difícil é o corte que ainda sai torto, a junta que ainda abre; o modelo é a peça do mestre, e a comparação se faz pondo as duas lado a lado. Na música e no esporte, é o compasso ou o movimento que se evita, isolado e repetido devagar. Quem trabalha num ofício de pessoas, ensinar, vender, cuidar, encontra a parte difícil na conversa que adia ou na situação em que costuma falhar, e a treina antes, por escrito ou em voz alta, como Franklin treinava o ensaio. E quem tem o domínio num ofício de horas vagas, ao lado de outro trabalho, faz menos horas, mas faz o mesmo gesto: a parte difícil primeiro, e a hora real anotada à noite.", PI)
add("Se as horas sobem e a dificuldade não, você está repetindo o que já sabe, e o sinal disso é que você nunca erra; volte ao segundo passo e escreva um alvo que hoje você não consegue cumprir. Se as horas caem dia após dia, a parte difícil foi escolhida grande demais e cada sessão acaba em derrota; desça um degrau, para algo que você consegue uma vez em cada três tentativas. Se você começa pela parte difícil e depois de dez minutos está em outra coisa, a segunda e a quarta linhas são o seu instrumento, e quase sempre há uma lacuna que ainda não tem nome. E se as horas reais, somadas na noite de passagem, lhe parecerem poucas, escreva-as como são; arredondadas, elas deixam de mostrar se aumentam.", PI)
exe("6", "Do aprender", "H", "Enquanto ensinamos, aprendemos.", "Sêneca",
 "Quando você fechar o livro ou terminar o estudo: um ou dois minutos, e diga ou escreva o essencial, de memória.",
 ["Quem tenta explicar descobre logo o que não entendeu.",
  "Na carta oitenta e quatro, Sêneca escreve a Lucílio que devemos imitar as abelhas, que andam de flor em flor, escolhem o que serve para o mel e depois o dispõem e misturam nos favos até que já não se reconheça de que flor veio. Do mesmo modo, diz ele, o que se juntou da leitura deve primeiro ser separado, porque as coisas se guardam melhor quando distintas, e depois fundido pelo nosso próprio engenho num só sabor. E acrescenta que o alimento que fica inteiro no estômago pesa, e só nutre quando é digerido. Ler, para Sêneca, é só recolher, e o saber se faz depois, quando quem leu trabalha o que leu até lhe dar sua própria forma. A leitura que não passa por essa digestão fica na memória como coisa alheia, e não chega a ser sua. Escrever de memória, ao fechar o livro, é a forma mais curta dessa digestão: o que você escreve sem o texto à frente já passou por você.",
  "Durante séculos, os estudantes da Europa fizeram essa digestão com um caderno. Erasmo de Roterdã, o humanista do século XVI, no <i>De copia</i>, aconselhava quem lia a preparar um livro com títulos, as virtudes, os vícios, os grandes temas, e a copiar embaixo de cada um o que fosse encontrando de melhor. Isso se chamava caderno de lugares-comuns, dos <i>loci</i>, os lugares onde as ideias são guardadas para serem achadas depois. O que dava valor ao caderno era a escolha do título, que obrigava a decidir de que tratava aquilo que se acabara de ler; a cópia, qualquer copista fazia. As três ideias que você escreve ao fechar o livro pedem a mesma decisão.",
  "A psicologia confirmou, muito depois, o que as abelhas de Sêneca sugeriam. Em 2006, Henry Roediger e Jeffrey Karpicke deram a estudantes textos curtos para estudar. Uns liam o texto e voltavam a lê-lo; outros o liam uma vez e depois escreviam, sem tê-lo à frente, tudo o que lembravam. Cinco minutos depois, os que tinham relido se saíam um pouco melhor. Dois dias depois, e sobretudo uma semana depois, a vantagem tinha se invertido com folga: os que tinham tentado recordar lembravam muito mais. E o mais instrutivo: os que só releram estavam mais confiantes de que iam lembrar. Reler torna o texto familiar, e é fácil confundir essa familiaridade com saber.",
  "E há a frase que dá nome ao exercício. Na sétima carta, Sêneca aconselha Lucílio a fugir da multidão e a conviver com quem possa torná-lo melhor e com quem ele mesmo possa tornar melhores, porque o proveito é mútuo: os homens, enquanto ensinam, aprendem. Explicar em voz alta é a recordação mais exigente que existe, porque o ouvinte, mesmo imaginado, não aceita saltos. Onde quem explica hesita, ali estava o que não foi entendido.",
  "Michael Faraday começou assim. Em 1812, aos vinte anos, aprendiz de encadernador em Londres, ganhou de um freguês da oficina entradas para as últimas conferências de Humphry Davy na Royal Institution. Tomou notas enquanto ouvia e, em casa, reescreveu-as por extenso, com o que tinha ouvido e o que tinha entendido, e com desenhos dos aparelhos; encadernou o resultado num volume grosso e o mandou a Davy, pedindo trabalho. Em março de 1813 era assistente de laboratório na mesma casa. Faraday nunca deixou de explicar o que aprendia. Anos depois criou ali as conferências de Natal para os jovens, e deu ele mesmo dezenove séries delas; a mais conhecida, sobre a história química de uma vela, foi feita para um público de crianças e não pulava nenhum passo. Quem reescreve de memória o que ouviu, e depois o explica a outros, faz as duas metades deste exercício.",
  "Parece que isso torna a leitura lenta, quando há tanto para ler. Torna, sim, um pouco mais lenta, dois minutos por sessão. Mas a conta que importa se faz nas páginas que ficaram, e por essa conta quem lê e recorda avança mais depressa do que quem lê e relê."],
 ["Ao fechar o livro, antes de se levantar, escreva de memória as três ideias principais, sem olhar.",
  "Depois abra e confira. Corrija o que você esqueceu ou entendeu mal.",
  "Uma vez por dia, explique em voz alta, durante um minuto, algo que você estudou hoje, como se desse uma aula.",
  "Na margem de cada livro, pelo menos uma discordância sua. <font color='#6b6b6b'>(Lição V)</font>"],
 "O erro mais comum vem com ar de zelo: em vez de recordar, você volta a ler, e a releitura dá a sensação de saber sem que você saiba. O outro é resumir copiando o texto, frase por frase, com o livro aberto ao lado.",
 "uma frase de memória.", "você explica o que estudou nos últimos dias sem consultar nada.",
 comeco=[
  "É a noite da quinta passagem. Você escreveu <i>chegou</i> ao lado do traço da prática deliberada, e são cinco as que ficaram. Se você lê as Lições na ordem e nenhuma das que ficaram voltou, a que você leu esta noite foi a quinta, a da leitura, e o exercício que entra amanhã é parente dela. O exercício do aprender treina um gesto de um ou dois minutos no fim de cada estudo: fechar o livro e dizer ou escrever, de memória, o essencial do que você leu, e só depois abrir e conferir.",
  "A ocasião é o fim de uma sessão de leitura ou de estudo: fechar o livro, terminar a aula, sair de uma lição. O estudante a tem várias vezes por dia. O operário que lê meia hora no caminho para o trabalho a tem quando chega. O aprendiz de um ofício a tem quando o mestre acaba de lhe mostrar um movimento, e quem ouve uma conferência a tem na saída. Ela se reconhece pelo impulso que a acompanha, o de fechar e seguir, ou o de voltar a ler o que acabou de ser lido.",
  "Amanhã de manhã, ao prever a ocasião, você vai ver quando vai ler ou estudar, e vai pôr ao lado do livro uma folha e uma caneta. Vai escolher também a hora do minuto em voz alta, em que vai explicar algo que estudou nesse dia; o fim da última sessão do dia é a mais simples. Quando fechar o livro, antes de se levantar, você vai escrever as três ideias principais sem olhar; depois vai abrir, conferir e corrigir. Enquanto lê, deixe na margem pelo menos uma discordância sua.",
  "No instante de fechar o livro, a mão logo quer outra coisa, ou os olhos voltam à página para uma última leitura, <i>só para fixar</i>. Deixe o livro fechado e escreva as três ideias como vierem. Quase sempre elas vêm piores do que você esperava, e é por virem piores que a conferência tem alguma coisa a lhe ensinar. O minuto em voz alta vai lhe parecer ridículo na primeira vez, numa sala vazia, dando aula para ninguém. Sinta-se um impostor, e diga-o assim mesmo, inteiro.",
  "Se você estuda várias vezes por dia, a sessão que mais pesa é a mais longa, ou a do assunto que mais lhe custa.",
 ],
 marca="Marca-se só a recordação de memória ao fechar o livro, antes de reler; a conferência, o minuto em voz alta e a discordância na margem servem ao gesto e não entram na marca. À noite, olhe para a sessão principal. Se, ao fechar o livro, você recordou de memória antes de reler, é traço. Se você fechou e seguiu, ou releu em vez de recordar, é cruz. Se você não sabe se o que escreveu foi de memória ou com um olho na página, é cruz. Ponto, nos dias em que não houve leitura nem estudo. Escreve-se <i>chegou</i> na noite em que você percebe que, ao fechar o livro, já estava dizendo por dentro as ideias principais antes de se lembrar do caderno, e que a folha as recebeu quase sem ser preciso pedir. Se foi a folha posta ao lado do livro que o lembrou, ainda não chegou. Depois do <i>chegou</i> fica: recordar de memória ao fechar o livro, antes de reler.", sai="as três ideias de cada estudo escritas de memória e corrigidas, um minuto por dia em voz alta sobre o que você estudou, e uma discordância sua na margem de cada livro. No <i>Manual operacional</i>, as ações do grupo <i>Aprender</i>.",
 porque=[
  "<b>A ideia.</b> A epígrafe vem de uma carta de Sêneca a Lucílio, que o <i>Do sentido</i> conta. O sentido é que quem explica algo a outra pessoa tem de pôr em ordem o que sabe, sem saltos, e descobre nesse esforço onde o saber lhe falta. A frase abre este exercício porque escrever de memória, ao fechar o livro, é dar essa aula a você mesmo. Recordar é trazer de volta, sem o texto à frente, o que se leu. O psicólogo Henry Roediger passou anos mostrando que esse esforço já é, ele mesmo, aprendizagem: cada vez que você tira uma ideia da memória, ela fica mais fácil de encontrar na vez seguinte, coisa que reler não faz com a mesma força. Fechar o livro e escrever o essencial é o modo mais simples de fazer isso todos os dias.",
  "<b>O mecanismo.</b> Primeiro, testar-se retém mais do que reler, e isso está entre os resultados mais sólidos da psicologia da aprendizagem: Christopher Rowland reuniu em 2014 sessenta e um estudos e encontrou uma vantagem clara da recordação sobre a releitura, e a revisão de John Dunlosky e colegas, em 2013, pôs a prática de recordar entre as duas únicas técnicas de estudo de alta utilidade. Segundo, recordar custa e é menos agradável do que reler, e esse custo engana. A releitura parece fácil porque o texto ficou familiar, e a familiaridade é confundida com saber; a recordação com os olhos fora da página mostra o que de fato ficou, e a conferência logo depois corrige o resto.",
  "<b>Por isso.</b> Fecho o livro e escrevo de memória porque o que tiro da memória fica, e o que releio só me parece sabido, e porque só ao conferir vejo o que falhou."],
 saber="A vantagem da recordação sobre a releitura é das mais sólidas da psicologia da aprendizagem, repetida em centenas de experimentos e também em salas de aula. Ela foi medida sobretudo com textos, listas e matéria escolar, e vale menos diretamente para habilidades do corpo ou para obras longas. O gesto de um ou dois minutos é uma versão curta do que os estudos testaram, sem ensaio próprio. A força é alta para o princípio e moderada para a forma breve.")
add("Quem aprende um ofício com as mãos aplica o gesto ao fim da lição: repete de memória, sem o mestre olhando, o movimento que acabou de aprender, e só depois confere. Quem aprende ouvindo, numa aula ou numa conversa com alguém que sabe mais, faz a recordação ao sair, a caminho de casa, em três frases ditas por dentro e escritas ao chegar. Quem lê pouco aplica o gesto do mesmo modo, a cada capítulo, e retém mais do que retinha relendo. E o minuto em voz alta pode ter um ouvinte de verdade: um filho, um colega, um amigo paciente.", PI)
add("Se, ao fechar o livro, nada vem, a leitura foi dispersa, e a falha está antes deste exercício: use a terceira linha durante a leitura e recorde com mais frequência, ao fim de cada capítulo em vez de ao fim da sessão. Se vêm só detalhes, uma história, um nome, e não as ideias, pergunte, ao recordar, <i>o que o autor quer que eu pense?</i>, e escreva isso primeiro. Se a conferência mostra sempre os mesmos erros, você entendeu mal desde a primeira leitura, e esse é o trecho a reler, e só esse. Se a aula em voz alta lhe parece ridícula, escreva-a como uma carta a alguém: a carta também não aceita saltos. E se as discordâncias na margem são todas de forma e nunca de fundo, você ainda está lendo para concordar.", PI)
exe("7", "Da crítica", "J", "Viva como se alguém que você respeita o observasse.", "Sêneca",
 "Quando entregar um trabalho a quem sabe mais: peça a crítica, ouça sem se defender, corrija.",
 [
  "Horácio, já poeta celebrado, escreveu aos Pisões, um pai e dois filhos que queriam fazer versos, a longa carta que depois passou a se chamar <i>Arte poética</i>. Perto do fim, ele lembra um amigo morto havia anos, Quintílio. Se você lesse alguma coisa para ele, conta Horácio, Quintílio dizia: <i>corrija isto, e isto</i>. Se você respondesse que não conseguia fazer melhor, que já tinha tentado duas e três vezes em vão, ele mandava riscar e devolver à bigorna os versos mal torneados. E se você preferisse defender o defeito a emendá-lo, ele não gastava com você nem mais uma palavra nem mais um esforço: deixava você amar, sozinho e sem rival, a si mesmo e à sua obra. No mesmo poema, Horácio aconselha guardar o que se escreveu até o nono ano antes de mostrá-lo ao mundo, e dá a razão: o que ficou em casa ainda pode ser riscado, e a palavra publicada não sabe voltar. Nos dois conselhos de Horácio, a emenda tem de vir antes de a obra sair, e Quintílio era quem a fazia vir a tempo. Pela mesma razão, o exercício leva a obra ao crítico ainda inacabada, enquanto ainda se pode riscar.",
  "O castigo de Quintílio é parar de falar. Quem se defende de toda crítica acaba recebendo de todos esse silêncio, e fica sem ninguém que lhe aponte os defeitos da obra.",
  "Plutarco, filósofo e biógrafo grego do primeiro século, que escreveu um tratado inteiro sobre como distinguir o bajulador do amigo, mostra o reverso. O bajulador imita tudo, como o camaleão, que segundo ele toma todas as cores menos o branco: imita seus gostos, seus defeitos, seu riso, e só não imita o que você tem de bom. Ali se lê uma frase que resume o caso: não preciso de um amigo que muda quando eu mudo e acena quando eu aceno; minha sombra faz isso melhor. Quem concorda com tudo devolve a você só o que você já pensava, e por isso não lhe ensina nada. O amigo se reconhece pela franqueza, e a franqueza, diz Plutarco, age como um remédio: dói, pede o momento certo, é dada a sós e nunca para humilhar. A pergunta com que se pede a crítica decide em parte o que se recebe: <i>O que você acha?</i> convida ao elogio; <i>O que está mais fraco aqui?</i> pede franqueza.",
  "Às vezes quem sabe mais está longe, e então é preciso ir até ele. Em outubro de 1705, Johann Sebastian Bach, com vinte anos e organista em Arnstadt, pediu ao consistório quatro semanas de licença e foi a Lübeck, a uns quatrocentos quilômetros dali, ouvir Dietrich Buxtehude, o organista mais admirado do norte da Alemanha. O obituário que o filho Carl Philipp Emanuel escreveu com um antigo aluno conta que ele fez a viagem a pé. Ficou cerca de quatro meses, ouvindo o mestre tocar na Marienkirche e aprendendo com ele o que nenhum organista de Arnstadt sabia lhe mostrar. Na volta, em fevereiro de 1706, o consistório lhe pediu contas da ausência e reclamou das variações estranhas que ele passara a pôr nos corais, que confundiam a congregação. A música dele já não era a mesma.",
  "O crítico também erra, há quem critique por inveja, por pressa ou pelo gosto de ferir, e ouvir sem defesa seria entregar-se a qualquer um. É verdade, e por isso o gesto tem duas metades separadas no tempo. No instante, você ouve inteiro e anota. O juízo sobre a crítica vem à noite, longe do calor, quando a vaidade já não está de guarda: você examina o que foi dito, guarda o que é verdadeiro e descarta o resto por escrito, com a razão. Defender-se no instante não protege você da crítica injusta, e impede você de ouvir até o fim a crítica justa que às vezes vem logo atrás dela."],
 ["Escolha a quem pedir: alguém que saiba mais e que lhe diga a verdade.",
  "Peça uma crítica específica: <i>o que está mais fraco aqui?</i>, e não <i>o que você acha?</i>",
  "Ouça até o fim. Não explique nem justifique. Agradeça.",
  "Anote, corrija e mostre a correção. Mostrar a correção é o que leva quem criticou você a voltar a fazê-lo."],
 "Há três maneiras de errar aqui, e a primeira engana a própria pessoa que a comete: pedir elogio disfarçado de crítica, com uma pergunta ampla, feita a quem gosta de você. A segunda é ficar se explicando enquanto o outro fala. A terceira é aceitar tudo sem examinar: ouvir sem defesa não é obedecer sem juízo, e o exame da noite existe para isso.",
 "releia seu trabalho como o crítico o leria e escreva três fraquezas.", "pedir crítica deixou de custar, e corrigir se tornou o passo seguinte natural.",
 comeco=["Você está na noite da sexta passagem, com a prática deliberada e o aprender já entre as que ficaram. Este é o primeiro exercício com a letra J, a do juízo, ao lado do nome. Agora você tem obra feita no limite, e obra feita no limite tem defeitos que o autor não vê, porque os olhos que a fizeram são os mesmos que a julgam. O exercício anterior ensinou você a descobrir o que não sabe tentando explicá-lo; este leva o trabalho a quem descobre por você o que você não consegue ver.",
  "O exercício da crítica treina o que você faz quando mostra seu trabalho a quem sabe mais: pede uma crítica precisa, ouve até o fim sem se defender, agradece, e depois corrige e mostra a correção.",
  "A ocasião é a entrega de um trabalho a alguém capaz de julgá-lo melhor do que você: o capítulo levado ao orientador, a peça mostrada ao mestre da oficina, o relatório entregue a uma chefe exigente, o prato que o cozinheiro novo põe diante do chefe de cozinha. Também é ocasião a crítica que chega sem ter sido pedida, de um colega ou de quem vive com você. Ao contrário das microações anteriores, esta ocasião pode passar dias sem vir, porque a obra fica guardada à espera de estar pronta, e ela nunca está.",
  "Por isso a manhã de amanhã começará com uma escolha escrita: a quem você vai mostrar o quê, e quando, ainda que esteja inacabado. O livro não sabe quem é essa pessoa. Escolha-a você, entre quem sabe mais do que você e lhe diz a verdade, e escreva o nome no caderno. Prepare a pergunta estreita, <i>o que está mais fraco aqui?</i> Durante o dia, quando a entrega acontecer, você ouvirá até o fim, sem explicar nada, anotará e agradecerá. À noite, longe do calor do momento, examinará o que ouviu, guardará o que é verdadeiro e descartará o resto por escrito, com a razão. Nos dias seguintes, corrigirá e levará a correção a quem criticou você.",
  "Quando o outro começar a apontar o que está fraco, sobe à sua boca uma explicação: <i>isso foi de propósito</i>, <i>essa parte ainda não está acabada</i>. Perceba-a no instante em que se forma. Guarde-a por dentro até o outro acabar; se ainda valer alguma coisa à noite, o exame da noite a recebe.",
  "Se num dia você mostra várias coisas a várias pessoas, a ocasião que mais pesa é a entrega a quem mais sabe, ou a da obra que mais lhe importa."],
 marca="Marca-se só o pedido da crítica precisa, a escuta até o fim sem defesa e, num dia em que você tinha uma correção a mostrar, mostrá-la; a escolha da manhã e o exame da noite servem o gesto e não entram na marca. À noite, olhe para a entrega que mais pesou. Se você pediu a crítica precisa e a ouviu até o fim sem se defender, é traço; num dia em que você tinha uma correção a mostrar, mostrá-la faz parte do gesto. Se você se explicou enquanto o outro falava, se pediu elogio disfarçado de crítica, ou se a correção ficou na gaveta, é cruz. Se você não sabe se aquela sua frase foi pergunta ou defesa, é cruz. Ponto se hoje não houve entrega nem crítica. Mas aqui os pontos pedem vigilância: nenhum é falha, mas nenhum treina nada, e eles podem se suceder noite após noite enquanto você guarda a obra. Se de manhã você escolheu a quem mostrar e não mostrou, a ocasião veio na hora que você marcou, e é cruz. <i>Chegou</i> quer dizer que, numa entrega, a pergunta estreita e o silêncio enquanto o outro falava vieram sem que o breviário lembrasse você; foi a entrega que lembrou você. Depois do <i>chegou</i> fica: pedir a crítica precisa e ouvi-la até o fim, e o exame da noite, nas noites em que houve crítica.", sai="o nome de quem sabe mais e lhe diz a verdade, a pergunta estreita preparada, cada crítica anotada e examinada por escrito à noite, e a correção levada a quem a fez. No <i>Manual operacional</i>, as ações do grupo <i>Pessoas</i>.",
 porque=[
  "<b>A ideia.</b> A epígrafe resume o conselho de Epicuro que Sêneca passa a Lucílio e que <i>Da máscara</i> lhe contou: ter sempre diante dos olhos um homem melhor e viver como se ele nos visse. A epígrafe abre este exercício porque a crítica pedida a quem sabe mais é esse olhar tornado real. Robert Greene, em <i>Maestria</i>, dedica um capítulo inteiro ao mestre, a quem está mais adiante no mesmo ofício. O que o mestre lhe dá é um par de olhos que você não tem. Quem fez a obra a julga com o saber com que a fez, e por isso os defeitos que nasceram do que ainda não sabe ficam invisíveis para ele. Quem sabe mais os vê na primeira leitura e pode apontá-los.",
  "<b>O mecanismo.</b> Primeiro, a crítica só lhe dá o que você não vê se você a ouvir inteira. A defesa vem depressa e sem decisão, e enquanto você prepara a explicação deixa de ouvir o resto, que muitas vezes é a parte justa. Segundo, quem critica só volta a fazê-lo se vir que a crítica serviu; a correção mostrada é essa prova, e cada defesa ensina ao crítico que não vale a pena falar. Nenhum estudo citado neste livro mede isso; são duas razões tiradas do ofício.",
  "<b>Por isso.</b> <i>Faço isto porque não vejo sozinho os defeitos que nascem do que ainda não sei, e porque só continuará me dizendo a verdade quem me vir ouvi-la e corrigir.</i>"],
 saber="Os estudos sobre o retorno de desempenho sustentam um efeito médio favorável, com uma ressalva: na revisão de Avraham Kluger e Angelo DeNisi, de 1996, cerca de um terço dos retornos piorou o desempenho, sobretudo quando desviava a atenção da tarefa para a própria pessoa. Isso apoia ouvir a crítica como notícia sobre a obra, e nada diz sobre a regra de não se defender, que vem do ofício. A força é fraca para o gesto exato.")
add("O gesto admite variações que não mudam sua ocasião. Se ninguém perto de você sabe mais do que você no seu domínio, o mestre pode estar longe: uma carta com a peça e a pergunta específica cumpre o gesto, e a resposta, quando chegar, é lida do mesmo modo, até o fim, antes de qualquer réplica. Se a crítica vem sem ter sido pedida, de um chefe, de um colega, de quem vive com você, ela também é ocasião: ouça, agradeça, anote, e o exame fica para a noite. Se você tem um crítico fiel, cuide para não fazer dele o único; um só par de olhos acaba vendo apenas os defeitos que já conhece. E quando a obra é grande demais para ser mostrada inteira, mostre uma parte, uma página, um movimento, uma série, e peça a crítica dessa parte.", PI)
add("Se a microação não chega, leia as marcas antes de se julgar. Muitos pontos e poucos traços dizem que a ocasião não vem, e ela quase sempre não vem pelo mesmo motivo: você guarda a obra até estar pronta, e ela nunca está; os pontos se sucedem noite após noite sem que você treine nada. O ajuste se faz de manhã: escreva a quem vai mostrar o quê, e mostre a obra inacabada. Traços sem correção mostrada são outro sintoma. Você ouviu bem e nada mudou, e o crítico, na terceira vez, começará a se calar como Quintílio; a causa é tratar o quarto passo como opcional. E se cada crítica pesa sobre você durante dias, a causa provável está na pergunta: você pediu um juízo sobre o todo e ouviu uma sentença sobre si. Peça a crítica de uma parte, com uma pergunta estreita, e leia a resposta como juízo sobre essa parte do trabalho.", PI)
exe("8", "Das pessoas", "J", "Temos duas orelhas e uma só boca.", "Zenão",
 "Quando alguém falar com você: deixe a pessoa terminar. Pergunte antes de opinar.",
 [
  "Plutarco escreveu um pequeno tratado, <i>Sobre como ouvir</i>, para um rapaz chamado Nicandro, no momento em que este vestia a roupa de homem feito e deixava os preceptores. Liberto dos mestres, avisa Plutarco, o jovem se julga livre e cai sob senhores piores, os próprios desejos; e a primeira defesa contra eles é aprender a ouvir. Os conselhos são concretos: não interromper, não saltar sobre a primeira frase com uma objeção, esperar que o outro termine, e só então perguntar, sobre o que ele disse e não sobre o que interessa a você. O ouvinte, compara Plutarco, é como o jogador que recebe a bola: precisa se mover no ritmo de quem a lança, ou a jogada morre. E é dele a imagem que ficou, a do espírito comparado à lenha, que precisa de uma faísca para arder, e não a um vaso que se enche. Ouvir bem, para Plutarco, é deixar que o que o outro diz acenda seu próprio pensamento; a pergunta que nasce das últimas palavras dele é o sinal de que a faísca pegou.",
  "Quase mil e quinhentos anos depois, Montaigne, já com mais de cinquenta anos, escreveu no terceiro livro dos <i>Ensaios</i> um capítulo sobre a arte de conversar. A conversa lhe parecia o exercício mais fecundo e mais natural do espírito, mais do que os livros. E ele conta como a praticava: quando o contradizem, desperta nele a atenção, e não a cólera; ele avança na direção de quem o contradiz, porque essa pessoa o instrui. Ele se interessava menos por saber quem vencia do que pela ordem com que se discutia. A regra dele é a mesma do seu gesto: no momento em que o outro fala, o que ele diz importa mais do que aquilo que você ia dizer.",
  "Um médico aprendeu essa regra com uma paciente. Na primavera de 1889, em Viena, Sigmund Freud tratava uma senhora que nos <i>Estudos sobre a histeria</i> ele chamou de Emmy von N. Ele a interrogava muito, querendo saber de onde vinha cada sintoma. Numa das notas daquelas semanas, conta que ela lhe disse, num tom claramente aborrecido, que parasse de lhe perguntar de onde vinha isto ou aquilo e a deixasse contar o que tinha a dizer. Freud concordou, e a deixou falar até o fim. Dessa conversa e de outras parecidas saiu, nos anos seguintes, um modo de tratar em que o médico se cala e deixa o doente ir aonde a fala o leva. Pense o que quiser da teoria que ele construiu depois; a correção da paciente vale para qualquer conversa. Quem pergunta cedo demais leva o outro para onde ele não ia, e só ouve o que já esperava ouvir.",
  "Você perguntará se não há algo de calculado em anotar à noite o que alguém disse para usar isso na conversa seguinte, como faz quem quer agradar ou vender. A técnica é a mesma; a diferença está no que se guarda. O bajulador de Plutarco também lembra tudo, mas só o que lhe serve para agradar. Quem escuta lembra o que importa ao outro: o nome do filho doente, a prova que ele ia fazer, o projeto de que falou de passagem. Se, ao reler as notas, você descobre que só guardou o que lhe convinha, o exercício lhe mostrou o que sua escuta seleciona."],
 ["Deixe o outro terminar a frase e conte um instante antes de falar.",
  "Faça uma pergunta antes de dar sua opinião.",
  "À noite, anote um detalhe que alguém lhe disse hoje.",
  "Na próxima conversa com essa pessoa, use esse detalhe."],
 "O erro mais sutil é a escuta fingida: você se cala, conta o instante e, enquanto isso, prepara a resposta. O mais visível são as perguntas de interrogatório, feitas em fila, que servem para ganhar e não para entender.",
 None, "você interrompe menos e lembra mais do que as pessoas lhe dizem.",
 comeco=["Na noite da sétima passagem, com a crítica entre as que ficaram, você lê este. A crítica treinou você a ouvir quando o assunto era você e quando tinha sido você a pedir. Este exercício leva a escuta para onde nada obriga você a se calar: a conversa comum, à mesa, no trabalho, em casa, com quem fala de si mesmo ou de coisa nenhuma. É mais difícil, porque ali ninguém lhe ensina o que você pediu, e a vontade de falar não encontra freio.",
  "O exercício das pessoas treina a escuta na conversa comum: deixar o outro acabar a frase, contar um instante antes de falar e fazer uma pergunta antes de dar sua opinião. À noite, você anota um detalhe que alguém lhe disse e o usa na próxima conversa com essa pessoa.",
  "A ocasião é alguém falando com você, e ela vem o dia inteiro: o colega que conta o que fez na véspera, o filho que explica uma briga na escola, o cliente que descreve o que quer, a vizinha na escada, a mulher ou o marido no jantar. Você a reconhece por dentro, pela resposta que já tem pronta antes de o outro acabar, e pela vontade de entrar na frase dele.",
  "Amanhã de manhã você antecipa as conversas que vai ter e escolhe a que mais lhe custa ouvir; quase sempre é em casa, com alguém próximo, onde a interrupção é costume de anos. Durante o dia, em cada conversa, você deixa o outro acabar, conta um instante e faz sua pergunta nascer das últimas palavras dele. À noite, escreve um detalhe de alguém. Nas manhãs seguintes, ao antecipar a ocasião, você relê esse detalhe, para tê-lo à mão no próximo encontro.",
  "Às vezes, no meio da frase do outro, a sua já está pronta, e a boca se abre um pouco antes do tempo. Repare nesse movimento: é a ocasião chegando. Conte o instante. É comum que venha então uma pergunta que serve só de ponte para o que você ia dizer, <i>mas você não acha que...?</i> Deixe-a passar e procure a que nasce das últimas palavras dele.",
  "São dezenas de ocasiões por dia, e elas não se contam uma a uma. A que mais pesa é a conversa que você escolheu de manhã; se o dia trouxe outra mais pesada, uma notícia difícil, uma discussão, é essa."],
 marca="Marca-se só, na conversa que mais pesou, deixar acabar e perguntar antes de opinar; o detalhe anotado à noite e usado na conversa seguinte serve o gesto e não entra na marca. Se você deixou o outro acabar e perguntou antes de opinar, é traço. Se interrompeu, ou se sua pergunta serviu só de caminho para sua resposta, é cruz. Se você não se lembra do que o outro disse depois da sua pergunta, é provável que não estivesse ouvindo, e é cruz. Ponto num dia sem conversa nenhuma, o que é raro. A linha do detalhe se escreve todas as noites enquanto este exercício é a da vez, e acaba quando ele chega. <i>Chegou</i> é a noite em que, na conversa que mais pesou, o instante de silêncio e a pergunta vieram antes da sua resposta sem que o breviário lembrasse você; foi a voz do outro que lembrou você. Depois do <i>chegou</i> fica: deixar acabar e perguntar antes de opinar.", sai="um detalhe de alguém escrito a cada noite e usado na conversa seguinte com essa pessoa, e a pergunta feita antes da sua opinião. No <i>Manual operacional</i>, as ações do grupo <i>Pessoas</i>.",
 porque=[
  "<b>A ideia.</b> A epígrafe é de Zenão, o da mão aberta e do punho fechado; Diógenes Laércio conta que ele a disse a um rapaz que falava sem parar: temos duas orelhas e uma só boca para ouvirmos mais e falarmos menos. Para Zenão, numa conversa, ouvir é a parte maior do trabalho, e quem só espera a vez de falar deixa esse trabalho por fazer. A epígrafe abre este exercício porque o gesto guarda essa proporção: o outro termina, você pergunta, e só então opina. Robert Greene, em <i>Maestria</i>, chama de inteligência social a capacidade de ver as pessoas como são. Para Greene, autor também de <i>As 48 leis do poder</i>, essa leitura é estratégica e serve para você se mover entre os outros a seu favor. O primeiro passo dela é uma coisa pequena e difícil: saber o que o outro disse, com as palavras dele, antes de saber o que você pensa disso. Na conversa comum, quase todo mundo prepara a resposta enquanto o outro ainda fala, e por isso guarda pouco do que ouviu.",
  "<b>O mecanismo.</b> Primeiro, enquanto você prepara sua frase, não ouve a dele: quem interrompe responde à frase que imaginou, e a que foi dita fica sem resposta. O instante de silêncio e a pergunta feita a partir das últimas palavras do outro só são possíveis se você as ouviu, e por isso obrigam você a ouvi-las. Segundo, o que alguém diz de passagem se perde em poucos dias; o detalhe escrito à noite e usado no encontro seguinte fica, e mostra ao outro que ele foi ouvido. Nenhum estudo citado neste livro mede este gesto; são razões tiradas da própria conversa.",
  "<b>Por isso.</b> <i>Faço isto porque o que me disseram e não escrevi eu já terei perdido no encontro seguinte.</i>"],
 saber="Nenhum estudo citado neste livro mede o gesto de deixar terminar e perguntar antes de opinar. O que se sabe com segurança é geral: a atenção dividida entre ouvir e preparar a resposta perde parte do que foi dito, e o que não se escreve se esquece depressa, como Ebbinghaus mediu com listas de sílabas. A força é a de uma razão bem fundada, sem prova experimental para este gesto.")
add("Na conversa entre várias pessoas, o gesto se aplica a quem está falando: deixe essa pessoa terminar mesmo que outro já a tenha interrompido, e sua pergunta pode devolver a ela a palavra que lhe tiraram. Com quem fala demais, o instante antes de falar continua valendo; o que muda é a pergunta, que pode trazer a conversa de volta ao ponto. Com quem desagrada a você, perguntar antes de opinar é ainda mais necessário, porque é aí que se responde com mais certeza à frase imaginada. E em casa, com os mais próximos, onde a interrupção já é costume de anos e ninguém repara nela, está a ocasião mais difícil. Quase sempre é também a mais importante, e é por ela que se decide a marca da noite.", PI)
add("Se os traços vêm fáceis e o sinal não chega, se noite após noite você marca traço e continua sem lembrar o que as pessoas lhe disseram, a escuta é a fingida de que os erros falam. O ajuste é pequeno e verificável. Sua pergunta tem de nascer das últimas palavras do outro; se você não consegue formulá-la a partir delas, não estava ouvindo. Se anota à noite e nunca usa o detalhe, a nota não volta aos seus olhos antes do encontro: releia-a de manhã, quando antecipar onde a ocasião vai aparecer. E se as conversas começam a parecer interrogatórios, se o outro se fecha, você perguntou demais. Uma pergunta, depois sua opinião. O exercício pede que a opinião venha depois da pergunta, e ela continua sendo dita.", PI)

estacao("Terceira estação", "Da maestria.")
st.extend(PEND); PEND.clear()
add("Na noite da oitava passagem você escreve <i>chegou</i> ao lado do traço das pessoas, e a segunda estação fica para trás, com quatro gestos que chegaram e ficaram: começar pela parte difícil e anotar as horas reais; fechar o livro e dizer de memória o essencial; levar o trabalho a quem sabe mais e ouvir a crítica até o fim; deixar o outro terminar a frase e perguntar antes de opinar. Somados aos da primeira estação, são oito, e você os faz todos os dias sem marca. Os dois primeiros dessa estação trabalharam sobre a obra. Os dois últimos puseram você diante dos outros, e é provável que, diante deles, a obra tenha começado a pesar de outra maneira.", PI)
add("Greene chama de maestria a última das três fases da formação num ofício; neste livro, ela começa pelo que você faz quando a obra, as pessoas e as circunstâncias deixam de obedecer: a irritação que sobe, a opinião contrariada, o conforto que pede, a vontade de contar, a coisa que deu errado. Quatro dos cinco exercícios desta estação têm a letra J. Eles se tornam mais rápidos e mais leves; nenhum se fará sozinho.", PI)
exe("9", "Da serenidade", "J", "Seja como o rochedo contra o qual as ondas quebram.", "Marco Aurélio",
 "Quando vierem a irritação ou a pressão: faça uma pausa; separe o que aconteceu do que você pensa; responda depois do pico.",
 [
  "Sêneca escreveu ao irmão Novato três livros sobre a ira, e começa lembrando que alguns sábios a chamaram de loucura breve: ela tem os mesmos sinais, os olhos acesos, o rosto vermelho, a voz que sobe, e a mesma surdez à razão. O remédio que ele mais repete é simples a ponto de parecer pouco: a demora. O primeiro ímpeto é violento e curto, e quem lhe dá tempo o encontra mais fraco. Entre os exemplos, Sêneca conta o de Platão, que, irritado com um escravo, levantou a mão para bater nele e a deteve no ar, e assim ficou, parado, até um amigo lhe perguntar o que fazia. Estou castigando um homem irado, respondeu. Em outra passagem do mesmo livro, Sêneca conta que Platão, irritado com outro escravo, pediu ao sobrinho, Espeusipo, que o castigasse por ele, porque ele mesmo estava irado. Nas duas histórias Platão faz o mesmo: reconhece que, irado, não está em condições de julgar, e tira a decisão das mãos da ira. <i>O que ele faria agora?</i> faz o mesmo com o eu antigo, com uma diferença: Platão tinha Espeusipo, e você não tem ninguém. Quem decide continua sendo você, com a voz de quem não está no pico, e a decisão é sua. Sêneca conta essas histórias para ensinar que a decisão espera o fim do ímpeto; a mão parada no ar é a pausa do segundo passo.",
  "Plutarco conta algo parecido sobre Augusto. O filósofo Atenodoro, que tinha vivido junto do imperador, pediu licença para voltar à terra natal, por causa da idade, e, ao se despedir, deixou ao imperador um conselho: quando você se irritar, não diga nem faça nada antes de recitar para si mesmo as vinte e quatro letras do alfabeto. Augusto tomou a mão dele, disse que ainda precisava dele e o reteve por mais um ano. O alfabeto vale só pelo tempo que leva para ser recitado: é um modo primitivo de ganhar os segundos em que o pico passa, e as duas respirações do segundo passo fazem o mesmo, com menos letras.",
  "Em julho de 1863, dias depois de Gettysburg, Lincoln soube que o exército de Lee tinha atravessado o Potomac e escapado, quando o general Meade, que acabara de vencê-lo, poderia tê-lo capturado, encurralado contra o rio. Lincoln se sentou e escreveu a Meade uma carta dura: a oportunidade de ouro estava perdida, e ele se sentia aflito além de qualquer medida. Depois guardou a carta. Ela foi encontrada entre os papéis dele, com uma anotação de próprio punho: nunca enviada, nem assinada. Lincoln não engoliu a irritação; pôs no papel cada linha dela. Mas não deixou que o pico decidisse a entrega. É daí que vem o último passo do modo.",
  "Há quem diga que certas coisas exigem resposta imediata, e que a calma, nesses momentos, é covardia com boas maneiras. Há perigos que pedem o corpo antes do juízo, e neles o corpo age, como deve. Mas são raros, e o exercício deixa o corpo agir diante do perigo; o que ele governa é a palavra e a réplica, que quase nunca perdem nada por esperar alguns minutos. O que se perde no pico é outra coisa: a frase que não se desdiz, a carta que já não se recolhe. E a resposta depois do pico pode ser dura, se for justa; muda só o momento em que ela é decidida."],
 ["Aprenda seu sinal no corpo: o calor no rosto, a mandíbula, a pressa na voz.",
  "Quando ele vier, faça uma pausa e respire devagar duas vezes.",
  "Separe por dentro: <i>o que aconteceu</i> e <i>o que eu acho do que aconteceu</i>.",
  "Responda depois do pico, com o que você vai fazer. Se for por escrito, escreva e espere antes de entregar."],
 "O primeiro erro é confundir serenidade com engolir: a irritação pode e às vezes deve ser dita, mas depois do pico e com calma. O segundo se parece com o gesto e fica aquém dele: fingir calma por fora enquanto se ferve por dentro, sem pausa e sem separação.",
 None, "o intervalo entre o golpe e a resposta aumentou, e suas respostas são mais calmas.",
 comeco=["O exercício que entra amanhã começa onde o anterior se rompe. A escuta que você treinou tem um ponto fraco: quando o que o outro diz fere você, já não basta deixá-lo terminar, porque por dentro você já respondeu antes de ele acabar. O exercício da serenidade treina o intervalo entre o golpe e a resposta. Quando a irritação ou a pressão sobem, você para, respira devagar duas vezes, separa por dentro o que aconteceu do que pensa do que aconteceu, e só responde depois que o pico passa. O pico é o ponto mais alto da irritação, os segundos ou minutos em que ela decide por você, se você deixar.",
  "A ocasião é a irritação ou a pressão, e ela se reconhece primeiro no corpo, antes de ter nome: o calor no rosto, a mandíbula apertada, a voz subindo. Ela vem com o colega que corta você numa reunião, com o filho que não se veste quando já é tarde, com o vizinho que faz barulho de madrugada, com o funcionário que lhe pede o mesmo papel pela terceira vez, com a obra que falha e deixa você irritado consigo mesmo. Vem também sem ninguém à frente: o prazo que aperta, a fila que não anda.",
  "Amanhã de manhã você se perguntará onde a irritação costuma chegar e com quem, e ouvirá por dentro a frase que vai doer. Durante o dia, aprenderá seu sinal: na primeira vez que a irritação vier, note em que parte do corpo ela se mostrou. Quando ela vier, as duas respirações, a separação dita em palavras e a resposta depois do pico; se a resposta for por escrito, escreva e espere antes de entregá-la. À noite, se você só percebeu a irritação depois de ter respondido, reconstrua o episódio de trás para a frente até encontrar o primeiro sinal.",
  "Quando a irritação vier, é comum que ela já traga uma frase pronta, dita por dentro com toda a certeza: <i>ela faz isso de propósito</i>. Essa frase pertence à segunda metade da separação, o que você pensa do que aconteceu, e chega vestida de fato. Diga por dentro as duas metades, cada uma no seu lugar: <i>ela me interrompeu</i>; <i>eu acho que ela não me leva a sério</i>. Depois, as duas respirações, e a resposta pode esperar.",
  "Num dia ruim a irritação vem várias vezes; num dia calmo, nenhuma. A ocasião que mais pesa é a de mais consequência: a pessoa de quem você mais depende, a palavra que não se desdiz."],
 marca="Marca-se só a pausa e a resposta depois do pico; a reconstrução do episódio à noite, quando você só percebeu a irritação depois de responder, serve o gesto, não entra na marca e acaba quando ele chega. À noite, olhe para a vez que mais pesou. Se você fez a pausa e respondeu depois do pico, é traço. Se respondeu no pico, é cruz. Calar por fora enquanto se ferve por dentro, sem a pausa e sem a separação, fica aquém do gesto; se você hesita, é cruz. Voltar depois à pessoa e reparar o que a pressa estragou é devido, mas não muda a marca da noite. Ponto se o dia passou sem irritação nem pressão. A separação entre o que aconteceu e o que você pensa disso será sempre um juízo, feito ali, no momento. <i>Chegou</i> quer dizer que, na vez que mais pesou, o corpo deu o sinal e as duas respirações vieram atrás dele sem que o breviário lembrasse você; foi o calor no rosto que lembrou você. Depois do <i>chegou</i> fica: a pausa e a resposta depois do pico.", sai="seu sinal no corpo identificado, as duas respirações quando ele vem, a separação entre o que aconteceu e o que você pensa disso, e a resposta dada depois do pico. No <i>Manual operacional</i>, as ações do grupo <i>Pensamento</i>.",
 porque=[
  "<b>A ideia.</b> A epígrafe vem das <i>Meditações</i> de Marco Aurélio: o rochedo à beira-mar, contra o qual as ondas batem sem parar, fica de pé, e em volta dele a água agitada acaba se aquietando. A imagem diz que a onda vem, e que o que depende de você é não ser levado por ela. A epígrafe abre este exercício porque a irritação é a onda: ela continuará vindo, e o gesto treina o que fica de pé enquanto ela quebra. Epicteto ensina, no <i>Manual</i>, que o que nos perturba é o juízo que fazemos das coisas. Para os estoicos, esse juízo é a única coisa que depende inteiramente de nós, e por isso é nele que se trabalha. Entre o fato e a reação há esse juízo, quase sempre rápido demais para ser notado, e ele chega colado ao fato, com a mesma certeza.",
  "<b>O mecanismo.</b> Primeiro, o pico é curto. O primeiro ímpeto da irritação é violento e breve, e quem lhe dá alguns segundos o encontra mais fraco; as duas respirações servem para comprar esses segundos. Para isso o livro tem a observação de Sêneca, e nenhum estudo. Segundo, dizer em palavras, lado a lado, o que aconteceu e o que você pensa disso tira da segunda metade a aparência de fato. Os psicólogos chamam de desfusão esse modo de olhar um pensamento como pensamento; uma meta-análise de estudos de laboratório (Levin e colegas, 2012) encontrou nela um efeito favorável, com evidência moderada.",
  "<b>Por isso.</b> <i>Faço isto porque o pico passa em segundos e a frase dita nele fica, e porque o que penso do que aconteceu, dito ao lado do fato, deixa de se fazer passar por ele.</i>"],
 saber="A meta-análise de Levin e colegas sustenta um efeito favorável da desfusão, com evidência moderada, em sessões curtas de laboratório, longe das brigas reais. Que o pico da irritação passe em segundos vem de Sêneca, sem medida neste livro. A força é moderada para a separação entre fato e pensamento, e apenas de observação para a pausa.")
add("A irritação com você mesmo, quando a obra falha ou o corpo não obedece, é ocasião do mesmo gesto: o sinal, as duas respirações, a separação entre o que aconteceu e o que você diz de si a respeito disso. A pressão sem ninguém à sua frente, o prazo que aperta, a fila que não anda, também é ocasião; ali não há a quem responder, e a resposta é o próximo ato. Com quem a irritação é antiga, porque a pessoa diz sempre a mesma coisa que fere você, a pausa pode começar antes do encontro: de manhã, ao antecipar a ocasião, você ouve por dentro a frase que vai doer, e o pico, quando vier, já terá sido visto uma vez. E se você só perceber a irritação depois de ter respondido, resta voltar à pessoa, passado o pico, e dizer o que você vai fazer.", PI)
add("Se as cruzes se juntam na mesma hora do dia ou em volta da mesma pessoa, a ocasião é previsível, e o que falha é a antecipação da manhã; muitas vezes também o sono, porque o cansaço corrói primeiro o juízo (§8). Se você faz a pausa e a resposta sai igual, só mais tarde, a causa está no que você faz durante a pausa: ensaia o ataque. A separação do terceiro passo precisa de palavras, ditas por dentro ou escritas, <i>ele chegou atrasado</i> de um lado, <i>ele não me respeita</i> do outro; sem ela, a demora serve só para preparar melhor o ataque. E se você nunca percebe o sinal do corpo a tempo, se só nota a irritação quando a voz já subiu, faça a reconstrução da noite que <i>Do começo</i> pede. Depois de alguns episódios, ele aparece quase sempre no mesmo lugar, e é aí que se aprende a vê-lo. E se, feito tudo isso, a microação não chega e a resistência não cede, o caminho continua pela passagem por decisão, que o Livro V ensina.", PI)
exe("10", "Da mente móvel", "J", "Se me mostrarem que erro, mudarei com alegria.", "Marco Aurélio",
 "Quando alguém contrariar você: <i>talvez você tenha razão</i>. Examine antes de defender; e, se o outro estiver certo, mude e diga isso.",
 [
  "Sócrates fazia de mudar por razão um método. No <i>Górgias</i> de Platão, antes de discutir com o célebre retor diante de uma sala cheia, ele avisa que espécie de homem é: dos que têm gosto em ser refutados quando dizem algo falso, e gosto em refutar quando o outro erra, mas não menos gosto em ser refutados do que em refutar, porque é um bem maior livrar a si mesmo do pior dos males do que livrar dele outra pessoa. O pior dos males, diz ali, é ter uma opinião falsa sobre as coisas que se discutem. Sócrates quer dizer que quem é refutado ganha mais do que quem refuta, porque perde um erro que levaria consigo. Os gregos chamavam de <i>élenchos</i> essa prova: perguntas que levam uma opinião até as consequências dela, para ver se ela aguenta. Sócrates aceitava passar por ela tanto quanto a impunha. Quem contraria você submete sua opinião, sem saber, a essa mesma prova.",
  "John Stuart Mill, filósofo inglês, em 1859, no segundo capítulo de <i>Sobre a liberdade</i>, deu forma moderna ao mesmo princípio: quem conhece apenas o próprio lado da questão conhece pouco dela. Ele lembra que Cícero estudava a causa do adversário com o mesmo empenho que a própria, ou maior, e acrescenta uma exigência que torna o exercício difícil. Não basta ouvir os argumentos contrários da boca de quem os refuta; é preciso ouvi-los de quem acredita neles, os defende a sério e faz por eles o melhor que pode. É isso que o segundo passo pede: repetir o argumento do outro até ele concordar que é esse, e não a caricatura que convinha a você responder.",
  "Darwin seguia uma regra que chamava de regra de ouro, como conta na <i>Autobiografia</i>. Sempre que lhe aparecia um fato publicado, uma observação nova ou uma ideia contrária aos resultados gerais dele, ele a anotava na hora, sem falta, porque tinha visto que esses fatos fugiam da memória muito mais depressa do que os favoráveis. Graças a esse hábito, dizia, poucas objeções lhe tinham sido feitas que ele já não tivesse notado e tentado responder. A crença que você escreverá a cada noite, numa linha, com o melhor argumento contra ela, é a regra de Darwin aplicada ao que você pensa de si, dos outros e do mundo.",
  "Você objetará que uma mente assim não sustenta nada, que muda com o último que falou, como um cata-vento. Marco Aurélio escreveu <i>se me mostrarem</i>, e mostrar exige prova. A mente móvel se move por razão e só por ela; diante da insistência, do cansaço ou do prestígio de quem fala, ela fica onde estava. Sócrates morreu sem mudar de posição diante de um tribunal inteiro, porque ninguém lhe mostrou que estava errado."],
 ["Quando alguém contraria você, a primeira frase é <i>talvez você tenha razão</i>.",
  "Peça o melhor argumento do outro e repita-o com suas palavras, até ele concordar que é isso.",
  "Só então responda. Se mudou de ideia, diga isso em voz alta.",
  "À noite, uma crença em que você se apoiou hoje, e o melhor argumento contra ela, numa linha."],
 "O erro que mais se confunde com o gesto é ceder por cansaço: você muda de posição para a conversa acabar, sem que o argumento tenha convencido você. O cansaço se sente, e não decide nada; aqui só o argumento decide. O outro erro é fingir abertura, dizer a primeira frase e repetir o argumento só para depois rebatê-lo melhor.",
 None, "você muda de posição quando deve, e admitir isso já custa pouco.",
 comeco=["Você está na noite da nona passagem, com a serenidade entre as que ficaram. Dela sobra uma pergunta incômoda: passado o pico, e se o outro tiver razão? A serenidade lhe deu o intervalo; a mente móvel trata do que você faz nele quando a irritação vinha de orgulho ferido.",
  "O exercício da mente móvel treina o que você faz quando alguém contraria você. Você diz primeiro <i>talvez você tenha razão</i>; pede o melhor argumento do outro e o repete com suas palavras até ele concordar que é esse; só então responde e, se mudou de ideia, diz isso.",
  "A ocasião é ser contrariado: alguém discorda do que você disse, corrige um número seu, põe em dúvida uma decisão, mostra que você está enganado sobre um fato. Acontece numa reunião de trabalho, à mesa da família quando se fala do que divide, numa carta que contesta seu relatório, com um filho adolescente certo de que você não entende nada. Também conta quando é você que se contraria, ao reler o que pensava há um ano. A ocasião se reconhece pela pressa de responder e pela resposta que já está pronta antes de o outro acabar.",
  "Amanhã de manhã você pensará onde e por quem é provável que você seja contrariado nesse dia. Durante o dia, quando acontecer, a primeira frase, o pedido do argumento, a repetição, e só depois a resposta. E à noite, em todas as noites daqui em diante, uma linha: uma crença em que você se apoiou hoje e o melhor argumento contra ela.",
  "<i>Talvez você tenha razão</i> custa a sair na primeira vez, e é provável que saia baixo, quase engolido, enquanto por dentro outra voz já diz <i>não tem, e eu sei por quê</i>. Diga a frase mesmo assim e peça logo o argumento: <i>explique-me melhor por quê</i>. Depois repita-o com suas palavras e pergunte se é isso. A voz de dentro pode esperar o fim da repetição; se ainda tiver razão nesse momento, terá o argumento à frente para responder.",
  "Se você é contrariado várias vezes, a ocasião que mais pesa é a que toca o que mais lhe importa, ou a que vem de quem você menos queria ouvir. Num dia em que ninguém contrariou você, a linha da noite continua, e nela é você que se contraria; a marca desse dia é ponto."],
 marca="Marca-se só, na contrariedade que mais pesou, examinar antes de defender: o <i>talvez você tenha razão</i>, o argumento do outro repetido e, quando ele tinha razão, a mudança dita; a linha da crença, à noite, serve o gesto e não entra na marca. Se você examinou antes de defender, repetindo o argumento do outro, e se, quando ele tinha razão, você disse isso, é traço. Se defendeu antes de examinar, ou se mudou de ideia e não disse, é cruz. Ceder por cansaço, sem que o argumento tenha convencido você, não é traço. Se você não sabe se mudou por razão ou por cansaço, é cruz. Ponto num dia em que ninguém contrariou você. <i>Chegou</i> se escreve na noite em que, numa contrariedade de fato, o <i>talvez você tenha razão</i> e o pedido do argumento vieram antes da réplica sem que o breviário lembrasse você; foi a pressa de responder que lembrou você. A linha da noite, escrita de caderno aberto, nunca dá <i>chegou</i> por si. Depois do <i>chegou</i> fica: examinar antes de defender, e a linha da crença todas as noites.", sai="uma linha por noite com uma crença em que você se apoiou e o melhor argumento contra ela, e o argumento de quem contraria você repetido até ele concordar que é esse. No <i>Manual operacional</i>, as ações do grupo <i>Pensamento</i>.",
 porque=[
  "<b>A ideia.</b> Marco Aurélio escreve, nas <i>Meditações</i>, que, se alguém lhe mostrar que ele pensa ou age mal, mudará com alegria, porque busca a verdade, e ninguém jamais foi prejudicado por ela. A mente móvel muda quando há razão para mudar, e só então. O que a trava é o orgulho, que sente a opinião contrariada como uma derrota de quem a tinha.",
  "<b>O mecanismo.</b> Primeiro, a pressa de defender ouve do argumento contrário só a parte que já sabe rebater, e responde a uma caricatura. Repetir o argumento do outro até ele concordar que é esse obriga você a ouvi-lo inteiro, e só um argumento ouvido inteiro pode lhe mostrar que você erra. Segundo, a memória guarda melhor o que nos dá razão do que o que nos contraria; Darwin notou isso em si mesmo e passou a anotar na hora os fatos contrários. A linha da noite, uma crença e o melhor argumento contra ela, faz o mesmo trabalho. Nenhum estudo citado neste livro mede isso; são razões de Darwin e do próprio exercício.",
  "<b>Por isso.</b> <i>Faço isto porque esqueço mais depressa o que me contraria do que o que me dá razão.</i>"],
 saber="O viés de confirmação, a tendência a procurar, notar e lembrar o que nos dá razão, está entre os achados mais repetidos da psicologia, revisto por Raymond Nickerson em 1998, e ele sustenta a necessidade do gesto. Nenhum estudo citado aqui mostra que repetir o argumento do outro ou anotar o argumento contrário corrija esse viés. A força é alta para o problema e fraca para o remédio, que se apoia no exemplo de Darwin.")
add("Se você é contrariado por escrito, o gesto é o mesmo, mais lento: você lê o argumento até o fim, reescreve o argumento com suas palavras na margem e só então responde. Se quem contraria você sabe menos do que você, a primeira frase continua valendo, porque o argumento se examina pela força dele e não pelo lugar de quem o diz. Se é você que se contraria, relendo o que pensava há um ano, vale a regra de Darwin: anote a mudança e a razão dela. E quando, examinado tudo, o outro está errado, diga isso com a mesma calma com que diria que ele tinha razão, e com o argumento à vista. O exercício obriga você a examinar; mudar só vem depois, quando o exame o pede.", PI)
add("Se <i>talvez você tenha razão</i> começou a sair em tom de ironia, ou como um tique que antecede a réplica de sempre, a frase se esvaziou. Ela só vale se o segundo passo vier logo atrás: a repetição do argumento do outro até ele concordar. Se, depois de muitas noites, você não mudou de ideia uma única vez, nem num ponto pequeno, há duas causas prováveis: ou você só conversa com quem pensa como você, e então a escolha de quem critica você pede revisão, ou você examina por formalidade e já sabe a conclusão antes de ouvir. Procure de propósito o contrário: um livro, uma pessoa, um argumento a que você ainda não tenha respondido. E se você muda de ideia sempre, a causa costuma ser cansaço ou desejo de agradar. Antes de mudar, escreva numa linha o argumento que convenceu você; se não consegue escrevê-lo, o argumento não convenceu você.", PI)
exe("11", "Da pobreza voluntária", "J", "É disto que eu tinha medo?", "Sêneca",
 "Quando vier o impulso do conforto: espere vinte e quatro horas. E uma recusa de conforto por dia, escolhida de manhã.",
 [
  "Sêneca escreve a carta do dia de pobreza num mês de dezembro, com Roma inteira nas Saturnais e a cidade suando nos banquetes, e se pergunta o que fazer: entrar na festa ou fugir dela. Propõe um terceiro caminho, mais duro do que a abstenção: os dias de comida pouca e barata e de roupa áspera, com a pergunta no fim. O soldado, lembra ele, faz manobras em tempo de paz, cava trincheiras sem inimigo à vista e se cansa em trabalho supérfluo, para não se cansar quando o trabalho for necessário. Quem quer que a escassez não o abale a ensaia enquanto ela está longe.",
  "Na mesma carta, Sêneca, que citava o adversário sempre que ele tinha razão, lembra que Epicuro tinha dias fixos em que matava a fome com pouco, para ver se faltava alguma coisa à alegria plena, e quanto faltava, e se valia a pena um grande esforço para preencher a falta. O mestre do prazer era o mais frugal dos homens. Vivia no Jardim a pão e água, e Diógenes Laércio conserva um pedido dele a um amigo: que lhe mandasse um potinho de queijo, para poder se banquetear quando quisesse. Epicuro ensinava que desfruta mais da abundância quem menos precisa dela. Entendido assim, o dia de pobreza protege o prazer do desgaste que o costume lhe traz.",
  "Diógenes, o cínico, levava consigo uma tigela para beber. Diógenes Laércio conta que um dia ele viu um menino beber água com as mãos em concha e jogou fora a tigela, dizendo que uma criança o vencera em simplicidade. E Thoreau, em 1845, foi viver dois anos numa cabana que construiu com as próprias mãos à beira do lago Walden, perto de Concord, porque queria viver deliberadamente. Ele conta em <i>Walden</i> que tinha sobre a mesa três pedaços de calcário e que se assustou ao descobrir que era preciso espaná-los todos os dias, enquanto a mobília do espírito continuava sem espanar; desgostoso, jogou as pedras pela janela. Um homem, escreveu, é rico na proporção das coisas de que pode prescindir. Diógenes era da escola cínica, que punha a liberdade em precisar do mínimo, e os dois gestos ensinam o mesmo: cada coisa de que você depende cobra de você cuidado e atenção, e a riqueza de que fala Thoreau é o tempo que fica livre quando você deixa de precisar dela. A recusa de cada manhã procura uma dessas coisas por dia.",
  "Isso parece virtude de monge, ou de quem não tem família nem contas, e uma recusa pequena por dia e um dia de comida simples não mudariam a vida de quem trabalha. Sêneca era um dos homens mais ricos de Roma quando escreveu a carta, e Thoreau, como os críticos dele gostam de lembrar, ia muitas vezes jantar na casa da família, em Concord. Nenhum dos dois pede que você jogue fora o que tem. O exercício pede uma recusa por dia, vinte e quatro horas de espera e, uma vez por ciclo, o dia de pobreza, e o que ele mede é quanto do seu tempo e do seu juízo o conforto decide sem consultar você. O dia de pobreza responde a isso com um fato."],
 ["Quando vier o impulso de conforto, escreva-o com a data e a hora.",
  "Espere vinte e quatro horas. Se ainda o quiser e couber nas suas regras, faça.",
  "De manhã, escolha uma recusa de conforto para o dia, pequena e concreta, e cumpra-a.",
  "Uma vez por ciclo, declarado na véspera, o dia de pobreza: comida simples, nenhuma compra, nenhum entretenimento. Na noite desse dia, escreva o que você descobriu que não precisava."],
 "Há quem transforme o exercício em castigo, e o dia de pobreza numa pena que se cumpre de dentes cerrados. E há a vaidade da austeridade, que aparece quando o pouco começa a ser mostrado: quem mostra o pouco recebe por ele o conforto de ser visto.",
 None, "o conforto deixou de decidir por você.",
 comeco=["Na noite da décima passagem, com a mente móvel entre as que ficaram, você lê este. A mente móvel solta uma opinião quando deve. Este exercício pede a mesma soltura em relação às coisas, e começa pelo menor: um impulso de conforto adiado por um dia.",
  "O exercício da pobreza voluntária treina uma espera. Quando vem o impulso de conforto, você o escreve com a data e a hora e espera vinte e quatro horas; se depois disso ainda o quiser e ele couber nas suas regras, você faz. E a cada manhã escolhe uma recusa de conforto para esse dia. Uma vez por ciclo, vive um dia inteiro com pouco, o dia de pobreza.",
  "A ocasião é o impulso de conforto: a vontade de comprar o que não estava previsto, de comer sem fome, de abrir uma distração sem tê-la escolhido, de tomar o caminho fácil num detalhe do dia, pedir que levem você em vez de andar dez minutos a pé, o doce no fim da tarde. Ele se reconhece por chegar sem pedir licença, com a mão já no meio do gesto.",
  "Amanhã de manhã você porá uma folha onde o impulso costuma aparecer e escreverá, se ainda não as tem, as suas regras: o que cabe no seu dinheiro e no seu tempo, com números quando puderem tê-los. Escolherá a recusa desse dia, e daí em diante uma a cada manhã: o açúcar que você não põe, o caminho que faz a pé, a distração que não abre antes da obra. O dia de pobreza não tem data fixa; você o declara na véspera, à noite, nunca na própria manhã, e convém que ele caia enquanto este exercício é a da vez. Durante o dia, cada impulso vai para a folha, com a hora; vinte e quatro horas depois, você decide. Na noite do dia de pobreza, escreva o que você descobriu que não precisava.",
  "O impulso traz uma frase curta e razoável: <i>mereço</i>, <i>é só desta vez</i>, <i>é tão pouco</i>. A frase chega quando a mão já está no meio do gesto. A folha só lhe pede a data e a hora. A decisão fica para daqui a vinte e quatro horas, e você não tem de tomá-la agora, nem de vencer a frase; basta adiá-la.",
  "Os impulsos vêm muitas vezes, quase todos pequenos. O que mais pesa é o maior em dinheiro ou em tempo, ou o que volta todos os dias à mesma hora."],
 marca="Marca-se só, no impulso que mais pesou, escrevê-lo e esperar as vinte e quatro horas; a recusa escolhida de manhã, as regras de dinheiro e de tempo e o dia de pobreza servem o gesto e não entram na marca. Se você o escreveu e esperou, é traço. Fazer, passadas as vinte e quatro horas, o que cabe nas suas regras também faz parte do gesto. Se você cedeu na hora a esse impulso, é cruz. Se à noite você descobre impulsos a que obedeceu sem vê-los chegar, a ocasião veio, e conta como cedida. Num dia sem impulso, é ponto, mas um dia sem impulso nenhum merece desconfiança. No dia de pobreza, a marca continua sendo sobre o impulso. <i>Chegou</i> significa que, no impulso que mais pesou, a mão parou e foi à folha sem que o breviário lembrasse você; foi o próprio impulso que lembrou você. Depois do <i>chegou</i> fica: escrever o impulso e esperar as vinte e quatro horas.", sai="a folha dos impulsos com data e hora, suas regras de dinheiro e de tempo escritas, uma recusa de conforto cumprida por dia e, do dia de pobreza, a linha do que você não precisava. No <i>Manual operacional</i>, as ações do grupo <i>Privação voluntária</i>.",
 porque=[
  "<b>A ideia.</b> Sêneca aconselha Lucílio, numa das cartas, a reservar alguns dias de pobreza, em que se contente com pouquíssimo, comida pouca e barata, roupa áspera, e no fim se pergunte: é disto que eu tinha medo? Quem ensaia o pouco descobre que aguenta mais do que temia, e o conforto perde parte do poder sobre ele. O conforto, quando decide por você, costuma decidir pelo adiamento.",
  "<b>O mecanismo.</b> Primeiro, o impulso chega com a mão já no meio do gesto, e quem decide nesse instante decide com a força dele. Escrevê-lo com a hora e esperar vinte e quatro horas leva a decisão para quando ele já baixou, e o impulso pequeno, adiado, quase sempre desaparece. Deixar a vontade passar sem obedecer a ela tem apoio no estudo pequeno e preliminar de Bowen e Marlatt, com fumantes, que a nona linha contou a você. Segundo, você só sabe de quanto precisa quando passa sem isso; a recusa diária e o dia de pobreza respondem à pergunta de Sêneca pela experiência. Aqui há a razão de Sêneca, e nenhum estudo.",
  "<b>Por isso.</b> <i>Faço isto porque o impulso, adiado um dia, perde a força com que chegou, e porque só sei de quanto preciso quando passo sem isso.</i>"],
 saber="O estudo de Bowen e Marlatt, com estudantes fumantes, sustenta que observar a vontade sem obedecer a ela reduziu o fumo na semana seguinte; é um estudo só, curto e preliminar. A espera de vinte e quatro horas e a recusa diária não foram testadas, e a ideia de Sêneca, de que só se sabe de quanto se precisa passando sem isso, vem da experiência, sem medida. A força é fraca.")
add("O impulso de conforto não se reduz a comprar. É também a comida a mais quando não há fome, o entretenimento que se abre sem escolha, a troca do caminho difícil pelo fácil num detalhe qualquer do dia. Todos cabem na ocasião, e a espera é a mesma para o pequeno e para o grande: o pequeno, adiado um dia, quase sempre desaparece. Se você vive com outras pessoas, o dia de pobreza é seu e não delas; não se impõe a ninguém a austeridade que você escolheu, e a comida simples pode ser apenas o seu prato. A recusa de cada dia também se adapta à vida que você tem: quem não compra nada passa sem o doce, quem não come doces faz a pé o caminho curto, e quem vive com o dinheiro apertado recusa conforto de tempo, a distração aberta antes da obra.", PI)
add("Se a folha dos impulsos fica quase vazia, o conforto não deixou de pedir: o impulso age antes de ser percebido, e a mão já fez o que ele queria quando você se lembra de escrever. O ajuste vem da segunda lei: ponha a folha onde o impulso costuma aparecer e escreva assim que vier a primeira frase interior. Se, passadas as vinte e quatro horas, você faz sempre o que tinha adiado, a falha está nas regras, que você nunca escreveu; <i>couber nas suas regras</i> pressupõe que elas existam. Escreva-as num dia calmo, com números quando puderem tê-los. E se o dia de pobreza irrita você e o dia seguinte vira um banquete de desforra, você fez dele um castigo e esqueceu a quarta lei: nada se compensa. Faça o próximo mais leve e ponha a atenção na pergunta da noite, o que você descobriu que não precisava. E se a recusa da manhã é sempre a mesma e já não custa nada, ela deixou de ser recusa: escolha outra.", PI)
exe("12", "Da discrição", "H", "As ovelhas não mostram quanto comeram; digerem e dão lã.", "Epicteto",
 "Quando vier a vontade de contar um plano: cale-se e volte à obra. <font color='#6b6b6b'>(Lição IX)</font>",
 [
  "No Sermão da Montanha, tal como Mateus o conserva, Jesus fala dos que dão esmola tocando trombeta diante de si, nas sinagogas e nas ruas, para serem louvados, e diz deles uma coisa exata: já receberam a sua recompensa. E dá a regra contrária: quando você der esmola, que a sua mão esquerda não saiba o que faz a direita, para que a esmola fique em segredo. A frase vale para quem crê e para quem não crê, porque descreve um mecanismo. Quem anuncia o ato recebe o louvor antes de praticá-lo, e com ele parte da razão para praticá-lo. A sétima lei diz o mesmo da obra. O ato bom que ninguém saberá, pequeno, um por dia, treina a mesma recusa onde não há obra em jogo, só o gosto de ser visto.",
  "Em Crotona, no sul da Itália, mais de quinhentos anos antes de Cristo, Pitágoras recebia discípulos, e a tradição, que chega por Diógenes Laércio e por Jâmblico, diz que os novos passavam cinco anos em silêncio, ouvindo as lições sem ver o mestre, que falava por trás de uma cortina, até serem julgados dignos de vê-lo. O número pode ser lenda, e a ideia continua de pé. Antes de falar de uma coisa, o discípulo aprendia a carregá-la calado, e o silêncio era ele mesmo um exercício. Em ponto pequeno, é o que você aprenderá enquanto este exercício for a da vez: a vontade de contar sobe e passa, e o trabalho continua sem ela.",
  "Epicteto, no mesmo <i>Manual</i> de onde vêm as ovelhas, dá o exercício na forma mais pura. Se algum dia você quiser se treinar para suportar, diz ele, faça isso para si e não para os de fora: quando estiver com muita sede, tome na boca um gole de água fresca, cuspa-o e não conte a ninguém. O treino feito para ser visto já recebeu o pagamento no olhar dos outros, como a esmola tocada a trombeta, e só o treino feito em segredo treina a vontade. O ato bom que ninguém saberá é esse gole de água cuspido.",
  "Carl Friedrich Gauss, o maior matemático do seu século, levou essa discrição ao próprio ofício. Tinha por lema <i>pauca sed matura</i>, poucas coisas, mas maduras, gravado num selo com uma árvore de poucos frutos, e só publicava o que estivesse acabado e demonstrado sem lacuna. O que ainda não estava ia para um pequeno caderno, começado em março de 1796, quando ele tinha dezoito anos, com a construção do polígono de dezessete lados com régua e compasso. Ali ele anotou, em linhas curtas e sem contar a ninguém, resultados que outros só publicariam décadas depois, com o nome deles. O caderno ficou com a família e só foi conhecido em 1898. A matemática da época o via publicar pouco e devagar, e ninguém sabia quanto ele tinha guardado. Gauss pagou esse preço de olhos abertos: falava do que estava maduro, e o resto amadurecia calado, a salvo da conversa e do aplauso.",
  "Contar o plano, diz-se, ajuda a cumpri-lo, porque quem diz em voz alta se compromete e não quer passar vergonha. A sétima lei já lhe respondeu: ao parceiro se leva o feito, e não o plano."],
 ["Quando vier a vontade de contar, cale-se e escreva-a na folha de captura.",
  "Volte à obra.",
  "Só se fala do que está concluído, e só se perguntarem.",
  "Um ato bom por dia, pequeno, que ninguém saberá."],
 "O erro mais sério é confundir discrição com isolamento ou com mentira: esconder dos seus o que eles precisam saber, ou dizer que não faz nada quando faz. E pedir crítica não é anunciar; a crítica que você treinou no sétimo exercício continua.",
 None, "você fala apenas do que já está feito.",
 comeco=["Você está na noite da décima primeira passagem, e a pobreza voluntária ficou entre as que ficaram. Na pobreza voluntária você ensaiou o pouco nas coisas; este exercício o ensaia nas palavras. Ser visto também é um conforto, e ele se obtém antes do tempo, sem obra feita, contando. É a imagem de si mesmo como alguém que tenta, e quem conta o plano recebe por ele o aplauso que caberia à obra feita.",
  "O exercício da discrição treina o silêncio sobre o que ainda não está feito. Quando vem a vontade de contar um plano, você se cala, escreve a vontade na folha de captura e volta à obra. Só se fala do que está concluído, e só se perguntarem. E, a cada dia, um ato bom e pequeno que ninguém saberá. À mesa, o plano contado chega à sessão seguinte já meio pago, e <i>isto</i> custa mais a acabar.",
  "A ocasião é a vontade de contar. Ela vem à mesa com amigos, quando alguém fala do que anda fazendo e você tem uma coisa maior para dizer; vem no trabalho, quando um projeto seu ainda está no papel e seria agradável anunciá-lo; vem em casa, no fim do dia, com tudo o que você vai começar. Ela se reconhece pelo prazer antecipado, o gosto de ver a cara do outro antes de haver obra.",
  "Amanhã de manhã você antecipa onde a vontade de contar vai aparecer: o encontro, a conversa, a pessoa a quem você costuma contar tudo. Durante o dia, quando ela vier, você se cala, escreve uma linha na folha de captura e volta ao que estava fazendo; se lhe perguntarem diretamente, você responde com o que está feito, em poucas palavras. O ato bom do dia é feito quando couber, pequeno, e depois não se conta a ninguém.",
  "A vontade vem quase sempre num bom momento, à mesa, com alguém que gosta de você, e traz uma frase generosa: <i>conte, ele vai gostar de saber</i>. Talvez a frase seja verdadeira. Escreva-a na folha de captura mesmo assim, como escreveria qualquer outra coisa que interrompe, e pergunte ao outro como vai a vida dele. Quando o plano estiver feito, ele vai gostar de saber o que você fez.",
  "A vontade pode vir várias vezes ao dia, ou nenhuma. A ocasião que mais pesa é a que toca o plano que mais lhe importa."],
 marca="Marca-se só, na vontade de contar que mais pesou, calar e voltar à obra; o ato bom do dia, que ninguém saberá, serve o gesto e não entra na marca. Se você se calou e voltou à obra, é traço. Se contou esse plano, e deixar adivinhar com meias frases também é contar, é cruz. Se você não sabe se aquela meia frase deixou adivinhar, é cruz. Num dia em que a vontade de contar não veio, é ponto. Você escreve <i>chegou</i> na noite em que, na vontade que mais pesou, você se calou sem que o breviário lembrasse você; foi o prazer antecipado que lembrou você. Depois do <i>chegou</i> fica: calar a vontade de contar e voltar à obra.", sai="a vontade de contar posta na folha de captura em vez de dita, a resposta curta com o que está feito quando lhe perguntam, e um ato bom por dia que você não contou.",
 porque=[
  "<b>A ideia.</b> A epígrafe é a imagem das ovelhas que a sétima lei do Livro II já apresentou a você por inteiro. Quem aprendeu, para Epicteto, se reconhece pelo que produz com o que aprendeu, como a ovelha pela lã. A epígrafe abre este exercício porque o plano contado é o pasto mostrado antes de haver lã.",
  "<b>O mecanismo.</b> Primeiro, o anúncio paga adiantado. Quando outra pessoa reconhece aquilo que você pretende fazer de si, o espírito registra isso como em parte conquistado e afrouxa. É o estudo de Gollwitzer e colegas, de 2009, que a sétima lei do Livro II contou a você, e ele deve ser lido com a prudência devida a um estudo. Segundo, o plano contado põe a obra sob o olhar dos outros antes de ela estar pronta para isso (Lição IX), e você passa a trabalhar também para esse olhar. Este segundo ponto é razão; nenhum estudo citado neste livro o mede.",
  "<b>Por isso.</b> <i>Faço isto porque o plano contado me paga antes da obra, e porque o que ainda não está feito se faz melhor longe do olhar dos outros.</i>"],
 saber="O estudo de Gollwitzer e colegas, de 2009, sustenta que anunciar uma intenção ligada à identidade, como a de se tornar psicólogo ou advogado, e vê-la reconhecida diminuiu o esforço seguinte. Foram poucos experimentos pequenos, com estudantes, sem replicação em larga escala, e o estudo não mediu planos comuns. O segundo ponto, a obra sob o olhar dos outros, é razão. A força é fraca.")
add("Se lhe perguntam diretamente o que você anda fazendo, responda com o que está feito, em poucas palavras, e pare aí. Se seu trabalho exige que outros conheçam seus planos, porque dependem deles para organizar os próprios, dê a eles a informação necessária e nada do brilho que a acompanharia; a prova é perguntar a si mesmo se você diria aquilo caso ninguém fosse admirar você por isso. O ato bom de cada dia pode mudar de forma: um trabalho feito para alguém sem que você conte a essa pessoa, uma dívida paga que ninguém cobrava, uma recomendação feita em favor de alguém que nunca saberá quem foi. A condição é sempre a mesma: que você não conte depois.", PI)
add("Se você não conta o plano mas deixa que ele seja adivinhado, com meias frases, <i>ando com uma coisa grande que ainda não posso dizer</i>, a vontade de contar foi satisfeita por outro caminho, e é cruz. Se a folha de captura se enche de vontades de contar sempre o mesmo plano, a causa provável está na obra: ela parou, e contar o plano dá a sensação de avanço que a obra deixou de dar. O ajuste é voltar à obra pela primeira linha, e não calar com mais força. A discrição se aplica aos planos e ao desejo de ser visto; o que os seus precisam saber se diz.", PI)
exe("13", "Do amor ao destino", "J", "Não querer nada diferente, nem para a frente, nem para trás.", "Nietzsche",
 "Quando algo der errado: uma linha com a causa, e o próximo passo feito. Sem lamento.",
 [
  "Epicteto, escravo liberto e, segundo a tradição, coxo desde a juventude, pôs no <i>Manual</i>, no capítulo 8, uma regra que só parece fácil: não peça que as coisas aconteçam como você quer; queira que aconteçam como acontecem, e sua vida correrá serena. A regra não manda desistir de agir. O primeiro exercício deste livro já separou, com ele, o que depende de você do que não depende; este aplica a separação depois do fato. O que aconteceu já não depende de você. O próximo passo depende, e é só nele que a linha da noite põe a mão.",
  "Marco Aurélio, o imperador dos acampamentos do Danúbio de que o Proêmio falou, deixou a forma mais curta desta ideia (<i>Meditações</i>, V, 20). Os homens, diz ele, podem impedir a ação dele, mas não a disposição, porque o espírito converte o obstáculo e faz dele matéria: o que impede a ação faz a ação avançar, e o que está no caminho se torna caminho. O que ele deixa ali é uma técnica: tomar o que bloqueou o plano e perguntar o que isso permite fazer agora. Para ele, o que o obstáculo deixa fazer é sempre um ato de virtude, a paciência, a justiça, a moderação, porque a virtude é o único bem e nenhum obstáculo a tira; aqui a técnica se aplica ao plano do dia.",
  "Nietzsche escreveu o aforismo que abre o quarto livro de <i>A gaia ciência</i> em janeiro de 1882, em Gênova, para o ano-novo. Tinha deixado a cátedra de Basileia três anos antes, por doença; passava dias com dores de cabeça que o fechavam no escuro, e a vista lhe falhava. Escreveu que queria aprender cada vez mais a ver como belo o que é necessário nas coisas, e chamou isso de amor fati: que seja este, de agora em diante, o meu amor. Não queria fazer guerra ao que é feio, nem acusar, nem sequer os acusadores; desviar o olhar seria a única negação dele; e queria ser, algum dia, apenas alguém que diz sim. A fórmula do <i>Ecce Homo</i>, anos depois, retoma esta. Quem a escreveu não estava em condições de dizê-la por conforto. No aforismo de Nietzsche, o que já não pode ser outro se recebe sem acusação, e a única recusa que se permite é desviar o olhar. Na linha de queda, isso quer dizer escrever o que aconteceu sem culpado e sem queixa. Mas a fórmula do <i>Ecce Homo</i> pede mais do que este exercício: não querer nada diferente, nem para a frente, nem para trás. O próximo passo da linha de queda quer que amanhã seja diferente, e a anti-visão e a visão do seu dia zero são, as duas, um querer diferente para a frente. Nietzsche não chamaria isso de amor fati. O livro toma dele só a parte que olha para trás, receber a queda sem acusação; a parte que olha para a frente vem dos estoicos, que ele tinha por rivais.",
  "John Milton, poeta inglês, ficou cego por volta de 1652, aos quarenta e poucos anos, no meio da obra política que lhe tomara a maturidade. Depois da Restauração, em 1660, ele se escondeu, chegou a ser preso e perdeu boa parte do que tinha. Foi nesses anos, cego, que compôs o <i>Paraíso perdido</i>, publicado em 1667. Os primeiros biógrafos contam que ele compunha de noite, de memória, e de manhã esperava quem escrevesse os versos por ele, queixando-se, se a pessoa tardava, de que precisava ser ordenhado. Num soneto sobre a cegueira, ele se perguntara como serviria sem a luz, e a Paciência lhe respondia que Deus não precisa da obra do homem nem dos dons que lhe deu; servem melhor a Deus os que levam bem o jugo brando dele, e também servem os que apenas estão de pé e esperam. No soneto de Milton, o valor de uma vida diante de Deus não se mede pelo que ela produz, e a espera paciente já é serviço inteiro. O soneto não pede obra nenhuma, e o livro, ao contar o que veio depois, usa a vida dele para outra coisa: cego, ele compôs com a memória e com a voz. Essa vida, mais do que o soneto, é a regra de Marco Aurélio vivida, o obstáculo feito modo de trabalhar, e o próximo passo da sua linha de queda pode ter essa forma, diferente da que você planejava.",
  "Você dirá que há coisas que não se amam, uma doença, uma morte, uma injustiça feita a quem você ama, e que pedir amor a isso é obsceno. O exercício não pede tanto. A ocasião dele está à medida do dia: o plano que caiu, a entrega recusada, o gesto que não chega. Nem Nietzsche pede que se aprove o mal; pede que se deixe de lhe fazer guerra onde a guerra já não muda nada. E há dores para as quais nenhum exercício foi escrito, nem este. Diante delas, este livro não lhe pede marca nenhuma.",
  "A releitura do terceiro passo tem um antepassado, e é a última história que lhe conto nesta parte do caminho. Inácio de Loyola, nos <i>Exercícios espirituais</i>, ensinava um exame particular, dirigido a uma só falta: de manhã, ao levantar, propor a si mesmo guardar-se dela; depois do almoço, pedir contas a si mesmo, hora por hora, e marcar numa linha tantos pontos quantas as vezes em que caíra; à noite, o mesmo, em outra linha; e depois comparar as linhas, a de hoje com a de ontem, uma semana com a outra, para ver se diminuíam. E o exame geral da noite mandava começar dando graças, antes de procurar as faltas. A folha de marcas e as linhas de queda são parentes desse papel. Relidas, elas servem para procurar o padrão; e começar pelo que deu certo ajuda a ler o resto com a cabeça fria."],
 ["Quando algo der errado, sem lamento e sem culpar ninguém, escreva uma linha: <i>o que aconteceu, onde estava o buraco, qual é o próximo passo</i>.",
  "Faça o próximo passo no mesmo dia.",
  "Uma vez por ciclo, releia todas as linhas de queda e procure o que se repete."],
 "O erro mais frequente é confundir este exercício com resignação: encolher os ombros e não fazer o passo. O outro é fingir que não dói, escrever a linha com uma calma que você não tem e pular o buraco. O exercício pede que se use o que aconteceu.",
 None, "as quedas passaram a ser lidas como dados sobre o que ajustar, e já não como razão para parar.",
 comeco=["É a noite da décima segunda passagem, e você lê o último exercício. Atrás de você há muitas noites de marcas, e é provável que entre elas haja quedas: cruzes, talvez noites em que a dúvida lhe recusou o <i>chegou</i>, talvez microações que já tinham ficado e voltaram a ser a da vez, linhas de queda escritas em noites ruins. Os doze exercícios anteriores trataram do que fazer; este trata do que fazer com o que não deu certo, e por isso vem no fim, quando já há matéria para ele.",
  "O exercício do amor ao destino treina o que você faz depois que uma coisa dá errado: escreve uma linha, sem lamento e sem culpar ninguém, com o que aconteceu, onde estava o buraco e qual é o próximo passo; e faz esse passo no mesmo dia.",
  "A ocasião é algo que deu errado, à medida do dia: o plano que caiu porque choveu, a entrega devolvida cheia de emendas, a viagem perdida por minutos, a conversa que acabou mal, uma noite de cruz, uma das que ficaram que cedeu. A grande dor, a doença ou o luto ficam fora dela, porque para eles nenhum exercício deste livro foi escrito. A ocasião se reconhece pela voz que começa logo a contar a história do que aconteceu, com culpados e com queixas.",
  "Amanhã de manhã não haverá muito a antecipar, porque o que dá errado não avisa; basta você saber onde está a folha em que vai escrever a linha. Durante o dia, quando algo der errado, a linha com as três partes, e o próximo passo feito antes de o dia acabar, nem que seja a versão de dois minutos da sexta linha. À noite, a marca.",
  "Quando algo dá errado, a primeira coisa a vir é essa história, já contada por dentro com começo, meio e fim: quem teve a culpa, como era evitável, o que isso diz de você. Ela costuma vir inteira e depressa. A linha das três partes tem pouco espaço para ela, e é por isso que se escreve a linha: <i>o que aconteceu</i> pede o fato sem adjetivos, <i>onde estava o buraco</i> pede um lugar, <i>qual é o próximo passo</i> pede um ato que caiba no dia. O que a queda diz de você não tem linha.",
  "Num dia difícil, várias coisas dão errado. A ocasião que mais pesa é a maior delas, ou a que mais puxa você para o lamento."],
 marca="À noite, olhe para a coisa que mais pesou. Se você escreveu a linha sem lamento e fez o próximo passo no mesmo dia, é traço. Se o lamento venceu, ou se o passo escrito ficou por fazer, é cruz: escrevê-lo e não fazê-lo é cruz. Se a linha saiu com um culpado dentro e você hesita, é cruz. Ponto se nada deu errado; não se fabricam quedas para treinar o exercício. A releitura de todas as linhas de queda, uma vez por ciclo, não tem noite própria e fica fora da marca. <i>Chegou</i> quer dizer que, na coisa que mais pesou, a linha em três partes tomou o lugar do lamento sem que o breviário lembrasse você; foi a própria queda que lembrou você. Depois do <i>chegou</i> fica: a linha em três partes no lugar do lamento, com o próximo passo feito no mesmo dia.", sai="uma linha em três partes para cada coisa que deu errado, com o próximo passo feito no mesmo dia, e as linhas de queda do ciclo relidas uma vez, com o que se repete anotado. No <i>Manual operacional</i>, as ações do grupo <i>Pensamento</i>.",
 porque=[
  "<b>A ideia.</b> Nietzsche, em <i>Ecce Homo</i>, chama de amor fati amar o que é necessário, sem querer nada diferente, nem para a frente, nem para trás. O gesto deste exercício segue essa fórmula só na metade que olha para trás, como o <i>Do sentido</i> conta; o próximo passo vem da técnica estoica do obstáculo que se torna caminho (Marco Aurélio, <i>Meditações</i>, V, 20; Epicteto, <i>Manual</i>, 8). Diante do que deu errado, em vez de lamentar a queda, você lê o que ela mostra e faz o passo que ela ainda permite. A queda diz onde a estrutura cedeu.",
  "<b>O mecanismo.</b> Primeiro, o lamento é uma sentença sobre o caráter, e vem depressa porque já está pronta; ele fecha o caso antes de a queda ser examinada. A linha em três partes pede um fato, um lugar e um ato, e um buraco com lugar pode ser tapado, coisa que nenhuma sentença permite. Segundo, quem se condena depois de falhar tem medo de olhar a falha, e quem não a olha não a corrige. Num estudo de Juliana Breines e Serena Chen (2012), pessoas levadas a se tratar com compreensão depois de falhar num teste estudaram mais tempo para o teste seguinte; o estudo é bem desenhado, e ainda lhe falta uma replicação independente.",
  "<b>Por isso.</b> <i>Faço isto porque o lamento fecha o caso antes de eu ver o buraco, e porque só corrijo a queda que consigo olhar sem me condenar.</i>"],
 saber="O estudo de Breines e Chen sustenta que tratar-se com compreensão depois de uma falha aumentou o tempo de estudo para o teste seguinte; é bem desenhado, feito com estudantes, e ainda espera replicação independente. Nenhum estudo testou a linha em três partes, com causa, lugar e ato. A força é fraca a moderada para a ideia de que a condenação afasta da falha, e nula para a forma do gesto.")
add("Quando o que deu errado foi obra de outra pessoa, a linha continua sem culpado: o que aconteceu, onde estava o buraco que cabia a você, qual é o seu próximo passo. Há quase sempre um buraco que cabia a você, mesmo pequeno, e é o único sobre o qual você pode fazer alguma coisa. Quando o que deu errado é grande, o próximo passo pode ser mínimo, a versão de dois minutos da sexta linha, desde que seja feito no mesmo dia.", PI)
add("Se as linhas de queda crescem até virar parágrafos, o lamento voltou disfarçado de análise, e a forma é o remédio: uma linha, três partes, e nenhuma delas pergunta quem você é. Se você escreve o próximo passo e não o faz no mesmo dia, a noite marca cruz; o ajuste é diminuir o passo até ele caber no que resta do dia. E se, ao reler as linhas no fim do ciclo, você encontra o mesmo buraco cinco, dez vezes, o problema deixou de estar na queda e passou ao terreno. Leve-o à manhã seguinte como pergunta sobre o desenho: o ambiente, a ordem da mesa, a ocasião que nunca foi bem definida.", PI)

add("Uma noite, que o livro não sabe quando será, a décima terceira microação chegará. Na ocasião que mais pesou, a linha em três partes terá vindo no lugar do lamento sem que o caderno lembrasse você, e você escreverá <i>chegou</i> ao lado do último traço do ciclo. Nessa noite não haverá exercício seguinte para ler, e na manhã seguinte não entrará nenhum. As treze estarão entre as que ficaram, e continuam todos os dias, cada uma na sua ocasião. Os dias que isso levou estão na folha de marcas. À mesa, quando você se senta e diz <i>Isto, até acabar</i>, o que vem buscar você continua vindo, e encontra treze gestos que já não pedem caderno.", PI)
add("O ciclo acaba aí, e o caminho manda você ao Livro V, em <i>Da prova</i>: ao fim de cada ciclo, antes de voltar à estação zero, você responde por escrito às perguntas da prova do ciclo. Depois vêm o Interlúdio e <i>Do retorno</i>, e por fim um novo dia zero e o primeiro exercício outra vez: a mesa em ordem, a lista do que está aberto, o bloco de absorção, agora com a prática de um ciclo inteiro.", PI)
add("Se, em algum ponto das estações, na primeira ou no meio da terceira, você reparou numa coisa que nenhum exercício resolveu, você conhece a forma dela. É um hábito antigo que volta sempre à mesma hora, no mesmo lugar, com o mesmo pagamento, e que nenhum gesto novo desaloja: os exercícios acrescentam, e ele não se deixa vencer por acréscimo.", PI)
add("Para ele não há passagem nem estação, e não é preciso esperar que as treze cheguem para enfrentá-lo. É dele que trata o livro seguinte.", PI)
add("Antes de virar a página, confira onde você está. Se a décima terceira ainda não tem, na folha de marcas, uma noite de <i>chegou</i> escrita sem dúvida, ela continua sendo a da vez, e a prova do ciclo espera; quando tiver, abra o Livro V em <i>Da prova</i>. E se um hábito antigo desfaz o que os exercícios fazem, leia o Livro IV agora, sem esperar o fim das estações.", PI); fleur()
# O ornamento vai junto do último parágrafo, para não ficar sozinho numa página.
st[-2:] = [KeepTogether(st[-2:])]
# ===================== LIVRO IV =====================
livro("IV", "Do corte")
add("<i>“Dá-me a castidade e a continência, mas não ainda.”</i>", ParagraphStyle('c1', parent=PC, fontSize=12.5, spaceAfter=2))
add("Santo Agostinho, <i>Confissões</i>, VIII", ParagraphStyle('c2', parent=EPA, spaceAfter=18))
add("Há hábitos que desfazem o estado de foco antes que ele comece, porque dão em um minuto o que a obra só dá em uma tarde inteira, e depois deixam a atenção incapaz de se fixar em uma coisa só. O corte é para esses.", PI)
add("Você lê este livro na noite em que percebe que um hábito antigo desfaz o que os exercícios fazem, em qualquer ponto das estações, e sai dele com <i>Dias limpos</i> começada: a linha datada e assinada no alto, a lista das pontes riscada e a paixão contrária escrita.", PI); add("Você vai voltar a este livro depois disso: a <i>Da paixão contrária</i>, quando a hora em que o hábito morava ficar vazia; a <i>Da queda</i>, no dia em que cair; a <i>Da contagem</i>, nas noites dos trinta e dos noventa dias. E se você cair dois dias seguidos, ou se a linha cair uma vez e depois outra, releia a nota do fim de <i>Da contagem</i> e os sinais de <i>Do escrúpulo</i>, no Livro V, e procure ajuda profissional.", PI)
add("Você está em algum ponto das estações. Pode ser ainda na primeira, pode ser no meio da terceira; o livro não sabe em qual, e para o que vem a seguir isso não importa. As noites são feitas como você aprendeu: a marca, a linha do dia, a linha da queda quando houve queda. E em uma delas, ao percorrer a folha de marcas, você percebe uma conta que não fecha. Os traços estão lá, a da vez avança, algumas já ficaram, e mesmo assim a vida, vista de um mês para o outro, quase não se mexe. O que o gesto tece de dia, alguma coisa desfaz quando ninguém está olhando. Você procura a falha na folha, e ela não está na folha.", PI)
add("A falha está em um hábito antigo que nenhum exercício toca, porque nenhum foi feito para tocá-lo. O livro não sabe qual é o seu. Você sabe, e é provável que saiba há muito tempo: ele volta à mesma hora, no mesmo lugar, com o mesmo pagamento, e os gestos novos passam ao lado dele sem desalojá-lo. Repare no que lhe ocorre no instante em que você o reconhece. Muitas vezes é uma frase mansa: <i>disso cuido depois, quando os exercícios estiverem feitos</i>. Ou então: <i>também não é tão grave assim</i>. Essa frase tem nome neste livro, e foi Agostinho quem o deu, na epígrafe que você acabou de ler: <i>mas não ainda</i>. Agostinho nasceu no norte da África no século IV, foi professor de retórica antes de ser bispo de Hipona e contou nas <i>Confissões</i> os anos em que quis largar uma vida e não conseguia. Na juventude, rezava pedindo a castidade e a continência, e acrescentava <i>não ainda</i>, porque temia ser atendido depressa demais. A frase abre este livro porque é esse adiamento que o corte vem encerrar.", PI)
add("Conheço este trecho do caminho; eu também passei por ele. É aquele em que se percebe que construir não basta. O Livro III ensinou você a pôr coisas onde não havia nada: a ordem, a hora, a obra, a escuta. Mas ninguém chega ao caminho como um terreno vazio. O seu já está ocupado por hábitos que têm suas horas e seus lugares, e que não vão embora só porque chegaram vizinhos novos.", PI)
add("Para esse hábito, o livro tem outra operação, e a chama de <b>corte</b>. Cortar é deixar um hábito de uma vez, a partir de um dia certo, com uma linha escrita à mão, no presente, datada e assinada. Depois essa linha é guardada com o corpo, pondo distância entre você e a ocasião. O corte corre ao lado dos exercícios, e não depois deles: a da vez continua sendo treinada como sempre, e o corte segue junto, um de cada vez. Ele não tem passagem nem <i>chegou</i>, e é a única coisa do método que não tem piso nos dias maus. No lugar da passagem, tem a contagem dos <b>dias limpos</b>, os dias em que você não cedeu, em uma página própria do caderno, <i>Dias limpos</i>, a página 35, logo depois das folhas de marcas.", PI)
add("Esta noite, não trace nada ainda. Leia até o fim de <i>Do modo</i> e, antes de fechar o caderno, faça só o primeiro passo, o de nomear. A linha fica para amanhã de manhã.", PI)

sec("Da decisão")
st.append(Paragraph("D O &nbsp; P O R Q U Ê", LBX))
for par in ["<b>A ideia.</b> Um hábito se forma por repetição, e Agostinho descreveu os degraus no livro oitavo das <i>Confissões</i>: da vontade desviada nasce o desejo; o desejo atendido vira costume; o costume a que não se resiste vira necessidade. São três degraus, e nenhum pede uma decisão grave, só que a coisa se repita. Por isso a saída raramente acontece pelo caminho inverso, devagar e aos poucos: enquanto houver repetição, ela trabalha a favor do hábito. O corte deixa o hábito de uma vez.", "<b>O mecanismo.</b> Primeiro, a linha absoluta tira a quantidade da discussão. Moderar obriga a decidir, em cada ocasião, quanto se concede, e essa decisão é tomada sempre no pior momento, com a coisa ao alcance da mão; com a linha, não resta quantidade a decidir. Segundo, um hábito é disparado pelas pistas do lugar, da hora e da companhia, com relativa independência da intenção do momento. David Neal e Wendy Wood viram pessoas continuarem a comer pipoca velha no cinema, onde o hábito tinha sua pista, contra a própria preferência. Por isso os passos de <i>Do modo</i> afastam a ocasião e mudam o terreno, em vez de pedir força diante dela.", "<b>Por isso.</b> Corto de uma vez porque moderar me faria negociar em cada ocasião, perto da coisa, e afasto a ocasião porque o hábito dispara no lugar e na hora de sempre."]: add(par, PI)
add("O pedido de Agostinho era sincero, e o <i>não ainda</i> também. O hábito aceitava a mudança, e sempre a adiava por mais um dia razoável.", PI)
add("A cena em que o adiamento acabou aconteceu no verão de 386, em Milão. Agostinho tinha trinta e um anos, ensinava retórica, já não tinha dúvida nenhuma sobre o que devia fazer, e não o fazia. Um conterrâneo africano, Ponticiano, veio visitá-lo e falou, quase por acaso, de Antão, o monge do deserto, e de dois funcionários do imperador que, em Tréveris, tinham encontrado a vida de Antão em uma cabana e largado tudo no mesmo dia. Agostinho ouvia, e diz que era como se o tivessem posto diante do próprio rosto.", PI)
add("Quando Ponticiano saiu, Agostinho foi para o jardim da casa onde morava, e Alípio, o amigo, o seguiu. Arrancava os cabelos, batia na testa, apertava os joelhos entre as mãos entrelaçadas. Escreve que o corpo lhe obedecia ao menor sinal da vontade, mas que a vontade não obedecia a si mesma: ela mandava, e a ordem não se cumpria, porque não mandava por inteiro. Agostinho quer dizer que metade dele queria largar e a outra metade não, e que uma vontade dividida manda sem ser obedecida. A linha que você vai traçar amanhã busca essa ordem dada por inteiro, sem uma metade guardada para depois. E os velhos hábitos, que ele chama de ninharias das ninharias, o puxavam pela roupa de carne e murmuravam: <i>vai nos deixar? a partir deste momento, nunca mais?</i>.", PI)
add("Ele se afastou de Alípio, deitou-se debaixo de uma figueira e chorou. <i>Até quando? Amanhã, e amanhã? Por que não agora?</i> Foi então que ouviu, de uma casa vizinha, uma voz de criança, menino ou menina, ele não sabia, que repetia como em uma cantiga: <i>tolle lege, tolle lege</i>, toma e lê. Não se lembrava de nenhuma brincadeira com essas palavras. Voltou ao banco onde tinha deixado Alípio e o livro das cartas de Paulo, abriu o livro ao acaso e leu a primeira passagem que lhe caiu sob os olhos: nada de comilanças e bebedeiras, nada de devassidão, nada de brigas e invejas; revesti-vos do Senhor Jesus Cristo, e não cuideis da carne para satisfazer seus desejos. Não quis ler mais, escreve, nem era preciso.", PI)
add("Pese o que a cena tem e o que lhe falta. Falta-lhe um argumento novo: Agostinho sabia havia anos tudo o que precisava saber. Ela tem uma hora, um lugar, um gesto concreto e uma frase que acaba com o <i>amanhã</i>. E a última instrução que ele leu, não cuideis da carne, isto é, não lhe prepare o caminho, já é o terceiro passo do modo, o de queimar as pontes. Mas Agostinho não conta essa cena como uma decisão sua. Para ele, a vontade dividida não se cura sozinha, porque não consegue querer por inteiro por si mesma (VIII, 9); ele leu a voz de criança como uma ordem de Deus, e o que veio depois como graça. No livro décimo, já bispo, escreveu a Deus: dá o que ordenas, e ordena o que quiseres (X, 29). Foi essa frase que indignou Pelágio, para quem a vontade bem conduzida bastava. O que se faz aqui com a cena é uma leitura secular, que Agostinho julgaria insuficiente: ela toma da cena a hora, o lugar, a última instrução e o fim do <i>amanhã</i>, e deixa o resto com ele. As razões você já tem; falta fixar o dia e o terreno, e é isso o que a linha e as pontes fazem.", PI)
add("Pode ser que ainda esta noite, ao nomear, lhe venha uma proposta mais razoável do que o <i>não ainda</i>. <i>E se eu só diminuir? Só nos dias bons, só um pouco, só de vez em quando.</i> Ela merece resposta, porque parece sensata, e muitas vezes é a última forma que o adiamento assume.", PI)
add("Construir e romper são operações diferentes. Um gesto novo se forma aos poucos, por repetição; um hábito que se corta é deixado de uma vez. Para muitos, abster-se por completo custa menos do que se moderar.", PI)
add("Você dirá, e com fundamento, que isso contraria o melhor dos antigos. Aristóteles ensinou que a virtude está no meio-termo, entre o excesso e a falta. O homem temperado bebe, distrai-se, come um doce, e faz isso na medida certa. À luz disso, o corte absoluto parece uma forma de excesso: medo do prazer vestido de virtude.", PI)
add("A objeção é séria, e o próprio Aristóteles responde a ela. No mesmo capítulo em que define o meio-termo (<i>Ética a Nicômaco</i> II, 6), ele avisa que nem toda ação e nem toda paixão o admitem. Há coisas cujo nome já traz a falta dentro: a inveja, a impudência, o adultério, o roubo. Em relação a elas, nunca se acerta; sempre se erra. Não há adultério bem feito, com a mulher devida, no momento devido, do modo devido. O meio-termo é regra para o que tem medida, e só para isso.", PI)
add("E há uma segunda resposta, mais fina. O meio-termo de Aristóteles é relativo a nós, e não às coisas: o que é muito para um é pouco para outro. Para quem já desceu os três degraus de Agostinho, a medida justa daquele ato particular pode ser zero. A temperança continua sendo meio-termo na vida inteira, no comer, no beber, no descansar, enquanto aquela coisa, só aquela, fica de fora. Três capítulos adiante (II, 9), Aristóteles ainda dá um conselho que parece escrito para o primeiro mês de um corte: quem quer chegar ao meio deve primeiro se afastar para o extremo contrário àquele a que tende, como se faz com a vara torta que se quer endireitar.", PI)
add("Samuel Johnson, o grande homem de letras do século XVIII inglês, de corpo enorme e apetites à altura, sabia disso por experiência. Passou longos períodos sem tocar em vinho e, quando insistiam para que bebesse só um pouco, respondia que não sabia beber pouco, e por isso não bebia: a abstinência lhe era fácil, a moderação seria difícil (paráfrase do que registram Boswell e Hannah More). Há quem saiba se moderar diante de uma coisa e só saiba se abster diante de outra.", PI)
add("É isso que você decide esta noite, diante do hábito que vai nomear. Lembre as vezes em que tentou moderar essa coisa, e como terminou cada uma; a última linha da lista das provas, em <i>Da outra chance</i>, a que diz o que falhou na maneira de tentar, pode ajudar você a lembrar. Se a moderação lhe serviu e ainda serve, você não precisa de corte, e fecha este livro até o dia em que precisar. Se a memória lhe mostra a mesma tentativa várias vezes, com o mesmo fim, então diante dessa coisa você é da espécie de Johnson, e a linha é para você.", PI)
add("Ao nomear, pode acontecer outra coisa: você descobrir que o hábito tem a forma de uma frase. <i>Eu nunca termino nada. Gente como a gente não chega lá.</i> Alguém a disse uma vez, em uma cozinha qualquer, e já a esqueceu; você continua a repeti-la como se ela descrevesse um fato. Uma frase herdada também se corta. Nomeie-a por escrito, como nomearia um gesto, e responda a ela toda noite com o que a folha de marcas mostra. <font color='#6b6b6b'>(Lição II)</font>", PI)

sec("Do modo")
add("Os passos são sete. Os cinco primeiros são feitos entre esta noite e o fim de amanhã; os dois últimos começam amanhã e não terminam. Eles ficam aqui em ordem, secos, para que você os encontre quando tiver dúvida. Em seguida, vou lhe contar o dia em que você vai fazê-los.", PI)
corte = [
 ("Nomeie", "o que você vai deixar, com verbo e objeto e sem adjetivo: em vez de <i>sou um desastre</i>, <i>faço X</i>. Depois, a ocasião: lugar, hora, estado, companhia. E o pagamento: alívio, excitação, fuga, companhia. Sem ocasião e pagamento, você não sabe onde pôr o corte."),
 ("Trace a linha", "à mão, em uma frase absoluta, curta, no presente, com a data: <i>A partir de hoje, não ____.</i> Sem “vou tentar”, sem “vou diminuir”, sem “quase nunca”. Escreva-a em uma hora fria, longe da ocasião. Assine. Copie-a para o alto da página Dias limpos, a página 35 do caderno."),
 ("Queime as pontes", "no mesmo dia, enquanto a decisão está quente. Liste tudo o que facilita o hábito e remova: jogue fora, afaste, tranque, entregue a chave a outra pessoa. Cada passo a mais entre o impulso e o ato é uma oportunidade a mais para a onda passar."),
 ("Mude o terreno", "onde o hábito morava. Se ele vivia em um lugar, mude o lugar; se vivia em uma hora, ocupe a hora; se vivia em uma sequência, quebre a sequência. O hábito depende do cenário: quando o cenário muda, ele perde o apoio, e os primeiros dias depois de uma mudança são os mais favoráveis para cortar."),
 ("Ponha algo no lugar:", "um gesto definido para o instante em que a ocasião chegar, escrito antes: <i>quando acontecer ____, eu faço ____</i>. As mãos não podem ficar vazias, senão voltam ao velho. Para o instante, basta um gesto; para a vida, é preciso uma paixão, e é dela que trata a seção seguinte."),
 ("Atravesse a onda", "com a nona linha, todas as vezes que a vontade vier: <i>É a onda. Ela sobe, e passa. O que faço com as mãos agora?</i> Ela sobe e passa; sua tarefa é não obedecer enquanto ela passa."),
 ("Conte os dias", "na página Dias limpos: em cada noite em que você não cedeu, uma casa. Se você cair, <i>caí; a linha continua</i>, e nunca dois dias seguidos."),
]
for i,(a,b) in enumerate(corte,1):
    add(f"{rom(i)}. &nbsp;<b>{a}</b> {b}", LAW)

add("<b>Esta noite, o primeiro passo.</b> Em uma página nova do caderno, escreva o comportamento. O livro não sabe o que você vai escrever; sabe que, se lhe saiu um adjetivo, você ainda não nomeou. Embaixo, três linhas: onde e quando ele aparece; em que estado e com quem; o que ele lhe paga. O pagamento é o que mais custa escrever. Se não o encontrar, pense na última vez: o que havia no minuto antes, e o que ficou no minuto depois. Depois feche o caderno sem traçar a linha, e vá dormir.", PI)
add("<b>Amanhã de manhã, a linha.</b> Depois dos minutos de sempre (o caderno aberto antes de tudo, o estribilho, a linha da manhã, o breviário) e longe da hora em que o hábito costuma vir, escreva embaixo do nome: <i>A partir de hoje, não ____</i>, e a data. No presente, curta, absoluta. Se a mão quiser escrever <i>vou tentar</i>, ou <i>quase nunca</i>, é o <i>não ainda</i> pedindo um lugar na frase; risque e recomece. Assine. Depois abra a página <i>Dias limpos</i>, a página 35 do caderno, e copie a linha para o alto dela, com a data e a assinatura. Por que de manhã, e longe da ocasião, quem conta é Homero.", PI)
add("No canto XII da <i>Odisseia</i>, antes que Ulisses deixe a ilha de Circe, ela lhe diz o que ele vai encontrar: duas sereias sentadas em um prado à beira-mar, cantando, e em volta delas um monte de ossos de homens. Quem ouve o canto não volta para casa. Circe lhe dá duas instruções. Para os companheiros, cera nos ouvidos, para que não ouçam nada. Para ele, se quiser ouvir, que o amarrem de pé ao mastro, com as cordas presas à base; e, se ele pedir que o soltem, que apertem os nós.", PI)
add("Ulisses faz exatamente isso. Tapa com cera os ouvidos dos remadores, um por um; eles o amarram ao mastro. Quando o navio passa ao alcance da voz, as sereias cantam, e o que oferecem não é um prazer grosseiro: dizem que sabem tudo o que se passou em Troia, e tudo o que acontece sobre a terra fecunda. O que tenta Ulisses é o conhecimento, uma coisa nobre, posta no lugar errado. Ele faz sinal com as sobrancelhas para que o soltem; Perimedes e Euríloco se levantam e o amarram com mais cordas. O navio passa. Só quando já não se ouve nada os companheiros tiram a cera e o desamarram.", PI)
add("A sua manhã copia três coisas dessa cena. A primeira: a decisão foi tomada longe das sereias, em terra firme, com tempo. Ao alcance do canto não se decide nada de importante, e por isso a linha é escrita de manhã, de cabeça fria, e não na hora em que o hábito chama. A segunda: Ulisses deu ordem para que desobedecessem às suas próprias ordens futuras. Sabia que, na hora, pediria com toda a convicção, e tirou de antemão a autoridade desse pedido. A linha que você assinou é essa ordem, e a máscara trabalha do mesmo modo. Quem decidiu em terra firme foi você, com o rosto dele; quem pede no meio do canto é a voz antiga, que já não tem autoridade sobre a linha. A terceira: há duas maneiras de passar, a cera e o mastro. A cera é não se expor; o mastro é se expor amarrado. A maior parte dos cortes pede cera; o mastro fica para a ocasião que não se pode evitar, e mesmo então as cordas são postas antes.", PI)
add("Em 1979, o filósofo norueguês Jon Elster deu a um livro o título <i>Ulisses e as sereias</i> e usou a cena para pensar uma coisa que a teoria da escolha racional tinha dificuldade em admitir: um homem pode ser racional justamente por saber que não o será. Ulisses é fraco e sabe disso, e usa a força do momento lúcido para amarrar o momento fraco. Elster chamou isso de pré-compromisso: escolher agora de modo a restringir as escolhas que você terá depois. Chamou-o de racionalidade imperfeita, a de quem não confia em si mesmo. A linha que você assinou de manhã é um pré-compromisso desse tipo, e as pontes que vai queimar hoje são outro.", PI)
add("<b>No resto do dia, as pontes.</b> O que protege a linha é o terreno em volta dela, e o terreno se arruma hoje. Thomas Schelling, economista americano que tinha estudado a dissuasão entre nações, voltou-se, nos mesmos anos de Elster, para a menor guerra que existe, a que acontece dentro de uma pessoa. Ele a descreveu como uma disputa entre dois eus que se revezam no comando: o que de manhã decide não fazer e o que à noite quer fazer. O eu da manhã não pode vencer o da noite em uma discussão, porque não estará presente quando ela acontecer. Só pode lhe deixar o terreno arrumado: o que falta em casa, a promessa feita a outra pessoa, a chave entregue, o caminho mais longo. As táticas que Schelling reuniu são quase todas desse tipo. São modestas, e gastam o esforço uma vez, de antemão, para não ter de pedi-lo todas as noites.", PI)
add("Victor Hugo usou uma delas para terminar um livro. No verão de 1830, ele devia ao editor um romance que adiava havia muito tempo, e o editor lhe tinha dado um prazo final. Segundo conta Adèle, a mulher dele, no livro que escreveu sobre a vida do marido, Hugo comprou um frasco de tinta e um grosso agasalho de lã cinzenta que o cobria da cabeça aos pés. Trancou à chave a roupa de sair, para não ter a tentação de pôr os pés na rua, e entrou no romance como em uma prisão. Terminou <i>Notre-Dame de Paris</i> em janeiro de 1831, e o frasco de tinta, conta ela, acabou ao mesmo tempo. Pode ser que o afeto de quem contou tenha arredondado a anedota; o gesto pode ser imitado.", PI)
add("Ainda hoje, faça a lista das pontes: cada objeto, caminho, hora e companhia que deixam o hábito ao alcance da sua mão. Pergunte qual é, no seu caso, a roupa de sair de Hugo. Ao lado de cada ponte, escreva o que vai fazer com ela, e risque-a quando estiver feito. Se alguma não puder ser removida hoje, afaste-a e escreva o dia em que vai removê-la. No mesmo dia, mude o terreno: se o hábito morava em um lugar, não se sente lá esta noite; se morava em uma hora, a hora já tem dono; se morava em uma sequência (um jantar, um caminho, um cansaço), quebre-a em um ponto à sua escolha.", PI)
add("<b>Antes da primeira ocasião, o gesto.</b> Escreva no caderno, embaixo das pontes: <i>quando acontecer ____, eu faço ____</i>. Um gesto curto, feito com as mãos, que possa ser feito em qualquer lugar onde a ocasião pegar você: levantar e mudar de sala, sair para andar, abrir a obra, pôr o corpo em outra tarefa. Para o instante, basta isso.", PI)
add("Mas você objeta, e é a objeção mais comum a esta altura: tudo o que se proíbe cresce. Quanto mais digo a mim mesmo que não, mais penso naquilo, e a linha absoluta vira um ídolo em volta do qual o pensamento gira o dia inteiro.", PI)
add("A objeção tem a seu favor um dos experimentos mais conhecidos da psicologia. Dostoiévski, em um livro de viagem de 1863, desafiava o leitor a não pensar em um urso branco. Em 1987, Daniel Wegner e colegas levaram o desafio ao laboratório. Pediram a estudantes que dissessem em voz alta, durante cinco minutos, tudo o que lhes passava pela cabeça, sem pensar em um urso branco, e que tocassem uma campainha sempre que pensassem nele. Eles a tocaram mais de uma vez por minuto. E, quando depois foram autorizados a pensar no urso, pensaram nele mais do que aqueles que tinham essa permissão desde o começo. A supressão, sozinha, produz o rebote.", PI)
add("O mesmo trabalho trouxe outra coisa, que quase ninguém repete. Um grupo recebeu, além da proibição, uma alternativa: sempre que o urso aparecesse, pensar em outra imagem, definida de antemão. Nesse grupo, o rebote foi muito menor. A objeção acerta, portanto, contra um corte feito só de <i>não</i>, e este livro nunca o propõe assim. O gesto que você acabou de escrever é a imagem definida de antemão, e o que falta, para a vida inteira, vem na seção seguinte, com Espinosa.", PI)
add("<b>A primeira onda.</b> Ela virá, talvez na hora de sempre, talvez fora dela, quando você menos esperar. Raramente diz <i>quebre a linha</i>. Diz <i>só hoje</i>, ou <i>só para ver como é</i>, ou <i>já decidi, posso ficar perto sem ceder</i>. A nona linha do Livro I, que até hoje você guardou sem usar, passa a ser sua a partir deste dia, como foi dito lá: <i>É a onda. Ela sobe, e passa. O que faço com as mãos agora?</i> Dê nome a ela, não discuta com ela e faça o gesto que escreveu. Se ela vier com muita força, abra o caderno e leia a frase da anti-visão, na folha do dia zero. É para isto que ela se lê: para a onda e para as noites de passagem.", PI)
add("Sobre a terceira daquelas frases, a de quem se julga seguro perto da ocasião, Agostinho conta outra história, no livro sexto, e o protagonista é Alípio, o amigo que estava no jardim. Anos antes, em Roma, para onde tinha ido estudar direito, uns colegas que voltavam de um jantar o arrastaram à força para o anfiteatro, em um dia de combates de gladiadores, espetáculo que ele detestava. Ele resistiu e lhes disse: podeis levar o meu corpo para lá; não podeis fazer com que eu volte para lá os olhos e o espírito; estarei ausente, mesmo estando presente. Sentou-se e fechou os olhos. Durante algum tempo, cumpriu.", PI)
add("Então um homem caiu na arena, a multidão rugiu, e o grito entrou pelos ouvidos dele. Vencido pela curiosidade, e seguro de que, fosse o que fosse, saberia desprezá-lo, abriu os olhos. Viu o sangue e bebeu com ele a crueldade; não desviou o rosto, fixou-o, e se deliciou sem perceber. Saiu de lá, escreve Agostinho, já não como o homem que tinha entrado, mas como um da multidão que o levara; e voltou depois, e levava outros consigo. O erro dele, comenta Agostinho, foi ter confiado demais em si mesmo, com mais ousadia do que firmeza.", PI)
add("Repare onde ele caiu. A decisão era firme, dita em voz alta, diante de testemunhas. Ele caiu porque confiou nela em um lugar onde ela não podia valer, e porque achou que podia olhar só por um instante. A linha que você traçou de manhã não o autoriza a se sentar no anfiteatro de olhos fechados. Quando a onda lhe disser que já não há perigo, levante-se e saia de onde está: é para isso que serve o gesto.", PI)
add("A nona linha tem uma antepassada. Epicteto ensinava em Nicópolis a rapazes que tinham atravessado o mar para aprender filosofia e continuavam cedendo como todo mundo. No décimo oitavo discurso do segundo livro dos <i>Discursos</i>, ele lhes diz o que fazer na hora. Quando a impressão pegar você, não se deixe arrastar pela vivacidade dela. Diga a ela: <i>espere um pouco por mim, impressão; deixe-me ver quem você é e do que se trata; deixe-me pôr você à prova</i>. E não a deixe ir adiante, desenhando a cena seguinte, e a seguinte, porque, se você deixar, ela o leva aonde quer. Traga para o lugar dela outra impressão, bela e nobre, e expulse com ela a sórdida. Note a ordem: um intervalo, um exame, uma substituição. É a nona linha, e é o quinto passo.", PI)
add("<b>À noite, a primeira casa.</b> Nos minutos da noite, depois da marca da microação da vez, abra <i>Dias limpos</i>. Se você não cedeu, preencha a primeira casa, a do número um. É um gesto de segundos, e é ele que, somado noite após noite, faz a contagem. Se você cedeu logo no primeiro dia, essa noite não ganha casa, e você lê <i>Da queda</i> esta noite mesmo, antes de dormir. De onde vem a contagem, e o que fazer quando ela cresce, eu conto em <i>Da contagem</i>.", PI)

sec("Da paixão contrária")
add("<i>“Um afeto não pode ser refreado nem suprimido senão por um afeto contrário e mais forte.”</i>", ParagraphStyle('sp1', parent=PC, fontSize=12, spaceAfter=2))
add("Espinosa, <i>Ética</i>, IV, proposição 7", ParagraphStyle('sp2', parent=EPA, spaceAfter=14))
add("Depois de alguns dias, às vezes já na primeira semana, você percebe uma coisa que os passos não resolvem. A hora em que o hábito morava ficou vazia. O gesto que você escreveu cobre o instante da onda, e o instante passa; mas a hora inteira fica, e as mãos não sabem o que fazer com ela. Aparece um tédio que você não sabe a quem atribuir, ou uma inquietação sem objeto. Cortar deixa esse vazio: horas, energia, um ritual, uma sensação que o hábito fornecia. O lugar não fica desocupado por muito tempo. Se nada o ocupar, o velho hábito volta a ocupá-lo.", PI)
add("A vontade sozinha raramente vence um desejo antigo. Baruch de Espinosa, filósofo de Amsterdã do século XVII, escreveu a <i>Ética</i> à maneira de um livro de geometria, com definições e proposições, e chamava de afeto aquilo que aumenta ou diminui a nossa força de agir: o desejo, a alegria, a tristeza e os que nascem deles. Na frase que abre esta seção, ele diz que um afeto só cede a outro, contrário e mais forte. Para Espinosa, uma ordem da razão, sozinha, não desloca um desejo; só outro desejo o desloca. Para o seu corte, isso quer dizer que a linha e as pontes tiram o hábito do caminho, mas que ainda falta querer outra coisa com força. Thomas Chalmers, pregador escocês, chamou isso de <i>o poder expulsivo de uma nova afeição</i>: um amor se expulsa com outro amor, e mal se expulsa com argumentos. Quem corta precisa, portanto, de outra afeição, maior, que ocupe as horas e o lugar da antiga.", PI)
add("Espinosa diz mais, algumas proposições adiante, e o que ele diz é desconfortável para quem confia nos bons argumentos. O conhecimento verdadeiro do bem e do mal, escreve, não pode refrear afeto nenhum enquanto é apenas verdadeiro; só o refreia na medida em que ele mesmo é sentido como afeto (<i>Ética</i> IV, proposição 14, paráfrase). Saber que o hábito lhe faz mal não pesa nada na balança, enquanto for só saber. Começa a pesar quando vira desejo, quando você quer outra coisa com a força com que queria aquela. Pouco depois, Espinosa cita o verso que Ovídio põe na boca de Medeia: vejo o melhor e o aprovo, e sigo o pior. Nas <i>Metamorfoses</i>, Medeia o diz quando se apaixona por Jasão contra o próprio juízo, e Espinosa a cita como exemplo do que acabou de demonstrar: ela sabia, e o saber não pesou. É o seu caso quando você diz que sabe que o hábito lhe faz mal.", PI)
add("Chalmers pregou o sermão que deu nome à ideia no começo do século XIX, sobre um versículo da primeira carta de João: não ameis o mundo. O problema era o mesmo que o seu nesta semana: como se tira de um homem um amor que lhe faz mal? O caminho habitual era a demonstração. Mostra-se ao homem que aquilo que ele ama é vão, passageiro, indigno, e espera-se que, convencido, ele deixe de amar. Chalmers observou que isso quase nunca dá certo, e disse por quê: o coração humano não suporta ficar vazio. Ele precisa se prender a alguma coisa. Se você lhe arranca o objeto sem lhe dar outro, ele fica em carne viva e volta ao antigo, que é o que conhece. E Chalmers notou que os próprios vícios se expulsam uns aos outros, como no rapaz dado aos prazeres que, já homem feito, se torna avarento. Alguma afeição vai ocupar o lugar da antiga; convém que seja você a escolhê-la.", PI)
add("Houve um homem que viveu isso sem ter lido nenhum dos dois: o mesmo Inácio de quem, no dia zero, você tomou o exame do leito de morte. Ele contou a história já velho, ditando suas memórias a um companheiro. Em maio de 1521, em Pamplona, Íñigo de Loyola, fidalgo basco de trinta anos, vaidoso, dado a armas e a damas, foi atingido por uma bala de canhão que lhe quebrou uma perna e feriu a outra. Levaram-no para a casa da família, em Loyola. Os ossos se soldaram mal, e ele deixou que os quebrassem de novo, sem dizer palavra. Depois, como um osso tinha ficado saliente abaixo do joelho e o enfeava, mandou que o serrassem, por vaidade. A convalescença foi longa.", PI)
add("Para passar o tempo, pediu romances de cavalaria, que eram sua leitura de sempre. Não havia nenhum em casa. Deram-lhe o que havia: uma vida de Cristo e um livro de vidas de santos. Ele os leu por falta de coisa melhor, e se viu alternando dois devaneios. Em um, imaginava as façanhas que faria para servir uma dama de condição muito acima da dele, e ficava horas nisso. No outro, perguntava-se: <i>e se eu fizesse o que fez São Francisco, o que fez São Domingos?</i>", PI)
add("E ele percebeu uma diferença. Os pensamentos da dama lhe davam muito gosto enquanto duravam, mas, quando os largava, ficava seco e descontente. Os outros, de ir descalço a Jerusalém, de comer só ervas, não só o consolavam enquanto pensava neles, como também o deixavam contente e alegre depois. Ninguém pregou para ele contra os romances. Uma paixão maior foi ocupando o lugar da menor, à força de comparação, e a menor saiu.", PI)
add("Duas coisas dessa cena servem a você nesta semana. A primeira: Íñigo escolheu a paixão nova pelo que ela deixava depois, e não por raciocínio. É um bom teste para a sua: escolha aquilo que, uma hora depois, deixa você contente por ter feito, e ponha de lado o que só agrada enquanto dura. Anos depois, Inácio fez dessa observação o começo das regras do discernimento dos espíritos. Essas regras leem a consolação e a desolação à luz do fim para o qual, segundo ele, o homem foi criado, louvar e servir a Deus, e não se reduzem ao humor de uma hora; o livro guarda delas só esse teste. A segunda: a troca começou porque faltaram os romances. Foi a ponte queimada, por acaso, que abriu o lugar; o resto dependeu do que se pôs dentro dele.", PI)
add("Escolha a paixão, então, em uma destas noites, com a página do nome do hábito à sua frente, porque é lá que estão as horas e o pagamento que ela precisa cobrir. Escreva-a no caderno, embaixo da linha: o que é, a hora em que entra e a primeira meta, com um número. Os passos para escolhê-la e mantê-la são estes:", PI)
paix = [
 ("Meça o vazio.", "Quanto tempo o hábito ocupava, em que horas, e o que ele lhe dava: alívio, excitação, fuga, companhia. É esse lugar que a nova paixão precisa preencher."),
 ("Escolha a paixão contrária.", "Algo que exija o corpo ou a obra, que tenha progresso visível e que seja tão difícil quanto o velho hábito era fácil: correr, lutar, um instrumento, uma língua, o trabalho no seu domínio. Que ela responda à mesma necessidade: se o hábito era alívio, algo que esgote; se era excitação, algo que desafie."),
 ("Ocupe as mesmas horas.", "A paixão nova entra exatamente no horário e no lugar onde morava a antiga. A hora em que a vontade costumava vir passa a pertencer a outra coisa."),
 ("Dê a ela uma escada.", "Metas crescentes e anotadas: mais distância, mais carga, mais páginas, mais horas. Sem metas anotadas, o interesse se dispersa."),
 ("Deixe que ela seja desmedida no começo.", "Nos primeiros meses, deixe que ela tome mais espaço do que pareceria razoável. O excesso é deliberado, e é a vara torta de Aristóteles: é ele que expulsa o velho."),
 ("Vigie a balança.", "Se a nova paixão passar a servir de fuga em vez de construção, ou começar a ferir o sono, o corpo ou as pessoas, ela passou a cumprir a função do velho hábito. A oitava lei vale também aqui."),
]
for i,(a,b) in enumerate(paix,1):
    add(f"{rom(i)}. &nbsp;<b>{a}</b> {b}", LAW)
add("Se, depois de um mês, você se pegar fugindo para a paixão nova como fugia para a velha, ou perdendo sono por causa dela, releia o sexto ponto antes de dormir.", PI)

sec("Da queda")
add("Pode ser que você nunca caia, ou que caia na segunda semana, ou depois de dois meses, em uma noite de cansaço em que a ocasião pegou você longe do gesto. O livro não sabe. Ele conta o dia a você para que, se esse dia vier, você já saiba o que fazer nele.", PI)
add("Logo depois de ceder vem uma frase, quase sempre a mesma: <i>já que caí, o dia está perdido</i>. Ou <i>amanhã recomeço do zero</i>, ou <i>afinal não sou capaz</i>. É assim que uma queda vira recaída. Responda a ela com a frase deste livro, e diga-a por dentro, inteira: <i>caí; a linha continua</i>. Depois faça bem a ocasião seguinte, ainda hoje, se ela vier. À noite, faça a linha da queda, como faz para a da vez: onde foi, e o que vai fazer de diferente. Nomeie a ocasião que trouxe a queda e, se ela abriu uma ponte que você não tinha visto, acrescente-a à lista e afaste-a também. Em <i>Dias limpos</i>, essa noite não ganha casa; a linha no alto da página não se apaga nem se reescreve e, como diz a quarta lei, nada volta ao começo.", PI)
add("Amanhã é o dia que a lei protege: nunca dois dias seguidos. Nos exercícios, o dia seguinte a uma cruz admite o piso; o corte não tem piso, e não se reduz, nem doente, nem em viagem. Releia a linha de manhã, releia a lista das pontes, preveja onde a ocasião de ontem pode voltar e ponha o gesto à frente dela antes que ela chegue.", PI)
add("Alan Marlatt, psicólogo americano que passou a vida estudando recaídas, deu nome a esse <i>já que caí</i>: efeito de violação da abstinência. Quem explicava a queda pelo caráter, de modo total e permanente (<i>sou fraco, sempre fui, nunca vou conseguir</i>), e sentia o choque entre o que acabara de fazer e quem dizia ser, tendia a deixar o deslize virar uma recaída inteira: se a linha já estava quebrada, que importava o resto? Quem a explicava pela ocasião (<i>estava cansado, estava sozinho, estava ali</i>) voltava à linha mais vezes. Dessa distinção entre deslize e recaída nasceu o que se chamou de prevenção da recaída (nota clínica, paráfrase).", PI)
add("Por isso a frase deste livro não pede que você se sinta bem com a queda, nem deixa que você se condene por ela. Pede uma coisa exata: anotar a ocasião. Uma ocasião nomeada pode ser evitada ou preparada na próxima vez; um juízo sobre o próprio caráter não indica nada que se possa fazer.", PI)
add("Epicteto, no mesmo discurso de que lhe falei na primeira onda, viu o outro desenho, o da queda que se repete com promessa. Se você perder uma vez, diz ele aos alunos, e disser que vai vencer na próxima, e perder de novo, e de novo, vai acabar em um estado tão fraco que nem vai perceber que erra, e vai começar a arranjar razões para o que faz. É o <i>não ainda</i> de Agostinho visto de fora, por um mestre que o via se repetir nos alunos. E é por isso que a lei é branda com a primeira queda e severa com a segunda.", PI)
add("Tolstói, ainda rapaz, deixou esse desenho por escrito. Os diários que começou em 1847, aos dezoito anos, num hospital de Kazan, abrem com regras de vida, e as páginas dos anos seguintes voltam a elas sem parar: o jogo, a ociosidade, a resolução de recomeçar no dia seguinte, a queda, a resolução de novo. Ele chegava a anotar de manhã o que faria naquele dia e, à noite, o que deixara de fazer. O jogo de cartas lhe custou caro. Em 1854, para pagar dívidas, vendeu a um vizinho a casa principal de Iásnaia Poliana, que foi desmontada e levada embora; ele ficou com as alas que sobraram. O homem que escreveria <i>Guerra e paz</i> naquela mesma terra passou anos fazendo listas novas. Lidos hoje, os diários mostram o que Epicteto via nos alunos: cada promessa feita sem mudar a ocasião abria caminho à queda seguinte.", PI)
add("E não espere que a linha cale tudo. Mais de dez anos depois do jardim, já bispo, Agostinho escreveu no livro décimo das <i>Confissões</i> que as imagens dos velhos hábitos continuavam vivas na sua memória: de dia vinham fracas, e no sono vinham com tanta força que quase arrancavam o consentimento. Ele não concluiu daí que o jardim tinha sido inútil. Concluiu que a memória guarda o que o corpo já deixou, e que guardar a linha é um trabalho que não acaba no dia em que ela é traçada. E pediu, nas mesmas páginas, que a mão de Deus o curasse também disso, porque não esperava conseguir isso sozinho.", PI)

sec("Da contagem")
add("Nas noites seguintes, a contagem se faz quase sem palavras: a marca da microação da vez e, depois, uma casa em <i>Dias limpos</i>. Um corte de cada vez.", PI)
add("A contagem vem do mesmo discurso de Epicteto, e ele o começa com uma observação que parece banal: todo hábito e toda capacidade se conservam e crescem pelos atos que lhes correspondem. Anda-se melhor andando, corre-se melhor correndo; e quem passa trinta dias sem ler verá o que acontece. A consequência que ele tira é o que torna o discurso precioso: o mesmo vale para o que você quer perder. Quando você cede à ira, diz ele, não sofreu apenas aquele mal uma vez; alimentou o hábito, pôs lenha na fogueira. Cada vez que você cede, isso se acumula, e a abstenção também. Fique quieto, no começo, e conte os dias em que não se irritou: <i>eu me irritava todos os dias; agora, um sim, outro não; depois, a cada três; depois, a cada quatro</i>. E, se chegar aos trinta dias, ofereça um sacrifício aos deuses, porque o hábito primeiro se enfraquece, depois se apaga de todo. A página <i>Dias limpos</i> e o marco dos trinta dias são essa página de Epicteto, quase sem tirar nem pôr.", PI)
add("Os trinta dias e os noventa dias servem de marcos para olhar para trás, e não de prazo para afrouxar. Na noite em que você preencher a trigésima casa, demore-se mais um minuto. Releia a linha no alto da página, a lista das pontes, as linhas de queda do corte, se houver, e a meta da paixão contrária. Observe o que mudou nas horas que o hábito ocupava, e no que as ocupa agora. Na nonagésima, o mesmo. Depois delas, a linha continua, e a contagem também.", PI)
add("Epicteto acrescenta um aviso para esses meses. As doenças do espírito, diz ele, deixam marcas, como a febre deixa no corpo depois de ceder: quem não se curou de todo não fica como antes, e a mesma ocasião reabre a ferida mais depressa do que da primeira vez. É provável que, perto de um desses marcos, uma voz lhe diga que você já pode voltar a ficar perto da coisa, só para provar que ela já não o pega. A contagem que cresce não diz isso. Diz que a cicatriz está fechando, e uma cicatriz recente se rasga com pouco. As pontes queimadas não se reabrem.", PI)
add("Há hábitos que já não obedecem à decisão, por mais firme que ela seja. Se a linha cai uma vez e outra, se você caiu dois dias seguidos apesar das pontes, do gesto e da paixão contrária, ou se o hábito já está lhe custando a saúde, o dinheiro ou as pessoas, procure ajuda profissional. Procurá-la faz parte do corte.", NOTE)
add("Daqui em diante, você vai andar com a microação da vez em uma mão e um corte na outra. Quando as duas coisas são feitas a sério, aparece um perigo de outra ordem, no ponto em que o caminho parece mais seguro. Um método levado a sério assim, com leis, marcas e linhas absolutas, pode se voltar contra quem o usa: endurecê-lo, deixá-lo surdo para o que o cansaço lhe diz, fazer de cada falha uma acusação. Contra isso, as leis não bastam. É preciso juízo, e o juízo tem um livro próprio, que você vai ler no meio das estações, ou antes, se o método começar a apertar.", PI)


add("Olhe agora para o caderno. Se a linha não está no presente, com data e assinatura, no alto de <i>Dias limpos</i>, volte ao segundo passo de <i>Do modo</i>; se nada foi riscado na lista das pontes no próprio dia da linha, risque hoje, antes de dormir. Se a paixão contrária não está escrita, com a hora e uma meta com número, escreva-a esta noite. E se você caiu dois dias seguidos, ou se a linha cai uma vez e outra, leia a nota de <i>Da contagem</i>, que manda procurar ajuda profissional.", PI)
# O fecho vai junto do parágrafo anterior, para não ficar sozinho no alto de uma página.
st[-2:] = [KeepTogether(st[-2:])]
# ===================== DO PÊNDULO =====================
estribilho_pagina()
st.append(PageBreak()); sp(30)
add("Em qualquer ponto das estações", LIV)
QUANDO["Do pêndulo"] = "quando o cansaço bater"
add("Do pêndulo", LT); sumario(st[-1], 0, "Do pêndulo")
SEC_NO_SUMARIO = True


sec("Do pêndulo")
add("Leia isto em uma noite, fora das horas da obra, e leia o capítulo inteiro: na noite do dia em que bateu em você aquilo de que ele trata, ou antes, para reconhecê-lo quando vier, porque vem para quase todos os que fazem um caminho como este. Se hoje bateu e você se levantou da mesa antes da hora, essa hora foi do pêndulo, e já passou. A marca desta noite se decide como sempre, sobre a da vez e a ocasião que mais pesou, e o resto do capítulo serve para que, da próxima vez, você fique.", PI); add("Esta noite, você vai decorar os seis passos de <i>Do instante</i>, e sair daqui sabendo esses passos sem abrir o livro; se o pêndulo bateu hoje, você sai também com a linha da folha de captura decidida. Você vai voltar a este capítulo quando o pêndulo bater no meio da obra, e então vai dizer de cor os seis passos, começando pela linha II; o capítulo fica para a noite. Quando o pêndulo voltar e você não souber se é ele ou o cansaço que não passa, releia o fim de <i>Do que volta</i> e faça a prova do sono, em <i>Da resistência que fala</i>, no Livro V. E quando a pergunta deixar a obra e passar para a sua vida inteira, releia <i>Da descida</i> e os sinais de <i>Do escrúpulo</i>, no Livro V; se for a ideia de que seria melhor não estar aqui, fale hoje com alguém.", PI)
add("Vou lhe contar como acontece. Você está no meio do processo. As primeiras semanas ficaram para trás, há microações entre as que ficaram, e o dia de hoje até ia bem, talvez depressa. Você não estava em um trecho difícil. De repente, sem causa que você encontre, vem um peso no corpo, e com ele uma voz:", PI)
for v in ["Estou cansado.", "Será que tudo isso vale mesmo a pena?", "Estou muito cansado. Tenho de parar."]:
    add(v, VOICE)
sp(6)
add("Ela vem quase sempre nesta ordem: primeiro o corpo, depois a pergunta, depois a conclusão. Vem no meio da manhã ou no meio da tarde, depois de vinte minutos ou de duas horas; não tem hora. Às vezes passa em um minuto. Às vezes fica, vai embora e, quando parecia ter ido, volta mais um pouco, e persiste. É por isso que este livro a chama de pêndulo: ela oscila, e oscila sozinha, sem que você tenha feito nada para pô-la em movimento.", PI)
add("Você já conhece duas vozes parecidas, e convém separar esta delas. A da linha II, no Livro I, chega com o trecho difícil e pede para largar aquele trecho; você a reconhece pela coincidência entre a vontade de parar e a resistência da obra. O pêndulo pode bater em um trecho fácil, com a obra andando, e pergunta pelo valor do todo. A resistência que fala, no Livro V, traz argumentos e volta igual noite após noite, sem ceder ao começo nem ao repouso. O pêndulo traz um argumento só, o cansaço, e uma pergunta, e na maior parte das vezes vai embora pelo próprio movimento. Pode acontecer que um dia ele deixe de oscilar e fique parado do mesmo lado durante semanas; então já é outra coisa, e o Livro V tem as provas para ela. Este capítulo trata do caso comum, o do pêndulo que vai e volta.", PI)
add("O caso comum pede uma coisa só, e o capítulo inteiro serve para que você a entenda por dentro: você continua. A pergunta sobre se a obra vale a pena teve resposta no dia zero, por escrito, e no meio do passo ela não se reabre: você termina o passo e segue. É uma escolha, e o livro a declara: no meio da obra, entre continuar e ouvir o que o cansaço diz, ele dá prioridade a continuar. Ouvir tem hora marcada: a noite, a passagem e, quando o pêndulo deixa de oscilar, as quatro provas do Livro V. Primeiro, o que você faz; depois, o que outros entenderam deste instante.", PI)

sec("Do instante")
add("Quando o pêndulo bate, a pergunta <i>isto vale a pena?</i> parece pedir resposta imediata. Você viu em <i>Da forma</i>, no Livro I, que o exame pertence à noite e que durante o dia há o ato. Uma pergunta sobre o valor do todo é exame, e da maior espécie, e por isso fica para a noite. Os passos são seis, e nenhum é novo: são a linha II e a folha de captura postas em ordem para este caso.", PI)
pend = [
 ("Repare.", "Perceba que a voz veio, e que ela pergunta pelo todo e não pelo trecho. Não responda a ela agora, nem a favor nem contra."),
 ("Diga a linha II.", "<i>É vontade, não fato. Até o fim deste passo.</i> O cansaço que você sente é real; a conclusão que ele tira, <i>tenho de parar</i>, pertence à vontade."),
 ("Termine o passo.", "A frase, a série, o parágrafo, com a mão no lugar, como a linha pede."),
 ("Escreva a pergunta,", "se ela insistir: uma linha na folha de captura, com a hora, por exemplo <i>dez e quarenta, cansado, vale a pena?</i> Escrita, ela sai da cabeça e espera pela noite, como tudo o que vai para lá. Depois volte à obra."),
 ("Olhe outra vez", "no fim do passo. Se passou, siga. Se ainda está lá, outro passo, e outro, enquanto houver obra antes da hora de parar que você escreveu de manhã. Se continua inteira, feche em um ponto, como diz a linha II, e amanhã retome sem névoa."),
 ("À noite,", "depois da marca, decida a linha da captura como as outras: ela se faz amanhã, se marca para um dia ou se risca. Se o pêndulo voltar todos os dias e deixar de passar, a pergunta vai para as quatro provas do Livro V."),
]
for i, (a, b) in enumerate(pend, 1):
    add(f"{rom(i)}. &nbsp;<b>{a}</b> {b}", LAW)
sp(4)
add("D O &nbsp; P O R Q U Ê", LBX)
add("<b>A ideia.</b> Os monges do deserto egípcio, de quem a linha III lhe falou, conheciam esse peso e o chamavam de acédia. Evágrio Pôntico, que o descreveu com minúcia, lhe deu como remédio a <i>hypomoné</i>, a perseverança; a palavra grega quer dizer, ao pé da letra, ficar debaixo, aguentar sem sair do lugar. O pêndulo pede que você saia, e a resposta dos monges era ficar o tempo necessário para ele passar.", PI)
add("<b>O mecanismo.</b> Primeiro, a pergunta pelo valor do todo, feita no meio do cansaço, é julgada por um juiz que naquele instante só vê o cansaço; escrita e adiada para a noite, ela é julgada com as folhas à frente e de cabeça mais fria. Segundo, o passo pequeno da linha II deixa o tempo correr sem obedecer, e o pêndulo, que oscila sozinho, quase sempre volta para o outro lado nesse tempo. Nenhum estudo testou esses passos; o que fica dito é razão, somada ao que contam os autores das seções seguintes.", PI)
add("<b>Por isso.</b> <i>Faço isto porque o cansaço do instante não sabe responder pelo todo, e porque o pêndulo, se o deixo oscilar sem obedecer a ele, volta sozinho para o outro lado.</i>", PI)

sec("Do demônio do meio-dia")
add("Evágrio vem primeiro, porque descreveu este instante de perto. Nasceu no Ponto, à beira do mar Negro, por volta de 345, e foi diácono e pregador conhecido em Constantinopla. Depois de uma crise, deixou a cidade e foi viver como monge no deserto do Egito, onde passou os últimos dezesseis anos da vida; morreu em 399. Escreveu para outros monges um manual curto, o <i>Prático</i>, em capítulos numerados, sobre os pensamentos que os assaltavam no trabalho de cada dia. A linha III lhe contou o retrato que ele faz da acédia: o sol que parece não andar, o dia de cinquenta horas, o monge à janela. Aqui nos interessa o resto do que ele ensina.", PI)
add("A palavra vem do grego <i>akédia</i>, e quer dizer falta de cuidado: o estado de quem deixou de se importar. Evágrio a situa entre a quarta e a oitava hora, contadas desde o nascer do sol, isto é, no meio do dia, quando o fervor da manhã já passou e o fim ainda não se vê. Para entender o que ele quer dizer, convém saber como pensava. Para Evágrio, a vida do monge era um treino, que ele chamava de vida prática, e o adversário eram os pensamentos que se apresentam ao espírito e o empurram para um ato. Cada um tem o seu alvo: a gula empurra para a comida, a ira para a palavra dura. O alvo da acédia é fazer o monge sair: da cela, do trabalho, da vida que escolheu. Essa vida, para Evágrio, é a que se volta para Deus, e a acédia é tristeza e fastio diante desse bem. O demônio faz o monge odiar o lugar, a vida que leva e o trabalho das mãos (<i>Prático</i>, 12), e a tradição que veio depois dele a chamou de tristeza do bem espiritual. E a arma dela é o tempo. Ela faz o presente parecer longuíssimo e o futuro vazio, e assim a tarefa de hoje parece não valer nada, porque não acaba e não leva a lugar nenhum. É exatamente a pergunta do pêndulo, <i>isto vale a pena?</i>, feita no meio do dia.", PI)
add("O que ele manda fazer tem três partes, e cada uma tem a sua razão. A primeira é não sair da cela na hora da tentação (<i>Prático</i>, 28, paráfrase). A acédia pede uma decisão grande, ir embora, e é justamente essa que se deve recusar a ela, porque, tomada naquela hora, seria tomada por ela. A segunda é dividir a alma em duas, uma parte que consola e outra que é consolada, e semear na parte abatida boas esperanças (<i>Prático</i>, 27, paráfrase). Ou seja, não se discute com o pensamento nos termos dele; fala-se consigo mesmo com exatidão, sem negar o cansaço e sem dar razão a ele. O livro toma de Evágrio só isto, uma parte que fala e outra que ouve, e deixa a consolação para os monges. A terceira é a perseverança de que falei acima: ficar debaixo do peso enquanto ele dura.", PI)
add("E Evágrio acrescenta uma observação. No fim do capítulo em que descreve o demônio do meio-dia, escreve que nenhum outro pensamento vem logo atrás dele, e que, depois da luta, ficam na alma um estado de paz e uma alegria indizível (<i>Prático</i>, 12, paráfrase). A acédia atravessada sem obediência, portanto, ensina alguma coisa ao monge: que o peso passou sem que ele precisasse sair, e que da próxima vez ele pode ficar de novo. Para você, os passos de <i>Do instante</i> fazem o mesmo em escala pequena. Terminar o passo é ficar na cela. A linha da folha de captura é a parte que fala à outra, e lhe diz um fato: a pergunta será ouvida à noite. E se hoje você ficou, talvez tenha percebido, uma hora depois, uma calma que não esperava; se não percebeu, repare da próxima vez.", PI)

sec("Do fastio")
add("A segunda voz é a de Sêneca, que você leu no estribilho e em <i>Do dia</i>. Provavelmente nos anos em que ainda era conselheiro de Nero, ele escreveu a um amigo mais novo, Aneu Sereno, o tratado <i>Da tranquilidade da alma</i>, que começa pela carta em que Sereno lhe pede um diagnóstico. Sereno descrevia seu estado com uma precisão que talvez você reconheça. Não estava doente, dizia, e também não estava são. Tinha boas intenções, e elas oscilavam: decidia uma vida e, dias depois, desanimava dela e desejava outra; nada o prendia por muito tempo.", PI)
add("No segundo capítulo, Sêneca dá nome ao mal. Ele o chama de desagrado de si, <i>displicentia sui</i>, e de fastio, <i>taedium</i>: o estado de um espírito que não se assenta em lugar nenhum. E descreve o que faz quem sofre disso. Viaja, muda de casa, troca uma ocupação por outra, sempre esperando que a próxima o liberte. Cita então um verso de Lucrécio, o poeta romano que pôs em verso a física de Epicuro: assim cada um foge sempre de si mesmo. E pergunta de que serve fugir, se não se escapa: cada um segue a si mesmo e pesa sobre si mesmo, o mais pesado dos companheiros.", PI)
add("Para entender o que Sêneca quer ensinar, lembre-se de que, para os estoicos, a tranquilidade era um estado preciso, o do espírito que está de acordo consigo e segue o seu caminho sem oscilar. O contrário dela era essa oscilação. E o ponto do diagnóstico é que a causa está no espírito, e não no lugar nem na tarefa. Quem troca de obra porque a obra pesa leva o peso consigo para a seguinte. O remédio que Sêneca propõe vai no sentido oposto ao da fuga: dedicar-se de modo constante a uma ocupação escolhida e útil, e alternar o trabalho com um descanso que tem a sua medida (é desse fim do tratado que vem a frase sobre o descanso que abre <i>Do descanso</i>, no Livro II).", PI)
add("Isso se aplica ao pêndulo de modo muito direto. É frequente que a pergunta <i>isto vale a pena?</i> venha acompanhada de outra, mais baixa: <i>outra coisa valeria</i>. Uma obra diferente, outro domínio, outro método. Pelo diagnóstico de Sêneca, o peso vai com você para a seguinte, e a outra coisa só parece leve porque você ainda não a carregou. Por isso, como diz a nona lei, as correções esperam as passagens. O que o pêndulo lhe disser fica escrito na folha de captura; se for verdade, há de ser verdade também na passagem.", PI)
add("Flaubert viveu as duas metades desse diagnóstico. No outono de 1849, leu aos amigos Louis Bouilhet e Maxime Du Camp, ao longo de quatro dias, a primeira versão da <i>Tentação de santo Antão</i>, que tinha por sua obra-prima. Segundo as <i>Recordações literárias</i> de Du Camp, que talvez aumente a cena, os dois lhe disseram que jogasse o manuscrito ao fogo e tomasse um assunto comum, da vida de província. Dali saiu <i>Madame Bovary</i>, escrita de 1851 a 1856. Nas cartas a Louise Colet desses anos, ele se queixa do livro com frequência: dias inteiros para uma página, frases refeitas noite adentro, saudade dos assuntos grandiosos que deixara. Bovary lhe parecia, às vezes, uma tarefa imposta, e a vontade de outra obra voltava a cada trecho difícil. E não trocou de obra. A queixa ia para as cartas, à noite, e no dia seguinte ele voltava à mesma página.", PI)
add("Há ainda uma frase de Sêneca que convém ter à mão nesses dias, e que vem das cartas a Lucílio. Na décima sexta, ele diz ao amigo que persevere e que dê força ao que já tem com estudo assíduo, até que seja boa mente o que agora é boa vontade. As duas expressões são técnicas. A boa vontade, <i>bona voluntas</i>, é querer o bem, e precisa ser defendida a cada vez, contra cada cansaço. A boa mente, <i>bona mens</i>, é o espírito já assentado, em que o bem se tornou a maneira habitual de agir. Na lição de Sêneca, só se passa de uma à outra perseverando, e a perseverança se faz justamente nos dias em que a boa vontade é posta à prova. Os dias do pêndulo são desses. Cada um que você atravessa é um dos dias de que a passagem é feita; o Interlúdio, no fim do ciclo, chama esse assentamento de <i>héxis</i>.", PI)

sec("Da obra de homem")
add("O Livro I começou com Marco Aurélio debaixo das cobertas, em uma manhã em que lhe custava se levantar. O trecho que você leu no Livro I continua, e o resto dele é o que serve ao pêndulo, porque responde exatamente à frase <i>tenho de parar</i>.", PI)
add("Marco Aurélio faz a si mesmo a objeção: mas também é preciso descansar. E responde que sim. Só que a natureza deu medida ao descanso, como deu medida ao comer e ao beber, e ele passa da medida, além do que basta; e nas ações fica aquém do que pode. Depois se acusa: você não ama a si mesmo, porque, se amasse, amaria a sua natureza e o que ela quer. E dá o exemplo dos que amam o seu ofício, que se gastam nele, esquecidos de se lavar e de comer (<i>Meditações</i>, V, 1, paráfrase).", PI)
add("A obra de homem, como você leu no Livro I, é agir segundo a razão, e o estoico acrescenta: na parte que lhe cabe, em favor do que é comum. Viver segundo essa natureza era, para eles, o próprio bem; o conforto e o prazer contavam como coisas indiferentes, nem boas nem más. Por isso, quando ele se pergunta se nasceu para ficar aquecido, está perguntando para que serve um homem. E quando diz que quem não trabalha não ama a si mesmo, usa uma ideia estoica precisa: o amor de si é o amor da própria natureza, e quem o tem quer a obra dela, como o artesão quer o seu ofício.", PI)
add("A lição para o seu instante está no que ele diz sobre o descanso. Marco Aurélio o aceita, e diz que o descanso tem uma medida dada de antemão, e que a voz da preguiça pede sempre mais do que essa medida, enquanto a ação fica sempre aquém. O seu livro já lhe deu a medida: a hora de parar, que você escreve toda manhã, e o dia de ócio, declarado na véspera, como conta <i>Do descanso</i>. Quando o pêndulo diz <i>tenho de parar</i> às dez e quarenta de uma manhã que ia bem, ele pede descanso fora da medida. A resposta de Marco Aurélio é a que você já tem escrita: você vai descansar na hora que marcou. E a pergunta <i>isto vale a pena?</i> tem, para ele, a mesma resposta que a sexta linha deu à falta de vontade. O que vale foi escrito na folha do dia zero, quando você olhou a sua vida de frente, e o cansaço de uma manhã não tem autoridade para revisá-lo.", PI)
add("O que Marco Aurélio quer que fique é a imagem de alguém que ama o que faz e por isso continua nos dias em que não tem vontade.", PI)

sec("Do segundo fôlego")
add("Vou lhe contar agora de William James, que o livro já apresentou a você nas manhãs frias da linha VI e que reaparece, no Livro V, na crise de 1870. Em dezembro de 1906, ele era o psicólogo mais conhecido dos Estados Unidos e, como presidente da associação americana de psicologia, leu uma conferência publicada no ano seguinte com o título <i>As energias dos homens</i>. Ele começa por uma experiência que todos conhecem: pegar um trabalho, de cabeça ou de músculos, sem vontade nenhuma, e ir se aquecendo nele.", PI)
add("Depois chama a atenção para a forma mais clara desse aquecimento, o segundo fôlego. Costumamos, diz ele, parar uma ocupação assim que encontramos a primeira camada séria de fadiga. Mas, se uma necessidade fora do comum nos obriga a continuar, acontece uma coisa surpreendente: a fadiga piora até certo ponto crítico, e depois, aos poucos ou de repente, passa, e ficamos mais descansados do que antes. Teríamos chegado a uma reserva de energia que a fadiga escondia e a que costumamos obedecer como se fosse o fim. E pode haver, acrescenta, um terceiro e um quarto fôlego.", PI)
add("Por trás disso está uma tese de James sobre a vida de todos os dias. A maior parte das pessoas, pensava ele, vive habitualmente muito abaixo da energia de que dispõe, por um hábito de ficar aquém de si; e a fadiga a que obedecemos muitas vezes é um ponto de parada habitual, mais do que um limite. Ele dizia também o que libera as reservas: a necessidade, as ideias que nos tomam, o esforço da vontade, a disciplina. E lembrava que há limites, e que as árvores não crescem até o céu. Pedia apenas que a primeira fadiga não fosse tomada pela última.", PI)
add("É aqui que o pêndulo costuma bater: na primeira camada. O passo da linha II é a maneira pequena de fazer o que James descreve, ver se há mais por baixo, sem prometer coisa nenhuma a você. Convém que você saiba os limites da ideia. O que James reuniu foram cartas, testemunhos e observações, e não medições; o segundo fôlego de quem corre hoje se explica por razões do corpo, e não está demonstrado que a fadiga do espírito tenha camadas assim. O que sobra basta para o seu instante: a primeira fadiga não mede o que resta.", PI)
add("Há pesquisa mais recente que vai no mesmo sentido, e eu a apresento com o grau de certeza que ela tem. Em 1998, Roy Baumeister e colegas propuseram que a força de vontade funciona como um combustível que se gasta com o uso, e chamaram o efeito de esgotamento do ego; seguiram-se centenas de estudos. Em 2016, Martin Hagger e colegas repetiram uma versão padrão do experimento em vinte e três laboratórios, com mais de dois mil participantes, e o efeito ficou perto de zero. E já em 2010 Veronika Job, Carol Dweck e Gregory Walton tinham verificado, em laboratório, que quem acreditava que a força de vontade não se esgota depressa não mostrava a queda depois de uma tarefa exigente, e quem acreditava que ela se esgotava a mostrava. Nada disso diz que o cansaço seja imaginário; o efeito de dormir pouco está medido, e o Manual operacional o cita. Diz que parte do que sentimos como vontade esgotada, depois de pouco esforço, depende do que esperamos sentir. Quando o <i>estou muito cansado</i> chega no meio de uma manhã que ia depressa, é provável que venha dessa parte.", PI)

sec("Da descida")
add("A última voz é a de Albert Camus, e é a que leva a pergunta mais longe. Ele nasceu em 1913 na Argélia, em uma família pobre, e escreveu <i>O mito de Sísifo</i> entre 1940 e 1941; o livro saiu em 1942, na França, durante a ocupação. Ele começa dizendo que julgar se a vida vale ou não vale a pena ser vivida é responder à questão fundamental da filosofia. Camus chama de absurdo o choque entre a exigência humana de sentido e um mundo que não responde a ela, e o ensaio inteiro procura saber como se vive sabendo disso.", PI)
add("Há nele uma passagem que parece escrita para o seu instante. Acontece, diz Camus, que os cenários desabam. Acordar, o bonde, quatro horas de escritório ou de fábrica, a refeição, o bonde, quatro horas de trabalho, a refeição, o sono, e segunda, terça, quarta, quinta, sexta e sábado no mesmo ritmo; segue-se esse caminho a maior parte do tempo sem dificuldade. Um dia, apenas, surge o porquê, e tudo começa nesse cansaço tingido de espanto. E acrescenta que o cansaço está no fim dos atos de uma vida maquinal, e ao mesmo tempo inaugura o movimento da consciência.", PI)
add("Em Camus, a pergunta <i>por quê?</i>, quando surge no meio da rotina, marca o começo da lucidez: a consciência acorda justamente no cansaço. O erro, para ele, está nas duas maneiras de fugir dela: abandonar, que ele examina e recusa, e saltar para uma esperança que dispense a pergunta. A resposta que ele propõe é continuar vivendo de olhos abertos, com a pergunta ao lado, e é para mostrar isso que ele conta o mito. Os deuses condenaram Sísifo a empurrar um rochedo até o alto de uma encosta, de onde ele volta a rolar, sem fim. O que interessa a Camus é a descida, quando Sísifo volta ao rochedo. Essa hora, que retorna tão certa quanto o castigo, é a hora da consciência, e nela Sísifo é superior ao seu destino. O rochedo é coisa dele. O ensaio termina dizendo que a própria luta para chegar aos cumes basta para encher um coração de homem, e que é preciso imaginar Sísifo feliz (tradução livre). Feliz, aqui, quer dizer dono do próprio esforço, sem precisar que alguém de fora lhe garanta o sentido.", PI)
add("Para você, isso ensina duas coisas. A primeira é que a pergunta do pêndulo é legítima. Ela surge no meio do caminho, no cansaço, como Camus diz, e você não precisa calá-la nem se envergonhar dela. A segunda é que ela não obriga a largar: Sísifo faz a pergunta e volta ao rochedo, e é nesse retorno, feito com consciência, que Camus põe a dignidade dele. Para Camus, essa consciência é presença constante; aqui ela tem hora: no meio do passo, a pergunta é escrita na folha de captura e espera pela noite. O seu caso é mais leve que o dele. A sua obra foi escolhida por você no dia zero, e não imposta por deuses, e não rola de volta: a linha do dia mostra, noite após noite, o que passou a existir. Mas uma coisa precisa ser dita com clareza. Se a pergunta deixar a obra e passar para a sua vida inteira, se em vez de <i>isto vale a pena?</i> vier a ideia de que seria melhor não estar aqui, isso pertence a outro lugar do livro: está entre os sinais de <i>Do escrúpulo</i>, no Livro V, o terceiro, e pede que você fale com alguém hoje.", PI)

sec("Do que volta")
add("O pêndulo volta. Talvez amanhã, talvez daqui a três semanas, quando você já tinha se esquecido dele, e com as mesmas palavras. A volta dele diz só que você ainda está no trecho do caminho em que ele oscila, e todos aqueles de quem lhe falei o viveram muitas vezes: Evágrio escrevia para monges com anos de cela, e Marco Aurélio escreveu o quinto livro quando já era imperador havia muito tempo. Nenhum deles conta que o pêndulo tenha deixado de vir de vez.", PI)
add("Mas contam que ele muda, e há razões para isso. A primeira está na lei dupla de Maine de Biran, que Ravaisson retomou e que você vai ler, ou já leu, no Interlúdio: o que se sofre repetidamente é sentido cada vez menos, e o que se faz repetidamente é feito cada vez melhor. Cada vez que você fica, o peso que veio é suportado mais uma vez, e na vez seguinte pesa um pouco menos; e o passo que você dá com ele presente fica mais fácil de dar. A segunda é a rotina. Uma obra feita na mesma hora e no mesmo lugar começa e continua quase sozinha, como a oitava linha lhe disse a propósito das pistas do contexto, e uma obra que continua sozinha dá ao pêndulo menos ocasião. A terceira é aquilo que Sêneca chamava de passar da boa vontade à boa mente, e Evágrio de paz que fica depois da luta. É por isso que, com o tempo, o pêndulo costuma bater mais fraco e mais raro. Quanto mais fraco e quanto mais raro, ninguém sabe lhe dizer; as suas folhas, relidas em uma passagem, vão dizer isso melhor do que eu. E chega um momento em que a rotina o absorve: a voz vem, a mão continua, e só à noite, ao fazer a marca, você se lembra de que ela veio.", PI)
add("Há, ainda assim, um cansaço que não oscila, e convém que você o conheça para não confundi-lo. Ele vem quase sempre no fim, e não no meio: depois de horas, quando os olhos já não seguram a linha, o mesmo erro se repete, a mesma frase é lida três vezes sem entrar. Não traz pergunta sobre o valor de coisa nenhuma; diz apenas que o corpo chegou ao fim do que tinha para hoje. E não passa no fim do passo, nem do segundo. Para esse cansaço há a hora de parar, marcada de manhã, e a obra se fecha onde está, sem culpa. Evágrio deixou aos monges um conselho do seu mestre que cabe aqui inteiro: viver como quem vai morrer amanhã, e tratar o corpo como quem vai viver muitos anos (<i>Prático</i>, 29, paráfrase). A primeira metade, explica ele, corta os pensamentos da acédia, porque a obra de hoje importa hoje; a segunda mantém o corpo na medida, para que o trabalho dure.", PI)
add("Na maior parte dos dias, você não vai precisar disto, e vai reconhecer o caso raro pela hora em que ele vem e por ele não passar. Se a dúvida ficar, as provas do Livro V separam os dois: a do começo, que você já fez ao terminar o passo, e a do sono, que se faz amanhã de manhã. Se você acordou com febre, há o piso. Se o cansaço atravessa as noites, há o dia de ócio, declarado na véspera. E se o sono não descansa, noite após noite, isso está entre os sinais de <i>Do escrúpulo</i>, e pede um médico.", PI)
add("Esta noite, se o pêndulo bateu, decida a linha que ficou na folha de captura, faça a marca e feche o caderno. Amanhã, a obra de hoje desce da obra em curso, como em todas as manhãs. Ao se sentar, diga a frase de <i>Da assentada</i>, <i>Isto, até acabar</i>, e o pêndulo, se voltar, vai encontrar você diante de uma coisa só.", PI)
add("Antes de fechar o caderno, confira o que já aconteceu. Se você ainda não sabe de cor os seis passos de <i>Do instante</i>, começando pela linha II, releia-os antes da próxima obra. Se o pêndulo bateu hoje e a pergunta não ficou escrita na folha de captura, ou não foi decidida esta noite, escreva-a agora e decida-a como as outras linhas. E se a pergunta deixou a obra e passou para a sua vida inteira, leia os sinais em <i>Do escrúpulo</i>; se for a ideia de que seria melhor não estar aqui, procure ajuda hoje.", PI); fleur()
# O fecho vai junto do parágrafo anterior, para não ficar sozinho numa página.
st[-3:] = [KeepTogether(st[-3:])]

# ===================== LIVRO V: DISCERNIMENTO =====================
livro("V", "Do discernimento")
add("<i>“A virtude é um meio-termo, determinado pela razão, tal como o determinaria o homem prudente.”</i>", ParagraphStyle('ds1', parent=PC, fontSize=12, spaceAfter=2))
add("Aristóteles, <i>Ética a Nicômaco</i>, II", ParagraphStyle('ds2', parent=EPA, spaceAfter=18))
add("O estado de foco também pede juízo, e o juízo se aprende. Este livro ensina a reconhecer quando uma regra ainda serve à obra e quando deixou de servir, e quando uma resistência é preguiça e quando traz uma informação.", PI)
add("Leia este livro inteiro no meio das estações, numa noite sem pressa, e <i>Da prova</i> agora uma vez só; você sai dele com a página das quatro provas e a conclusão embaixo, e com os cinco sinais de <i>Do escrúpulo</i> sabidos sem abrir o livro. Volte a <i>Da resistência que fala</i> quando a da vez não chegar há muitas noites ou a mesma resistência não ceder; a <i>Do escrúpulo</i>, quando a anti-visão ou o exame da noite afundarem você ou a marca não se decidir noite após noite; e a <i>Da prova</i>, na noite em que a décima terceira chegar ou numa das seguintes, antes do novo dia zero.", PI)
add("Se você chegou aqui pela ordem, muitas noites se passaram. Você está em algum ponto do meio das estações, com algumas microações já entre as que ficaram, talvez um corte com a sua contagem correndo, e a folha de marcas cheia de traços, de algumas cruzes e de umas poucas noites de <i>chegou</i>. Este é o trecho plano e longo do caminho, e é nele, e não no dia zero, que o método encontra situações que nenhuma regra escrita antecipa por inteiro. Uma doença em casa, um filho que nasce, um pai que morre, uma mudança de cidade; um mês em que a lei do sono não se cumpre porque alguém precisa de você à noite; um exercício que você cumpre à risca e que, cumprido à risca, deixou de fazer sentido.", PI)
add("Se você chegou antes do tempo, leia assim mesmo pela ordem; se o que o trouxe foi o caderno inteiro pesando mais do que ajuda, e você tiver pressa, comece por <i>Do escrúpulo</i>.", PI)
add("Este livro foi escrito para quem sabe o que deve fazer e não faz. Para essa pessoa, quase toda resistência é para atravessar. Mas ninguém está nesse lugar o tempo todo, e um método que não reconhece os próprios limites acaba quebrando quem o usa.", PI)
add("Aristóteles chamava de <i>phrónesis</i>, prudência, a virtude que decide as outras: saber o que convém, a quem, quando e quanto. A coragem sem prudência vira temeridade; a firmeza sem prudência vira rigidez. Nenhuma lei deste livro dispensa o juízo; as leis servem para que ele não seja usado como desculpa. A epígrafe deste livro junta as duas coisas. O Livro IV conta que, para Aristóteles, a virtude é um meio-termo entre o excesso e a falta; a frase acrescenta que quem determina esse meio é a razão, e que a medida dessa razão é o que faria o homem prudente diante do caso, sem tabela que o dispense. É a forma da pergunta de <i>Da máscara</i>: Aristóteles também mede o ato por um homem, ainda que o dele seja o prudente, de fins retos. Diante do caso difícil, você pergunta <i>O que ele faria agora?</i>, e as provas que vêm a seguir garantem que <i>ele</i> tem juízo: firme no que importa, e capaz de ver quando a regra deixou de servir à obra.", PI)
add("No sexto livro da <i>Ética</i>, ele diz como essa virtude se forma, e o que diz consola pouco quem queria uma regra. A prudência se ocupa de coisas particulares, que podem ser de outra maneira, e por isso não é ciência, que trata do que não muda. E por isso, observa, um rapaz pode ser bom geômetra e bom matemático, sábio nessas coisas, mas não se vê um rapaz prudente: a prudência pede experiência, e a experiência pede tempo. Ela se aprende nas noites que você já tem atrás de si, e é por isso que este livro se lê no meio do caminho.", PI)
add("No começo da mesma obra (I, 2), Aristóteles compara quem conhece o seu fim a um arqueiro que tem um alvo: não acertará mais vezes no que deve? O juízo só se orienta se houver alvo, e o seu está escrito desde o dia zero, na visão e na anti-visão. Mas o arqueiro não segue uma regra fixa: o vento muda, a distância muda, e o mesmo alvo pede, a cada tiro, outra pontaria. Em outro trecho (II, 6), Aristóteles acrescenta que errar é fácil e acertar é difícil, porque há muitas maneiras de errar o alvo e uma só de acertá-lo. O ato certo, portanto, é estreito: de cada lado do meio há mais de uma maneira de falhar, e por isso a pontaria se refaz a cada caso. Nas próximas noites, apertar a lei quando a vida mudou e afrouxá-la quando ela só custa são duas maneiras de errar o mesmo alvo.", PI)
add("Os gregos tinham uma palavra para a outra metade do juízo: <i>kairós</i>, o momento oportuno, que não se confunde com a hora do relógio. O primeiro dos <i>Aforismos</i> atribuídos a Hipócrates, o médico grego de Cós do século V antes de Cristo, liga essa palavra às dificuldades do médico: a vida é breve, a arte é longa, a ocasião é fugaz, a experiência enganadora, o juízo difícil. O bom médico sabe a regra e sabe quando ela se aplica a este doente, hoje. É isso que este livro pede a você para as leis do método.", PI)
add("Pascal, em um dos fragmentos dos <i>Pensamentos</i>, distinguiu dois espíritos. O espírito de geometria trabalha com princípios poucos, nítidos, afastados do uso comum: custa vê-los, mas, uma vez vistos, ninguém se engana a partir deles. O espírito de finura trabalha com princípios que estão diante de todos, no uso de todos os dias, mas são tantos e tão sutis que quase todos escapam; é preciso vê-los com um só olhar, e não no fim de uma cadeia de raciocínios. O método, com as suas marcas e contagens, é obra do primeiro espírito, e precisa dele: sem a folha de marcas, a impressão do momento governaria tudo. A sua vida pede o segundo. Quem só tem o primeiro aplica as leis como teoremas e não percebe quando o terreno mudou. Nas provas que vêm a seguir, você vai precisar dos dois: do primeiro para escrevê-las e contar as marcas, do segundo para ler o que elas dizem da sua vida.", PI)

sec("Das quatro quedas")
add("A linha da queda pede duas coisas: onde foi, e o que você vai fazer de diferente. A segunda depende de um diagnóstico que a primeira raramente dá sozinha, porque a mesma cruz pode ter quatro causas, e cada uma pede outro remédio. Antes de perguntar se uma resistência informa, pergunte de que espécie foi a queda. As quatro vêm aqui na ordem em que se examinam, porque cada uma supõe que a anterior não aconteceu: quem não viu a ocasião não chegou a pôr o gesto à prova, e quem não tinha o gesto à mão não chegou a perguntar para quê.", PI)
add("<i>A falha de ocasião.</i> A ocasião veio e você não a reconheceu. O sinal está na lembrança: você só soube da queda depois, no caminho para casa ou à noite, ao fazer a marca, e não se lembra de ter escolhido ceder, porque não houve escolha. Foi o que aconteceu à mulher de <i>Do primeiro dia</i> na terça da semana de prazos. O remédio está na manhã. A previsão foi vaga, <i>quando eu estudar</i>, e precisa ficar exata: o lugar, a hora aproximada e o que vem logo antes, porque é o que vem antes que anuncia a ocasião. Escreva esse aviso na linha da queda e, na manhã seguinte, preveja a ocasião a partir dele.", PI)
add("<i>A falha de gesto.</i> Você viu a ocasião, soube que era ela e mesmo assim não fez. O sinal é a hesitação: um instante parado diante dela, sem saber por onde começar, e depois outra coisa. Quase sempre o gesto, tal como você o tinha na cabeça, era grande ou vago demais: <i>organizar tudo</i>, no lugar de tirar da mesa o que distrai; <i>estudar o capítulo</i>, no lugar de abrir na página e ler a primeira frase. O remédio é o tamanho. O gesto do exercício fica como está até uma passagem; o que se corrige agora é a frase com que você o diz a si mesmo de manhã, reduzida ao que as mãos fazem nos primeiros segundos, e, na ocasião, a versão de dois minutos da sexta linha. Se a queda de gesto se repete com o gesto já reduzido, a forma da microação talvez não caiba na sua vida, e isso se decide numa passagem.", PI)
add("<i>A falha de sentido.</i> Você viu a ocasião, sabia o que fazer e podia fazê-lo, e não quis, porque naquele instante o gesto pareceu não servir para nada. O sinal é a indiferença: a queda vem sem luta, e a linha da manhã desse dia foi escrita de cor, sem que você pensasse no que escrevia. O porquê se gastou pelo uso, como se gasta qualquer frase repetida. O remédio é religar o gesto à obra. Na linha da queda, escreva numa frase para que servia aquele gesto ontem, que obra ele protegia; na manhã seguinte, escreva a obra de hoje devagar, conferindo que ela desce da obra em curso, e preveja a ocasião como o ponto em que essa obra se ganha ou se perde. A folha do dia zero e a frase da anti-visão ficam para as passagens, porque o peso delas se gasta com o uso. Se a falha de sentido volta muitas noites e se estende à obra inteira, leve-a à prova do fim, na seção seguinte, que diz se o destino precisa ser revisto.", PI)
add("<i>A falha de terreno.</i> Você viu a ocasião, tinha o gesto e o porquê, e o que estava em volta não deixou: a casa cheia sem uma mesa livre, a ocasião posta numa hora em que você já não tem cabeça, a noite mal dormida, a pessoa que entra e pede. O sinal é que a linha da queda nomeia uma coisa fora de você, e que a mesma coisa volta nas quedas seguintes. Desconfie um pouco desse sinal, porque o terreno é a desculpa mais à mão: só conta o obstáculo que um estranho veria se estivesse na sala. O remédio depende da duração. Se o obstáculo é passageiro, uma febre, uma viagem, uma semana de prazos, ele é a circunstância para a qual existe o piso, declarado de manhã. Se é constante, arrume o terreno antes da ocasião, como o Livro IV ensina a fazer com as pontes: o que distrai fora do alcance desde a véspera, o quarto defendido para o sono, a porta fechada e a hora combinada com quem mora com você. E se o que falha é a hora, porque a vida já não comporta a ocasião onde você a pôs, a ocasião se muda numa passagem, por escrito; a seção seguinte conta o caso de um homem que fez isso.", PI)
add("Uma queda só raramente basta para o diagnóstico. Releia juntas as linhas da queda das últimas semanas numa noite de passagem, ou quando a da vez não chegar há muitas noites. Quatro cruzes de ocasião pedem uma previsão melhor, e nenhuma lei mais dura; quatro de terreno pedem que se arrume a casa; quatro de gesto ou de sentido, com os remédios já tentados, são a matéria das provas que vêm a seguir.", PI)
add("No fim de agosto de 1854, o cólera matou mais de quinhentas pessoas em dez dias, em poucas ruas do Soho, em Londres. O médico John Snow marcou cada morto no mapa do bairro. As mortes se juntavam em volta de uma bomba pública da Broad Street, e foram as exceções que fecharam o diagnóstico: o asilo de pobres da rua ao lado, com mais de quinhentos internos e poço próprio, teve poucas mortes; os setenta homens de uma cervejaria da mesma rua, que bebiam a cerveja da casa, nenhuma; e uma viúva de Hampstead que mandava buscar a água daquela bomba porque preferia o gosto dela, morreu. A pedido dele, a paróquia retirou o braço da bomba. Snow conta tudo em <i>Sobre o modo de transmissão do cólera</i>, de 1855, e admite que a epidemia já declinava quando isso foi feito. A causa estava no desenho das mortes lidas juntas, como a das suas quedas está nas linhas de várias semanas.", PI)

sec("Da resistência que fala")
add("Em uma manhã destas, na hora da ocasião, ou em uma noite ao fazer a marca, vem uma voz. Você conhece as do Livro I, que pediam cinco minutos ou um depois. Esta fala de outra maneira: traz argumentos, e alguns são bons. Ela diz coisas assim:", PI)
for v in ["O cansaço é de verdade, e também conta.",
          "Isso deixou de fazer sentido para você; já percebeu que faz isso sem saber para quê?",
          "Há semanas que você tenta, e nada. Talvez o problema seja o gesto, e não você.",
          "O método foi feito para uma vida mais simples do que a sua.",
          "Hoje você tem razões verdadeiras; amanhã faz o dobro."]:
    add(v, VOICE)
sp(6)
add("Algumas dessas frases mentem e outras podem dizer a verdade, e todas chegam com a mesma voz, parecida com a sua. A última mente sempre, porque a quarta lei já respondeu a ela: nada se compensa. As outras não são julgadas pelo tom. São julgadas pelo que acontece quando você as põe à prova.", PI)
add("Há duas resistências, e por fora elas se parecem. A primeira é a que se atravessa: preguiça, tédio, o medo do trecho difícil, a vontade de fazer algo mais fácil. Ela não diz nada sobre a obra; diz apenas que a obra custa. A segunda é a que informa: o esgotamento real, o objetivo que perdeu o sentido, a circunstância que mudou, a dor que pede outra coisa. O erro do homem disperso é tratar toda resistência como informação, e por isso ele nunca age. O erro do homem rígido é tratar toda resistência como fraqueza, e por isso um dia ele se quebra. Quatro provas separam uma da outra:", PI)
provas = [
 ("A prova do começo.", "Faça a versão de dois minutos, na ocasião. Se, depois dela, a resistência se dissolve, era da primeira espécie. Se ela cresce, ou se o peso continua igual depois de começar, pode ser da segunda."),
 ("A prova do sono.", "Durma, descanse e olhe de novo pela manhã. A resistência da primeira espécie volta igual todos os dias, e cede ao primeiro movimento. O esgotamento real diminui com o repouso."),
 ("A prova do fim.", "Pergunte: <i>se isto já estivesse terminado, eu ficaria contente?</i> Se a resposta é sim, a resistência é ao caminho, e o caminho se atravessa. Se a resposta é não, talvez seja o destino que precisa ser revisto."),
 ("A prova da duração.", "Uma resistência que acompanha a mesma obra noite após noite, sem nunca ceder ao começo nem ao repouso, já deixou de ser preguiça, e pede que se reveja o domínio; apertar a lei não a resolve. Se o <i>chegou</i> não vem, a passagem é declarada por decisão, como se ensina mais abaixo."),
]
for i,(a_,b_) in enumerate(provas,1):
    add(f"{rom(i)}. &nbsp;<b>{a_}</b> {b_}", LAW)
add("<b>A noite das provas.</b> As provas são feitas por escrito, e sobre uma resistência só, a que mais pesa em você agora. Em uma noite, depois dos minutos de sempre, abra o caderno em uma página nova. No alto, escreva a resistência em uma linha: a que ela se agarra, a que horas vem, o que ela lhe diz. Embaixo, quatro linhas, uma para cada prova. Duas são feitas na hora. Na do fim, responda à pergunta; se a resposta não for sim nem não, mas alívio ou indiferença, escreva-a assim. Na da duração, abra a folha de marcas e conte: há quantas noites essa resistência o acompanha, quantas cruzes houve desde que ela veio, se ela cedeu alguma vez ao começo ou ao descanso.", PI)
add("As outras duas pedem o dia seguinte. Deite-se na hora, com a lei do sono defendida da melhor forma que puder. De manhã, nos minutos do caderno, antes de abrir qualquer outra coisa, olhe de novo a resistência e escreva na segunda linha se ela pesa o mesmo, mais ou menos. E quando a ocasião vier, faça a versão de dois minutos, a sexta linha do Livro I, sem pedir mais do que isso; à noite, escreva na primeira linha o que aconteceu depois dela. Nessa segunda noite, leia as quatro linhas juntas e escreva embaixo uma conclusão, em uma frase.", PI)
add("Cada prova responde a uma pergunta diferente, e as respostas apontam para lugares diferentes. Se o começo dissolveu a resistência, ela era da primeira espécie, e a lei se cumpre como sempre. Se o sono a aliviou, era cansaço, e o remédio é o piso, declarado de manhã, a hora de parar respeitada e, se o cansaço já atravessa as noites, um dia de ócio. Se o fim respondeu não, ou se a duração mostra muitas noites sem que nada ceda, ela informa, e o que informa é levado a uma passagem, por escrito.", PI)
add("As provas pedem uma noite e um dia. Antes delas, e em qualquer dia, três sinais mais finos ajudam a desconfiar de uma espécie ou da outra, sem decidir nada sozinhos. O primeiro está nas razões. A resistência que se atravessa troca de razão a cada dia e conserva a conclusão, que é sempre adiar; a que informa repete a mesma razão, com o mesmo conteúdo, e a conclusão dela pede uma mudança: outra hora, outra forma, outro fim. O segundo está na hora em que ela fala. A primeira só aparece diante da ocasião e se cala quando a ocasião passa; a segunda fala também longe dela, num domingo, no meio de outra conversa, quando nada lhe está sendo pedido. O terceiro está no preço. A primeira oferece alívio imediato e não cobra nada; a segunda traz, junto com a razão, um custo, porque ouvi-la obriga a admitir uma escolha errada ou a perder o que já se pôs nela, e por isso é a que você menos gostaria de ouvir.", PI)
add("Um homem treina às seis da manhã. Na segunda, a voz lhe diz que choveu; na terça, que dormiu mal; na quarta, que há reunião cedo. As razões mudam, a conclusão é sempre <i>amanhã</i>, e às sete, passada a hora, ela não diz mais nada. Essa se atravessa. Uma mulher estuda piano depois do jantar, e toda noite a voz lhe diz a mesma coisa: o filho do vizinho dorme do outro lado da parede, e ela toca com medo de acordá-lo. A frase volta no almoço, quando ninguém lhe pede piano, e não propõe adiar; propõe trocar a hora, justamente a que ela mais gostava de ter. Essa informa que a ocasião foi mal escolhida, e ela a leva às provas e, se as provas confirmarem, a uma passagem.", PI)
add("Há um caso que nenhuma das quatro toca sozinha, e é a única porta que <i>Da máscara</i> deixou aberta para você. Se a resistência não se agarra a uma obra, mas a quase tudo o que a visão lhe pede, faça a prova do fim sobre a visão inteira: leia o segundo ponto da folha do dia zero e pergunte se, já vivendo aquela vida, você ficaria contente. Se a resposta honesta for alívio, o erro está na escolha do rosto, que o eu antigo fez em um só dia, e a resistência informa sobre <i>ele</i>. A correção é feita em uma passagem, por escrito, no segundo ponto da folha, com as marcas à frente; com a visão corrigida, <i>ele</i> se refaz, e a pergunta passa a ser feita ao rosto novo. Até essa noite, ela é feita ao antigo.", PI)
add("Deixe-me contar o caso de um homem que fez este caminho antes de você. Não é um nome da história, e basta que você saiba dele o que as suas folhas guardaram. No quarto mês, ele tinha um relatório difícil para entregar e sentia, todas as manhãs, um peso enorme antes de começá-lo. Fez os dois minutos, uma frase ruim, e dez minutos depois tinha esquecido o peso. Era a primeira espécie, e a lei se cumpriu sem drama.", PI)
add("No mês seguinte, o pai dele adoeceu, e ele passou três semanas dormindo em cadeiras de hospital. A microação da vez começou a cair, e ele se acusava de preguiça. Em uma noite em que um irmão o substituiu, dormiu oito horas seguidas, e no dia seguinte, quando a ocasião veio, fez a microação sem esforço. A resistência tinha diminuído com o descanso: era cansaço. A resposta certa, para ele, era o piso, declarado de manhã, e a lei do sono defendida como fosse possível, e não uma lei mais apertada.", PI)
add("Mais tarde ainda, ele fez a terceira prova sobre um curso que tinha escolhido aos vinte anos para agradar a outra pessoa, e que arrastava havia meses. <i>Se já estivesse terminado, eu ficaria contente?</i> A resposta honesta foi que ficaria aliviado, o que é diferente. Diante de um livro que lhe custava cada página, a mesma pergunta lhe dava uma alegria clara: o livro era caminho a atravessar. O curso talvez fosse destino a rever, e ele o reviu em uma passagem, por escrito, com as marcas à frente, e não em uma noite ruim.", PI)
add("E depois de tudo isso, durante muitas noites, a microação da vez caía noite sim, noite não. Nenhum <i>chegou</i> aparecia ao lado dos traços, os pisos se cumpriam a custo, e nem o começo nem o descanso mudavam nada. A tentação dele foi acrescentar uma lei, levantar-se mais cedo. A quarta prova mandava parar de apertar e, em uma passagem, voltar por escrito ao exercício zero e perguntar se o domínio ainda era o dele. Mas a passagem, que só um <i>chegou</i> trazia, não vinha, e sem ela não havia noite em que ele pudesse corrigir alguma coisa. É para isto que existe a segunda forma.", PI)
add("<b>A passagem por decisão.</b> É a única passagem sem <i>chegou</i>, e é a única correção possível quando a da vez não chega e a resistência não cede. Eu a ensino aqui por inteiro, porque ela não está explicada em nenhum outro lugar do livro. Ela se declara assim:", PI)
pd = [
 ("Quando.", "Em uma noite sem cruz, depois de você ter feito por escrito as quatro provas e concluído, na frase escrita embaixo delas, que a resistência informa. Nunca em uma noite de cruz, nunca no dia em que a microação entrou, nunca por cansaço de uma noite."),
 ("A linha.", "No caderno, depois da marca: <i>passagem por decisão</i>, a data, e a razão em uma linha, tirada da conclusão das provas."),
 ("A noite.", "Nela se faz o que se faz em toda passagem: lê-se a Lição seguinte; releem-se a folha do dia zero, com a frase da anti-visão, e a página do Homem; fazem-se por escrito as correções que as marcas pedirem; revê-se o domínio, por escrito, diante das marcas."),
 ("A decisão.", "Uma de duas. Se o domínio continua sendo o seu e o que falha é a forma da microação, redefina por escrito a ocasião ou o gesto dela, e ela continua sendo a da vez; a nova forma é escrita no caderno, e é lá que você a lê de manhã, no lugar da linha do breviário. Se o domínio mudou, volte à estação zero na manhã seguinte e refaça o exercício zero, como fez no dia zero."),
 ("O limite.", "Ela não serve para pular exercício. A da vez só passa a ficar com <i>chegou</i> escrito em uma noite de traço, sem dúvida, como sempre."),
]
for i,(a_,b_) in enumerate(pd,1):
    add(f"{rom(i)}. &nbsp;<b>{a_}</b> {b_}", LAW)
add("O homem do relatório a declarou em uma noite em que não tinha caído. A da vez era a primeira hora do dia longe das distrações, e as manhãs dele, desde a doença do pai, pertenciam ao hospital. As provas tinham lhe dito que o domínio continuava sendo o dele; o que a vida já não comportava era a ocasião. Ele escreveu a linha, leu a Lição, releu a folha do dia zero e mudou a ocasião para a primeira hora depois de voltar para casa, com o mesmo gesto. A microação continuou sendo a da vez, e semanas depois, em uma noite de traço, ele escreveu ao lado <i>chegou</i>. Se as provas tivessem lhe dito o contrário, a mesma noite o teria mandado à estação zero, sem precisar esperar o fim do ciclo.", PI)
add("Quando nada dá prazer há semanas, quando o sono não descansa e o peso está em tudo e não em uma obra, isso não se resolve com este livro, nem com uma passagem por decisão. É hora de procurar um profissional, e procurá-lo faz parte do governo de si que este livro pede. Os sinais estão em <i>Do escrúpulo</i>.", NOTE)

sec("Da firmeza e da rigidez")
add("Talvez isto já tenha acontecido com você, ou aconteça nas próximas semanas: você se pega defendendo uma lei contra a razão para a qual ela existe. Cumpre a hora da microação com um filho doente no colo, porque a lei é a lei. Recusa o piso em um dia de febre, porque o piso lhe parece fraqueza. Por fora parece firmeza, e convém saber distinguir os dois nomes.", PI)
add("<b>Firme</b> é quem mantém a linha no que importa. <b>Rígido</b> é quem mantém a forma depois que a realidade mudou, e já não pergunta para que a regra existia. A pergunta que separa os dois cabe em uma linha, e você pode fazê-la sempre que uma lei lhe pesar: <i>para que existe esta regra, e o que ela protege hoje?</i> Se a resposta é a obra, ou o gesto, ou a segunda queda que ela impede, cumpra-a. Se a resposta é só a própria regra, você está guardando a forma. Com a máscara acontece o mesmo: mantê-la no que serve à obra é firmeza, e mantê-la quando já não serve ao rosto que você tem é rigidez.", PI)
add("Sêneca, no tratado <i>Dos benefícios</i>, ao discutir se quem prometeu fica obrigado a cumprir em qualquer caso, escreveu que o sábio não muda de decisão enquanto permanecem as condições em que a tomou; mas, se as condições mudaram, mudar de decisão é ser coerente com elas. A constância do sábio, para Sêneca, pertence ao juízo que decidiu. Para os estoicos, só o juízo depende de nós, e manter uma regra cujas condições desapareceram seria obedecer à letra dela contra o juízo que a fez. As leis deste livro valem enquanto servem. É essa a diferença entre corrigir o método e fugir dele, e ela se vê no caderno: a correção deixa uma linha datada, escrita em uma passagem, com as marcas à frente.", PI)
add("Kepler passou anos, a partir de 1600, tentando ajustar a órbita de Marte a círculos, a forma que a astronomia tinha por perfeita desde os gregos. Chegou a uma hipótese que concordava com as observações de Tycho Brahe em quase tudo e errava, em alguns pontos, por oito minutos de arco, cerca de um quarto do diâmetro aparente da Lua. Kepler sabia que Tycho observava com precisão maior do que essa, e escreveu na <i>Astronomia nova</i>, de 1609, que, se achasse possível desprezar aqueles oito minutos, teria remendado a hipótese; como não era, foram eles, sozinhos, que abriram o caminho para reformar a astronomia inteira. Largou o círculo e chegou à elipse. A regra que ele guardou foi a fidelidade às observações, para a qual o círculo existia, e a forma caiu quando deixou de servir a ela.", PI)
add("O Livro II mandou para cá o sinal de que a hora de parar já não basta. Quem o dá é a prova do sono: se você respeita a hora de parar todos os dias e, manhã após manhã, o cansaço não diminui, a noite já não o desfaz. Então declare, na véspera, à noite, um dia de ócio, com as paredes que o Livro II deu a ele. Se, depois dele, o cansaço volta igual, já não é caso para o ócio; é caso para a nota com que termina a seção anterior.", PI)
add("E há uma rigidez mais sutil, a de transformar o próprio livro em obra. Se ler, reler, anotar e aperfeiçoar o método toma mais do que os poucos minutos da manhã e da noite, o método passou a ocupar o lugar de um velho hábito, o de se preparar em vez de fazer. O sinal é simples, e aparece à noite, na linha do dia: o dia teve ar de disciplina e você não escreveu nada que exista agora e não existisse de manhã. Nesses dias, o livro tomou o lugar de <i>isto</i>; feche-o e volte à obra que tinha à frente.", PI)

sec("Do chegou e do engano")
add("Talvez você já tenha escrito alguns <i>chegou</i> e, ao relê-los numa destas noites, desconfie de um deles. A desconfiança é justa. A quarta regra de <i>Da medida</i> continua a mesma; o que segue diz o que, numa noite de marca, conta como dúvida, e na dúvida, como você sabe, não chegou.", PI)
add("Comece pela testemunha, que é fraca. A lembrança de um dia se refaz cada vez que é chamada, e se refaz com os desejos de quem lembra: quem quer avançar lembra a sessão em que avançou. E o gesto feito sem decisão deixa pouco rastro, e a falta de rastro se parece muito com o esquecimento. Por isso a marca se faz na mesma noite, e nunca se escreve <i>chegou</i> sobre um dia que já passou: na manhã seguinte, a lembrança já foi refeita a seu favor. E por isso não se lembrar da decisão só vale como sinal se você se lembra da sessão. Se a sessão inteira está turva, falta a testemunha, e sem testemunha a coluna fica vazia.", PI)
add("Feitas na noite, três provas separam o <i>chegou</i> do engano. A primeira é a da ocasião. O <i>chegou</i> conta na ocasião que mais pesou, e uma ocasião pesa pelo que as linhas da queda dizem dela: a hora em que você cedia, o cansaço, a companhia, a pressa. Se o gesto veio sozinho num dia em que a ocasião mais pesada foi branda, ele veio onde nunca tinha faltado, e isso ainda é dúvida. O <i>chegou</i> verdadeiro aparece nas condições em que você caía. A segunda é a da repetição. O gesto que chega costuma dar sinal antes, em ocasiões diferentes, num dia de semana e num sábado, descansado e cansado, como deu à mulher na noite de dúvida que precedeu a certa. Se ele precisou do caderno em todas as noites anteriores e, numa noite boa, veio sozinho, o mais provável é que a noite tenha sido boa. A terceira é a do breviário. Pergunte o que estava à vista e o que você leu antes da ocasião. Se o breviário estava aberto, ou se a linha da manhã ainda soava quando você se sentou, a lembrança pode ter vindo dele, e o gesto foi lembrado, ainda que sem a frase <i>agora tiro isto</i>. No <i>chegou</i>, quem lembra é a ocasião, e só ela. Basta uma prova falhar para haver dúvida.", PI)
add("Essas provas têm apoio no que a psicologia sabe do hábito. Wendy Wood e David Neal descreveram o hábito, em 2007, como uma resposta disparada pela pista do contexto, aprendida pela repetição naquele contexto e relativamente independente do objetivo do momento. O <i>chegou</i> registra o primeiro sinal disso: o gesto disparado pela pista, a mesa vista ao sentar, e não pelo objetivo lembrado, que é o trabalho do caderno e do breviário. Cada prova testa uma parte da definição. A ocasião pesada testa a independência do objetivo, porque é nela que o objetivo do momento, descansar ou adiar, puxa para o outro lado. As ocasiões diferentes testam se quem disparou foi a pista ou o acaso de um dia. O breviário fora de vista testa se a lembrança veio da pista ou da intenção. E a mesma literatura explica por que um <i>chegou</i> ainda não é hábito feito: a força do hábito cresce aos poucos, a cada repetição, como no estudo de Lally o gesto ia saindo sem pensar ao longo de semanas e meses. O <i>chegou</i> marca um ponto dessa subida, e a consolidação acontece entre as que ficaram.", PI)
add("Resta o gesto que chegou e um dia se perde. A sexta regra de <i>Da medida</i> já diz o que fazer: a queda vai para a última coluna, com a linha da queda, e, duas noites seguidas, o gesto volta a ser a da vez. O que a regra não diz é como ler a perda. Releia as linhas da queda e procure o que mudou na ocasião. Se o gesto caiu nas primeiras semanas depois da passagem sem que nada mudasse, o mais provável é que o <i>chegou</i> tenha sido escrito cedo, e as três provas pedem mais rigor de você na próxima vez. Se caiu depois de meses, procure a pista: uma mudança de casa, de horário, de mesa, uma viagem. O hábito que Wood e Neal descrevem depende da pista que o dispara; quando ela some, ele fica sem gatilho, ainda que o que você aprendeu continue lá. O gesto volta então a ser lembrado pelo caderno até se prender à pista nova, e costuma chegar mais depressa, como a ordem da mulher; se a ocasião escrita deixou de existir, a emenda se faz na passagem, por escrito, como qualquer outra. Em nenhum dos casos se risca o <i>chegou</i> antigo. Ele fica na folha daquela noite, como cada cruz fica na dela, e mostra a quem relê as folhas onde você se enganou.", PI)

sec("Do escrúpulo")
add("Há uma terceira maneira de o método se virar contra quem o usa, e ela se reconhece pela noite. Você faz a marca e não consegue decidi-la. <i>Foi traço mesmo? A ocasião que mais pesou foi esta, ou foi a outra, em que cedi? E o piso de terça, não terá sido preguiça disfarçada de piso?</i> Você escreve cruz, por via das dúvidas. Na noite seguinte, a mesma pergunta, e outra cruz. O exame passa a durar vinte minutos, e acaba em uma acusação. Se isso lhe soa conhecido, a sua prática tem o defeito que Inácio de Loyola viveu em Manresa, e o remédio dele serve a você ao pé da letra.", PI)
add("Inácio, o mesmo da convalescença, foi viver em Manresa em 1522, depois de fazer em Montserrat a confissão geral de toda a sua vida; lá começou o caderno dos Exercícios de que você se serviu no dia zero. Pouco depois começaram os escrúpulos. Parecia-lhe sempre que não tinha confessado tudo, ou que tinha confessado mal. Voltava ao confessor, anotava os pecados para não esquecer nenhum, e não tinha paz. Conta na <i>Autobiografia</i> que o tormento chegou a ponto de lhe vir a tentação de se atirar por uma abertura do quarto onde rezava. Decidiu não comer nem beber até alcançar alívio, e passou assim uma semana inteira, até que o confessor lhe mandou parar.", PI)
add("Não foi mais exame que o libertou. Libertou-o uma decisão, que ele diz ter tomado com grande clareza, de não voltar a confessar nada do passado. Anos depois, com a experiência de quem tinha passado por ali, escreveu nos <i>Exercícios espirituais</i> algumas notas para quem sofre de escrúpulos. Em uma, dá o exemplo de quem pisa uma cruz formada por duas palhas e se atormenta com a ideia de ter pecado. Em outra, observa que o inimigo trata uma consciência delicada tentando torná-la ainda mais delicada, até a angústia, e uma consciência grosseira tentando torná-la mais grosseira; e que a alma que quer aproveitar deve fazer o contrário da tendência que nota em si, e se firmar no meio, para ficar em paz. É o conselho da vara torta de Aristóteles, aplicado à consciência.", PI)
add("Para você, o remédio se diz em três gestos. A regra <i>na dúvida, cruz</i> continua de pé para o caso duvidoso de uma noite; o escrúpulo faz da dúvida o estado de todas as noites, e enche a folha de cruzes sem queda. Primeiro: decida, de uma vez, por escrito, não reabrir as marcas já postas, e não volte atrás para corrigir folhas antigas. Segundo: quando a dúvida vier sobre o passado, trate-a com a nona linha, como uma onda que passa, e não como um processo a julgar. Terceiro: o exame da marca tem cinco minutos, e no fim deles o caderno se fecha, decidido ou não; o que não se decidiu em cinco minutos se marca pela regra e não se rumina.", PI)
add("Três casos pedem mais do que esses gestos. Se, apesar deles, o exame passa dos cinco minutos noite após noite, ou se a simples visão do caderno já lhe traz angústia, o escrúpulo venceu o remédio, e você está no quinto dos sinais que esta seção dá mais adiante. E se você se pega pondo traço onde houve cruz, a folha deixou de registrar. Na primeira vez, escreva na linha desta noite que mentiu, sem corrigir a marca antiga. Se acontecer de novo, a marca mentida gasta a mesma confiança na própria palavra que <i>Da primeira marca</i> começou a refazer. Em qualquer dos três casos, suspenda o método: escreva no caderno a data e a palavra <i>suspenso</i>, feche-o, e fale com alguém com formação para ouvir você antes de reabri-lo.", PI)
add("John Stuart Mill quebrou de outra maneira, e contou isso mais tarde na <i>Autobiografia</i>. O pai o tinha educado com grego aos três anos e lógica aos doze, em um regime que fez dele, aos vinte, um prodígio de análise, com um fim de vida claro: reformar o mundo. No outono de 1826, em um estado de abatimento como o que todos conhecem em algum momento, ele fez a si mesmo esta pergunta: <i>suponha que todos os seus objetivos se realizassem, que todas as mudanças nas instituições e nas opiniões que você busca se cumprissem neste instante; isso seria uma grande alegria e felicidade para você?</i> E uma consciência que ele não conseguia calar lhe respondeu claramente: <i>não</i> (paráfrase, <i>Autobiografia</i>, cap. V). Diz que o coração lhe afundou no peito, e que tudo aquilo sobre o que tinha construído a vida desabou.", PI)
add("Repare: Mill fez a si mesmo, quase palavra por palavra, a terceira prova, e recebeu o não. Mas o não dele não queria dizer que o destino estava errado; ele trabalhou a vida inteira pelas mesmas reformas. Queria dizer que alguma coisa nele, por baixo de todos os destinos, tinha se apagado. Passou meses assim, cumprindo o trabalho mecanicamente. E não falou com ninguém: o pai, que seria a pessoa natural, era também o autor da educação que ele agora suspeitava ser a causa, e ele não via outra pessoa a quem recorrer. Eis a advertência que cabe a você: as provas deste livro supõem um homem cujo juízo funciona. Quando o que adoece é o próprio juízo, elas respondem errado, e com toda a convicção.", PI)
add("Mill atribuiu a crise, em parte, ao hábito da análise: tinha sido treinado para decompor tudo, e a análise sem descanso tende a gastar os sentimentos. Saiu devagar. Um dia, lendo as memórias de Marmontel, chegou à passagem em que o autor, ainda rapaz, perde o pai e sente que há de ser tudo para a família; chorou, e soube que não era uma pedra. Em 1828, leu Wordsworth, e encontrou nos poemas sobre a natureza e a vida simples aquilo que chamou de cultura dos sentimentos, alegrias que não dependem de luta nem de imperfeição para existir. Tirou daí uma regra que convém a quem segue um método como este: pergunte a si mesmo se é feliz, e você deixa de ser; só são felizes os que têm o espírito posto em outra coisa que não a própria felicidade, uma obra, uma pessoa, uma arte praticada por si mesma.", PI)
add("Para você, isso quer dizer que o exame da noite tem limite. Cinco minutos, e não mais; a folha de marcas serve para registrar, e não para você se dissecar. Se o método treina você a se vigiar de tal modo que você já não sente nada do que faz, falta a ele o que Wordsworth foi para Mill: aquilo que você faz sem contar, com a atenção posta na coisa e não em si mesmo, como nas tardes em que, diante de uma coisa só, você se esquece de se vigiar <font color='#6b6b6b'>(Lição III)</font>. A hora de parar e o dia de ócio existem também para isso.", PI)
add("William James, aos vinte e oito anos, estava pior. Tinha se formado em medicina sem vontade de exercê-la, tinha o corpo doente e uma melancolia que durava havia anos e o fazia duvidar de que valesse a pena continuar. Em 30 de abril de 1870, escreveu no diário que o dia anterior tinha sido uma crise na sua vida. Acabara de ler a primeira parte do segundo dos <i>Ensaios</i> do filósofo francês Charles Renouvier, e não via razão para que a definição de livre-arbítrio que encontrara ali (sustentar um pensamento porque o escolho, quando poderia ter outros) fosse a definição de uma ilusão. <i>O meu primeiro ato de livre-arbítrio será acreditar no livre-arbítrio</i>, escreveu.", PI)
add("Não se deixe enganar pela beleza da frase: o que ele decidiu foi modesto e provisório. Assumiria, até o ano seguinte, que o livre-arbítrio não era ilusão; durante o resto do ano, se absteria da especulação e da ruminação em que a sua natureza mais se comprazia, e cultivaria o sentimento da liberdade moral lendo livros que o favorecessem, e agindo. Um prazo, uma linha, uma paixão contrária para as horas da ruminação. James não saiu da crise nesse dia, e a melancolia voltou a ele ao longo da vida; mas ganhou um ponto onde apoiar o pé. É a outra face da lição de Mill. Para James, a saída veio de largar a ruminação e agir; para Mill, de deixar de se examinar e voltar a sentir. Saber qual das duas cabe a você é trabalho deste livro, e nem sempre se consegue sozinho.", PI)
add("Por isso digo a você com clareza quando um método como este deixa de bastar. Há sinais que não se tratam com traços nem com linhas, e que pedem um médico ou alguém com formação para ouvir você. Saiba-os sem abrir o livro:", PI)
sinais = [
 ("Se há semanas nada lhe dá prazer,", "nem o que antes dava, e não só a obra."),
 ("Se o sono não descansa você,", "ou você não dorme, noite após noite."),
 ("Se lhe vêm pensamentos de morte,", "a ideia de que seria melhor não estar aqui, mesmo que passem depressa."),
 ("Se um hábito que você cortou volta sempre,", "apesar das pontes queimadas, da paixão contrária e da contagem, e já está lhe custando a saúde, o dinheiro ou as pessoas."),
 ("Se o método, em vez de pôr você em ordem, atormenta você,", "e o exame da noite se tornou a pior hora do dia."),
]
for i,(a_,b_) in enumerate(sinais,1):
    add(f"{rom(i)}. &nbsp;<b>{a_}</b> {b_}", LAW)
add("Nada disso mede a sua disciplina. Mede um estado que tem tratamento, e esse tratamento não está neste livro. Não é preciso esperar que fique grave. Mill passou meses sozinho porque não via com quem falar; você não precisa repetir esse erro. <b>Se o pensamento de morte aparecer, não espere pela próxima passagem nem pela manhã seguinte: fale hoje com alguém, e procure ajuda hoje.</b> Nada no caderno se perde com isso. A contagem espera, os exercícios esperam, e o que importa acima de qualquer linha é que você esteja aqui para retomá-la.", PI)

sec("Do que este método não resolve")
add("Este método treina gestos, e há males que nenhum gesto alcança. Nos casos abaixo ele não resolve nada, e insistir nele gasta um tempo que o caso não tem. O remédio de cada um está fora deste livro:", PI)
naoresolve = [
 ("Doença mental.", "Depressão, transtorno bipolar, transtorno de ansiedade ou outro estado que um médico nomeie se tratam com ele e com quem ele indicar; durante o tratamento, o método só continua se esse profissional não vir nele um peso. No Brasil, o CVV atende pelo 188 a qualquer hora."),
 ("Dívida e falta de dinheiro.", "Ponha numa folha cada dívida, com o credor, o valor e os juros, e leve essa folha a quem possa renegociá-la ou orientar você; a disciplina ajuda a cumprir o acordo, mas não paga a conta."),
 ("Relação em que alguém fere você.", "Se alguém fere você, com as mãos ou com a palavra, saia do alcance dessa pessoa e conte o que acontece a alguém de fora da relação; havendo perigo, ligue 190."),
 ("Luto recente.", "Nos primeiros meses depois de uma morte, deixe o método em suspenso, com o piso no máximo, porque o luto tem um tempo que não se treina; se, passado esse tempo, ele ainda impedir a vida, procure um médico."),
 ("Trauma.", "O que feriu você a fundo se trabalha com um terapeuta formado para isso, e nem o exame da noite nem a escrita sobre o que perturba devem reabrir essa ferida sozinhos, como o <i>Manual operacional</i> já avisa."),
 ("Dependência química.", "A dependência de álcool, de remédio ou de droga se trata com médico e com serviço especializado, que no SUS é o CAPS AD; o corte do Livro IV foi feito para hábitos, e parar de uma vez certas substâncias, o álcool entre elas, pode ser perigoso sem acompanhamento."),
]
for i,(a_,b_) in enumerate(naoresolve,1):
    add(f"{rom(i)}. &nbsp;<i>{a_}</i> {b_}", LAW)

sec("Da prova")
add("Esta seção é para outra noite, mais adiante: a noite em que a décima terceira microação chegar, ou uma das seguintes, antes do novo dia zero. Leia-a agora uma vez, para saber o que o espera, e volte a ela nessa noite.", PI)
add("Nessa noite, você terá à frente as folhas de marcas do ciclo, as linhas de queda e a folha do dia zero. É provável que lhe pareça que mudou pouco. Vista de dentro, a mudança quase não se nota. Ela consiste em abrir o trabalho sem vontade, ficar em uma coisa só até ela acabar, voltar depois da dispersão, ouvir uma crítica sem inventar defesa. Essa mudança, onde houver, vem do ciclo em que você fez o que o livro descreve, sobretudo das semanas em que as frases já não produziam entusiasmo e a rotina tinha voltado a ser banal.", PI)
add("Por isso, o que se avalia aqui são os atos que o ciclo produziu. Antes de voltar à estação zero, responda por escrito, na página seguinte, às cinco perguntas da prova, uma de cada vez, com as folhas à frente. Responda com o que você faz, e não com o que sente: se uma resposta lhe sair como um estado, <i>estou mais calmo</i>, procure nas folhas o ato que o mostra, e escreva o ato. Se as respostas forem pobres, o defeito pode estar no método, e não apenas em você: corrija-o, por escrito, e leve a correção ao novo dia zero.", PI)

# página da prova
st.append(PageBreak()); sp(20)
add("A prova do ciclo", ParagraphStyle('pv', parent=LT, fontSize=20, spaceAfter=6)); sumario(st[-1], 1, "A prova do ciclo")
add("Ciclo nº ____ &nbsp;&nbsp; de ___/___/_____ &nbsp; a ___/___/_____", ParagraphStyle('pv2', parent=PC, spaceAfter=18))
LN = ParagraphStyle('ln', **{**base, 'textColor': colors.HexColor('#b0b0b0')}, fontSize=11, leading=22)
perg = ["O que faço hoje sem negociar que, no começo do ciclo, não fazia? E em que tardes fiquei numa coisa só até ela acabar, e o que havia nelas?",
        "O que abandonei de vez?",
        "Onde o método falhou, e por quê?",
        "Que resistência ouvi, em vez de atravessar? Fiz bem?",
        "O que muda no próximo ciclo?"]
for q in perg:
    st.append(KeepTogether([Paragraph(f"<i>{q}</i>", ParagraphStyle('pq', parent=P, spaceBefore=6, spaceAfter=2)),
                            Paragraph("_"*78 + "<br/>" + "_"*78 + "<br/>" + "_"*78, LN)]))
add("Este livro se fecha com uma página escrita. Se você ainda não escreveu em uma linha a resistência que mais lhe pesa, com o resultado de cada uma das quatro provas e uma conclusão, comece hoje pela do fim e pela da duração, e amanhã de manhã faça a do sono. Se um dos sinais da lista de <i>Do escrúpulo</i> é seu, procure ajuda, e o caderno espera; se for o pensamento de morte, procure-a hoje. E no fim do ciclo, se uma das cinco respostas da prova diz o que você sente em vez do que você faz, reescreva-a com o que você faz.", PI); fleur()
# O ornamento vai junto do último parágrafo, para não ficar sozinho numa página.
st[-2:] = [KeepTogether(st[-2:])]
# ===================== INTERLÚDIO: DO HÁBITO E DE QUEM SE É =====================
estribilho_pagina()
st.append(PageBreak()); sp(8)
add("I N T E R L Ú D I O", LIV)
add("Do hábito e de quem se é", LT); sumario(st[-1], 0, "Interlúdio · Do hábito e de quem se é")
SEC_NO_SUMARIO = True
add("<i>“As virtudes não nascem em nós nem por natureza nem contra a natureza: somos feitos para recebê-las, e nos completamos nelas pelo costume.”</i>", ParagraphStyle('it1', parent=PC, fontSize=12, spaceAfter=2))
add("Aristóteles, <i>Ética a Nicômaco</i>, II, 1 (paráfrase)", ParagraphStyle('it2', parent=EPA, spaceAfter=18))
add("Leia este capítulo devagar no fim do ciclo, na noite em que respondeu à prova ou numa das seguintes; você sai daqui com o capítulo do ciclo escrito pela lista de <i>Do exercício</i> e uma só promessa para o ciclo seguinte, dita em atos. Volte a <i>Da objeção que ficou</i> e a <i>Do mesmo e de si</i> quando, diante das folhas, se perguntar quem fez tudo isto, e a <i>Da vontade que desceu</i> quando achar que mudou pouco.", PI)

add("Se ainda não respondeu às cinco perguntas de <i>Da prova</i>, este capítulo ainda não é seu: volte lá, responda, e só depois continue.", PI)
add("Antes de fechar o caderno, ponha sobre a mesa o que o ciclo deixou. As folhas de marcas, uma linha por dia, meses delas. Na coluna do número da microação da vez, o um das primeiras noites e depois o dois, o três, até o treze; se alguma das que ficaram caiu duas noites seguidas e voltou a ser a da vez, o mesmo número aparece lá duas vezes, separado. Na coluna estreita, os <i>chegou</i>, um em cada noite de passagem, menos nas passagens por decisão, se houve alguma. As cruzes, com a linha da queda escrita embaixo de cada uma, na letra que você tinha em cada noite. E, na primeira página, a folha do dia zero, que você escreveu num dia sem trabalho, há meses, com a anti-visão e a visão. O livro não sabe o que está escrito nela. Você sabe, e esta noite vai lê-la ao lado das folhas.", PI)
add("A esta altura surge uma pergunta que a prova não fez. A prova perguntou o que você faz hoje sem negociar. A outra vem em voz mais baixa, quando você olha a letra da primeira página, e soa assim: <i>quem fez tudo isto?</i> Quem acabou de responder à prova é quem escreveu a anti-visão? Se é o mesmo, talvez só a superfície tenha mudado. Se é outro, para quem você trabalhou?", PI)
add("Este capítulo não traz linha nem lei novas, e não mexe na prova. Ele está aqui, entre a prova e o dia zero seguinte, porque esta é a primeira noite em que você olha para trás com um ciclo de provas na mão, e é nela que a pergunta pesa. Eu também parei nesta noite e fiz a mesma pergunta. O que conto a seguir são as respostas que outros deram a ela, de Aristóteles a MacIntyre, na ordem do tempo. No fim há um único exercício, para o fim de cada ciclo, e é com ele escrito que você sai daqui.", PI)
add("Duas palavras vão lhe servir esta noite, e convém fixá-las antes de qualquer autor. <b>Hábito</b> é o que você faz por repetição, de tal modo que, com o tempo, passa a fazê-lo sem ter de decidir de novo: é o que o <i>chegou</i>, numa noite de passagem, começa a registrar. <b>Caráter</b> é a maneira de ser pela qual quem conhece você sabe, mais ou menos, o que você vai fazer: a sua forma habitual de responder ao medo, ao prazer, à pressa, ao outro. A pergunta desta noite é sobre a relação entre as duas: se o caráter é só a soma dos hábitos ou se há nele mais alguma coisa, e onde estava essa coisa nas noites em que você marcava cruzes.", PI)

sec("Da objeção que ficou")
add("A pergunta já tinha aparecido a você no dia zero, quando o Prólogo previu o protesto <i>sou mais do que os meus atos</i> e lhe deu só metade da resposta: o dia zero lê provas e não pronuncia sentença sobre o fundo. A outra metade ficou, de propósito, para depois do primeiro ciclo, porque naquele dia a objeção também servia de abrigo.", PI)
add("Esta noite, com as folhas na mesa, a objeção volta com outro rosto. Já não serve para negar a semana antiga; serve para perguntar pelo que há por baixo das marcas. Talvez ela chegue a você assim: <i>se sou apenas o que faço, então durante este ciclo fui uma sucessão de traços e cruzes, e amanhã, se parar, volto a ser a semana da anti-visão; se sou mais do que faço, que coisa é essa, e onde estava enquanto eu falhava?</i> Há nas duas perguntas uma inquietação legítima, e a filosofia se ocupa dela há vinte e quatro séculos, com várias respostas que se corrigem umas às outras.", PI)

sec("Do costume e do caráter")
add("Começo por Atenas, por volta de 335 antes de Cristo. Aristóteles, de volta à cidade depois de anos fora, ensina no Liceu, um ginásio fora das muralhas, junto de um bosque consagrado a Apolo. A tradição diz que ele dava as lições caminhando pelas alamedas cobertas, e que daí veio o nome dado aos discípulos dele, peripatéticos, os que andam em volta. Os livros que chamamos de <i>Ética a Nicômaco</i> guardam, ao que tudo indica, o que se dizia nessas lições, e a pergunta que os atravessa é a mesma que você faz esta noite: como alguém se torna bom, se não nasceu assim?", PI)
add("A primeira resposta está numa palavra. No começo do segundo livro, Aristóteles observa que a virtude do caráter tira o nome do costume, por uma pequena mudança. Em grego são duas palavras quase iguais. <i>Éthos</i>, com a vogal breve, é o hábito, o que se faz por repetição. <i>Ēthos</i>, com a vogal longa, é o caráter, a maneira de ser de alguém, e nos poemas mais antigos era o lugar habitual a que um animal volta, a morada dele. A língua guardou o que a experiência ensinava: o caráter é o costume que se assentou. Assim, as duas palavras que você fixou há pouco já estavam juntas no grego.", PI)
add("Logo em seguida vem o exemplo que todo leitor da <i>Ética</i> conhece. A pedra, que por natureza cai, não se habitua a subir, ainda que alguém a atire para cima dez mil vezes; o fogo não se habitua a descer. O que é por natureza não se altera pelo hábito. As virtudes, porém, não nos são nem dadas nem vedadas: o homem nasce apto a recebê-las e se completa nelas pelo costume, como diz a epígrafe deste capítulo.", PI)
add("Aristóteles chama de <i>héxis</i> aquilo que esse costume deixa em quem o pratica, palavra que o latim traduziu por <i>habitus</i> e que se perde um pouco no nosso <i>hábito</i>. Ela vem do verbo <i>échein</i>: ter, segurar, estar de certa maneira. A <i>héxis</i> é um ter: uma disposição adquirida e firme, que faz com que alguém, diante do medo ou do prazer, se porte bem ou mal sem ter de deliberar do zero. Você já a encontrou de passagem no Livro II. Esta noite, importa o que ela responde à objeção.", PI)
add("A <i>héxis</i> fica por baixo dos atos, e nenhum deles a esgota, nem a soma deles. O corajoso que dorme continua corajoso; quem fugiu uma vez não se tornou covarde por isso. A disposição sobrevive a cada ação, e nisso a objeção tem razão: você é mais do que os seus atos de hoje. Mas ela só se forma por atos, e só por atos se desfaz. Tornamo-nos justos praticando atos justos, e a disposição está formada quando o ato já não custa, como você leu no Livro II; a frieza do começo vai embora com esse sinal. Olhe para a coluna estreita das suas folhas. Cada <i>chegou</i> que você escreveu ali marca a noite em que um gesto começou a ser disposição; o sinal de consolidação de cada exercício, no Livro III, descreve esse gesto já maduro.", PI)
add("Convém, porém, que você saiba o que Aristóteles exigia antes de chamar uma disposição de virtude, porque o método não dá tudo a você. A virtude, diz ele, é uma disposição de escolha, <i>héxis proairetiké</i> (II, 6), e o ato virtuoso pede que quem o faz saiba o que faz, o escolha pelo que o ato é e o faça a partir de uma disposição firme (II, 4, paráfrase). Ou seja, a virtude é o hábito de escolher bem, de olhos abertos, em vista da vida boa, e nunca um gesto que se faz sem decidir. Os gestos deste livro são escolhidos pelo que dão a uma obra, e os marcados com H são feitos quase sem decisão. Pelos critérios dele, o que o método treina, sobretudo no corte do Livro IV, em que você ainda deseja o que largou, está mais perto da <i>enkráteia</i>: a continência de quem deseja mal e se domina, que ele punha abaixo da temperança, na qual o desejo já concorda com o juízo (VII, 9). O livro toma de Aristóteles a formação pelos atos; a escolha do que merece ser escolhido fica com você.", PI)
add("A primeira resposta é, então, dupla: a disposição não se reduz aos atos de um dia, e só se forma por atos repetidos, como os que as folhas sobre a sua mesa registram.", PI)

sec("Da mulher e do bezerro")
add("A segunda resposta é menos tranquila e vem de Montaigne, que leu Aristóteles e desconfiava de quase tudo, e desconfiava do costume menos do que de qualquer outra força. No capítulo dos <i>Ensaios</i> que dedica ao costume, <i>Do costume e de não mudar facilmente uma lei recebida</i>, ele começa por uma história que ele próprio apresenta como fábula, forjada por alguém que, segundo diz, entendeu muito bem o poder do hábito. Uma mulher de aldeia aprendeu a acariciar e a carregar nos braços um bezerro desde a hora em que ele nasceu. Fez isso todos os dias, sem interromper. E ganhou, pelo costume, isto: quando o bezerro já era um grande boi, ela ainda o carregava.", PI)
add("Repare no que a fábula conta e no que ela cala. Não houve um dia em que a mulher se tornou forte. Nenhum dia pesou muito mais do que o anterior: o bezerro crescia um pouco por noite, e os braços dela, um pouco por noite, cresciam também. Se, no último dia, tivessem posto nos braços dela o boi inteiro sem os anos de antes, ela teria caído com ele. Ela carregou mil vezes um animal ligeiramente mais pesado que o da véspera, e é só isso que a fábula lhe atribui. É a mesma lição da lenda de Mílon, que você encontrou no exercício do corpo. Montaigne, porém, a conta a propósito da servidão.", PI)
add("O costume, escreve ele, é uma mestra-escola violenta e traiçoeira. Essa mestra instala em nós a autoridade dela pouco a pouco, às escondidas, com um começo brando e humilde; depois, assentada com a ajuda do tempo, nos mostra um rosto furioso e tirânico, contra o qual já não temos sequer a liberdade de erguer os olhos. E Montaigne conta, no mesmo capítulo, que Platão repreendeu um menino que jogava com nozes. O menino respondeu que estava sendo repreendido por pouca coisa. <i>O costume</i>, disse Platão, <i>não é coisa pouca</i>. Na resposta de Platão, cada jogo pequeno ensina ao menino uma inclinação, e é justamente por ser pequeno que ninguém o vigia. Montaigne conta as duas histórias juntas para mostrar a mesma força nos dois sentidos: a força que deu à mulher braços para o boi é a mesma que, sem que ninguém perceba, prende a vida a um costume que já não se escolhe.", PI)
add("Olhe agora para a primeira página e para a última folha de marcas, e veja nelas a mesma lei pelos dois lados. A semana que você descreveu na terceira pergunta do dia zero também era um bezerro carregado todos os dias, e por isso pesava tão pouco e era tão difícil de largar. O ciclo trocou, devagar, o animal que você tem nos braços, e as folhas mostram a troca noite a noite. À pergunta sobre quem você é por baixo disso, Montaigne dá uma resposta desconfortável: o que você é depende do costume mais do que você gostaria de admitir. Montaigne conta a fábula como aviso contra a servidão ao costume, e aqui ela serve para você escolher os costumes aos quais se sujeita.", PI)

sec("Do feixe")
add("Um século e meio depois, um jovem escocês levou a desconfiança mais longe. David Hume tinha pouco mais de vinte anos quando escreveu o <i>Tratado da natureza humana</i>, retirado em La Flèche, no interior da França, e na seção sobre a identidade pessoal fez uma experiência que você pode repetir esta noite. Quando entro mais intimamente naquilo que chamo de <i>eu mesmo</i>, escreve ele, sempre tropeço numa percepção particular: de calor ou de frio, de luz ou de sombra, de amor ou de ódio, de dor ou de prazer. Nunca consigo me flagrar sem uma percepção, e nunca observo coisa alguma além da percepção. Daí a conclusão que escandalizou os contemporâneos: aquilo que chamamos de eu não passa de um feixe, uma coleção de percepções diferentes que se sucedem com uma rapidez inconcebível, em fluxo e movimento perpétuos.", PI)
add("Faça a experiência agora, à mesa, com as folhas à frente. Feche os olhos e procure em você o que é mais do que os seus atos e estados, aquilo que estava presente no primeiro dia e está presente agora, igual. Você vai encontrar uma lembrança, um cansaço, uma frase, o peso do corpo na cadeira. Procure aquilo que possui essas coisas, e vai encontrar outra lembrança.", PI)
add("Alguém tiraria daí que tudo isto foi em vão. Se não há um eu por baixo do feixe, não houve ninguém que mudasse; houve percepções se sucedendo, umas com traços e outras com cruzes, e chamar isso de transformação é falar de um sujeito que não existe. A objeção parece sutil, e na prática serve de pretexto: se ninguém muda, ninguém precisa começar no dia seguinte ao dia zero.", PI)
add("Hume não tirou dela essa conclusão. Na mesma seção, quando procura algo com que comparar a alma, escolhe uma imagem política: uma república, cujos membros estão unidos por laços recíprocos de governo e subordinação e dão origem a outros, que continuam a mesma república na mudança incessante das partes. E acrescenta que, assim como a mesma república pode mudar não só os membros mas também as leis e a constituição, a mesma pessoa pode variar de caráter e de disposições sem perder a identidade. A unidade da pessoa vem das relações, e de nenhuma substância escondida: a causa que liga uma percepção à seguinte, a memória que as percorre.", PI)
add("Anos depois, na <i>Investigação sobre o entendimento humano</i>, ao perguntar por que esperamos que o futuro se pareça com o passado, Hume responde que quem nos leva a isso é o costume, e não a razão, e escreve:", PI)
st.append(KeepTogether([Paragraph("<i>“O costume é, pois, o grande guia da vida humana.”</i>", ParagraphStyle('it3', parent=PC, fontSize=12, spaceAfter=2)),
                        Paragraph("Hume, <i>Investigação sobre o entendimento humano</i>, V", ParagraphStyle('it4', parent=EPA, spaceAfter=14))]))
add("Lido assim, o feixe descreve o que você fez durante o ciclo. Se você é uma república de percepções governada pelo costume, mudar é mudar as leis da república, e as leis dela são os costumes; você as mudou uma microação de cada vez, sem precisar convencer um eu escondido por trás delas. A objeção do dia zero pedia um eu maior do que os atos; Hume oferece um feixe de percepções, ligado por relações e sem nada por baixo. Ele fala de percepções, e não de atos; é o livro que estende a imagem aos costumes que governam os atos, e essa ordem pode ser alterada. Nessa imagem, cada traço das suas folhas confirmou um costume da república.", PI)
add("Hume, honesto, confessou num apêndice ao <i>Tratado</i> que a própria explicação não o satisfazia e que se via num labirinto. Para praticar, você não precisa sair dele: em qualquer hipótese sobre o que você é, o costume governa, e obedece ao que se repete.", PI)

sec("Da vontade que desceu")
add("Hume deixou o costume do lado de fora da razão, como uma força cega. Em 1838, em Paris, um jovem de vinte e cinco anos defendeu uma tese breve que olhava o costume por dentro. Félix Ravaisson a chamou simplesmente de <i>Do hábito</i>, e nela descreveu o que acontece com um movimento que se repete.", PI)
add("No começo, diz ele, o movimento é inteiramente vontade: há esforço, há consciência de cada parte, há a distância sentida entre querer e fazer. Com a repetição, o esforço diminui e a consciência diminui com ele, mas o movimento não piora: ele se torna mais rápido, mais certo, mais fácil. Ele se aproxima do instinto, até parecer que nasceu com o corpo. O hábito é essa passagem, por graus insensíveis, da vontade à natureza. Uma natureza adquirida, uma segunda natureza, e Ravaisson insiste em que ela não é mecânica: o que desceu ao corpo continua a ser uma inclinação, um querer que já não precisa querer a si mesmo. Ravaisson retoma ainda uma lei dupla que Maine de Biran, filósofo francês, tinha formulado no começo do século, num ensaio sobre a influência do hábito na faculdade de pensar. A sensação repetida enfraquece; a ação repetida se fortalece. O que você sofre, sente cada vez menos; o que você faz, faz cada vez melhor.", PI)
add("Isso responde à segunda metade da objeção, a que pergunta onde você estava enquanto falhava. Lembre-se, se puder, das primeiras manhãs do exercício do corpo, ou das noites do terminar, em que voltar ao que estava aberto custava mais do que abrir uma coisa nova. Se elas custavam, essa vontade não se gastou: desceu ao gesto. Ela está hoje no que você faz sem decidir, nos exercícios marcados com H, que acontecem quase sem decisão, e na rapidez maior dos marcados com J. Quando você procura em si a vontade de antes e não a encontra, é porque ela passou para o gesto, que já não pede esforço. É também por isso que, ao fim do ciclo, talvez você já tenha tido tardes inteiras numa coisa só, com as horas passando sem custo.", PI)
add("E isso explica uma coisa que o Livro V deixou dita sem explicar: vista de dentro, a mudança quase não se nota. A lei dupla de Maine de Biran trabalha contra a sua impressão. O esforço do começo desapareceu justamente porque o gesto se tornou seu, e por isso, ao fim do ciclo, você sente menos do que esperava sentir.", PI)
add("Resta ainda uma pergunta que as folhas fazem sem dizê-la. Você treinou treze gestos, um de cada vez, cada um com a própria ocasião e o próprio <i>chegou</i>: saiu do ciclo com treze hábitos, ou com um caráter? Aristóteles respondeu a essa pergunta para as virtudes de que tratava. No sexto livro da <i>Ética a Nicômaco</i>, diz que as virtudes de caráter não existem, no sentido pleno, separadas da prudência, a <i>phrónesis</i>, e que com ela, que é uma só, vêm todas (VI, 13, paráfrase). Sem ela, são o que ele chama de virtudes naturais: boas inclinações que, sem juízo, causam dano, como um corpo forte que se move sem ver e cai com mais força por não ver. Com isso Aristóteles quer dizer que o que faz de várias disposições um só caráter é o juízo que, em cada caso, vê o que convém à vida inteira. O livro não dá a você essa prudência, como você leu em <i>Do costume e do caráter</i>, e por isso adapta a resposta. O que une os treze gestos é o homem da visão: os gestos são os meios dele, tirados da folha do dia zero, e a máscara é o princípio que os junta, porque é a pergunta sobre ele que escolhe, a cada entrada, o que você faz. Ravaisson fala de uma segunda natureza, no singular, e é no singular que a máscara a pede, com um só rosto. Essa escolha, <i>Do retorno</i> a reabre no fim de cada ciclo.", PI)

sec("Do que se conta")
add("A resposta seguinte vem de um teatro. Nos Estados Unidos, durante as últimas décadas do século XIX, um mesmo homem subiu ao palco milhares de vezes no mesmo papel. Joseph Jefferson, o ator mais célebre da época no país, fez o papel de Rip Van Winkle numa adaptação do conto de Washington Irving. O Rip do palco é um bêbado afável que, a cada copo novo, se desculpa com a mesma frase, e a plateia ria com ele: <i>desta vez não conta</i>.", PI)
add("Em 1890, William James levou o Rip para o capítulo sobre o hábito dos <i>Princípios de psicologia</i>. Ele pode não contar a vez, comenta James, e um céu bondoso pode não contá-la; mas ela está sendo contada do mesmo modo. Lá embaixo, entre as células e as fibras nervosas, as moléculas estão contando, registrando e guardando, para usar contra ele quando vier a próxima tentação. Nada do que alguma vez fazemos, em sentido estritamente científico, se apaga.", PI)
add("O capítulo começa pela matéria. Os seres vivos, escreve James, são feitos de uma substância plástica, e plasticidade quer dizer possuir uma estrutura fraca o bastante para ceder a uma influência, mas forte o bastante para não ceder toda de uma vez. O sistema nervoso, como a água que corre, cava o próprio leito e, depois de cavá-lo, volta a correr por ele.", PI)
add("Da matéria, James passa à conduta e tira, apoiado no psicólogo escocês Alexander Bain, umas poucas máximas para quem quer adquirir um hábito novo ou largar um velho. A primeira: lançar-se com uma iniciativa tão forte e tão decidida quanto possível, juntando em torno da decisão todas as circunstâncias que a reforcem. Foi o seu dia zero, e é a linha do corte traçada, datada e assinada no mesmo dia em que se queimam as pontes. James sugere até um compromisso público; o livro prefere a promessa assinada e o silêncio da sétima lei, mas o princípio é o mesmo. A segunda máxima: nunca permitir uma exceção enquanto o hábito novo não estiver bem enraizado. Cada lapso, diz James, é como deixar cair o novelo que se estava enrolando com cuidado: um só deslize desfaz mais voltas do que muitas voltas tornam a enrolar. A terceira: agarrar a primeira ocasião possível para agir segundo cada resolução, antes que ela esfrie. Entre as leis do livro, essa é a segunda: percebeu, aja, antes que se forme a segunda frase interior.", PI)
add("O Rip tem, neste livro, três maneiras de falar, e talvez você as tenha ouvido em alguma noite do ciclo. A primeira pede um ponto no dia em que a ocasião veio e você cedeu: é dizer <i>desta vez não conta</i>. A segunda fala do intervalo entre duas quedas: o Rip diria que o dia sem ocasião entre duas cruzes as separou, e o livro as conta como seguidas. A terceira escreve <i>chegou</i> numa noite em que você não tem certeza, para que a da vez passe a ficar e a seguinte entre: é o Rip de outra maneira, descontando adiantado o que ainda não está feito. As regras que respondem a cada uma estão em <i>Da medida</i>. A folha de marcas é a contabilidade que as moléculas de James fazem de qualquer modo. O livro apenas pediu que você a fizesse à vista, com a sua letra, em vez de deixá-la correr às escondidas contra você; é ela que você tem agora sobre a mesa.", PI)
add("Há aqui uma dificuldade: James manda não admitir exceção alguma, e o livro deixou que uma microação chegasse com cruzes pelo caminho; entre a manhã em que ela entrou e a noite do <i>chegou</i> pode ter havido três ou quatro, e as suas folhas dizem quantas. Isso não é deixar cair o novelo três ou quatro vezes? A diferença está na palavra. A exceção de que James fala é uma licença que se concede antes, ou uma queda que se desconta depois: a do Rip, que bebe e não conta. A cruz faz o contrário das duas. Ela conta a queda, com a linha de queda ao lado, dizendo onde estava o buraco. E a máxima de James, no que tem de verdadeiro, vive inteira na quinta lei: nunca dois dias seguidos de queda, e um ponto no meio não os separa.", PI)

sec("Do mesmo e de si")
add("Falta uma parte da objeção, e para ela vou lhe contar uma cena de Roma. Cartago, meados do século III antes de Cristo. Marco Atílio Régulo, cônsul romano feito prisioneiro na guerra contra os cartagineses, é mandado a Roma sob juramento: deve negociar a troca de prisioneiros e, se ela fracassar, voltar. No Senado, ele aconselha que a troca seja recusada, porque não convém a Roma. Depois, contra os pedidos da família e dos amigos, embarca de volta para Cartago, onde o esperam a prisão e a morte. Cícero conta a história no terceiro livro de <i>Dos deveres</i>, como exemplo do dever; os historiadores de hoje duvidam de parte dela. Mas o que Roma guardou foi o gesto: um homem que, chegado o dia, já não podia querer o que tinha jurado, e cumpriu.", PI)
add("Fica nessa cena um resto da objeção a que nenhuma das respostas anteriores responde. Quando você diz <i>sou mais do que os meus atos</i>, talvez não queira falar de disposições. Talvez queira dizer que há em você alguém que responde pelos atos, que pode prometê-los antes e reconhecê-los depois. Esse alguém não aparece em nenhuma folha de marcas, e é ele que esta noite lê as folhas e que respondeu à prova.", PI)
add("Paul Ricoeur deu nome a esse alguém em 1990, em <i>O si-mesmo como outro</i>. Há, diz ele, dois sentidos em que uma pessoa permanece a mesma ao longo do tempo, e o latim tinha uma palavra para cada um. <i>Idem</i> é a mesmidade: aquilo que continua igual e permite reconhecer alguém, como se reconhece um rosto ou uma assinatura. No plano da pessoa, a mesmidade é o caráter, o conjunto das disposições duradouras pelas quais os outros reconhecem você, e Ricoeur o liga expressamente ao hábito: cada hábito contraído se sedimenta e se torna um traço de caráter. Tudo o que contei até aqui é sobre o <i>idem</i>.", PI)
add("<i>Ipse</i> é outra coisa: o si que se mantém, mesmo quando muda. Para Ricoeur, o modelo dessa permanência é a palavra dada e cumprida, e não o caráter. Quem promete fixa o que fará num tempo em que já poderá querer outra coisa, ter outra opinião, sentir outra inclinação; e, chegado esse tempo, mantém. Ainda que o meu desejo mude, ainda que eu mude de opinião, eu mantenho. Essa constância desafia a mudança, em vez de depender de que nada tenha mudado. Ricoeur a chama de manutenção de si.", PI)
add("Lembre-se agora da frase que você disse esta manhã, como em todas as manhãs do ciclo, e repare na forma que ela tem. <i>Reivindique-se para si</i> está no imperativo. Ela não descreve o seu caráter, que no primeiro dia ainda era, em boa parte, o da anti-visão; manda fazer uma coisa naquele dia. Quem a diz de manhã a toma como palavra dada a si mesmo. Em Ricoeur, a promessa responde a alguém que conta comigo; aqui ela se dobra sobre você, e quem conta com você é você mesmo. A palavra tem objeto preciso: as horas desse dia e a microação da vez na ocasião dela. Como toda promessa séria, ela não garante que você não vá cair. Cada manhã a palavra foi dada, cada noite a marca verificou se ela foi mantida. Vista assim, a folha de marcas é o registro de uma promessa renovada a cada manhã do ciclo.", PI)
add("Agora você pode responder à pergunta com que a noite começou: se você é quem escreveu a anti-visão. No <i>idem</i>, você é um pouco menos aquele que era: há hábitos novos sedimentados onde moravam os velhos, e haverá mais. No <i>ipse</i>, contam os dias em que você manteve a palavra sem que ela lhe desse gosto nenhum; as suas folhas sabem quantos foram esses dias, e o livro não. E aqui a objeção do dia zero recebe a parte de razão que lhe faltava. Você é mais do que os seus atos no sentido exato de ser quem os promete e responde por eles. Mas esse si só se atesta mantendo, e se mantém em atos. É nesse sentido que a primeira carta a Lucílio manda que cada um reivindique a si mesmo: a posse de si se exerce em atos, hora a hora.", PI)

sec("Da vida como história")
add("A última resposta desta noite é de Alasdair MacIntyre, em <i>Depois da virtude</i>, de 1981, e começa por uma cena banal. Um homem está no quintal cavando a terra, e MacIntyre pergunta o que ele está fazendo. As respostas que ele enumera são todas verdadeiras: cava; cuida do jardim; faz exercício; prepara a terra para o inverno; agrada à mulher. O corpo faz o mesmo movimento em todas. O que distingue uma da outra é a história em que o gesto entra, e sem ela o gesto nem chega a ser compreensível.", PI)
add("Daí MacIntyre tira uma ideia antiga com palavras novas. Contra a vida moderna repartida em segmentos, cada um com as próprias normas, em que o eu se dissolve numa sucessão de papéis, ele propõe que a unidade de uma vida humana é a unidade de uma narrativa. O homem, escreve, é, nas ações e nas práticas, tanto quanto nas ficções, essencialmente um animal que conta histórias. E só posso responder à pergunta <i>que devo fazer?</i> se puder responder a uma anterior: <i>de que história, ou histórias, faço parte?</i> Um traço isolado das suas folhas diz tão pouco quanto o movimento do homem que cava; dentro do ciclo, ele ganha o sentido da história a que pertence.", PI)
add("MacIntyre chama essa vida de busca e acrescenta um ponto que serve a quem acabou um ciclo. A busca não começa com o bem perfeitamente definido; o que se procura se aprende procurando, e as virtudes são as disposições que sustentam a busca e, ao mesmo tempo, ensinam o que ela procura. A sua visão do dia zero foi escrita por alguém que ainda não tinha feito um ciclo. É natural que, ao relê-la esta noite, você veja nela coisas a corrigir; não as corrija na folha antiga, porque a correção pertence à nova folha do próximo dia zero. É o que MacIntyre descreve: aprender, procurando, o que se procura. E ser o sujeito de uma história, diz ainda MacIntyre, é ser alguém a quem se podem pedir contas dos atos que a compõem. Na narrativa cabem o <i>idem</i> e o <i>ipse</i> de Ricoeur: a continuidade do caráter e a responsabilidade de quem manteve a palavra.", PI)
add("Há quem pense, como o filósofo inglês Derek Parfit, que a ligação entre quem você é e quem será daqui a vinte anos é mais frouxa do que a linguagem finge, e tire daí deveres para com esse herdeiro <font color='#6b6b6b'>(Lição VIII)</font>. A história não desmente essa frouxidão; ela liga os seus estados sucessivos numa sequência pela qual você responde. E Franklin, que escreveu a própria vida em livro e guardou dentro dele o caderno de virtudes <font color='#6b6b6b'>(Lição XI)</font>, sabia que o caderno só ganhava sentido dentro da história que ele contava com ele.", PI)

sec("Do exercício")
add("O exercício vem disso, e é o que lhe resta fazer antes do novo dia zero, esta noite ou numa das próximas. A prova do ciclo respondeu ao que você faz, e continua como está, com as cinco perguntas dela. Agora você escreve o ciclo como um capítulo da sua vida. O que contei serve de molde: o primeiro parágrafo é do <i>idem</i>, o que se sedimentou e o que não; o segundo, do <i>ipse</i>, a palavra mantida; o terceiro é uma promessa, a forma que Ricoeur dá à permanência de si. Os passos são estes.", PI)
cap = [
 ("Quando.", "Numa noite entre a prova e o dia zero seguinte, a sós e longe de toda distração. Uma hora, no máximo. Se passar disso, você está tratando o capítulo como obra, e ele não é."),
 ("O título.", "No alto da página 37, o número do ciclo, as datas e um título curto, como o de um capítulo de livro, que nomeie o ciclo pelo que de fato aconteceu nele."),
 ("O que fui.", "Primeiro parágrafo. Quem começou o ciclo e quem o terminou, contado pelas provas: a folha do dia zero, as folhas de marcas, as linhas do dia e as linhas de queda. Só fatos, como os escreveria alguém que observasse você durante o ciclo inteiro. Inclua o que não mudou."),
 ("O que mantive.", "Segundo parágrafo. A palavra que você cumpriu quando não tinha vontade, e as vezes em que voltou depois de uma cruz. É o parágrafo do <i>ipse</i>: o que você sustentou ao longo do ciclo."),
 ("O que prometo.", "Terceiro parágrafo. Uma promessa para o ciclo seguinte, uma só, dita em atos e não em estados, que o dia zero vai traduzir na folha dele. Não a repita em outros lugares nem a conte a ninguém (sétima lei)."),
 ("Onde se escreve.", "Nas páginas 37 e 38 do caderno deste ciclo. O novo dia zero abre um caderno novo, e este é guardado com os dos ciclos anteriores. Os capítulos não são relidos durante o ciclo, nem nas noites de passagem. Na véspera de cada novo dia zero, todos são relidos, cada um no próprio caderno, de uma vez, antes de dormir."),
]
for i,(a_,b_) in enumerate(cap,1):
    add(f"{rom(i)}. &nbsp;<b>{a_}</b> {b_}", LAW)
add("Dois erros a evitar, ambos já conhecidos. Escrever bonito, como se alguém fosse ler: ninguém vai ler, e o capítulo enfeitado mente a quem o reler daqui a três anos. E escrever uma sentença em vez de uma história: <i>fui fraco</i> ou <i>sou outra pessoa</i> são veredictos, e um veredicto sobre o caráter fecha o processo que a história deixa aberto. A história diz o que aconteceu e onde estava o buraco.", PI)
add("Quando terminar, leia os três parágrafos uma vez. Se, ao relê-los, você encontrar no primeiro um juízo sobre si, troque-o pelo que aconteceu; se a promessa do terceiro disser um estado, escreva o ato que o mostraria. Relidos na véspera de cada dia zero, os capítulos vão responder à pergunta deste interlúdio com os seus próprios fatos: você verá o que se sedimentou, o que voltou a cair, o que se manteve através de tudo.", PI)

add("Depois deste capítulo vêm as Doze Lições, que agora se releem todas, com o ciclo feito, e a página do Homem, que você relê como quem volta a assinar: relê-la é dar de novo a palavra a quem vai escrever o próximo capítulo. Por fim, <i>Do retorno</i>, que leva você ao novo dia zero.", PI)
add("Antes de passar às Lições, confira que o capítulo do ciclo tem número, datas, título e três parágrafos, com uma só promessa, dita em atos, e que está nas páginas 37 e 38 do caderno deste ciclo; o que faltar, complete pela lista de <i>Do exercício</i> antes do novo dia zero.", PI); fleur()
# ===================== LIVRO VI =====================
import json
LIC = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'licoes.json')))
NOTA = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'nota.txt')).read().split("\n\n")
livro("VI", "Das doze lições")
add("para os dias em que o corpo pesa mais que a vontade", ParagraphStyle('l5s', parent=EXQ, alignment=TA_CENTER, fontSize=12, spaceAfter=4))
add("por M Castro", ParagraphStyle('l5a', parent=EPA, spaceAfter=30))
add("<i>\u201cUma geração vai, e outra geração vem; mas a terra permanece para sempre.\u201d</i>", ParagraphStyle('e1', parent=PC, fontSize=11.5))
add("Eclesiastes 1:4", ParagraphStyle('e2', parent=EPA, spaceAfter=12))
add("<i>\u201cNinguém se banha duas vezes no mesmo rio.\u201d</i>", ParagraphStyle('e3', parent=PC, fontSize=11.5))
add("Heráclito (atribuído)", ParagraphStyle('e4', parent=EPA, spaceAfter=30))
add("Leia a <i>Nota inicial</i> e a Lição I na primeira noite de passagem, depois da marca. São de outro autor, M Castro, falam com outra voz e não lhe pedem ato nem escrita. Em cada noite de passagem seguinte, ou num dia de ócio, leia a Lição seguinte na ordem, e só essa; isso leva menos de dez minutos e não ocupa o lugar da prática. Fora dessa ordem, volte à Lição IV quando, depois de uma queda, a sua cabeça escrever uma sentença sobre o seu caráter, e à Lição II quando uma frase herdada, como <i>eu nunca termino nada</i>, parecer a você descrever um fato. Se as doze acabarem antes do fim do ciclo, releia em cada passagem seguinte a que mais lhe servir, e no fim do ciclo releia todas, com o ciclo feito. Você sai deste livro com uma Lição lida em cada noite de passagem, na ordem, e com as doze lidas no fim do ciclo.", PI)
# A nota inicial começa na página seguinte, inteira, em vez de deixar a sua última linha sozinha.
st.append(PageBreak())
sec("Nota inicial")
for par in NOTA: add(par, PI)
add("As lições não substituem a prática: dão a ela o porquê. Foram feitas pequenas correções de fato onde o texto original se afastava do registro histórico.", NOTE)

LBL5 = ParagraphStyle('lbl5', **{**base, 'textColor': GRAY}, fontSize=9.5, leading=12, alignment=TA_CENTER, spaceBefore=16, spaceAfter=8, keepWithNext=1)
QQ = ParagraphStyle('qq', fontName='G-I', textColor=INK, fontSize=12, leading=16.5, alignment=TA_CENTER, leftIndent=20, rightIndent=20, spaceAfter=2)
QAu = ParagraphStyle('qau', **{**base, 'textColor': GRAY}, fontSize=10, leading=13, alignment=TA_CENTER, spaceAfter=10)
def citas(t):
    out = []
    for m in re.finditer(r"\u201c(.*?)\u201d\s*\u2014\s*(.*?)(?=\u201c|$)", t, re.S):
        q = re.sub(r"\s*\n\s*", " ", m.group(1)).strip()
        a = re.sub(r"\s*\n\s*", " ", m.group(2)).strip()
        out.append((q, a))
    return out
NOMES = {"O exemplo real":"O &nbsp;EXEMPLO &nbsp;REAL","A crítica":"A &nbsp;CRÍTICA","O que diz o autor":"O &nbsp;QUE &nbsp;DIZ &nbsp;O &nbsp;AUTOR","A meditação":"A &nbsp;MEDITAÇÃO"}
for Lc in LIC:
    st.append(PageBreak()); sp(24)
    add(f"L I Ç Ã O &nbsp; {Lc['num']}", LIV)
    add(Lc['title'], ParagraphStyle('lt5', parent=LT, fontSize=21, spaceAfter=14))
    sumario(st[-1], 1, f"Lição {Lc['num']} · {Lc['title']}")
    for k in ["O exemplo real","A crítica","O que diz o autor","A meditação"]:
        if k == "O que diz o autor":
            # O rótulo vai no bloco da primeira citação: o keepWithNext do LBL5
            # não segura um KeepTogether na mesma página.
            rotulo = [Paragraph(NOMES[k], LBL5)]
            for q, a in citas(Lc['secs'][k]):
                st.append(KeepTogether(rotulo + [Paragraph(f"\u201c{q}\u201d", QQ), Paragraph(f"\u2014 {a}", QAu)]))
                rotulo = []
            st.extend(rotulo)
        else:
            add(NOMES[k], LBL5)
            add(Lc['secs'][k], PI)
    add(Lc['secs']["A lição"], BOX)

